using UnityEngine;
using System.Collections.Generic;

public class RandomValueGenerator : MonoBehaviour
{
    private float _floatRangeMin, _floatRangeMax;
    private int _intRangeMin, _intRangeMax;
    private Dictionary<float, float> _customDistribution;

    public void SetFloatRange(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");
        _floatRangeMin = min;
        _floatRangeMax = max;
    }

    public void SetIntRange(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value must be less than maximum value.");
        _intRangeMin = min;
        _intRangeMax = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(_floatRangeMin, _floatRangeMax);
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range(_intRangeMin, _intRangeMax + 1); // Add 1 for exclusive upper bound
    }

    public void SetCustomDistribution(Dictionary<float, float> distribution)
    {
        if (distribution == null || distribution.Count == 0)
            throw new ArgumentException("Distribution must not be empty.");
        _customDistribution = distribution;
    }

    public float GetRandomFromCustomDistribution()
    {
        if (_customDistribution == null || _customDistribution.Count == 0)
            return GetRandomFloat(); // Fallback to uniform distribution
        float randomValue = UnityEngine.Random.value;
        float cumulativeProbability = 0.0f;
        foreach (var entry in _customDistribution)
        {
            cumulativeProbability += entry.Value;
            if (randomValue <= cumulativeProbability)
                return entry.Key;
        }
        throw new InvalidOperationException("Random value generation from distribution failed.");
    }

    public override string ToString()
    {
        return $"Float Range:({_floatRangeMin}, {_floatRangeMax}), Int Range:({_intRangeMin}, {_intRangeMax})";
    }
}
