    public function handleUserAccountRequests() {
        $method = $_SERVER['REQUEST_METHOD'];
        $data = json_decode(file_get_contents('php://input'), true);

        try {
            switch ($method) {
                case 'POST':
                    if (isset($data['id'])) {
                        // Update user
                        $result = $this->updateUserAccount($data);
                    } else {
                        // Create user
