```cpp
#include <iostream>
#include <vector>
#include <cmath>

struct Point {
    double x, y;
};

class QuadtreeNode {
public:
    Point center;
    double size;
    std::vector<Point> points;
    QuadtreeNode* children[4];

    QuadtreeNode(Point c, double s) : center(c), size(s) {
        for (int i = 0; i < 4; ++i) children[i] = nullptr;
    }

    ~QuadtreeNode() {
        for (int i = 0; i < 4; ++i) delete children[i];
    }
};

class Quadtree {
public:
    QuadtreeNode* root;
    int maxDepth;

    Quadtree(Point origin, double size, int depth)
        : root(new QuadtreeNode(origin, size)), maxDepth(depth) {}

    ~Quadtree() { delete root; }

    void insert(const Point& point) {
        insertRecursive(root, point, 0);
    }

    Point nearestNeighbor(const Point& queryPoint) const {
        return findNearestNeighbor(root, queryPoint, root->center, std::numeric_limits<double>::max());
    }

private:
    void insertRecursive(QuadtreeNode* node, const Point& point, int currentDepth) {
        if (currentDepth == maxDepth || node->points.size() < 4) {
            node->points.push_back(point);
        } else {
            int index = getIndex(node, point);
            if (!node->children[index]) {
                node->children[index] = new QuadtreeNode(subdivide(node, index), node->size / 2);
            }
            insertRecursive(node->children[index], point, currentDepth + 1);
        }
    }

    int getIndex(const QuadtreeNode* node, const Point& point) const {
        bool topLeft = (point.x < node->center.x && point.y < node->center.y);
        bool topRight = (point.x >= node->center.x && point.y < node->center.y);
        bool bottomLeft = (point.x < node->center.x && point.y >= node->center.y);
        return (topLeft ? 0 : (topRight ? 1 : (bottomLeft ? 2 : 3)));
    }

    Point subdivide(const QuadtreeNode* node, int index) const {
        double halfSize = node->size / 2;
        switch (index) {
            case 0: return {node->center.x - halfSize, node->center.y - halfSize};
            case 1: return {node->center.x + halfSize, node->center.y - halfSize};
            case 2: return {node->center.x - halfSize, node->center.y + halfSize};
            default: return {node->center.x + halfSize, node->center.y + halfSize};
        }
    }

    Point findNearestNeighbor(const QuadtreeNode* node, const Point& queryPoint, const Point& bestPoint, double bestDist) const {
        if (node == nullptr) return bestPoint;
        double dist = std::sqrt((queryPoint.x - node->center.x) * (queryPoint.x - node->center.x) + (queryPoint.y - node->center.y) * (queryPoint.y - node->center.y));
        if (dist < bestDist) {
            for (const auto& point : node->points) {
                double candidateDist = std::sqrt((queryPoint.x - point.x) * (queryPoint.x - point.x) + (queryPoint.y - point.y) * (queryPoint.y - point.y));
                if (candidateDist < bestDist) {
                    bestDist = candidateDist;
                    bestPoint = point;
                }
            }
        }

        for (int i = 0; i < 4; ++i) {
            Point childCenter = subdivide(node, i);
            double dx = queryPoint.x - childCenter.x;
            double dy = queryPoint.y - childCenter.y;
            double dSquared = dx * dx + dy * dy;

            if (dSquared <= bestDist * bestDist) {
                Point candidate = findNearestNeighbor(node->children[i], queryPoint, bestPoint, bestDist);
                double candidateDist = std::sqrt((queryPoint.x - candidate.x) * (queryPoint.x - candidate.x) + (queryPoint.y - candidate.y) * (queryPoint.y - candidate.y));
                if (candidateDist < bestDist) {
                    bestDist = candidateDist;
                    bestPoint = candidate;
                }
            }
        }

        return bestPoint;
    }
};

int main() {
    Quadtree qt({0.5, 0.5}, 1.0, 4);
    qt.insert({0.2, 0.3});
    qt.insert({0.7, 0.8});
    qt.insert({0.9, 0.4});

    Point queryPoint = {0.6, 0.6};
    Point nearest = qt.nearestNeighbor(queryPoint);
    std::cout << "Nearest neighbor to (" << queryPoint.x << ", " << queryPoint.y << ") is at (" << nearest.x << ", " << nearest.y << ")" << std::endl;

    return 0;
}
