#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_LENGTH 32
#define IV_LENGTH 16

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int derive_key(unsigned char *key, const unsigned char *password, size_t password_len, const unsigned char *salt, size_t salt_len) {
    if (PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, 10000, EVP_sha256(), KEY_LENGTH, key) != 1) {
        log_error("Failed to derive key using PBKDF2");
        return -1;
    }
    return 0;
}

int init_cipher(EVP_CIPHER_CTX *ctx, const unsigned char *password, size_t password_len, const unsigned char *salt, size_t salt_len, int for_encryption) {
    unsigned char key[KEY_LENGTH];
    unsigned char iv[IV_LENGTH];

    if (derive_key(key, password, password_len, salt, salt_len) != 0) {
        return -1;
    }

    if (!RAND_bytes(iv, IV_LENGTH)) {
        log_error("Failed to generate random IV");
        return -1;
    }

    if (!EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv, for_encryption ? 1 : 0)) {
        log_error("Failed to initialize cipher context");
        return -1;
    }

    return 0;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

int encrypt_data(const unsigned char *plaintext, size_t plaintext_len, const unsigned char *password, size_t password_len, const unsigned char *salt, size_t salt_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX ctx;
    int ciphertext_len;

    if (init_cipher(&ctx, password, password_len, salt, salt_len, 1) != 0) {
        return -1;
    }

    if (!EVP_EncryptUpdate(&ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) {
        log_error("Failed to encrypt data");
        cleanup_cipher(&ctx);
        return -1;
    }

    int final_len = 0;
    if (!EVP_EncryptFinal_ex(&ctx, ciphertext + ciphertext_len, &final_len)) {
        log_error("Failed to finalize encryption");
        cleanup_cipher(&ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(&ctx);

    return ciphertext_len + final_len;
}

int decrypt_data(const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *password, size_t password_len, const unsigned char *salt, size_t salt_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX ctx;
    int plaintext_len;

    if (init_cipher(&ctx, password, password_len, salt, salt_len, 0) != 0) {
        return -1;
    }

    if (!EVP_DecryptUpdate(&ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len)) {
        log_error("Failed to decrypt data");
        cleanup_cipher(&ctx);
        return -1;
    }

    int final_len = 0;
    if (!EVP_DecryptFinal_ex(&ctx, plaintext + plaintext_len, &final_len)) {
        log_error("Failed to finalize decryption");
        cleanup_cipher(&ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(&ctx);

    return plaintext_len + final_len;
}
