```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class NioClient {

    private final ConcurrentHashMap<String, AsynchronousSocketChannel> channels = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(10);

    public void connect(String host, int port) throws IOException {
        String key = host + ":" + port;
        if (channels.containsKey(key)) return;

        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open();
        channels.putIfAbsent(key, channel);
        channel.connect(new InetSocketAddress(host, port), null, new CompletionHandler<Void, Object>() {

            @Override
            public void completed(Void result, Object attachment) {
                // Connection successful
                System.out.println("Connected to " + host + ":" + port);
            }

            @Override
            public void failed(Throwable exc, Object attachment) {
                // Connection failed, retry after 5 seconds
                executor.schedule(() -> connect(host, port), 5, TimeUnit.SECONDS);
                exc.printStackTrace();
            }
        });
    }

    public void sendData(String host, int port, byte[] data) throws IOException {
        String key = host + ":" + port;
        AsynchronousSocketChannel channel = channels.get(key);
        if (channel == null) {
            throw new IOException("Not connected to " + host + ":" + port);
        }

        ByteBuffer buffer = ByteBuffer.wrap(data);
        channel.write(buffer, buffer, new CompletionHandler<Integer, ByteBuffer>() {

            @Override
            public void completed(Integer result, ByteBuffer attachment) {
                // Data sent successfully
                if (buffer.hasRemaining()) {
                    channel.write(buffer, buffer, this); // Continue sending remaining data
                } else {
                    System.out.println("Data sent: " + new String(data));
                }
            }

            @Override
            public void failed(Throwable exc, ByteBuffer attachment) {
                // Handle send failure
                exc.printStackTrace();
                try {
                    channel.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        });
    }

    public void receiveData(String host, int port, CompletionHandler<ByteBuffer, Object> handler) throws IOException {
        String key = host + ":" + port;
        AsynchronousSocketChannel channel = channels.get(key);
        if (channel == null) {
            throw new IOException("Not connected to " + host + ":" + port);
        }

        ByteBuffer buffer = ByteBuffer.allocate(1024);
        channel.read(buffer, buffer, handler);
    }
}
