#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
} Record;

void loadAndDeserialize(const char* filename, long** offsets, int** keys, Record** records, int numRecords) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    *offsets = (long*)malloc(numRecords * sizeof(long));
    *keys = (int*)malloc(numRecords * sizeof(int));
    *records = (Record*)malloc(numRecords * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        perror("Failed to allocate memory");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    // Simulate BinaryFormatter deserialization
    fread(*offsets, sizeof(long), numRecords, file);
    fread(*keys, sizeof(int), numRecords, file);

    for (int i = 0; i < numRecords; ++i) {
        (*records)[i].value = rand() % 100 + 1; // Random value between 1 and 100
    }

    fclose(file);
}
```

This code defines a `loadAndDeserialize` function that takes the filename of a binary file, pointers to arrays for offsets and keys, and a pointer to an array of records. It reads the data from the file into these arrays and initializes each record's value with a random number between 1 and 100.

