// Function to copy a specified range of bytes from a list of buffered data chunks into a new buffer
function copyBufferedData(chunks, start, end) {
  let totalLength = 0;

  // Calculate total length of all chunks
  for (let chunk of chunks) {
    totalLength += chunk.length;
  }

  // Validate start and end positions
  if (start < 0 || end > totalLength || start >= end) {
    throw new Error('Invalid range specified');
  }

  let copiedData = Buffer.alloc(end - start);
  let dataOffset = 0;

  for (let chunk of chunks) {
    if (dataOffset + chunk.length > start) { // Check if the current chunk is within the range
      let copyStart = Math.max(0, start - dataOffset); // Calculate the starting point to copy from the current chunk
      let copyEnd = Math.min(end - dataOffset, chunk.length); // Calculate the ending point for copying from the current chunk

      chunk.copy(copiedData, end - dataOffset - copyEnd, copyStart, copyEnd);
    }

    dataOffset += chunk.length;
  }

  return copiedData;
}

// Example usage
const chunks = [Buffer.from('Hello'), Buffer.from(' World'), Buffer.from('!')];
console.log(copyBufferedData(chunks, 6, 12).toString()); // Output: 'World!'
```

This code snippet defines a function `copyBufferedData` that takes a list of buffered data chunks and a range (start and end) as input. It calculates the total length of all chunks, validates the specified range, and then iterates through each chunk to copy the relevant portion into a new buffer. The function uses the `copy` method from Node.js Buffer to efficiently copy bytes between buffers. If the start or end positions are invalid, it throws an error.

