namespace SecureRandomGenerator {
    class MT19937ThreadSafe {
    public:
        static std::mt19937_64 generator;
        static void* secureSeed;

        MT19937ThreadSafe(unsigned long seed) {
            setSeed(seed);
        }

        ~MT19937ThreadSafe() {
            // Clean up resources if necessary
        }

        unsigned long nextRandom() {
            return generator();
        }

    private:
        static void hashSeed(const char* data, size_t length, unsigned char* output) {
            SHA256_CTX sha256;
            SHA256_Init(&sha256);
            SHA256_Update(&sha256, data, length);
            SHA256_Final(output, &sha256);
        }

        void setSeed(unsigned long seed) {
            unsigned char hashedSeed[SHA256_DIGEST_LENGTH];
            hashSeed(reinterpret_cast<const char*>(&seed), sizeof(seed), hashedSeed);

            // Convert the hashed seed to a 64-bit integer
            std::memcpy(&generator.seed(), hashedSeed, sizeof(std::mt19937_64::result_type));
        }
    };

    std::mt19937_64 MT19937ThreadSafe::generator;
    void* MT19937ThreadSafe::secureSeed = nullptr;
}

int main() {
    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back([i]() {
            SecureRandomGenerator::MT19937ThreadSafe rng(static_cast<unsigned long>(i));
            for (int j = 0; j < 5; ++j) {
                std::cout << "Thread " << i << ": " << rng.nextRandom() << std::endl;
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
