import java.io.*;
import java.util.*;

public class FileProcessor {

    public static void main(String[] args) {
        String filePath = "example.txt";
        String commandToExecute = "ls -l";

        try {
            // Check if file exists and delete it
            File file = new File(filePath);
            if (file.exists()) {
                if (!file.delete()) {
                    System.out.println("Failed to delete the file.");
                    return;
                }
            }

            // Write some lines to the file for demonstration
            writeLinesToFile(filePath);

            // Sort lines and get the sequence number from the last line
            List<String> sortedLines = sortFileLines(filePath);
            int sequenceNumber = extractSequenceNumber(sortedLines);
            System.out.println("Sequence Number: " + sequenceNumber);

            // Execute command and handle streams
            executeCommand(commandToExecute, filePath);

        } catch (IOException e) {
            System.err.println("An error occurred: " + e.getMessage());
        }
    }

    private static void writeLinesToFile(String filePath) throws IOException {
        BufferedWriter writer = new BufferedWriter(new FileWriter(filePath));
        writer.write("line3\n");
        writer.write("line1\n");
        writer.write("line2\n");
        writer.close();
    }

    private static List<String> sortFileLines(String filePath) throws IOException {
        List<String> lines = new ArrayList<>();
        BufferedReader reader = new BufferedReader(new FileReader(filePath));
        String line;
        while ((line = reader.readLine()) != null) {
            lines.add(line);
        }
        reader.close();
        Collections.sort(lines);
        return lines;
    }

    private static int extractSequenceNumber(List<String> sortedLines) {
        if (sortedLines.isEmpty()) {
            return -1;
        }
        String lastLine = sortedLines.get(sortedLines.size() - 1);
        // Assuming the sequence number is at the end of the line
        String[] parts = lastLine.split(" ");
        return Integer.parseInt(parts[parts.length - 1]);
    }

    private static void executeCommand(String command, String filePath) throws IOException {
        Process process = Runtime.getRuntime().exec(command, null, new File(filePath));
        BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        String line;
        System.out.println("Output:");
        while ((line = outputReader.readLine()) != null) {
            System.out.println(line);
        }

        System.err.println("Error:");
        while ((line = errorReader.readLine()) != null) {
            System.err.println(line);
        }
    }
}
