public class NIOConnectionHandler {

    private AsynchronousChannelGroup group;
    private ActiveMQConnectionFactory connectionFactory;

    public NIOConnectionHandler(int numberOfThreads, String brokerURL) throws IOException {
        this.group = AsynchronousChannelGroup.withFixedThreadPool(numberOfThreads);
        this.connectionFactory = new ActiveMQConnectionFactory(brokerURL);
    }

    public void connectAndTransferData(String remoteAddress, int port, String oauthRequestLocation)
            throws IOException, Exception {
        try (AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(group)) {
            channel.connect(new InetSocketAddress(remoteAddress, port), null,
                    new CompletionHandler<Void, Void>() {
                        @Override
                        public void completed(Void result, Void attachment) {
                            ByteBuffer buffer = ByteBuffer.allocate(1024);
                            channel.read(buffer, buffer,
                                    new CompletionHandler<Integer, ByteBuffer>() {
                                        @Override
                                        public void completed(Integer bytesRead, ByteBuffer attachment) {
                                            if (bytesRead == -1) {
                                                processMessage(attachment.array());
                                                closeChannel(channel);
                                            } else {
                                                attachment.flip();
                                                channel.write(attachment, null, this);
                                            }
                                        }

                                        @Override
                                        public void failed(Throwable exc, ByteBuffer attachment) {
                                            // Handle the failure case
                                            closeChannel(channel);
                                        }
                                    });
                        }

                        @Override
                        public void failed(Throwable exc, Void attachment) {
                            // Retry the connection logic here
                            connectAndTransferData(remoteAddress, port, oauthRequestLocation);
                        }
                    });
        } catch (IOException e) {
            handleConnectionException(e);
        }
    }

