#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <string.h>
#include <stdlib.h>

#define AES_BLOCK_SIZE 16

typedef struct {
    unsigned char *key;
    size_t key_len;
} encryption_key_t;

encryption_key_t derive_key(const char *password, size_t password_len, const char *salt, size_t salt_len) {
    // Implement key derivation using a secure hash function (e.g., SHA-256)
    // Example using OpenSSL's EVP_PKEY_CTX for bcrypt:
    EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_BCRYPT, NULL);
    EVP_PKEY_derive_init(ctx);
    EVP_PKEY_derive_set_params(ctx, password, password_len, salt, salt_len);
    EVP_PKEY_derive(ctx, &key_len, &key);
    EVP_PKEY_CTX_free(ctx);

    encryption_key_t key_info;
    key_info.key = key;
    key_info.key_len = key_len;

    return key_info;
}

void encrypt(const char *plaintext, size_t plaintext_len, const encryption_key_t *key_info, unsigned char **ciphertext, size_t *ciphertext_len) {
    // Implement AES-256-CBC encryption with a dynamically generated IV
    unsigned char iv[AES_BLOCK_SIZE];
    if (!RAND_bytes(iv, sizeof(iv))) {
        // Handle error: Failed to generate random IV
        return;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_info->key, iv);

    int len;
    EVP_EncryptUpdate(ctx, NULL, &len, plaintext, plaintext_len);
    *ciphertext_len = len;

    *ciphertext = malloc(*ciphertext_len + AES_BLOCK_SIZE);
    EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len);
    *ciphertext_len += len;

    int ciphertext_len_temp;
    EVP_EncryptFinal_ex(ctx, *ciphertext + len, &ciphertext_len_temp);
    *ciphertext_len += ciphertext_len_temp;

    EVP_CIPHER_CTX_free(ctx);

    // Store IV along with ciphertext for decryption
}

void decrypt(unsigned char *ciphertext, size_t ciphertext_len, const encryption_key_t *key_info, unsigned char **plaintext, size_t *plaintext_len) {
    // Implement AES-256-CBC decryption using the stored IV and key
    unsigned char iv[AES_BLOCK_SIZE];
    memcpy(iv, ciphertext, sizeof(iv));
    ciphertext += sizeof(iv);
    ciphertext_len -= sizeof(iv);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_info->key, iv);

    int len;
    EVP_DecryptUpdate(ctx, NULL, &len, ciphertext, ciphertext_len);
    *plaintext_len = len;

    *plaintext = malloc(*plaintext_len);
    EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len);
    *plaintext_len += len;

    int plaintext_len_temp;
    EVP_DecryptFinal_ex(ctx, *plaintext + len, &plaintext_len_temp);
    *plaintext_len += plaintext_len_temp;

    EVP_CIPHER_CTX_free(ctx);

    // Securely dispose of IV and temporary variables
}

void free_encryption_key(encryption_key_t *key_info) {
    OPENSSL_cleanse(key_info->key, key_info->key_len);
    free(key_info->key);
    key_info->key = NULL;
    key_info->key_len = 0;
}
