NFAPI_CRC_INDICATION_PDU_T* generateNfapiCrcIndications(int num_elements, int *error_code) {
    if (num_elements <= 0) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    pdu->num_elements = num_elements;
    pdu->rx_ue_info = malloc(num_elements * sizeof(RX_UE_INFORMATION_TAG));
    pdu->crc_indication = malloc(num_elements * sizeof(CRC_INDICATION_REL8_TAG));

    if (!pdu->rx_ue_info || !pdu->crc_indication) {
        free(pdu);
        *error_code = -3; // Memory allocation failed
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int tags_size;
    RX_UE_INFORMATION_TAG *tags;

    if (fetchUeTagsAndRnti(&tags, &tags_size) != 0) {
        free(pdu->rx_ue_info);
        free(pdu->crc_indication);
        free(pdu);
        *error_code = -4; // Data retrieval failed
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_elements && i < tags_size; i++) {
        pthread_mutex_lock(&mutex);
        pdu->rx_ue_info[i].rx_ue_information_tag = tags[i].rx_ue_information_tag;
        pdu->rx_ue_info[i].rnti = tags[i].rnti;
        pdu->crc_indication[i].crc_flag = (rand() % 2) == 0; // Random CRC flag
        pthread_mutex_unlock(&mutex);
    }

    free(tags);

    pthread_mutex_destroy(&mutex);

    *error_code = 0; // Success
    return pdu;
}

