import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class FileHashCalculator {

    public static String getFileSHA256(String filePath, int bufferSize) {
        MessageDigest digest = null;
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 algorithm not found", e);
        }

        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] buffer = new byte[bufferSize];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        } catch (IOException e) {
            throw new RuntimeException("Error reading file: " + filePath, e);
        }

        return bytesToHex(digest.digest());
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String filePath = "path/to/your/file"; // Replace with your file path
        int bufferSize = 8192; // 8KB buffer size

        try {
            String sha256Hash = getFileSHA256(filePath, bufferSize);
            System.out.println("SHA-256 Hash: " + sha256Hash);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

This code snippet defines a `FileHashCalculator` class with a static method `getFileSHA256` that calculates the SHA-256 hash of a file specified by its path. The method reads the file in chunks using the provided buffer size to handle large files efficiently. It uses Java's `MessageDigest` for generating the hash and handles potential exceptions such as file not found, permission errors, and I/O errors. The `bytesToHex` helper method converts the byte array produced by the digest into a hexadecimal string representation. The `main` method demonstrates how to use this class to calculate and print the SHA-256 hash of a file.

