    public CustomUserManager()
        : base(new UserStore<ApplicationUser>(new ApplicationDbContext()))
    {
        // Configure user lockout defaults
        this.DefaultAccountLockoutTimeSpan = TimeSpan.FromMinutes(5);
        this.MaxFailedAccessAttemptsBeforeLockout = 10;

        // Enable user lockout notifications
        this.UserTokenProvider = new DataProtectorTokenProvider<ApplicationUser, string>(GlobalConfiguration.Configuration.DataProtectionProvider.Create("ASP.NET Identity"));

        // Customize validation logic
        this.UserValidator = new UserValidator<ApplicationUser>(this)
        {
            AllowOnlyAlphanumericUserNames = true,
            RequireUniqueEmail = true
        };

        this.PasswordValidator = new PasswordValidator
        {
            RequiredLength = 6,
            RequireNonLetterOrDigit = true,
            RequireDigit = true,
            RequireLowercase = true,
            RequireUppercase = true
        };
    }

    // Custom validation logic for usernames and passwords
    public async override Task<IdentityResult> CreateAsync(ApplicationUser user, string password)
    {
        // Check against banned words or patterns
        if (IsBannedWord(user.UserName) || IsBannedPattern(password))
        {
            return IdentityResult.Failed("Username or password contains a banned word or pattern.");
        }

        return await base.CreateAsync(user, password);
    }

    public async override Task<IdentityResult> ChangePasswordAsync(string userId, string currentPassword, string newPassword)
    {
        // Check against banned words or patterns
        if (IsBannedWord(newPassword) || IsBannedPattern(currentPassword))
        {
            return IdentityResult.Failed("New or old password contains a banned word or pattern.");
        }

        return await base.ChangePasswordAsync(userId, currentPassword, newPassword);
    }

    private bool IsBannedWord(string text)
    {
        // List of banned words
        string[] bannedWords = { "banned", "word1", "word2" };
        foreach (var word in bannedWords)
        {
            if (text.Contains(word))
            {
                return true;
            }
        }
        return false;
    }

    private bool IsBannedPattern(string text)
    {
        // Regular expression for banned patterns
        string pattern = @"pattern|regex";
        return System.Text.RegularExpressions.Regex.IsMatch(text, pattern);
    }

    public async Task LogLockoutEventAsync(string userId, DateTimeOffset lockoutEnd)
    {
