        }
        catch (Exception ex)
        {
            // Handle potential issues such as network failures when interacting with the external logging system
            // Example: Log error to a local file or another logging mechanism
        }
    }

    public override async Task<IdentityResult> LockoutUserAsync(string userId, int lockoutSpanInMinutes)
    {
        var result = await base.LockoutUserAsync(userId, TimeSpan.FromMinutes(lockoutSpanInMinutes));

        if (result.Succeeded)
        {
            // Log the lockout event
            await LogLockoutEventAsync(userId, DateTimeOffset.UtcNow.AddMinutes(lockoutSpanInMinutes));
