```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Function declarations
void encryptFile(const char* inputFile, const char* outputFile, const char* keyFile);
void decryptFile(const char* inputFile, const char* outputFile, const char* keyFile);
int readKeyFile(const char* keyFile, unsigned char** key, int* keySize);
void writeOutputFile(const char* outputFile, const unsigned char* outputBuffer, size_t outputLength);

// Main function
int main(int argc, char* argv[]) {
    // Command-line argument parsing and error checking
    // ...

    if (strcmp(argv[1], "-e") == 0) {
        encryptFile(argv[2], argv[3], argv[4]);
    } else if (strcmp(argv[1], "-d") == 0) {
        decryptFile(argv[2], argv[3], argv[4]);
    } else {
        fprintf(stderr, "Invalid command-line arguments\n");
        return 1;
    }

    // Logging and feedback
    printf("Operation completed successfully.\n");

    return 0;
}

// Function to encrypt a file
void encryptFile(const char* inputFile, const char* outputFile, const char* keyFile) {
    unsigned char* key = NULL;
    int keySize = 0;

    if (readKeyFile(keyFile, &key, &keySize) != 0) {
        fprintf(stderr, "Failed to read key file.\n");
        return;
    }

    FILE* input = fopen(inputFile, "rb");
    if (!input) {
        perror("Error opening input file");
        free(key);
        return;
    }

    FILE* output = fopen(outputFile, "wb");
    if (!output) {
        perror("Error opening output file");
        fclose(input);
        free(key);
        return;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context.\n");
        fclose(input);
        fclose(output);
        free(key);
        return;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Encryption initialization failed.\n");
        EVP_CIPHER_CTX_free(ctx);
        fclose(input);
        fclose(output);
        free(key);
        return;
    }

    unsigned char inputBuffer[4096];
    unsigned char outputBuffer[4096 + EVP_CIPHER_block_size(EVP_aes_256_cbc())];
    int bytesRead, bytesWritten;

    while ((bytesRead = fread(inputBuffer, 1, sizeof(inputBuffer), input)) > 0) {
        if (1 != EVP_EncryptUpdate(ctx, outputBuffer, &bytesWritten, inputBuffer, bytesRead)) {
            fprintf(stderr, "Encryption update failed.\n");
            EVP_CIPHER_CTX_free(ctx);
            fclose(input);
            fclose(output);
            free(key);
            return;
        }
        fwrite(outputBuffer, 1, bytesWritten, output);
    }

    if (1 != EVP_EncryptFinal_ex(ctx, outputBuffer, &bytesWritten)) {
        fprintf(stderr, "Encryption final failed.\n");
        EVP_CIPHER_CTX_free(ctx);
        fclose(input);
        fclose(output);
        free(key);
        return;
    }
    fwrite(outputBuffer, 1, bytesWritten, output);

    EVP_CIPHER_CTX_free(ctx);
    fclose(input);
    fclose(output);
    free(key);
}

// Function to decrypt a file
void decryptFile(const char* inputFile, const char* outputFile, const char* keyFile) {
    unsigned char* key = NULL;
    int keySize = 0;

    if (readKeyFile(keyFile, &key, &keySize) != 0) {
        fprintf(stderr, "Failed to read key file.\n");
        return;
    }

    FILE* input = fopen(inputFile, "rb");
    if (!input) {
        perror("Error opening input file");
        free(key);
        return;
    }

    FILE* output = fopen(outputFile, "wb");
    if (!output) {
        perror("Error opening output file");
        fclose(input);
        free(key);
        return;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context.\n");
        fclose(input);
        fclose(output);
        free(key);
        return;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Decryption initialization failed.\n");
        EVP_CIPHER_CTX_free(ctx);
        fclose(input);
        fclose(output);
        free(key);
        return;
    }

    unsigned char inputBuffer[4096];
    unsigned char outputBuffer[4096 + EVP_CIPHER_block_size(EVP_aes_256_cbc())];
    int bytesRead, bytesWritten;

    while ((bytesRead = fread(inputBuffer, 1, sizeof(inputBuffer), input)) > 0) {
        if (1 != EVP_DecryptUpdate(ctx, outputBuffer, &bytesWritten, inputBuffer, bytesRead)) {
            fprintf(stderr, "Decryption update failed.\n");
            EVP_CIPHER_CTX_free(ctx);
            fclose(input);
            fclose(output);
            free(key);
            return;
        }
        fwrite(outputBuffer, 1, bytesWritten, output);
    }

    if (1 != EVP_DecryptFinal_ex(ctx, outputBuffer, &bytesWritten)) {
        fprintf(stderr, "Decryption final failed.\n");
        EVP_CIPHER_CTX_free(ctx);
        fclose(input);
        fclose(output);
        free(key);
        return;
    }
    fwrite(outputBuffer, 1, bytesWritten, output);

    EVP_CIPHER_CTX_free(ctx);
    fclose(input);
    fclose(output);
    free(key);
}

// Function to read a key from file
int readKeyFile(const char* keyFile, unsigned char** key, int* keySize) {
    FILE* fp = fopen(keyFile, "rb");
    if (!fp) {
        perror("Error opening key file");
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    *keySize = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    *key = (unsigned char*)malloc(*keySize);
    if (!*key) {
        perror("Memory allocation failed for key");
        fclose(fp);
        return 1;
    }

    size_t bytesRead = fread(*key, 1, *keySize, fp);
    fclose(fp);

    if (bytesRead != *keySize) {
        fprintf(stderr, "Error reading key file\n");
        free(*key);
        return 1;
    }

    return 0;
}

// Function to write output to a file
void writeOutputFile(const char* outputFile, const unsigned char* outputBuffer, size_t outputLength) {
    FILE* fp = fopen(outputFile, "wb");
    if (!fp) {
        perror("Error opening output file");
        return;
    }

    fwrite(outputBuffer, 1, outputLength, fp);
    fclose(fp);
}
