// Function to extract book names from a given text and count their occurrences.
function extractBookNames(text) {
  // Check if input is a valid string
  if (typeof text !== 'string' || text.trim() === '') {
    throw new Error('Invalid input: Please provide a non-empty string.');
  }

  // Configuration for book names including full, abbreviated, and variant spellings.
  const bookConfig = require('./book-config.json'); // Assuming external JSON configuration file
  const bookRegex = new RegExp(`\\b(${Object.keys(bookConfig).join('|')})\\b`, 'gi');

  // Object to store the count of each book name found in the text.
  let bookCount = {};

  // Extract book names using regular expressions and count their occurrences.
  let match;
  while ((match = bookRegex.exec(text)) !== null) {
    const bookName = match[0];
    if (bookCount.hasOwnProperty(bookName)) {
      bookCount[bookName]++;
    } else {
      bookCount[bookName] = 1;
    }
  }

  // Log the extracted book names and their counts.
  logBookExtractions(bookCount);

  return bookCount;
}

// Function to load book name variations from an external configuration file.
function loadBookConfig() {
  try {
    const fs = require('fs');
    const path = './book-config.json';
    return JSON.parse(fs.readFileSync(path, 'utf8'));
  } catch (error) {
    console.error('Failed to load book configuration:', error);
    return {};
  }
}

// Function to log the extracted book names and their counts.
function logBookExtractions(bookCount) {
  for (const [bookName, count] of Object.entries(bookCount)) {
    console.log(`Book: ${bookName}, Count: ${count}`);
  }
}

// Example usage:
const sampleText = "In the beginning, God created the heavens and the earth. This is from the Old Testament. In the New Testament, we read about Jesus Christ.";
try {
  const bookOccurrences = extractBookNames(sampleText);
  console.log(bookOccurrences);
} catch (error) {
  console.error(error.message);
}
