```c
#include <stdlib.h>
#include <string.h>

// Define the structs for MAC address and IP address
struct mac_address {
    unsigned char bytes[6];
};

struct ip_address {
    unsigned char bytes[4];
};

// Define the struct for network interface configuration
struct interface {
    char name[16];
    struct ip_address ip_address;
    struct mac_address mac_address;
    struct interface *next;
};

// Define the struct for router configuration
struct router {
    struct interface *interfaces;
    struct router *next;
};

// Function to create a new interface node
struct interface *create_interface(const char *name, const struct ip_address *ip, const struct mac_address *mac) {
    struct interface *new_interface = (struct interface *)malloc(sizeof(struct interface));
    if (!new_interface) return NULL;
    strcpy(new_interface->name, name);
    memcpy(&new_interface->ip_address, ip, sizeof(struct ip_address));
    memcpy(&new_interface->mac_address, mac, sizeof(struct mac_address));
    new_interface->next = NULL;
    return new_interface;
}

// Function to create a linked list of interfaces
struct router *create_router_configurations(struct interface **interfaces, int num_interfaces, struct router *router, int last_index) {
    if (last_index < 0 || last_index >= num_interfaces) return NULL;
    struct router *new_router = (struct router *)malloc(sizeof(struct router));
    if (!new_router) return NULL;
    new_router->next = NULL;

    struct interface *current_interface = interfaces[last_index];
    while (current_interface) {
        struct interface *new_node = create_interface(current_interface->name, &current_interface->ip_address, &current_interface->mac_address);
        if (!new_node) {
            // Free previously allocated nodes
            while (new_router->next) {
                struct router *temp = new_router;
                new_router = new_router->next;
                free(temp);
            }
            free(new_router);
            return NULL;
        }
        new_router->interfaces = new_node;

        if (!current_interface->next) break; // End of the list
        current_interface = current_interface->next;
    }

    if (router) {
        struct router *last_router = router;
        while (last_router->next) last_router = last_router->next;
        last_router->next = new_router;
    } else {
        router = new_router;
    }

    return router;
}

// Function to delete the entire linked list of configurations
void delete_router_configurations(struct router *router) {
    struct router *current = router;
    while (current) {
        struct router *temp = current;
        current = current->next;
        free(temp);
    }
}
```

This code snippet provides a complete implementation for creating and deleting a linked list of network interface configurations for a router. It includes functions to create new nodes, link them into a list, and clean up the memory when no longer needed.

