#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int transaction_id;
    double weight_sum;
    time_t timestamp;
} Transaction;

#define MAX_TRANSACTIONS 1000

Transaction transactions[MAX_TRANSACTIONS];
int num_transactions = 0;
int max_transactions = MAX_TRANSACTIONS;

// Function to add a new transaction
void add_transaction(int id, double weight) {
    if (num_transactions >= max_transactions) {
        printf("Error: Transaction buffer full\n");
        return;
    }

    transactions[num_transactions].transaction_id = id;
    transactions[num_transactions].weight_sum = weight;
    transactions[num_transactions].timestamp = time(NULL);
    num_transactions++;
}

// Function to filter and process transactions
int process_transactions(double *highest_weight_sum, int *num_recent_transactions) {
    time_t now = time(NULL);
    int highest_id = -1;

    for (int i = 0; i < num_transactions; i++) {
        if ((now - transactions[i].timestamp) > 60 || 
            (*num_recent_transactions >= 500 && 
             (transactions[i].timestamp == transactions[num_transactions-1].timestamp))) {
            continue;
        }

        *highest_weight_sum += transactions[i].weight_sum;

        if (transactions[i].transaction_id != highest_id || *highest_weight_sum > 1000) {
            *num_recent_transactions = 1;
            highest_id = transactions[i].transaction_id;
        } else {
            (*num_recent_transactions)++;
        }
    }

    return highest_id;
}

// Main function to simulate processing
int main() {
    srand(time(NULL));

    for (int i = 0; i < 5; i++) {
        int id = rand() % 1000 + 1;
        double weight = rand() % 100 + 1.0;

        add_transaction(id, weight);
    }

    double highest_weight_sum = 0.0;
    int num_recent_transactions = 0;

    int highest_id = process_transactions(&highest_weight_sum, &num_recent_transactions);

    printf("Highest Weight Sum: %.2f\n", highest_weight_sum);
    printf("Number of Recent Transactions: %d\n", num_recent_transactions);
    if (highest_id != -1) {
        printf("Highest ID with Weight Sum > 1000: %d\n", highest_id);
    } else {
        printf("No transactions meet the criteria.\n");
    }

    return 0;
}
