// Define the structure for CRC indication PDU
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to validate RX_UE_INFORMATION_TAG and RNTI values
int validate_rxue_information_tag(int tag) {
    // Placeholder validation logic
    if (tag < 0 || tag > 1000000) return 0; // Example range check
    return 1;
}

int validate_rnti(int rnti) {
    // Placeholder validation logic
    if (rnti <= 0 || rnti >= 65536) return 0; // Example range check for RNTI
    return 1;
}

// Function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu_list(int N, int *error_code) {
    if (N <= 0 || error_code == NULL) {
        *error_code = -1; // Invalid input error
        return NULL;
    }

    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        *error_code = -2; // Memory allocation error
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; i++) {
        int rxue_tag = rand() % 1000000;
        int rnti = rand() % 65536;

        // Validate RX_UE_INFORMATION_TAG and RNTI
        if (!validate_rxue_information_tag(rxue_tag) || !validate_rnti(rnti)) {
            *error_code = -3; // Validation error
            free(pdu_list);
            return NULL;
        }

        pdu_list[i].RX_UE_INFORMATION_TAG = rxue_tag;
        pdu_list[i].RNTI = rnti;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }

    *error_code = 0; // Success
    return pdu_list;
}

// Example usage
int main() {
    int N = 100000;
    int error_code;

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_and_populate_pdu_list(N, &error_code);
    if (pdu_list == NULL) {
        printf("Error: %d\n", error_code);
        return -1;
    }

    // Free the allocated memory
    free(pdu_list);

    return 0;
}
