```python
import os
import subprocess
from concurrent.futures import ThreadPoolExecutor
from cryptography.fernet import Fernet

class ConfigModifier:
    def __init__(self, files_list, encryption_key):
        self.files_list = files_list
        self.encryption_key = encryption_key
        self.cipher_suite = Fernet(encryption_key)

    def encrypt_value(self, value):
        try:
            return self.cipher_suite.encrypt(value.encode()).decode()
        except Exception as e:
            raise EncryptionFailure("Failed to encrypt value: " + str(e))

    def substitute_placeholders(self, content, params):
        for key, value in params.items():
            if isinstance(value, dict) and 'encrypt' in value:
                encrypted_value = self.encrypt_value(value['value'])
                content = content.replace('${' + key + '}', encrypted_value)
            else:
                content = content.replace('${' + key + '}', str(value))
        return content

    def modify_file(self, file_path, params):
        try:
            with open(file_path, 'r') as file:
                content = file.read()
            modified_content = self.substitute_placeholders(content, params)
            with open(file_path, 'w') as file:
                file.write(modified_content)
            print(f"File {file_path} modified successfully.")
        except FileNotFoundError:
            raise FileNotFound("File not found: " + file_path)

    def execute_shell_command(self, command):
        try:
            result = subprocess.run(command, shell=True, check=True, capture_output=True, text=True)
            return result.stdout
        except subprocess.CalledProcessError as e:
            raise SubprocessCommandExecutionError("Failed to execute command: " + str(e))

    def process_files(self):
        with ThreadPoolExecutor() as executor:
            for file_info in self.files_list:
                executor.submit(self.modify_file, file_info['file_path'], file_info['params'])
                if 'command' in file_info:
                    executor.submit(self.execute_shell_command, file_info['command'])

class FileNotFound(Exception):
    pass

class EncryptionFailure(Exception):
    pass

class SubprocessCommandExecutionError(Exception):
    pass

# Example usage
files_list = [
    {'file_path': '/path/to/config1.ini', 'params': {'param1': 'value1', 'password': {'value': 'my_password', 'encrypt': True}}},
    {'file_path': '/path/to/config2.ini', 'params': {'param2': 42}},
    {'file_path': '/path/to/run_script.sh', 'command': 'chmod +x /path/to/script.sh'}
]

encryption_key = Fernet.generate_key()
modifier = ConfigModifier(files_list, encryption_key)
modifier.process_files()
```
This Python script `ConfigModifier` is designed to dynamically generate and modify configuration files based on user input. It uses the `subprocess` module for executing shell commands and `concurrent.futures.ThreadPoolExecutor` for parallel processing of multiple files. The `encrypt_value` method encrypts sensitive information using a specified encryption key, ensuring that passwords are securely handled in configuration files. Custom exceptions like `FileNotFound`, `EncryptionFailure`, and `SubprocessCommandExecutionError` are raised to handle different error scenarios gracefully.

