import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.Properties;

public class FileHasher {

    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private static final Properties config = loadConfig();

    public static void main(String[] args) {
        String filePath = args[0];
        String dbConnectionString = args[1];
        int bufferSize = Integer.parseInt(args[2]);
        String hashType = args[3];

        try {
            String sha256Hash = computeFileHash(filePath, dbConnectionString, bufferSize, hashType);
            System.out.println("SHA-256 Hash: " + sha256Hash);
        } catch (IOException | NoSuchAlgorithmException | SQLException e) {
            e.printStackTrace();
        }
    }

    public static String computeFileHash(String filePath, String dbConnectionString, int bufferSize, String hashType)
            throws IOException, NoSuchAlgorithmException, SQLException {
        // Check cache
        if (config.containsKey(filePath)) {
            return config.getProperty(filePath);
        }

        InputStream inputStream = openInputStream(filePath);
        MessageDigest digest = MessageDigest.getInstance(hashType);

        byte[] buffer = new byte[bufferSize];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            digest.update(buffer, 0, bytesRead);
        }
        inputStream.close();

        String sha256Hash = bytesToHex(digest.digest());
        storeInDatabase(dbConnectionString, filePath, sha256Hash);

        // Store in cache
        config.setProperty(filePath, sha256Hash);
        saveConfig(config);

        return sha256Hash;
    }

    private static InputStream openInputStream(String filePath) throws IOException {
        if (filePath.startsWith("http") || filePath.startsWith("https")) {
            URL url = new URL(filePath);
            return Channels.newInputStream(url.openStream());
        } else {
            return new FileInputStream(filePath);
        }
    }

    private static void storeInDatabase(String dbConnectionString, String filePath, String sha256Hash)
            throws SQLException {
        try (Connection connection = DriverManager.getConnection(dbConnectionString)) {
            String sql = "INSERT INTO file_hashes (file_path, hash_value) VALUES (?, ?)";
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                statement.setString(1, filePath);
                statement.setString(2, sha256Hash);
                statement.executeUpdate();
            }
        } catch (SQLException e) {
            if (!e.getSQLState().equals("23000")) { // Ignore duplicate key errors
                throw e;
            }
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }

    private static Properties loadConfig() {
        // Load properties from file
        Properties props = new Properties();
        try (FileInputStream fis = new FileInputStream("config.properties")) {
            props.load(fis);
        } catch (IOException e) {
            e.printStackTrace();
        }
        return props;
    }

    private static void saveConfig(Properties props) {
        // Save properties to file
        try (OutputStream os = new FileOutputStream("config.properties")) {
            props.store(os, "File Hasher Configuration");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

