import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class FileHasher {
    private static final Map<String, String> cache = new HashMap<>();

    public static String getFileMD5(String filePath) throws IOException, NoSuchAlgorithmException {
        if (cache.containsKey(filePath)) {
            return cache.get(filePath);
        }

        FileInputStream fis = null;
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            fis = new FileInputStream(filePath);
            byte[] buffer = new byte[8192];
            int bytesRead;

            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }

            byte[] digest = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            String hash = sb.toString();

            cache.put(filePath, hash);
            return hash;
        } finally {
            if (fis != null) {
                fis.close();
            }
        }
    }

    public static boolean validateHashWithExternalService(String filePath, String externalHash) throws IOException, NoSuchAlgorithmException {
        String computedHash = getFileMD5(filePath);
        // Implement logic to call external service and compare hashes
        // Return true if hash matches, false otherwise
        return computedHash.equals(externalHash);
    }
}
