#include <iostream>
#include <forward_list>
#include <fstream>
#include <mutex>
#include <sstream>

// Define a structure to handle errors during file operations
struct FileError {
    std::string message;
};

class StringForwardList {
private:
    std::forward_list<std::string> list;
    mutable std::mutex mtx;

public:
    // Function to insert or append a string based on target presence
    void insertOrAppend(const std::string& target, const std::string& newStr) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = list.begin();
        while (it != list.end() && *it != target) {
            ++it;
        }
        if (it != list.end()) {
            list.insert_after(it, newStr);
        } else {
            list.push_back(newStr);
        }
    }

    // Function to merge external data source into the forward list
    void mergeExternalData(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            throw FileError{"Could not open file"};
        }

        std::lock_guard<std::mutex> lock(mtx);
        std::forward_list<std::string> newData;
        std::string line;

        while (std::getline(file, line)) {
            newData.push_front(line); // Insert at the front for efficient prepend
        }

        list.merge(newData); // Merge the new data into the main list
    }
};

int main() {
    StringForwardList sfl;
    try {
        sfl.insertOrAppend("apple", "orange");
        sfl.mergeExternalData("external_data.txt"); // Assuming this file contains strings to merge

        for (const auto& str : sfl.list) {
            std::cout << str << std::endl;
        }
    } catch (const FileError& e) {
        std::cerr << "File error: " << e.message << std::endl;
    }

    return 0;
}
