Write a C# class named `SecureDataHandler` that contains two methods: `DecryptMessage` and `ExecuteQuery`.

The `DecryptMessage` method should take a string parameter containing a Base64-encoded, encrypted message, a string key for Triple DES encryption, and a string IV (initialization vector) for decryption. It should decrypt the message using Triple DES and return the decrypted message as a string.

The `ExecuteQuery` method should take a byte array as input, send it to a database server, and return a `DataTableReader` object containing the result of the query.

Below is the implementation of the `SecureDataHandler` class:

```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class SecureDataHandler
{
    public string DecryptMessage(string encodedMessage, string key, string iv)
    {
        byte[] encryptedBytes = Convert.FromBase64String(encodedMessage);
        byte[] keyBytes = Encoding.UTF8.GetBytes(key);
        byte[] ivBytes = Encoding.UTF8.GetBytes(iv);

        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = keyBytes;
            tdes.Mode = CipherMode.CBC;
            tdes.IV = ivBytes;

            ICryptoTransform transform = tdes.CreateDecryptor();
            byte[] decryptedBytes = transform.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    public DataTableReader ExecuteQuery(byte[] inputBytes)
    {
        string connectionString = "YourConnectionStringHere";
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            SqlCommand command = new SqlCommand("SELECT * FROM YourTableName", connection);
            command.Parameters.AddWithValue("@inputParam", inputBytes);
            SqlDataAdapter adapter = new SqlDataAdapter(command);
            DataTable dataTable = new DataTable();
            adapter.Fill(dataTable);
            return dataTable.CreateDataReader();
        }
    }
}
