```java
import io.netty.handler.codec.http.websocketx.TextWebSocketFrame;
import io.netty.handler.codec.http.websocketx.WebSocketFrame;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@SpringBootApplication
public class WebSocketClientApplication {

    public static void main(String[] args) {
        SpringApplication.run(WebSocketClientApplication.class, args);
    }

    @Bean
    public WebClient webClient() {
        return WebClient.builder().build();
    }

    @Bean
    public Mono<Void> connectToMultipleServers(String[] serverEndpoints, String messageFormat) {
        return Flux.fromArray(serverEndpoints)
                .flatMap(endpoint -> connectToServer(endpoint, messageFormat))
                .then();
    }

    private Mono<Void> connectToServer(String endpoint, String messageFormat) {
        return webClient().websocket(uriBuilder -> uriBuilder.uri(endpoint).build())
                .doOnConnect(conn ->
                    conn.addHandlerLast(new WebSocketFrameHandler(messageFormat))
                        .addHandlerLast(new HeartbeatHandler()))
                .then();
    }

    private static class WebSocketFrameHandler extends io.netty.channel.ChannelInboundHandlerAdapter {
        private final String messageFormat;

        public WebSocketFrameHandler(String messageFormat) {
            this.messageFormat = messageFormat;
        }

        @Override
        public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
            if (msg instanceof WebSocketFrame) {
                WebSocketFrame frame = (WebSocketFrame) msg;
                if (frame instanceof TextWebSocketFrame) {
                    String textMessage = ((TextWebSocketFrame) frame).text();
                    System.out.println("Received message: " + textMessage);
                } else {
                    ByteBuf binaryMessage = frame.content();
                    System.out.println("Received binary message: " + binaryMessage.toString(StandardCharsets.UTF_8));
                }
            }
        }

        @Override
        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
            cause.printStackTrace();
            ctx.close();
        }
    }

    private static class HeartbeatHandler extends io.netty.channel.ChannelInboundHandlerAdapter {
        @Override
        public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
            if (evt instanceof IdleStateEvent && ((IdleStateEvent) evt).state() == IdleState.READER_IDLE) {
                ctx.writeAndFlush(new PingWebSocketFrame());
            }
        }

        @Override
        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
            cause.printStackTrace();
            ctx.close();
        }
    }
}
