```java
import java.util.concurrent.*;
import java.util.List;
import java.util.ArrayList;
import java.util.Random;
import java.lang.management.ManagementFactory;

public class ServiceManager {
    private static final int MAX_INSTANCES = 50;
    private final List<Service> instances = new ArrayList<>();
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final Random random = new Random();

    public ServiceManager(int minStartDelay, int maxStartDelay, int healthCheckInterval) {
        scheduler.scheduleAtFixedRate(this::checkHealth, 0, healthCheckInterval, TimeUnit.SECONDS);
        for (int i = 0; i < MAX_INSTANCES; i++) {
            startNewService(minStartDelay, maxStartDelay);
        }
    }

    private void startNewService(int minStartDelay, int maxStartDelay) {
        if (instances.size() >= MAX_INSTANCES) return;
        int delay = random.nextInt(maxStartDelay - minStartDelay + 1) + minStartDelay;
        executor.schedule(() -> {
            Service service = new Service();
            instances.add(service);
            service.start();
        }, delay, TimeUnit.SECONDS);
    }

    private void checkHealth() {
        List<Service> toRemove = new ArrayList<>();
        for (Service instance : instances) {
            if (!instance.isRunning()) {
                toRemove.add(instance);
                try {
                    sendStopMessage(instance.getId());
                } catch (NetworkException e) {
                    System.err.println("Failed to send stop message: " + e.getMessage());
                }
            }
        }
        instances.removeAll(toRemove);
    }

    private void sendStopMessage(String serviceId) throws NetworkException {
        // Simulate sending a message
        if (random.nextBoolean()) {
            throw new NetworkException("Network error occurred");
        }
        System.out.println("Stop message sent for service: " + serviceId);
    }

    public static void main(String[] args) {
        int minStartDelay = 5;
        int maxStartDelay = 10;
        int healthCheckInterval = 60;
        if (args.length >= 3) {
            minStartDelay = Integer.parseInt(args[0]);
            maxStartDelay = Integer.parseInt(args[1]);
            healthCheckInterval = Integer.parseInt(args[2]);
        }
        new ServiceManager(minStartDelay, maxStartDelay, healthCheckInterval);
    }

    private static class Service implements Runnable {
        private boolean running;
        private final String id = ManagementFactory.getRuntimeMXBean().getName();

        public void start() {
            running = true;
            executor.execute(this);
        }

        @Override
        public void run() {
            while (running) {
                // Simulate service work
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        public boolean isRunning() {
            return running;
        }

        public String getId() {
            return id;
        }

        public void stop() {
            running = false;
        }
    }

    private static class NetworkException extends Exception {
        public NetworkException(String message) {
            super(message);
        }
    }
}
