def run_module_tests(test_functions, label=None):
    import sys
    import traceback

    def run_test(func, test_data):
        print(f"Starting test: {test_data['name']}")
        try:
            func(test_data)
            result = 'passed'
        except AssertionError as e:
            result = 'failed'
            if label:
                print(f"{label}: ", end='')
            traceback.print_exc(file=sys.stdout)
        finally:
            print(f"Test {test_data['name']} {result}.")
        return result

    for func in test_functions:
        func_name = func.__name__
        test_data_for_func = [d for d in test_data if func_name in d.get('func_names', [])]
        for td in test_data_for_func:
            run_test(func, td)

# Example usage
def sample_test_function_1(test_data):
    try:
        result = my_module_function(test_data['input'])
        assert result == test_data['expected_output']
    except AssertionError:
        pass

def sample_test_function_2(test_data):
    try:
        result = another_module_function(test_data['input'])
        assert result == test_data['expected_output']
    except AssertionError:
        pass

test_data = [
    {'name': 'test_sample_func_1', 'input': 5, 'expected_output': 10},
    {'name': 'test_sample_func_2', 'input': 'hello', 'expected_output': 'world'}
]

run_module_tests([sample_test_function_1, sample_test_function_2], label='Sample Module')
