```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class GraphRandomizer
{
    private Dictionary<int, Vertex> vertices = new Dictionary<int, Vertex>();
    private List<Edge> edges = new List<Edge>();

    public void AddVertex(int id, float x, float y)
    {
        if (vertices.ContainsKey(id))
        {
            throw new ArgumentException("Vertex with the same ID already exists.");
        }
        vertices[id] = new Vertex { Id = id, X = x, Y = y };
    }

    public void AddEdge(int fromId, int toId, float weight)
    {
        if (!vertices.ContainsKey(fromId) || !vertices.ContainsKey(toId))
        {
            throw new ArgumentException("Invalid vertex IDs.");
        }
        if (fromId == toId)
        {
            throw new ArgumentException("Self-loop is not allowed.");
        }
        edges.Add(new Edge { FromId = fromId, ToId = toId, Weight = weight });
    }

    public float GenerateRandomFloat(float min, float max, bool inclusive = true)
    {
        if (min >= max)
        {
            throw new ArgumentException("Min value must be less than max value.");
        }
        return inclusive ? UnityEngine.Random.Range(min, max + 1) : UnityEngine.Random.Range(min, max);
    }

    public int GenerateRandomInt(int min, int max, bool inclusive = true)
    {
        if (min >= max)
        {
            throw new ArgumentException("Min value must be less than max value.");
        }
        return inclusive ? UnityEngine.Random.Range(min, max + 1) : UnityEngine.Random.Range(min, max);
    }

    public void ValidateGraph()
    {
        HashSet<int> visited = new HashSet<int>();
        foreach (var edge in edges)
        {
            if (!visited.Contains(edge.FromId))
            {
                visited.Add(edge.FromId);
                continue;
            }
            throw new InvalidOperationException("Duplicate edge detected.");
        }
    }

    // Additional methods for advanced functionalities like custom distributions, external system integration, etc.
}

public class Vertex
{
    public int Id { get; set; }
    public float X { get; set; }
    public float Y { get; set; }
    // Other properties and methods
}

public class Edge
{
    public int FromId { get; set; }
    public int ToId { get; set; }
    public float Weight { get; set; }
    // Other properties and methods
}
