use std::env;
use std::fs::{create_dir_all, remove_file};
use std::io::{self, Write};
use std::path::PathBuf;
use simplelog::{ConfigBuilder, LevelFilter, SimpleLogger};

#[derive(Debug)]
enum Error {
    EnvVarError(env::VarError),
    IoError(io::Error),
}

fn init_logging(log_dir: &str, log_file_name: &str, append: bool) -> Result<(), Error> {
    let mut log_path = PathBuf::from(log_dir);
    if !log_path.exists() || !log_path.is_dir() {
        create_dir_all(&log_path).map_err(|e| Error::IoError(e))?;
    }

    if !env::var_os("LOG_DIR").is_some() {
        env::set_var("LOG_DIR", &log_path);
    }

    log_path.push(log_file_name);
    let log_path_str = log_path.to_string_lossy();

    let config = ConfigBuilder::new()
        .set_time_format_str("%Y-%m-%d %H:%M:%S")
        .build();
    SimpleLogger::init(LevelFilter::Debug, config).map_err(|e| Error::IoError(e))?;

    let file_mode = if append {
        OpenOptions::new().write(true).append(true).create(true)
    } else {
        OpenOptions::new().write(true).truncate(true).create(true)
    };

    let mut file = file_mode.open(&log_path_str).map_err(|e| Error::IoError(e))?;
    writeln!(file, "Logging initialized at {}.", log_path_str)?;

    Ok(())
}

fn cleanup_logging() -> Result<(), io::Error> {
    if let Some(log_dir) = env::var_os("LOG_DIR") {
        let log_dir_path = PathBuf::from(log_dir);
        for entry in std::fs::read_dir(&log_dir_path)? {
            let entry = entry?;
            let path = entry.path();
            if path.is_file() {
                remove_file(path)?;
            }
        }
    }

    Ok(())
}

fn main() -> Result<(), Error> {
    init_logging("logs", "app.log", true)?;

    // Your application code here

    cleanup_logging()?;
    Ok(())
}
