#include <cstring>

struct Employee {
    int id;
    char* name;
    float salary;
};

class EmployeeManager {
public:
    EmployeeManager(const std::vector<int>& ids, const std::vector<std::string>& names, const std::vector<float>& salaries) {
        if (ids.size() != names.size() || ids.size() != salaries.size()) {
            throw std::invalid_argument("All input vectors must have the same size.");
        }

        numEmployees = ids.size();
        employees = new Employee[numEmployees];

        for (size_t i = 0; i < numEmployees; ++i) {
            employees[i].id = ids[i];
            employees[i].name = new char[names[i].length() + 1];
            std::strcpy(employees[i].name, names[i].c_str());
            employees[i].salary = salaries[i];
        }
    }

    ~EmployeeManager() {
        for (size_t i = 0; i < numEmployees; ++i) {
            delete[] employees[i].name;
        }
        delete[] employees;
    }

private:
    size_t numEmployees;
    Employee* employees;
};

int main() {
    std::vector<int> ids = {1, 2, 3};
    std::vector<std::string> names = {"John Doe", "Jane Smith", "Alice Johnson"};
    std::vector<float> salaries = {50000.5f, 60000.75f, 55000.0f};

    try {
        EmployeeManager manager(ids, names, salaries);
        // Use the manager object to access employee records
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
