```python
from flask import Flask, request, jsonify
import hmac
import hashlib
import json
from functools import lru_cache

app = Flask(__name__)

SECRET_TOKEN = "your_secret_token_here"

def validate_signature(request):
    signature = request.headers.get("X-Hub-Signature")
    payload = request.data.decode("utf-8")
    expected_signature = "sha1=" + hmac.new(SECRET_TOKEN.encode("utf-8"), payload.encode("utf-8"), hashlib.sha1).hexdigest()
    return hmac.compare_digest(signature, expected_signature)

@lru_cache(maxsize=128)
def get_handler(event_type):
    if event_type == "event1":
        return handle_event1
    elif event_type == "event2":
        return handle_event2
    else:
        raise ValueError("Unknown event type")

@app.route("/webhook", methods=["POST"])
def webhook():
    log_request(request)
    if not validate_signature(request):
        app.logger.error("Invalid signature")
        return jsonify({"error": "Invalid signature"}), 403

    try:
        payload = json.loads(request.data.decode("utf-8"))
    except json.JSONDecodeError as e:
        app.logger.error("Malformed JSON: %s", str(e))
        return jsonify({"error": "Malformed JSON"}), 400

    event_type = payload.get("event_type")
    if not event_type:
        app.logger.error("Missing event type in payload")
        return jsonify({"error": "Missing event type"}), 400

    try:
        handler = get_handler(event_type)
        response = handler(payload)
        log_response(response)
        return jsonify(response), 200
    except ValueError as e:
        app.logger.error("Invalid event type: %s", str(e))
        return jsonify({"error": "Invalid event type"}), 400

def handle_event1(payload):
    # Implement handler for event_type = "event1"
    pass

def handle_event2(payload):
    # Implement handler for event_type = "event2"
    pass

def log_request(request):
    app.logger.info("Received request: %s", str(request))

def log_response(response):
    app.logger.info("Response sent: %s", str(response))
```

This code defines a Flask application with one route `/webhook` that handles POST requests. It validates the signature of the incoming request using `validate_signature()` function and parses the JSON payload using `json.loads()`. Then it routes the request to the appropriate handler function based on the event type specified in the payload using `get_handler()` decorator, which implements caching for frequently requested events. 

The handlers `handle_event1` and `handle_event2` should be implemented as per the requirement of each event type. Error handling is done using try-except blocks to catch any exceptions raised by the handler functions or during parsing of the JSON payload. Logging is done using Flask's built-in logger.

```cpp
#include <iostream>
#include <forward_list>
#include <string>
#include <mutex>
#include <condition_variable>

class PageService {
public:
    bool updateElementHtml(const std::string& sectionId, const std::string& elementId, const std::string& htmlContent) {
        // Simulate asynchronous HTML update
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        return true; // Return true on successful update
    }
};

class WebPageHandler {
private:
    PageService pageService;
    std::mutex forwardListMutex;
    std::condition_variable cv;

public:
    enum class ResponseCode { OK, NOT_FOUND, ERROR };

    ResponseCode handlePostRequest(std::forward_list<std::string>& pageContent,
                                  const std::string& sectionId,
                                  const std::string& elementId,
                                  const std::string& htmlContent) {
        std::unique_lock<std::mutex> lock(forwardListMutex);
        auto it = std::find(pageContent.begin(), pageContent.end(), sectionId);

        if (it == pageContent.end()) {
            pageContent.push_back(htmlContent);
        } else {
            ++it;
            pageContent.insert(it, htmlContent);
        }

        cv.notify_one();

        // Simulate error handling
        bool updateSuccess = pageService.updateElementHtml(sectionId, elementId, htmlContent);
        if (!updateSuccess) {
            return ResponseCode::ERROR;
        }

        return ResponseCode::OK;
    }
};

int main() {
    WebPageHandler handler;
    std::forward_list<std::string> pageContent = {"Section1", "Content1", "Section2", "Content2"};
    std::string sectionId = "Section1";
    std::string elementId = "Element1";
    std::string htmlContent = "<div>New HTML Content</div>";

    auto response = handler.handlePostRequest(pageContent, sectionId, elementId, htmlContent);

    switch (response) {
        case WebPageHandler::ResponseCode::OK:
            std::cout << "Page should be refreshed." << std::endl;
            break;
        case WebPageHandler::ResponseCode::NOT_FOUND:
            std::cout << "Section ID not found." << std::endl;
            break;
        case WebPageHandler::ResponseCode::ERROR:
            std::cout << "Failed to update element HTML." << std::endl;
            break;
    }

    return 0;
}
