package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
)

type WebhookRequest struct {
	Event string `json:"event"`
	Data  map[string]interface{} `json:"data"`
}

func main() {
	r := gin.Default()

	kubeConfig, err := rest.InClusterConfig()
	if err != nil {
		panic(err.Error())
	}
	clientset, err := kubernetes.NewForConfig(kubeConfig)
	if err != nil {
		panic(err.Error())
	}

	r.POST("/webhook", func(c *gin.Context) {
		var req WebhookRequest
		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid JSON"})
			return
		}

		validated := validateSignature(req, "provider-secret-token")
		if !validated {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "HMAC signature validation failed"})
			return
		}

		routeToBackendServices(c, req)
	})

	r.Run(":8080")
}

func validateSignature(req WebhookRequest, secret string) bool {
	message := []byte(fmt.Sprintf("%s\n%s", req.Event, json.dumps(req.Data)))
	expectedMAC := hmac.New(sha256.New, []byte(secret))
	expectedMAC.Write(message)

	signatureHeader := c.GetHeader("X-Hmac-SHA256")
	signature, err := base64.StdEncoding.DecodeString(signatureHeader)
	if err != nil {
		return false
	}

	if !hmac.Equal(expectedMAC.Sum(nil), signature) {
		return false
	}
	return true
}

func routeToBackendServices(c *gin.Context, req WebhookRequest) {
	switch req.Event {
	case "event-type-1":
		handleEventType1(req.Data)
	case "event-type-2":
		handleEventType2(req.Data)
	default:
		c.JSON(http.StatusBadRequest, gin.H{"error": "Unknown event type"})
	}
}

func handleEventType1(data map[string]interface{}) {
	// Code to handle event type 1
}

func handleEventType2(data map[string]interface{}) {
	// Code to handle event type 2
}
```

