#include <iostream>
#include <cstdlib>
#include <sys/types.h>
#include <sys/wait.h>

int initializeOctree(int featureSize, int numLeafNodes, int dataCapacity) {
    pid_t pid = fork();
    if (pid == -1) {
        std::cerr << "Fork failed" << std::endl;
        return 0;
    } else if (pid == 0) {
        // Child process
        char* command = new char[256];
        snprintf(command, 256, "command_to_run_%d", featureSize);
        execl("/bin/sh", "sh", "-c", command, NULL);
        delete[] command;
        exit(1);
    } else {
        // Parent process
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            std::cerr << "Wait failed" << std::endl;
            return 0;
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            std::cerr << "Command execution failed" << std::endl;
            return 0;
        }

        // Initialize octree
        OctreeNode** octree = new OctreeNode*[numLeafNodes];
        for (int i = 0; i < numLeafNodes; ++i) {
            octree[i] = new OctreeNode();
        }
        if (!octree) {
            std::cerr << "Failed to allocate memory for octree" << std::endl;
            return 0;
        }

        int* prefixLeafs = new int[dataCapacity];
        char** data = new char*[dataCapacity];
        for (int i = 0; i < dataCapacity; ++i) {
            data[i] = new char[featureSize * featureSize];
        }
        if (!prefixLeafs || !data) {
            std::cerr << "Failed to allocate memory for arrays" << std::endl;
            delete[] octree;
            for (int i = 0; i < numLeafNodes; ++i) {
                delete octree[i];
            }
            delete[] prefixLeafs;
            for (int i = 0; i < dataCapacity; ++i) {
                delete[] data[i];
            }
            return 0;
        }

        // Initialize octree capacity
        Octree::capacity_ = dataCapacity;

        // Update octree with prefix leafs and data
        for (int i = 0; i < numLeafNodes; ++i) {
            octree[i]->prefixLeaf = prefixLeafs[i % dataCapacity];
            memcpy(octree[i]->data, data[i % dataCapacity], featureSize * featureSize);
        }

        delete[] octree;
        for (int i = 0; i < numLeafNodes; ++i) {
            delete octree[i];
        }
        delete[] prefixLeafs;
        for (int i = 0; i < dataCapacity; ++i) {
            delete[] data[i];
        }

        return 1;
    }
}
