// Import necessary libraries
const WebSocket = require('ws');
const mqtt = require('mqtt');

// Define the aggregation function using reduce()
function aggregateReadings(readings, timeWindow) {
  return readings.reduce((acc, reading) => {
    const timestamp = new Date(reading.timestamp);
    const key = `${reading.deviceID}-${Math.floor(timestamp / (timeWindow * 60 * 1000))}`;
    if (!acc[key]) {
      acc[key] = { deviceID: reading.deviceID, time: timestamp, readings: [] };
    }
    acc[key].readings.push(reading.value);
    return acc;
  }, {});
}

// Define a function to handle WebSocket connections
function handleWebSocket(deviceID, socket) {
  let buffer = [];
  socket.on('message', (data) => {
    const reading = JSON.parse(data);
    reading.deviceID = deviceID;
    buffer.push(reading);
    aggregateBuffer(buffer);
  });
  socket.on('close', () => {
    console.log(`Device ${deviceID} disconnected.`);
  });
}

// Define a function to handle MQTT connections
function handleMQTT(deviceID, client) {
  client.on('message', (topic, message) => {
    const reading = JSON.parse(message.toString());
    reading.deviceID = deviceID;
    aggregateBuffer([reading]);
  });
  client.on('end', () => {
    console.log(`Device ${deviceID} disconnected.`);
  });
}

// Define a function to aggregate readings from a buffer
function aggregateBuffer(buffer) {
  if (buffer.length > 0) {
    const aggregated = aggregateReadings(buffer, 300); // Aggregate every 5 minutes
    console.log('Aggregated Readings:', aggregated);
    buffer = []; // Clear the buffer after aggregation
  }
}

// Set up WebSocket server to receive data from IoT devices
const wsServer = new WebSocket.Server({ port: 8080 });
wsServer.on('connection', (socket) => {
  let deviceID;
  socket.on('message', (data) => {
    if (!deviceID) {
      deviceID = JSON.parse(data).deviceID;
      console.log(`Device ${deviceID} connected.`);
    }
    handleWebSocket(deviceID, socket);
  });
});

// Set up MQTT client to receive data from IoT devices
const mqttClient = mqtt.connect('mqtt://broker.hivemq.com');
mqttClient.on('connect', () => {
  mqttClient.subscribe('iot/device/+/readings');
});
mqttClient.on('message', (topic, message) => {
  const deviceID = topic.split('/')[2];
  handleMQTT(deviceID, mqttClient);
});

// Example usage
const sensorReadings = [
  { timestamp: '2023-04-01T12:00:00Z', deviceID: 'device1', value: 25 },
  { timestamp: '2023-04-01T12:05:00Z', deviceID: 'device1', value: 26 },
  { timestamp: '2023-04-01T12:00:00Z', deviceID: 'device2', value: 68 }
];
const aggregated = aggregateReadings(sensorReadings, 300);
console.log('Initial Aggregation:', aggregated);
