#include <iostream>
#include <vector>
#include <unordered_map>
#include <cmath>
#include <map>

class SpatialHashGrid {
public:
    struct Point {
        double x, y;
        Point(double _x = 0, double _y = 0) : x(_x), y(_y) {}
    };

    struct GridCell {
        std::vector<Point> points;
    };

    using Grid = std::unordered_map<int, std::unordered_map<int, GridCell>>;

    SpatialHashGrid(double cellSize, const std::map<double, double>& apiData)
        : cellSize(cellSize), grid() {
        for (const auto& [latitude, longitude] : apiData) {
            insert(Point(longitude, latitude));
        }
    }

    ~SpatialHashGrid() {}

    void insert(const Point& point) {
        int xCell = static_cast<int>(point.x / cellSize);
        int yCell = static_cast<int>(point.y / cellSize);
        grid[xCell][yCell].points.push_back(point);
    }

    void remove(const Point& point) {
        int xCell = static_cast<int>(point.x / cellSize);
        int yCell = static_cast<int>(point.y / cellSize);
        auto& cell = grid[xCell][yCell];
        cell.points.erase(std::remove(cell.points.begin(), cell.points.end(), point), cell.points.end());
    }

    std::vector<Point> queryClosestN(const Point& queryPoint, int N) {
        std::vector<std::pair<int, int>> neighbors;
        neighbors.push_back({static_cast<int>(queryPoint.x / cellSize), static_cast<int>(queryPoint.y / cellSize)});
        if (neighbors[0].first > 0) neighbors.push_back({neighbors[0].first - 1, neighbors[0].second});
        if (neighbors[0].first < grid.size() - 1) neighbors.push_back({neighbors[0].first + 1, neighbors[0].second});
        if (neighbors[0].second > 0) neighbors.push_back({neighbors[0].first, neighbors[0].second - 1});
        if (neighbors[0].second < grid[0].size() - 1) neighbors.push_back({neighbors[0].first, neighbors[0].second + 1});

        std::vector<Point> closestPoints;
        for (const auto& [xCell, yCell] : neighbors) {
            const auto& cell = grid[xCell][yCell];
            for (const auto& point : cell.points) {
                closestPoints.push_back(point);
            }
        }

        std::sort(closestPoints.begin(), closestPoints.end(), [&](const Point& a, const Point& b) {
            return distance(queryPoint, a) < distance(queryPoint, b);
        });

        if (closestPoints.size() > N) closestPoints.resize(N);

        return closestPoints;
    }

private:
    double cellSize;
    Grid grid;

    int hash(double value) {
        return static_cast<int>(value / cellSize);
    }

    double distance(const Point& a, const Point& b) {
        return std::sqrt(std::pow(a.x - b.x, 2) + std::pow(a.y - b.y, 2));
    }
};

int main() {
    std::map<double, double> apiData = {{37.4219983739726, -122.084}, {37.4219983739726, -122.085}};
    SpatialHashGrid grid(0.1, apiData);

    grid.insert({-122.0845, 37.4219});
    grid.remove({-122.084, 37.4219});

    auto closestPoints = grid.queryClosestN({-122.084, 37.4219}, 3);
    for (const auto& point : closestPoints) {
        std::cout << "(" << point.x << ", " << point.y << ")" << std::endl;
    }

    return 0;
}
