// Function to encrypt data using AES-256-GCM
int encrypt_data(const unsigned char *key, const unsigned char *data, size_t data_len, unsigned char *iv, unsigned char *ciphertext, unsigned char *tag) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return 0;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv) != 1 ||
        EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, data, data_len) != 1 ||
        EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &tag_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, tag_len, tag) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len + tag_len;
}

// Function to decrypt data using AES-256-GCM
int decrypt_data(const unsigned char *key, const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *iv, const unsigned char *tag) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return 0;

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv) != 1 ||
        EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len - tag_len) != 1 ||
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, tag_len, (unsigned char *)tag) != 1 ||
        EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &final_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

