public class DynamicSqlExecutor
{
    public static IDataReader ExecuteDynamicQuery(List<KeyValuePair<string, object>> parameters, SqlConnection connection, string templateCommand)
    {
        if (connection == null || string.IsNullOrEmpty(templateCommand))
            throw new ArgumentException("Invalid input parameters.");

        try
        {
            SqlCommand command = new SqlCommand(templateCommand, connection);
            foreach (var param in parameters)
            {
                // Validate and sanitize input parameters to prevent SQL injection
                var safeParamValue = SqlHelper.EscapeString(param.Value.ToString());
                command.Parameters.AddWithValue($"@{param.Key}", safeParamValue);
            }

            connection.Open();
            return command.ExecuteReader(CommandBehavior.CloseConnection);
        }
        catch (Exception ex)
        {
            // Log the exception with meaningful feedback
            Console.WriteLine($"An error occurred: {ex.Message}");
            throw;
        }
    }
}

public static class SqlHelper
{
    public static string EscapeString(string input)
    {
        if (string.IsNullOrEmpty(input))
            return input;

        // Implement a simple escaping mechanism for demonstration purposes
        // In a real-world scenario, use parameterized queries or a library designed to handle SQL injection
        input = input.Replace("'", "''");
        return input;
    }
}
