#include <iostream>
#include <forward_list>
#include <string>
#include <mutex>
#include <stdexcept>

class ForwardListManager {
public:
    void insertAfterOrAppend(const std::string& target, const std::string& newStr) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = forwardList_.begin();
        while (it != forwardList_.end()) {
            if (*it == target) {
                forwardList_.emplace_after(it, newStr);
                return;
            }
            ++it;
        }
        forwardList_.push_back(newStr);
    }

    void merge(const std::forward_list<std::string>& externalData) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& str : externalData) {
            insertAfterOrAppend(str, "merged");
        }
    }

    void removeAndFreeMemory() {
        std::lock_guard<std::mutex> lock(mutex_);
        forwardList_.clear();
    }

    void handleMalformedDataSource(const std::string& message) {
        throw std::runtime_error("Malformed data source: " + message);
    }

private:
    std::forward_list<std::string> forwardList_;
    std::mutex mutex_;
};

int main() {
    ForwardListManager manager;
    manager.merge({"apple", "banana", "cherry"});
    manager.insertAfterOrAppend("banana", "grape");
    manager.removeAndFreeMemory();
    try {
        manager.handleMalformedDataSource("Invalid format");
    } catch (const std::runtime_error& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
