#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <string.h>
#include <stdlib.h>

#define MIN_PASSWORD_LEN 8
#define MAX_PASSWORD_LEN 128
#define MIN_SALT_LEN 16
#define MAX_SALT_LEN 32

int initialize_aes_cbc(const char *password, int password_len, const char *salt, int salt_len,
                        unsigned char **key, unsigned char **iv) {
    if (password_len < MIN_PASSWORD_LEN || password_len > MAX_PASSWORD_LEN ||
        salt_len < MIN_SALT_LEN || salt_len > MAX_SALT_LEN) {
        fprintf(stderr, "Error: Password and salt must be within specified lengths.\n");
        return -1;
    }

    // Derive key using PBKDF2
    unsigned char derived_key[EVP_MAX_KEY_LENGTH];
    int derived_key_len = EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL);
    if (derived_key_len <= 0) {
        fprintf(stderr, "Error: Failed to create HMAC context.\n");
        return -1;
    }

    EVP_PKEY_CTX_set_hmac_key(derived_key_ctx, password, password_len);
    EVP_PKEY_CTX_set_hmac_length(derived_key_ctx, EVP_MAX_KEY_LENGTH);

    if (EVP_PKEY_derive(derived_key_ctx, derived_key, &derived_key_len) <= 0) {
        fprintf(stderr, "Error: Failed to derive key using HMAC.\n");
        return -1;
    }

    *key = malloc(EVP_MAX_KEY_LENGTH);
    memcpy(*key, derived_key, EVP_MAX_KEY_LENGTH);

    // Generate random IV
    if (RAND_bytes(*iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc())) != 1) {
        fprintf(stderr, "Error: Failed to generate random IV.\n");
        return -1;
    }

    return 0;
}

void cleanup(unsigned char *key, unsigned char *iv) {
    if (key) free(key);
    if (iv) free(iv);
}
