use hyper::{Client, Request, Method, Uri};
use hyper_tls::HttpsConnector;
use tokio::time::{Duration, Instant};
use std::collections::HashMap;
use log::{info, error};

#[derive(Debug)]
enum HttpError {
    Hyper(hyper::Error),
    RateLimit,
}

impl From<hyper::Error> for HttpError {
    fn from(e: hyper::Error) -> Self {
        HttpError::Hyper(e)
    }
}

struct RateLimiter {
    limit: u32,
    per_minute: Duration,
    last_reset: Instant,
    requests: HashMap<String, u32>,
}

impl RateLimiter {
    fn new(limit: u32, per_minute: Duration) -> Self {
        RateLimiter {
            limit,
            per_minute,
            last_reset: Instant::now(),
            requests: HashMap::new(),
        }
    }

    async fn check_and_record_request(&mut self, url: &str) -> Result<(), HttpError> {
        if self.requests.len() >= self.limit as usize {
            let now = Instant::now();
            if now - self.last_reset < self.per_minute {
                error!("Rate limit exceeded for URL: {}", url);
                return Err(HttpError::RateLimit);
            }
            self.requests.clear();
            self.last_reset = now;
        }

        let count = self.requests.entry(url.to_string()).or_insert(0);
        *count += 1;

        Ok(())
    }
}

async fn create_request_builder(
    url: &str,
    method: Method,
    headers: Option<HashMap<String, String>>,
    disable_certificate_validation: bool,
) -> Result<RequestBuilder, HttpError> {
    let https = HttpsConnector::new();
    let client = Client::builder().build(https);

    let mut req_builder = Request::builder()
        .method(method)
        .uri(url.parse::<Uri>()?);

    if let Some(headers) = headers {
        for (key, value) in headers {
            req_builder = req_builder.header(key, value);
        }
    }

    let request_url = url.to_string();
    let mut rate_limiter = RateLimiter::new(100, Duration::from_secs(60));

    if disable_certificate_validation {
        // Assuming a way to disable SSL verification is needed
        // This part depends on the specific implementation of hyper and its features
        unimplemented!()
    }

    rate_limiter.check_and_record_request(&request_url).await?;

    Ok(req_builder)
}

// Example usage:
#[tokio::main]
async fn main() {
    let url = "https://example.com/api";
    let method = Method::GET;
    let mut headers = HashMap::new();
    headers.insert("User-Agent".to_string(), "MyApp/1.0".to_string());

    match create_request_builder(url, method, Some(headers), false).await {
        Ok(req_builder) => info!("Request builder created successfully"),
        Err(e) => error!("Failed to create request builder: {:?}", e),
    }
}
