```python
import re
from datetime import datetime
from typing import List
import threading
import queue
import requests

def process_log_file(file_path: str, api_key: str) -> None:
    def read_lines():
        with open(file_path, 'r') as file:
            while True:
                chunk = file.read(1024)
                if not chunk:
                    break
                yield chunk.split('\n')

    def parse_line(line):
        pattern = r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) (\d+) (.*)'
        match = re.match(pattern, line)
        if match:
            return datetime.strptime(match.group(1), '%Y-%m-%d %H:%M:%S'), int(match.group(2)), match.group(3)
        return None

    def send_to_api(data):
        url = 'https://example.com/log'
        headers = {'Authorization': f'Bearer {api_key}', 'Content-Type': 'application/json'}
        response = requests.post(url, json=data, headers=headers)
        if response.status_code != 200:
            raise Exception(f"Failed to send data: {response.text}")

    def process_queue(q):
        max_sequence = None
        line_count = 0
        while True:
            chunk = q.get()
            for line in chunk:
                parsed_line = parse_line(line)
                if parsed_line:
                    line_count += 1
                    max_sequence = max(max_sequence, parsed_line[1]) if max_sequence is not None else parsed_line[1]
            q.task_done()

    q = queue.Queue()
    reader_thread = threading.Thread(target=lambda: [q.put(chunk) for chunk in read_lines()], daemon=True)
    processor_thread = threading.Thread(target=process_queue, args=(q,), daemon=True)

    reader_thread.start()
    processor_thread.start()

    reader_thread.join()
    q.join()
    processor_thread.join()

    summary_data = {
        'max_sequence': max_sequence,
        'total_lines': line_count
    }
    try:
        send_to_api(summary_data)
        print("Data sent successfully to the API.")
    except Exception as e:
        print(f"Failed to send data: {e}")

# Example usage:
# process_log_file('example.log', 'your_api_key_here')
```

