const { exec } = require('child_process');
const LRU = require('lru-cache');

// Constants
const CACHE_SIZE = 50;
const PAGE_SIZE = 10;

// Caching mechanism using LRU Cache
const cache = new LRU({ max: CACHE_SIZE });

// Function to execute shell command and handle errors
function executeCommand(command) {
    return new Promise((resolve, reject) => {
        exec(command, (error, stdout, stderr) => {
            if (error) {
                console.error(`Error executing command: ${command}`);
                reject(new Error(stderr));
            } else {
                resolve(stdout);
            }
        });
    });
}

// Function to paginate results
function paginateResults(results, page = 1) {
    const startIndex = (page - 1) * PAGE_SIZE;
    const endIndex = startIndex + PAGE_SIZE;
    return results.slice(startIndex, endIndex);
}

// Main function to execute command, cache result, and handle pagination
async function runCommand(command, page = 1) {
    try {
        // Check if result is in cache
        const cachedResult = cache.get(command);
        if (cachedResult) {
            console.log(`Cache hit for: ${command}`);
            return paginateResults(cachedResult, page);
        }

        // Execute command and store result in cache
        const result = await executeCommand(command);
        console.log(`Cache miss for: ${command}`);
        cache.set(command, result);

        return paginateResults(result, page);
    } catch (error) {
        console.error(`Error handling command: ${command}`);
        return `Error executing command: ${command}`;
    }
}

// Example usage
const command = 'ls -la'; // Replace with the desired shell command
runCommand(command, 1).then(console.log).catch(console.error);
```

This code provides a modular and efficient solution for executing a shell command using a child process, caching the results, and paginating the output. It also includes error handling, logging, and real-time update support.

