```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char timestamp[MAX_LINE_LENGTH];
    long packet_size;
} NetworkRecord;

double calculate_moving_average(NetworkRecord* records, int count, int window) {
    if (count < window) return -1; // Not enough data for average
    double sum = 0.0;
    for (int i = count - window; i < count; i++) {
        sum += records[i].packet_size;
    }
    return sum / window;
}

void process_log_file(const char* input_path, const char* output_path, int time_window) {
    FILE* input_file = fopen(input_path, "r");
    if (!input_file) {
        perror("Error opening input file");
        return;
    }

    FILE* output_file = fopen(output_path, "w");
    if (!output_file) {
        perror("Error opening output file");
        fclose(input_file);
        return;
    }

    NetworkRecord records[MAX_LINE_LENGTH];
    int record_count = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), input_file)) {
        // Parse the line into timestamp and packet size
        // Assuming format: "timestamp,packet_size"
        // Implement parsing logic here

        // Store the parsed data in records array
        strcpy(records[record_count].timestamp, /* extracted_timestamp */);
        records[record_count].packet_size = /* extracted_packet_size */;
        record_count++;

        if (record_count >= time_window) {
            double average = calculate_moving_average(records, record_count, time_window);
            fprintf(output_file, "%s,%f\n", records[record_count - 1].timestamp, average);

            // Shift the array to remove the oldest record
            memmove(records, records + 1, sizeof(NetworkRecord) * (record_count - 1));
            record_count--;
        }
    }

    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_log_file> <output_log_file> <time_window>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* input_path = argv[1];
    const char* output_path = argv[2];
    int time_window = atoi(argv[3]);

    process_log_file(input_path, output_path, time_window);

    printf("Log processing completed successfully.\n");

    return EXIT_SUCCESS;
}
```

