```cpp
// rng_library.h
#ifndef RNG_LIBRARY_H
#define RNG_LIBRARY_H

#include <vector>
#include <mutex>
#include <fstream>
#include <random>
#include <stdexcept>

class MersenneTwisterRNG {
private:
    std::mt19937_64 generator;
public:
    MersenneTwisterRNG(uint64_t seed) : generator(seed) {}

    double nextDouble() { return std::uniform_real_distribution<>(0.0, 1.0)(generator); }
    int nextInt(int min, int max) {
        std::uniform_int_distribution<> distribution(min, max);
        return distribution(generator);
    }
};

class RNGManager {
private:
    std::vector<MersenneTwisterRNG> rngs;
    std::mutex mutex;

public:
    void loadFromConfig(const std::string& configFilePath) {
        std::ifstream file(configFilePath);
        if (!file.is_open()) throw std::runtime_error("Failed to open config file");

        std::string line;
        while (std::getline(file, line)) {
            try {
                uint64_t seed = std::stoull(line);
                std::lock_guard<std::mutex> lock(mutex);
                rngs.push_back(MersenneTwisterRNG(seed));
            } catch (...) {
                throw std::runtime_error("Invalid seed in config file");
            }
        }

        if (rngs.empty()) throw std::runtime_error("No valid seeds found in config file");
    }

    MersenneTwisterRNG& getRNG(size_t index) {
        if (index >= rngs.size()) throw std::out_of_range("Invalid RNG index");

        return rngs[index];
    }
};

#endif // RNG_LIBRARY_H

// rng_library.cpp
#include "rng_library.h"

// rng_tests.cpp
#include <gtest/gtest.h>
#include <fstream>

TEST(RNGManagerTest, LoadFromConfig) {
    std::ofstream configFile("config.txt");
    configFile << "1234567890\n";
    configFile << "987654321\n";
    configFile.close();

    RNGManager manager;
    EXPECT_NO_THROW(manager.loadFromConfig("config.txt"));
    EXPECT_EQ(manager.getRNG(0).nextInt(0, 1), manager.getRNG(1).nextInt(0, 1));

    std::remove("config.txt");
}

TEST(RNGManagerTest, InvalidSeed) {
    std::ofstream configFile("config.txt");
    configFile << "abcde\n";
    configFile.close();

    RNGManager manager;
    EXPECT_THROW(manager.loadFromConfig("config.txt"), std::runtime_error);

    std::remove("config.txt");
}

TEST(RNGManagerTest, EmptyConfig) {
    std::ofstream configFile("config.txt");
    configFile.close();

    RNGManager manager;
    EXPECT_THROW(manager.loadFromConfig("config.txt"), std::runtime_error);

    std::remove("config.txt");
}
```

