// Function to handle HTTP POST requests for updating page content
EVP_CIPHER* handleHttpPostRequest(const std::forward_list<std::string>& pageContent, const std::string& sectionId, const std::string& elementId, const std::string& encryptedHtml) {
    std::string decryptedHtml = decryptHtml(encryptedHtml); // Assume decryptHtml function exists

    auto it = std::find(pageContent.begin(), pageContent.end(), sectionId);
    if (it != pageContent.end()) {
        pageContent.insert(++it, decryptedHtml); // Insert after the first occurrence
    } else {
        pageContent.push_front(decryptedHtml); // Append to the end
    }

    PageUpdater::getInstance()->updateElementAsync(sectionId, elementId, decryptedHtml);

    return EVP_aes_256_cbc(); // Return a pointer to an EVP_CIPHER structure representing AES-256-CBC cipher mode
}

