#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 1000

typedef struct {
    int age;
    double weighted_sum;
} Transaction;

typedef struct {
    sem_t *sem;
    pthread_mutex_t mutex;
    int max_weighted_sum_id;
    double max_weighted_sum;
    int transaction_count;
    Transaction transactions[MAX_TRANSACTIONS];
} FilterMetrics;

void* filter_transactions(void* arg) {
    FilterMetrics* metrics = (FilterMetrics*)arg;

    // Semaphore initialization
    if (sem_init(metrics->sem, 0, metrics->initial_value) == -1) {
        perror("Failed to initialize semaphore");
        return NULL;
    }

    for (int i = 0; i < MAX_TRANSACTIONS; ++i) {
        sem_wait(metrics->sem);

        // Perform transaction filtering logic here
        if (metrics->transactions[i].age <= 3 && metrics->transaction_count < 100 &&
            metrics->transactions[i].weighted_sum > metrics->max_weighted_sum) {
            pthread_mutex_lock(&metrics->mutex);
            metrics->max_weighted_sum = metrics->transactions[i].weighted_sum;
            metrics->max_weighted_sum_id = i;
            pthread_mutex_unlock(&metrics->mutex);
        }

        sem_post(metrics->sem);
    }

    // Semaphore destruction
    sem_destroy(metrics->sem);

    return NULL;
}

int main() {
    FilterMetrics metrics;
    metrics.sem = (sem_t*)malloc(sizeof(sem_t));
    metrics.initial_value = 10;

    // Initialize other necessary variables and perform filtering

    pthread_t thread;
    if (pthread_create(&thread, NULL, filter_transactions, &metrics) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Join the thread and handle any errors

    printf("Maximum weighted sum: %f\n", metrics.max_weighted_sum);
    printf("Transaction ID with maximum weighted sum: %d\n", metrics.max_weighted_sum_id);

    free(metrics.sem);
    return EXIT_SUCCESS;
}
