        File file = new File(filePath);

        try {
            if (file.exists()) {
                file.delete();
            }

            // Execute a command
            Runtime.getRuntime().exec("command", null, file.getParentFile());

            // Read output and error streams
            Process process = Runtime.getRuntime().exec("your/program");
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static String getPokemonWeaknesses(Pokemon pokemon) {
        switch (pokemon.getType()) {
            case "Fire":
                return "Water, Earth";
            case "Water":
                return "Fire, Grass";
            case "Grass":
                return "Fire, Flying";
            default:
                return "Unknown";
        }
    }

    public static int extractSequenceNumber(File file) throws IOException {
        List<String> lines = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                lines.add(line);
            }
        }

        Collections.sort(lines);
        String lastLine = lines.get(lines.size() - 1);
        return Integer.parseInt(lastLine.split(" ")[0]); // Assuming the sequence number is the first word
    }
}

