using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Web;

public class PageUpdaterController : IHttpHandler
{
    private readonly IPageService _pageService;
    private readonly ILogger _logger;

    public PageUpdaterController(IPageService pageService, ILogger logger)
    {
        _pageService = pageService ?? throw new ArgumentNullException(nameof(pageService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public bool IsReusable => false;

    public void ProcessRequest(HttpContext context)
    {
        if (context.Request.HttpMethod != "POST")
        {
            context.Response.StatusCode = 405; // Method Not Allowed
            return;
        }

        string sectionId = context.Request.Form["sectionId"];
        string elementId = context.Request.Form["elementId"];
        string htmlContent = context.Request.Form["htmlContent"];
        string password = context.Request.Form["password"];
        string salt = context.Request.Form["salt"];

        try
        {
            ValidateInputs(sectionId, elementId, htmlContent, password, salt);
            byte[] encryptedHtml = EncryptHtml(htmlContent, password, salt);

            _pageService.UpdateElementHtml(sectionId, elementId, encryptedHtml);

            context.Response.Write("Page should be refreshed.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex);
            context.Response.StatusCode = 500; // Internal Server Error
            context.Response.Write("An error occurred while processing your request.");
        }
    }

    private void ValidateInputs(string sectionId, string elementId, string htmlContent, string password, string salt)
    {
        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent) ||
            string.IsNullOrEmpty(password) || string.IsNullOrEmpty(salt))
        {
            throw new ArgumentException("All input parameters are required.");
        }

        // Additional validation logic can be added here
    }

    private byte[] EncryptHtml(string htmlContent, string password, string salt)
    {
        using (var aes = Aes.Create())
        {
            aes.KeySize = 256;
            aes.BlockSize = 128;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            byte[] key = DeriveKey(password, salt);
            byte[] iv = GenerateIV();

            aes.Key = key;
            aes.IV = iv;

            using (var encryptor = aes.CreateEncryptor(aes.Key, aes.IV))
            {
                using (var msEncrypt = new MemoryStream())
                {
                    using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        using (var swEncrypt = new StreamWriter(csEncrypt))
                        {
                            swEncrypt.Write(htmlContent);
                        }
                        return msEncrypt.ToArray();
                    }
                }
            }
        }
    }

    private byte[] DeriveKey(string password, string salt)
    {
        using (var sha256 = SHA256.Create())
        {
            byte[] saltBytes = Encoding.UTF8.GetBytes(salt);
            byte[] passwordBytes = Encoding.UTF8.GetBytes(password);

            byte[] combinedData = new byte[saltBytes.Length + passwordBytes.Length];
            Buffer.BlockCopy(saltBytes, 0, combinedData, 0, saltBytes.Length);
            Buffer.BlockCopy(passwordBytes, 0, combinedData, saltBytes.Length, passwordBytes.Length);

            return sha256.ComputeHash(combinedData);
        }
    }

    private byte[] GenerateIV()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            byte[] iv = new byte[16]; // AES block size
            rng.GetBytes(iv);
            return iv;
        }
    }
}
