```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class MessageProcessor : IDisposable
{
    private readonly Dictionary<string, Tuple<DesCryptoProvider, byte[]>> _keyPairs = new Dictionary<string, Tuple<DesCryptoProvider, byte[]>>();
    private readonly object _lockObject = new object();

    public void AddMessageType(string messageType, string key, string iv)
    {
        var desProvider = CreateDesCryptoProvider(key, iv);
        lock (_lockObject)
        {
            if (_keyPairs.ContainsKey(messageType))
                throw new ArgumentException("Message type already exists.");

            _keyPairs[messageType] = Tuple.Create(desProvider, Encoding.UTF8.GetBytes(iv));
        }
    }

    public void UpdateMessageType(string messageType, string key, string iv)
    {
        var desProvider = CreateDesCryptoProvider(key, iv);
        lock (_lockObject)
        {
            if (!_keyPairs.ContainsKey(messageType))
                throw new ArgumentException("Message type does not exist.");

            _keyPairs[messageType] = Tuple.Create(desProvider, Encoding.UTF8.GetBytes(iv));
        }
    }

    public void RemoveMessageType(string messageType)
    {
        lock (_lockObject)
        {
            if (!_keyPairs.ContainsKey(messageType))
                throw new ArgumentException("Message type does not exist.");

            _keyPairs.Remove(messageType);
        }
    }

    public string DecryptMessage(string messageType, string base64EncodedMessage)
    {
        byte[] iv;
        using (var desPair = GetDesCryptoProviderAndIV(messageType, out iv))
        {
            var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            var decryptedBytes = desPair.Item1.Decrypt(encryptedBytes, iv);

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    private DesCryptoProvider CreateDesCryptoProvider(string key, string iv)
    {
        byte[] keyBytes = Encoding.UTF8.GetBytes(key);
        byte[] ivBytes = Encoding.UTF8.GetBytes(iv);

        if (keyBytes.Length != 24 || ivBytes.Length != 8)
            throw new ArgumentException("Key and IV must be of correct length.");

        return new DesCryptoProvider(keyBytes, ivBytes);
    }

    private Tuple<DesCryptoProvider, byte[]> GetDesCryptoProviderAndIV(string messageType, out byte[] iv)
    {
        if (!_keyPairs.ContainsKey(messageType))
            throw new ArgumentException("Message type not supported.");

        var desPair = _keyPairs[messageType];
        iv = desPair.Item2;
        return desPair;
    }

    public void Dispose()
    {
        lock (_lockObject)
        {
            foreach (var pair in _keyPairs.Values)
                pair.Item1.Dispose();

            _keyPairs.Clear();
        }
    }
}

public class DesCryptoProvider : IDisposable
{
    private readonly TripleDES _des;

    public DesCryptoProvider(byte[] key, byte[] iv)
    {
        _des = TripleDES.Create();
        _des.Key = key;
        _des.IV = iv;
        _des.Mode = CipherMode.CBC;
        _des.Padding = PaddingMode.PKCS7;
    }

    public byte[] Encrypt(byte[] data, byte[] iv)
    {
        using (var msEncrypt = new MemoryStream())
        {
            using (var csEncrypt = new CryptoStream(msEncrypt, _des.CreateEncryptor(), CryptoStreamMode.Write))
            {
                csEncrypt.Write(data, 0, data.Length);
                csEncrypt.FlushFinalBlock();
            }
            return msEncrypt.ToArray();
        }
    }

    public byte[] Decrypt(byte[] data, byte[] iv)
    {
        using (var msDecrypt = new MemoryStream(data))
        {
            using (var csDecrypt = new CryptoStream(msDecrypt, _des.CreateDecryptor(), CryptoStreamMode.Read))
            {
                using (var srDecrypt = new StreamReader(csDecrypt))
                    return Encoding.UTF8.GetBytes(srDecrypt.ReadToEnd());
            }
        }
    }

    public void Dispose()
    {
        _des.Dispose();
    }
}
```

