#include <string.h>
#include <time.h>

struct RenameConfig {
    int numDigits;
    char fileType[10];
    int appendTimestamp;
};

int renameFileWithDynamicExtension(const char *originalFilename, const struct RenameConfig *config, char *newFilename) {
    if (strlen(originalFilename) == 0) {
        fprintf(stderr, "Error: Original filename is empty.\n");
        return -1;
    }

    size_t originalLen = strlen(originalFilename);
    if (originalLen > 255) {
        fprintf(stderr, "Error: Original filename exceeds maximum length of 255 characters.\n");
        return -1;
    }

    char *dotPos = strrchr(originalFilename, '.');
    if (dotPos == NULL) {
        fprintf(stderr, "Error: Invalid original filename format.\n");
        return -1;
    }

    size_t baseLen = dotPos - originalFilename;
    if (baseLen + strlen(config->fileType) + config->numDigits + 3 > 255) {
        fprintf(stderr, "Error: New filename exceeds maximum length of 255 characters.\n");
        return -1;
    }

    snprintf(newFilename, 256, "%.*s_%d.%s", (int)baseLen, originalFilename, config->numDigits, config->fileType);

    if (config->appendTimestamp != 0) {
        time_t now = time(NULL);
        char timestamp[16];
        strftime(timestamp, sizeof(timestamp), "_%Y%m%d%H%M%S", localtime(&now));
        strncat(newFilename, timestamp, 255 - strlen(newFilename));
    }

    return 0;
}
