```javascript
class StockStreamProcessor {
  constructor(config) {
    this.apiEndpoint = config.apiEndpoint;
    this.authToken = config.authToken;
    this.interval = config.interval || 1000;
    this.maxDataPoints = config.maxDataPoints || 1000;
    this.retryDelay = config.retryDelay || 5000;
    this.data = [];
    this.paused = false;
    this.isProcessing = false;
    this.processIntervalId = null;
    this.fetchDataPromise = null;
    this.headers = {
      'Authorization': `Bearer ${this.authToken}`
    };
  }

  async fetchData() {
    try {
      const response = await fetch(this.apiEndpoint, { headers: this.headers });
      if (!response.ok) throw new Error('Network response was not ok');
      return await response.json();
    } catch (error) {
      console.error('Failed to fetch data:', error);
      throw error;
    }
  }

  processData(dataPoint) {
    if (dataPoint && typeof dataPoint === 'object' && Object.keys(dataPoint).length > 0) {
      this.data.push(dataPoint);
      if (this.data.length >= this.maxDataPoints) {
        this.collectGarbage();
      }
    } else {
      console.warn('Invalid data point:', dataPoint);
    }
  }

  collectGarbage() {
    this.data = [];
    console.log('Garbage collected. Data array is now empty.');
  }

  async processStream() {
    if (this.paused || !this.isProcessing) return;

    try {
      const dataPoint = await this.fetchData();
      this.processData(dataPoint);
      setTimeout(() => this.processStream(), this.interval);
    } catch (error) {
      setTimeout(() => this.processStream(), this.retryDelay);
    }
  }

  start() {
    if (!this.isProcessing) {
      this.isProcessing = true;
      this.processStream();
    }
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
  }

  clearData() {
    this.collectGarbage();
  }
}

// Example usage:
const config = {
  apiEndpoint: 'https://api.stockmarketdata.com/stream',
  authToken: 'your-auth-token-here',
  interval: 2000,
  maxDataPoints: 500,
  retryDelay: 10000
};

const stockProcessor = new StockStreamProcessor(config);

// Start processing the stream
stockProcessor.start();

// Pause processing after 10 seconds
setTimeout(() => {
  stockProcessor.pause();
}, 10000);

// Resume processing after another 5 seconds
setTimeout(() => {
  stockProcessor.resume();
}, 15000);

// Clear data and start fresh after another 10 seconds
setTimeout(() => {
  stockProcessor.clearData();
  stockProcessor.start();
}, 25000);
