#include <pthread.h>

#define MAX_RECORDS 100000000

typedef struct {
    int value;
    // Add additional metadata fields here if needed
} record;

void log_message(const char* level, const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s: %s\n", ctime(&now), level, message);
}

long* load_offsets_from_csv(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        log_message("ERROR", "Failed to open offsets CSV file");
        return NULL;
    }

    long* offsets = malloc(MAX_RECORDS * sizeof(long));
    if (!offsets) {
        log_message("ERROR", "Memory allocation failed for offsets array");
        fclose(file);
        return NULL;
    }

    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), file)) {
        long value;
        if (sscanf(line, "%ld", &value) != 1 || value < 0) {
            log_message("ERROR", "Invalid or out-of-range offset value in CSV");
            free(offsets);
            fclose(file);
            return NULL;
        }
        offsets[count++] = value;
    }

    fclose(file);
    if (count == 0) {
        log_message("ERROR", "No valid offset values found in CSV");
        free(offsets);
        return NULL;
    }

    offsets = realloc(offsets, count * sizeof(long));
    return offsets;
}

int* load_keys_from_csv(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        log_message("ERROR", "Failed to open keys CSV file");
        return NULL;
    }

    int* keys = malloc(MAX_RECORDS * sizeof(int));
    if (!keys) {
        log_message("ERROR", "Memory allocation failed for keys array");
        fclose(file);
        return NULL;
    }

    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), file)) {
        int value;
        if (sscanf(line, "%d", &value) != 1 || value < 0) {
            log_message("ERROR", "Invalid or out-of-range key value in CSV");
            free(keys);
            fclose(file);
            return NULL;
        }
        keys[count++] = value;
    }

    fclose(file);
    if (count == 0) {
        log_message("ERROR", "No valid key values found in CSV");
        free(keys);
        return NULL;
    }

    keys = realloc(keys, count * sizeof(int));
    return keys;
}

record* initialize_records(long* offsets, int* keys, int num_records) {
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        log_message("ERROR", "Memory allocation failed for records array");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&lock);
        // Use bitwise operations to generate a random value within the specified range
        records[i].value = offsets[i] ^ keys[i];
        pthread_mutex_unlock(&lock);
    }

    return records;
}

void* init_arrays(void* arg) {
    const char* csv_file = "data.csv";
    long* offsets = load_offsets_from_csv(csv_file);
    if (!offsets) {
        return NULL;
    }

    int* keys = load_keys_from_csv(csv_file);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    int num_records = strlen(keys);
    record* records = initialize_records(offsets, keys, num_records);

    log_message("INFO", "Arrays initialized successfully");

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, init_arrays, NULL) != 0) {
        log_message("ERROR", "Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
