#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 4096
#define DEFAULT_DELIMITER ","
#define DEFAULT_PRECISION 2
#define MIN_VALUE -1000.0
#define MAX_VALUE 1000.0

typedef struct {
    char *filename;
    const char *output_dir;
    const char *delimiter;
    int precision;
} Config;

void* process_file(void* arg) {
    Config config = *(Config*)arg;
    FILE *input = fopen(config.filename, "r");
    if (!input) {
        perror("Error opening file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, input)) {
        char *token = strtok(line, config.delimiter);
        int count = 0;
        double sum = 0.0;

        // Calculate the sum of numeric fields and count them
        while (token) {
            char *endptr;
            double value = strtod(token, &endptr);
            if (*endptr == '\0') { // Check if conversion was successful
                sum += value;
                count++;
            } else {
                fprintf(stderr, "Error: Non-numeric field in line\n");
                break;
            }
            token = strtok(NULL, config.delimiter);
        }

        // Calculate the average of the last two fields or single field if odd
        double avg;
        if (count % 2 == 0) {
            avg = sum / 2.0;
        } else {
            int mid = count / 2;
            avg = (token ? strtod(token, NULL) : 0.0 + token[-1]) / 2.0;
        }

        // Print the line with average appended
        printf("%.*f\n", config.precision, avg);
    }

    fclose(input);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <config_file> <input_files...>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Config config;
    // Read configuration from file
    FILE *config_file = fopen(argv[1], "r");
    if (!config_file) {
        perror("Error opening config file");
        return EXIT_FAILURE;
    }
    fscanf(config_file, "delimiter=%[^ ]\n", (char*)&config.delimiter);
    fscanf(config_file, "precision=%d\n", &config.precision);
    fclose(config_file);

    // Set output directory
    strcpy(config.output_dir, "./output");

    pthread_t threads[argc - 2];
    for (int i = 0; i < argc - 2; i++) {
        config.filename = argv[i + 2];
        if (pthread_create(&threads[i], NULL, process_file, &config) != 0) {
            perror("Error creating thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < argc - 2; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
