public class XmlParser {
    private Dictionary<string, XPathDocument> cache = new Dictionary<string, XPathDocument>();

    public XmlElement ParseXml(string xmlUrl, string elementName, int pageNumber, out bool hasMoreResults) {
        if (!cache.ContainsKey(xmlUrl)) {
            var document = new XPathDocument(xmlUrl);
            cache[xmlUrl] = document;
        }

        var navigator = cache[xmlUrl].CreateNavigator();
        var xpathExpression = $"/*:root/*:element[{pageNumber}]"; // Replace with actual XPath expression

        try {
            var nodeIterator = navigator.Select(xpathExpression);

            if (!nodeIterator.MoveNext()) {
                hasMoreResults = false;
                throw new InvalidOperationException("No element found or multiple elements found with the given name.");
            }

            var firstElement = (XmlElement)nodeIterator.Current;
            hasMoreResults = nodeIterator.MoveNext();

            // Validate element against external API metadata
            // ...

            return firstElement;
        } catch (Exception ex) {
            // Log error for debugging purposes
            Console.WriteLine($"Error parsing XML: {ex.Message}");

            throw new InvalidOperationException("An error occurred while parsing the XML document.", ex);
        }
    }

    public void ClearCache() {
        cache.Clear();
    }
}
