#define LOG_FILE "transaction_logs.txt"

typedef struct {
    int id;
    time_t timestamp;
    double weighted_sum;
    char instrument[50];
} Transaction;

typedef struct {
    int transaction_count[MAX_INSTRUMENTS];
    double total_weighted_sum[MAX_INSTRUMENTS];
    time_t last_update[MAX_INSTRUMENTS];
    FILE* log_file;
} Metrics;

Metrics metrics = {0};

void initialize_metrics() {
    metrics.log_file = fopen(LOG_FILE, "w");
}

void update_transaction(Transaction transaction) {
    int instrument_index = 0; // Assuming a simple mapping for demonstration
    if (time(NULL) - transaction.timestamp > 60 || metrics.transaction_count[instrument_index] > 500 || metrics.total_weighted_sum[instrument_index] < 1000) {
        return;
    }

    metrics.transaction_count[instrument_index]++;
    metrics.total_weighted_sum[instrument_index] += transaction.weighted_sum;

    if (transaction.weighted_sum > 1000 && transaction.id != 0) {
        fprintf(metrics.log_file, "High-weighted transaction detected: ID=%d, Weighted Sum=%.2f\n", transaction.id, transaction.weighted_sum);
        fflush(metrics.log_file);
    }
}

void process_transactions(Transaction transactions[], int count) {
    for (int i = 0; i < count; i++) {
        update_transaction(transactions[i]);
    }
}

void finalize_metrics() {
    fclose(metrics.log_file);
}

int main() {
    initialize_metrics();

    Transaction transactions[] = {
        {1, time(NULL), 500.5, "Stocks"},
        {2, time(NULL) - 30, 700.7, "Bonds"},
        // Add more transactions as needed
    };

    int transaction_count = sizeof(transactions) / sizeof(transactions[0]);
    process_transactions(transactions, transaction_count);

    finalize_metrics();

    return 0;
}
