#include <functional>
#include <openssl/rand.h>
#include <botan/auto_rng.h>
#include <botan/rng.h>

// Define the random number generation interface
class RandomNumberGenerator {
public:
    virtual ~RandomNumberGenerator() = default;
    virtual void generateSecureNumbers(int count, std::vector<double>& numbers) const = 0;
};

// OpenSSL-based random number generator
class OpenSSLGenerator : public RandomNumberGenerator {
public:
    void generateSecureNumbers(int count, std::vector<double>& numbers) const override {
        for (int i = 0; i < count; ++i) {
            unsigned char buffer[8];
            if (RAND_bytes(buffer, sizeof(buffer)) == 1) {
                double number = *reinterpret_cast<double*>(buffer);
                numbers.push_back(number);
            }
        }
    }
};

// Botan-based random number generator
class BotanGenerator : public RandomNumberGenerator {
public:
    void generateSecureNumbers(int count, std::vector<double>& numbers) const override {
        Botan::AutoSeeded_RNG rng;
        for (int i = 0; i < count; ++i) {
            numbers.push_back(rng.random_double());
        }
    }
};

// Secure random number generation service
class SecureRandomNumberService {
public:
    SecureRandomNumberService(int workerThreads)
        : _workerThreads(workerThreads), _stop(false) {
        for (int i = 0; i < _workerThreads; ++i) {
            _workers.emplace_back(&SecureRandomNumberService::worker, this);
        }
    }

    ~SecureRandomNumberService() {
        {
            std::unique_lock<std::mutex> lock(_queueMutex);
            _stop = true;
        }
        _condition.notify_all();
        for (std::thread& worker : _workers) {
            worker.join();
        }
    }

    void generateNumbers(int count, std::vector<double>& numbers) const {
        std::unique_lock<std::mutex> lock(_queueMutex);
        _requestQueue.push(std::make_pair(count, &numbers));
        _condition.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(_queueMutex);
            _condition.wait(lock, [this] { return !_requestQueue.empty() || _stop; });
            if (_stop && _requestQueue.empty()) {
                break;
            }
            auto request = std::move(_requestQueue.front());
            _requestQueue.pop();
            lock.unlock();

            RandomNumberGenerator* generator = getGenerator();
            if (generator) {
                generator->generateSecureNumbers(request.first, *request.second);
                delete generator;
            } else {
                // Handle error: no available generator
                std::cerr << "Error: No available random number generator!" << std::endl;
            }
        }
    }

    RandomNumberGenerator* getGenerator() const {
        if (RAND_status()) {
            return new OpenSSLGenerator();
        } else if (Botan::AutoSeeded_RNG::is_available()) {
            return new BotanGenerator();
        } else {
            // Handle error: no available generator
            std::cerr << "Error: No available random number generator!" << std::endl;
            return nullptr;
        }
    }

private:
    int _workerThreads;
    bool _stop;
    mutable std::mutex _queueMutex;
    std::condition_variable _condition;
    std::queue<std::pair<int, std::vector<double>*>> _requestQueue;
    std::vector<std::thread> _workers;
};
