std::string handleHttpPostRequest(const std::forward_list<std::string>& elements, const std::string& pageSectionId, const std::string& elementId, const std::string& htmlContent) {
    HtmlService htmlService;
    std::lock_guard<std::mutex> lock(mutex); // Ensure thread safety

    std::forward_list<std::string> updatedElements = elements;

    auto it = updatedElements.begin();
    while (it != updatedElements.end()) {
        if (*it == pageSectionId) {
            it = updatedElements.insert_after(it, htmlContent);
            break;
        }
        ++it;
    }

    if (it == updatedElements.end()) {
        updatedElements.push_back(htmlContent);
    }

    std::string response = "DoNotRefreshPage";
    for (const auto& element : updatedElements) {
        std::string elementContent;
        if (!htmlService.searchElementById(elementId, elementContent)) {
            Logger::log("Error: Element ID not found");
            return response;
        }
        if (!htmlService.updateElementContent(elementId, htmlContent)) {
            Logger::log("Error: Failed to update element content");
            return response;
        }
    }

    // Simulate page refresh logic
    if (updatedElements.size() > elements.size()) {
        response = "RefreshPage";
    }

    Logger::log("Operation completed successfully");
    return response;
}
