#define MAX_RECORDS 1000
#define MAX_STR_LEN 256

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

RecordArray record_array = { .lock = PTHREAD_MUTEX_INITIALIZER };

void init_record_array() {
    pthread_mutex_lock(&record_array.lock);
    record_array.count = 0;
    pthread_mutex_unlock(&record_array.lock);
}

void add_record(long offset, int key) {
    pthread_mutex_lock(&record_array.lock);
    if (record_array.count < MAX_RECORDS) {
        Record new_record = { .offset = offset, .key = key };
        record_array.records[record_array.count++] = new_record;
    } else {
        printf("Error: Record array is full.\n");
    }
    pthread_mutex_unlock(&record_array.lock);
}

void *load_data_from_file(void *file_path) {
    FILE *file = fopen((char *)file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Assuming the binary file contains an array of 'long' offset values and another for 'int' keys
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    size_t num_records = fread(offsets, sizeof(long), MAX_RECORDS, file);
    if (fread(keys, sizeof(int), num_records, file) != num_records) {
        printf("Error reading data from file.\n");
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < num_records; i++) {
        add_record(offsets[i], keys[i]);
    }

    fclose(file);
    return NULL;
}

