public class GameConfigurationManager
{
    private string xmlFilePath;
    private Dictionary<string, object> configurationCache;
    private DateTime lastBackupTime;

    public GameConfigurationManager(string filePath)
    {
        xmlFilePath = filePath;
        configurationCache = new Dictionary<string, object>();
        LoadConfigurations();
    }

    public void UpdateConfiguration(string key, object value)
    {
        lock (configurationCache)
        {
            configurationCache[key] = value;
            ApplyConfigurationChanges();
        }
    }

    private void LoadConfigurations()
    {
        if (File.Exists(xmlFilePath))
        {
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.Load(xmlFilePath);
            foreach (XmlNode node in xmlDoc.DocumentElement.ChildNodes)
            {
                string key = node.Name;
                object value = node.InnerText;
                configurationCache[key] = value;
            }
        }
    }

    private void ApplyConfigurationChanges()
    {
        // Apply changes to game components
    }

    public object GetConfiguration(string key)
    {
        lock (configurationCache)
        {
            if (configurationCache.ContainsKey(key))
                return configurationCache[key];
            else
                throw new KeyNotFoundException("Configuration key not found.");
        }
    }

    private void BackupConfiguration()
    {
        if ((DateTime.Now - lastBackupTime).TotalMinutes > 5) // Backup every 5 minutes
        {
            string backupFilePath = xmlFilePath + ".bak";
            File.Copy(xmlFilePath, backupFilePath);
            lastBackupTime = DateTime.Now;
        }
    }

    public void RestorePreviousVersion()
    {
        string backupFilePath = xmlFilePath + ".bak";
        if (File.Exists(backupFilePath))
        {
            File.Copy(backupFilePath, xmlFilePath, true);
        }
        else
        {
            Console.WriteLine("No previous version available to restore.");
        }
    }

