char* process_tiff_image_and_oauth_request(const char* tiff_filename, const char* oauth_request) {
    ImageInfo image_info = parse_tiff_image(tiff_filename);
    if (image_info.bits_per_sample != 1 && image_info.bits_per_sample != 2 && image_info.bits_per_sample != 4 &&
        image_info.bits_per_sample != 8 && image_info.bits_per_sample != 16) {
        return "Error: Unsupported bits per sample";
    }

    char* private_key = NULL;
    char* certificate = NULL;
    int result = fetch_private_key_and_certificate(oauth_request, &private_key, &certificate);
    if (result != 0) {
        return "Error: Failed to fetch private key and certificate";
    }

    char* combined_pem = combine_pem_files(private_key, certificate);
    free(private_key);
    free(certificate);

    if (!validate_oauth_request(oauth_request)) {
        free(combined_pem);
        return "Error: Invalid OAuth request";
    }

    char* output = (char*)malloc(strlen(combined_pem) + strlen("Bits per sample: ") + 3 + strlen("\nSamples per pixel: ") + 2 + 1);
    sprintf(output, "%s%s%d\nSamples per pixel: %d", combined_pem, "Bits per sample: ", image_info.bits_per_sample, image_info.samples_per_pixel);

    free(combined_pem);
    return output;
}
