from sanic import Sanic
from sanic.response import json, text
from sanic.exceptions import NotFound, BadRequest, ServerError
from sanic_cors import CORS
import asyncio
import aiohttp
from functools import wraps
import time
from cachetools import TTLCache

app = Sanic("FinancialAPI")
CORS(app)
cache = TTLCache(maxsize=100, ttl=3600)

providers = {
    'alpha_vantage': 'https://www.alphavantage.co/query',
    'yahoo_finance': 'https://query2.finance.yahoo.com/v1/finance/quote',
    'coingecko': 'https://api.coingecko.com/api/v3/simple/'
}

async def fetch_data(url, params):
    async with aiohttp.ClientSession() as session:
        async with session.get(url, params=params) as response:
            return await response.json()

@app.route('/data', methods=['GET', 'POST'])
async def financial_data(request):
    if request.method == 'POST':
        data_type = request.form.get('type')
        provider = request.form.get('provider')
    else:
        data_type = request.args.get('type')
        provider = request.args.get('provider')

    if not data_type or not provider:
        raise BadRequest("Missing required parameters")

    url = providers.get(provider)
    if not url:
        raise NotFound(f"Provider {provider} not supported")

    try:
        cached_data = cache.get((data_type, provider))
        if cached_data:
            return json(cached_data)

        params = {'function': data_type}
        response = await fetch_data(url, params)
        data = response['Time Series (Daily)']  # Assuming daily time series for simplicity
        cache[(data_type, provider)] = data

        return json(data)
    except Exception as e:
        raise ServerError(f"Failed to retrieve data: {e}")

@app.middleware('response')
async def log_response(request, response):
    duration = time.time() - request['start_time']
    if response.status_code == 200:
        print(f"{request.method} {request.path} Success in {duration:.2f}s")
    else:
        print(f"{request.method} {request.path} Error {response.status_code} in {duration:.2f}s")
    return response

@app.exception(BadRequest)
def handle_bad_request(request, exception):
    return json({"error": "Invalid request parameters"}, status=400)

@app.exception(NotFound)
def handle_not_found(request, exception):
    return json({"error": "Resource not found"}, status=404)

@app.exception(ServerError)
def handle_server_error(request, exception):
    return json({"error": "Internal server error"}, status=500)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000)
