<?php

use Redis;
use OAuth2\Client as OAuthClient;

function authenticateUser($clientId, $clientSecret, $redirectUri, $code) {
    // Setup Redis for caching and rate limiting
    $redis = new Redis();
    $redis->connect('127.0.0.1', 6379);

    // Rate limiting: Limit to 5 requests per minute per IP
    $ip = $_SERVER['REMOTE_ADDR'];
    $key = "rate_limit:$ip";
    if ($redis->incr($key) > 5) {
        error_log("Rate limit exceeded for IP: " . $ip);
        return ['status' => 'error', 'message' => 'Too many requests. Please try again later.'];
    }
    $redis->expire($key, 60);

    // Setup OAuth2 client
    $client = new OAuthClient($clientId, $clientSecret, null, null, $redirectUri);
    $tokenEndpoint = 'https://oauth.provider.com/token';

    try {
        // Exchange code for access token
        $accessToken = $client->getAccessToken('authorization_code', ['code' => $code]);
        $accessTokenStr = json_encode($accessToken);

        // Store access token in session and Redis
        $_SESSION['access_token'] = $accessTokenStr;
        $redis->setex("auth_token:$ip", 3600, $accessTokenStr); // Cache for 1 hour

        // Retrieve user information using the access token
        $userInfoEndpoint = 'https://oauth.provider.com/userinfo';
        $userResponse = $client->get($userInfoEndpoint, ['access_token' => $accessToken['access_token']]);
        $userInfo = json_decode((string) $userResponse->getBody(), true);

        // Cache user information in Redis
        $redis->setex("user_info:$userInfo[id]", 86400, json_encode($userInfo)); // Cache for 24 hours

        return ['status' => 'success', 'data' => $userInfo];

    } catch (\Exception $e) {
        error_log("Authentication error: " . $e->getMessage());
        return ['status' => 'error', 'message' => 'Authentication failed. Please try again later.'];
    }
}

