use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{Instant, Duration};
use crossbeam_channel::{unbounded, Receiver, Sender};
use log4rs;

fn compile_files(source_files: Vec<String>, build_command: &str) -> Result<(), String> {
    let start_time = Instant::now();
    let total_memory = Arc::new(Mutex::new(0));
    let logger_config = log4rs::config::Config::builder()
        .build(log4rs::config::appender::console::ConsoleAppender::builder().build())
        .unwrap();
    log4rs::init_config(logger_config).unwrap();

    let (tx, rx): (Sender<_>, Receiver<_>) = unbounded();

    for file in source_files {
        let tx_clone = tx.clone();
        let total_memory_clone = Arc::clone(&total_memory);

        std::thread::spawn(move || {
            let output = Command::new(build_command)
                .arg(file)
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .output()
                .unwrap();

            if !output.status.success() {
                tx_clone.send(format!("Error compiling {}: {}", file, String::from_utf8_lossy(&output.stderr)))
                    .unwrap();
            } else {
                let memory = get_memory_usage(); // Function to get current RSS memory usage
                let mut max_memory = total_memory_clone.lock().unwrap();
                if *max_memory < memory {
                    *max_memory = memory;
                }

                tx_clone.send(format!("Compiled {}: {}", file, String::from_utf8_lossy(&output.stdout)))
                    .unwrap();
            }
        });
    }

    for _ in 0..source_files.len() {
        match rx.recv().unwrap() {
            Ok(message) => println!("{}", message),
            Err(e) => eprintln!("Error receiving message: {}", e),
        }
    }

    let total_time = start_time.elapsed();
    let max_memory = *total_memory.lock().unwrap();

    println!("Total compilation time: {:?}", total_time);
    println!("Peak memory usage: {} bytes", max_memory);

    Ok(())
}

fn get_memory_usage() -> usize {
    // Placeholder function to get current RSS memory usage
    0
}
