# External caching service setup with TTL (Time To Live) of 1 hour
cache = TTLCache(maxsize=100, ttl=3600)

@cached(cache)
def download_webpage(url):
    try:
        response = requests.get(url)
        response.raise_for_status()  # Raises an HTTPError for bad responses
        return response.text
    except requests.RequestException as e:
        print(f"Network error: {e}")
        return None

def calculate_hash(text):
    if text is None:
        raise ValueError("Text cannot be None")
    return sha256(text.encode()).hexdigest()

def detect_data_corruption(original_hash, new_hash):
    if original_hash != new_hash:
        print("Potential data corruption detected!")
        return True
    return False

def process_webpage(url):
    webpage_content = download_webpage(url)
    if webpage_content is None:
        return None

    initial_hash = calculate_hash(webpage_content)

    # Simulate network transmission
    transmitted_content = webpage_content  # In a real scenario, this would be sent over the network
    new_hash = calculate_hash(transmitted_content)

    if detect_data_corruption(initial_hash, new_hash):
        return None

    return new_hash

# Example usage
url = "https://example.com"
resulting_hash = process_webpage(url)
if resulting_hash:
    print(f"SHA-256 hash of the webpage: {resulting_hash}")
else:
    print("Failed to process the webpage.")
