```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <openssl/evp.h>

#define BUFFER_SIZE 4096

void encrypt_file(const char *in_filename, const char *out_filename, const unsigned char *key) {
    EVP_CIPHER_CTX *ctx;
    FILE *infile, *outfile;
    int len;
    unsigned char inbuf[BUFFER_SIZE], outbuf[BUFFER_SIZE];

    if (!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) handleErrors();

    if (!(infile = fopen(in_filename, "rb"))) handleErrors();
    if (!(outfile = fopen(out_filename, "wb"))) handleErrors();

    while ((len = fread(inbuf, 1, BUFFER_SIZE, infile)) > 0) {
        if (1 != EVP_EncryptUpdate(ctx, outbuf, &len, inbuf, len)) handleErrors();
        fwrite(outbuf, 1, len, outfile);
    }

    if (1 != EVP_EncryptFinal_ex(ctx, outbuf, &len)) handleErrors();
    fwrite(outbuf, 1, len, outfile);

    fclose(infile);
    fclose(outfile);
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_file(const char *in_filename, const char *out_filename, const unsigned char *key) {
    EVP_CIPHER_CTX *ctx;
    FILE *infile, *outfile;
    int len;
    unsigned char inbuf[BUFFER_SIZE], outbuf[BUFFER_SIZE];

    if (!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) handleErrors();

    if (!(infile = fopen(in_filename, "rb"))) handleErrors();
    if (!(outfile = fopen(out_filename, "wb"))) handleErrors();

    while ((len = fread(inbuf, 1, BUFFER_SIZE, infile)) > 0) {
        if (1 != EVP_DecryptUpdate(ctx, outbuf, &len, inbuf, len)) handleErrors();
        fwrite(outbuf, 1, len, outfile);
    }

    if (1 != EVP_DecryptFinal_ex(ctx, outbuf, &len)) handleErrors();
    fwrite(outbuf, 1, len, outfile);

    fclose(infile);
    fclose(outfile);
    EVP_CIPHER_CTX_free(ctx);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s [encrypt|decrypt] keyfile inputfile outputfile\n", argv[0]);
        return 1;
    }

    const char *mode = argv[1];
    const char *keyfile = argv[2];
    const char *in_filename = argv[3];
    const char *out_filename = argv[4];

    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];

    FILE *keyfp = fopen(keyfile, "rb");
    if (!keyfp) {
        perror("Failed to open key file");
        return 1;
    }

    fread(key, 1, sizeof(key), keyfp);
    fread(iv, 1, sizeof(iv), keyfp);

    fclose(keyfp);

    if (strcmp(mode, "encrypt") == 0) {
        encrypt_file(in_filename, out_filename, key);
    } else if (strcmp(mode, "decrypt") == 0) {
        decrypt_file(in_filename, out_filename, key);
    } else {
        fprintf(stderr, "Invalid mode. Use 'encrypt' or 'decrypt'.\n");
        return 1;
    }

    return 0;
}
```
