using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Microsoft.AspNet.Identity;

public class AccountValidator : IUserValidator<ApplicationUser>
{
    private static readonly List<string> oldTestamentBooks = new List<string> { "Genesis", "Exodus", "Leviticus", /* ... */ };
    private static readonly Dictionary<IdentityErrorDescriber, string> validationErrors = new Dictionary<IdentityErrorDescriber, string>();

    public IdentityResult ValidateAsync(ApplicationUser user)
    {
        if (user == null)
        {
            throw new ArgumentNullException("user");
        }

        List<string> errors = new List<string>();

        // Check for book names in the Old Testament
        foreach (var book in oldTestamentBooks)
        {
            var regex = new Regex(@"\b" + Regex.Escape(book) + @"\b", RegexOptions.IgnoreCase);
            if (regex.IsMatch(user.Password))
            {
                errors.Add(validationErrors[IdentityErrorDescriber.PasswordTooComplex]);
            }
        }

        // Check for password requirements
        if (user.Password.Length < 8)
        {
            errors.Add(validationErrors[IdentityErrorDescriber.PasswordTooShort]);
        }

        if (!user.Email.Contains("@"))
        {
            errors.Add(validationErrors[IdentityErrorDescriber.InvalidEmail]);
        }

        return new IdentityResult(errors);
    }
}

public class BookNameValidator
{
    private static readonly List<string> bookNames = new List<string> { "Genesis", "Exodus", "Leviticus", /* ... */ };
    private static readonly Dictionary<Regex, string> bookPatterns = new Dictionary<Regex, string>();

    public bool ValidateText(string text)
    {
        if (string.IsNullOrEmpty(text))
        {
            return true;
        }

        var cleanText = Regex.Replace(text.ToLower(), @"[\p{P}\p{S}]", "");

        foreach (var pattern in bookPatterns)
        {
            if (pattern.Key.IsMatch(cleanText))
            {
                throw new InvalidOperationException(pattern.Value);
            }
        }

        return false;
    }
}

