    public boolean processTransaction(String customerId, CreditCardInfo cardInfo, double amount) {
        if (!validateCreditCard(cardInfo)) {
            logger.severe("Invalid credit card information");
            return false;
        }

        String customerRegion = getCustomerRegion(customerId);
        String customerType = getCustomerType(customerId);

        if (isRateLimited(customerId)) {
            logger.warning("Transaction rate limit exceeded for customer: " + customerId);
            return false;
        }

        try {
            paymentGateway.processPayment(cardInfo, amount);
            updateTransactionCount(customerId);
            logTransactionEvent(customerId, amount, "SUCCESS");
            applyCustomRules(customerRegion, customerType, amount);
            return true;
        } catch (Exception e) {
            handlePaymentFailure(customerId, amount);
            logger.severe("Payment failed: " + e.getMessage());
            return false;
        }
    }

    private boolean validateCreditCard(CreditCardInfo cardInfo) {
        // Implement credit card validation logic here
        return true;
    }

    private String getCustomerRegion(String customerId) {
        return customerRegionMapping.getOrDefault(customerId, "UNKNOWN");
    }

    private String getCustomerType(String customerId) {
        return customerTypeMapping.getOrDefault(customerId, "UNKNOWN");
    }

    private boolean isRateLimited(String customerId) {
        int currentCount = transactionRateLimits.getOrDefault(customerId, 0);
        if (currentCount >= 10) { // Example limit
            return true;
        }
        transactionRateLimits.put(customerId, currentCount + 1);
        return false;
    }

    private void updateTransactionCount(String customerId) {
        int count = transactionRateLimits.getOrDefault(customerId, 0);
        transactionRateLimits.put(customerId, count + 1);
    }

