```csharp
using System;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text.Json;
using System.Threading.Tasks;

public class ApiClient
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<ApiClient> _logger;

    public ApiClient(HttpClient httpClient, ILogger<ApiClient> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> CallApiAsync(string url, Dictionary<string, string> headers)
    {
        if (string.IsNullOrEmpty(url))
            throw new ArgumentException("The URL cannot be null or empty.", nameof(url));

        var handler = new HttpClientHandler
        {
            AllowAutoRedirect = false,
            UseCookies = false
        };

        for (int attempt = 0; attempt < 4; attempt++)
        {
            try
            {
                using (var client = new HttpClient(handler))
                {
                    foreach (var header in headers)
                    {
                        client.DefaultRequestHeaders.Add(header.Key, header.Value);
                    }

                    var response = await client.GetAsync(url);

                    if (!response.IsSuccessStatusCode)
                    {
                        _logger.LogWarning("API call failed with status code: {StatusCode}", response.StatusCode);
                        continue;
                    }

                    return await response.Content.ReadAsStringAsync();
                }
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "HTTP request error on attempt {Attempt}.", attempt + 1);

                if (attempt == 3) throw; // Rethrow after last retry

                await Task.Delay((int)Math.Pow(2, attempt) * 100); // Exponential backoff
            }
        }

        _logger.LogError("API is unreachable after {Attempts} retries.", 4);
        return null;
    }
}
