use std::env;
use std::fs;
use std::path::PathBuf;
use log::{info, error};
use simple_logger::SimpleLogger;

fn initialize_logging(log_dir: &str, log_file_name: &str, append_mode: bool, log_level: log::LevelFilter) -> Result<(), Box<dyn std::error::Error>> {
    // Check if LOG_DIR is already set
    let mut log_path = env::var("LOG_DIR").unwrap_or_else(|_| String::new());

    if log_path.is_empty() {
        // Create a new directory at the user-specified location
        log_path = format!("{}/logs", log_dir);
        fs::create_dir_all(&log_path)?;
    } else {
        log_path = log_dir.to_string();
    }

    // Ensure that the log directory has write permissions for the current process
    fs::set_permissions(&log_path, fs::Permissions::from_mode(0o755))?;

    // Create a log file within the log directory
    let log_file_path = PathBuf::from(log_path).join(log_file_name);
    if append_mode {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .append(true)
            .create(true)
            .open(&log_file_path)?;
        file.write_all(b"Log file started\n")?;
    } else {
        fs::File::create(log_file_path)?;
    }

    // Configure a logging system to use this log file
    SimpleLogger::new()
        .with_level(log_level)
        .init()?;

    info!("Logging initialized at {:?}", &log_path);
    Ok(())
}

fn cleanup_logging() {
    // Placeholder for any necessary cleanup code
    info!("Cleaning up resources");
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    initialize_logging("/tmp", "app.log", true, log::LevelFilter::Debug)?;
    // Your application logic here
    cleanup_logging();
    Ok(())
}
