using System;
using System.Security.Cryptography;
using System.Text;

public class MD5HashGenerator
{
    private static readonly byte[] Salt = Encoding.UTF8.GetBytes("your-salt-here");

    public string GenerateMD5Hash(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        using (var md5 = MD5.Create())
        {
            var combined = Encoding.UTF8.GetBytes(Salt).Concat(Encoding.UTF8.GetBytes(input)).ToArray();
            var hashBytes = md5.ComputeHash(combined);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public string GenerateMD5Hash(string[] inputs)
    {
        if (inputs == null || inputs.Length == 0)
            throw new ArgumentException("Inputs array cannot be null or empty", nameof(inputs));

        using (var md5 = MD5.Create())
        {
            var combined = inputs.SelectMany(i => Encoding.UTF8.GetBytes(Salt).Concat(Encoding.UTF8.GetBytes(i))).ToArray();
            var hashBytes = md5.ComputeHash(combined);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public string GenerateMD5Hash(string input, byte[] salt)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        if (salt == null || salt.Length == 0)
            throw new ArgumentException("Salt cannot be null or empty", nameof(salt));

        using (var md5 = MD5.Create())
        {
            var combined = salt.Concat(Encoding.UTF8.GetBytes(input)).ToArray();
            var hashBytes = md5.ComputeHash(combined);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }
}
