    public void TestGenerateMD5Hash()
    {
        var generator = new MD5HashGenerator();

        string input1 = "Hello, world!";
        string expected1 = "3e25960a79dbc69b674cd4ec67a72c62";

        string input2 = null;
        Assert.ThrowsException<ArgumentException>(() => generator.GenerateMD5Hash(input2));

        string[] inputs = { "Hello, ", "world!", "" };
        string expected3 = "d41d8cd98f00b204e9800998ecf8427e";

        string inputWithSalt = "Test";
        byte[] salt = Encoding.UTF8.GetBytes("custom-salt");
        string expected4 = "d65a3102c368f658b3ba11f9e8c0f67a";

        Assert.AreEqual(expected1, generator.GenerateMD5Hash(input1));
        Assert.AreEqual(expected3, generator.GenerateMD5Hash(inputs));
        Assert.AreEqual(expected4, generator.GenerateMD5Hash(inputWithSalt, salt));
    }
}
