        for key, value in user_data.items():
            if isinstance(value, str) and '@' in value:
                user_data[key] = bcrypt.hashpw(value.encode('utf-8'), bcrypt.gensalt())
        return user_data

    def generate_random_graph(self, num_vertices, num_edges, vertex_range, edge_range):
        vertices = []
        for _ in range(num_vertices):
            properties = {f'prop_{i}': random.uniform(*vertex_range) for i in range(1, 4)}
            vertices.append(properties)

        edges = []
        for _ in range(num_edges):
            properties = {f'prop_{i}': random.uniform(*edge_range) for i in range(1, 3)}
            edges.append((random.choice(vertices), random.choice(vertices), properties))

        return vertices, edges

