class PageUpdater {
private:
    static std::mutex mutex_;
    static std::unordered_map<int, int> cacheVersion_;

public:
    static bool handlePOSTRequest(std::forward_list<std::string>& pageContent, int sectionID, int elementID, const std::string& htmlContent) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = std::find(pageContent.begin(), pageContent.end(), "section_id:" + std::to_string(sectionID));
        if (it != pageContent.end()) {
            pageContent.insert_after(it, "<!-- section_start:inserted_html -->" + htmlContent + "<!-- section_end:inserted_html -->");
            int currentVersion = cacheVersion_[sectionID];
            ElementService::updateElementAsync(elementID, htmlContent, std::atomic<bool>& successFlag);
            if (successFlag.load()) {
                cacheVersion_[sectionID] = currentVersion + 1;
                return true; // Refresh page
            } else {
                std::cerr << "Failed to update element " << elementID << std::endl;
                return false;
            }
        } else {
            pageContent.push_back("<!-- section_start:inserted_html -->" + htmlContent + "<!-- section_end:inserted_html -->");
            int currentVersion = cacheVersion_[sectionID];
            ElementService::updateElementAsync(elementID, htmlContent, std::atomic<bool>& successFlag);
            if (successFlag.load()) {
                cacheVersion_[sectionID] = currentVersion + 1;
                return true; // Refresh page
            } else {
                std::cerr << "Failed to update element " << elementID << std::endl;
                return false;
            }
        }
    }
};

std::mutex PageUpdater::mutex_;
std::unordered_map<int, int> PageUpdater::cacheVersion_;

