    async fn request<U>(&self, url: U) -> Result<Request<Body>, Box<dyn std::error::Error>>
    where
        U: TryInto<Uri>,
    {
        let uri = url.try_into()?;
        let mut builder = Request::builder().uri(uri);

        // Lock the rate limiter to prevent concurrent modifications
        let mut rate_limiter = self.rate_limiter.lock().await;
        while !rate_limiter.can_request() {
            tokio::time::sleep(rate_limiter.next_interval()).await;
        }
        rate_limiter.request();

        Ok(builder.method("GET").body(Body::empty())?)
    }

    async fn make_request<U>(&self, url: U) -> Result<String, Box<dyn std::error::Error>>
    where
        U: TryInto<Uri>,
    {
        let request = self.request(url).await?;
        let response = self.client.request(request).await?;

        if !response.status().is_success() {
            return Err(format!("Failed to make request: {}", response.status()).into());
        }

        let body = hyper::body::to_bytes(response.into_body()).await?;
        Ok(String::from_utf8(body.to_vec())?)
    }
}

struct RateLimiter {
    last_request_time: Instant,
    interval: Duration,
    max_requests_per_interval: u32,
    request_count: u32,
}

impl RateLimiter {
    fn new() -> Self {
        RateLimiter {
            last_request_time: Instant::now(),
            interval: Duration::from_secs(1),
            max_requests_per_interval: 5,
            request_count: 0,
        }
    }

    fn can_request(&self) -> bool {
        let now = Instant::now();
        if now.duration_since(self.last_request_time) >= self.interval {
            self.request_count = 0;
            true
        } else {
            self.request_count < self.max_requests_per_interval
        }
    }

    fn request(&mut self) {
        self.request_count += 1;
        if self.request_count == self.max_requests_per_interval {
            let time_since_last_request = Instant::now().duration_since(self.last_request_time);
            let remaining_time = self.interval - time_since_last_request;
            tokio::time::sleep(remaining_time).await;
            self.last_request_time = Instant::now();
        }
    }

    fn next_interval(&self) -> Duration {
        if self.request_count == self.max_requests_per_interval {
            self.interval - Instant::now().duration_since(self.last_request_time)
        } else {
            Duration::from_secs(0)
        }
    }
}

