public class ServiceManager {

    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(10);
    private Random random = new Random();

    public void startService(String serviceName, int delay) {
        long initialDelay = delay + random.nextInt(delay);
        scheduler.schedule(() -> runService(serviceName), initialDelay, TimeUnit.MILLISECONDS);
    }

    public void stopService(String serviceName) {
        // Implement logic to gracefully stop the service
    }

    private void runService(String serviceName) {
        try {
            System.out.println("Starting " + serviceName);
            simulateServiceOperation();
            System.out.println("Completed " + serviceName);
        } catch (Exception e) {
            System.err.println("Failed " + serviceName + ": " + e.getMessage());
        }
    }

    private void simulateServiceOperation() throws InterruptedException {
        // Simulate service operation with random duration and potential failures
        int duration = 1000 + random.nextInt(2000);
        if (random.nextDouble() < 0.1) {
            throw new RuntimeException("Simulated service failure");
        }
        Thread.sleep(duration);
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        manager.startService("service1", 5000);
        manager.startService("service2", 3000);
    }
}
