#include <iostream>
#include <filesystem>
#include <thread>
#include <vector>
#include <queue>
#include <future>
#include <mutex>
#include <condition_variable>
#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>

namespace beast = boost::beast;
namespace http = beast::http;
namespace net = boost::asio;

using tcp = net::ip::tcp;

class FileProcessor {
public:
    explicit FileProcessor(const std::string& directory, const std::string& apiUrl)
        : directory(directory), apiUrl(apiUrl) {}

    void start() {
        threadPool.reserve(numThreads);
        for (size_t i = 0; i < numThreads; ++i) {
            threadPool.emplace_back(&FileProcessor::processFiles, this);
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stopFlag = true;
        }
        cv.notify_all();
        for (auto& thread : threadPool) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    static constexpr size_t numThreads = 4;
    std::string directory;
    std::string apiUrl;
    std::vector<std::thread> threadPool;
    std::queue<std::string> fileQueue;
    std::mutex mutex;
    std::condition_variable cv;
    bool stopFlag = false;

    void processFiles() {
        while (true) {
            std::string filePath;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !fileQueue.empty() || stopFlag; });
                if (stopFlag && fileQueue.empty()) {
                    return;
                }
                filePath = fileQueue.front();
                fileQueue.pop();
            }

            try {
                std::ifstream file(filePath);
                std::string line;
                while (std::getline(file, line)) {
                    sendPostRequest(line);
                }
            } catch (const std::exception& e) {
                // Log error
                std::cerr << "Error processing file: " << filePath << ", exception: " << e.what() << std::endl;
            }
        }
    }

    void sendPostRequest(const std::string& data) {
        net::io_context ioc;
        tcp::resolver resolver(ioc);
        http::request<http::string_body> req{http::verb::post, apiUrl, 11};
        req.set(http::field::host, "example.com");
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        req.body() = data;
        req.prepare_payload();

        net::ssl::context ctx(net::ssl::context::tlsv12_client);
        ctx.set_default_verify_paths();

        auto const results = resolver.resolve("example.com", "https");
        tcp_stream stream(ioc, ctx);
        net::connect(stream.next_layer(), results.begin(), results.end());
        stream.handshake(net::ssl::stream_base::client);

        http::write(stream, req);
        http::response<http::string_body> res;
        http::read(stream, buffer, res);

        // Log response or error
    }
};

int main() {
    FileProcessor processor("/path/to/directory", "https://api.example.com/endpoint");
    processor.start();
    // Simulate running for some time
    std::this_thread::sleep_for(std::chrono::seconds(60));
    processor.stop();
    return 0;
}
```

This code provides a basic framework for processing text files asynchronously using the Boost library. It uses a thread pool to handle multiple file processing tasks concurrently and sends POST requests to an external API using the Sandesh client approach. The `FileProcessor` class manages the file queue, error handling, and thread synchronization. The `sendPostRequest` function demonstrates how to create and send HTTP POST requests using Boost.Beast.

