#include <string>
#include <stdexcept>
#include <mutex>

class StringAppender {
public:
    StringAppender(const std::string& appendSequence)
        : m_appendSequence(appendSequence) {}

    std::string appendToBuffer(const std::string& input, size_t bufferSize) const {
        if (bufferSize == 0) {
            throw std::invalid_argument("Buffer size must be greater than 0.");
        }

        std::lock_guard<std::mutex> lock(m_mutex);

        std::string result = input;
        size_t appendLength = m_appendSequence.length();
        if (result.length() + appendLength > bufferSize - 1) {
            throw std::length_error("Appended sequence would exceed buffer size.");
        }

        result.append(m_appendSequence);
        return result;
    }

private:
    const std::string m_appendSequence;
    mutable std::mutex m_mutex;
};
