```rust
use std::sync::{Arc, Mutex};
use std::thread;
use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use nix::sys::resource::{Resource, ResourceKind, setrlimit, Rlim, Rlims};
use log::{error, info, debug};

struct CompilationTask {
    source_file: String,
    max_memory_usage: usize,
}

enum CompilationResult {
    Success,
    TransientFailure,
    PersistentFailure,
}

fn compile_task(task: CompilationTask) -> CompilationResult {
    let start_time = Instant::now();
    let mut child = Command::new("cargo")
        .arg("build")
        .arg(&task.source_file)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("Failed to execute command");

    match child.wait() {
        Ok(status) if status.success() => {
            info!("Task {} completed successfully", task.source_file);
            CompilationResult::Success
        }
        _ => {
            error!("Task {} failed", task.source_file);
            CompilationResult::TransientFailure
        }
    }
}

fn compile_tasks(tasks: Vec<CompilationTask>, max_concurrent_tasks: usize, max_memory_usage_per_task: usize) {
    let tasks = Arc::new(Mutex::new(tasks));
    let mut handles = vec![];

    for _ in 0..max_concurrent_tasks {
        let tasks_clone = Arc::clone(&tasks);
        let handle = thread::spawn(move || loop {
            let task = {
                let mut tasks_lock = tasks_clone.lock().unwrap();
                if let Some(task) = tasks_lock.pop() {
                    task
                } else {
                    break;
                }
            };

            match compile_task(task) {
                CompilationResult::Success => continue,
                CompilationResult::TransientFailure => {
                    let mut tasks_lock = tasks_clone.lock().unwrap();
                    tasks_lock.push(task);
                }
                CompilationResult::PersistentFailure => {
                    error!("Task {} has persistent failure", task.source_file);
                }
            }

            // Retry logic here
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let total_time = Instant::now() - start_time;
    info!("Total compilation time: {:?}", total_time);
}

fn main() {
    let tasks = vec![
        CompilationTask {
            source_file: "src/main.rs".to_string(),
            max_memory_usage: 256,
        },
        // Add more tasks as needed
    ];

    compile_tasks(tasks, 4, 256);
}
```

This code snippet provides a basic structure for the Rust function described in the task. It includes error handling for task failures and demonstrates how to use threads for concurrent compilation. However, it does not include detailed features such as resource management, logging hooks, or platform-specific adaptations. The provided code is intended to serve as a starting point for further development.

