using System;
using System.Collections.Generic;
using System.Linq;

public class NetworkSimulator
{
    private Random random = new Random();
    private Dictionary<int, Node> nodes = new Dictionary<int, Node>();
    private List<Connection> connections = new List<Connection>();

    public int MinNodeId { get; set; }
    public int MaxNodeId { get; set; }
    public float MinCoordinate { get; set; }
    public float MaxCoordinate { get; set; }
    public int MinWeight { get; set; }
    public int MaxWeight { get; set; }

    public NetworkSimulator(int minNodeId, int maxNodeId, float minCoordinate, float maxCoordinate, int minWeight, int maxWeight)
    {
        if (minNodeId >= maxNodeId || minCoordinate >= maxCoordinate || minWeight >= maxWeight)
            throw new ArgumentException("Invalid range values.");

        MinNodeId = minNodeId;
        MaxNodeId = maxNodeId;
        MinCoordinate = minCoordinate;
        MaxCoordinate = maxCoordinate;
        MinWeight = minWeight;
        MaxWeight = maxWeight;
    }

    public void AddNode()
    {
        int nodeId = random.Next(MinNodeId, MaxNodeId + 1);
        Node node = new Node(nodeId, random.NextFloat(MinCoordinate, MaxCoordinate), random.NextFloat(MinCoordinate, MaxCoordinate));
        nodes[nodeId] = node;
    }

    public void AddConnection(int sourceId, int targetId)
    {
        if (!nodes.ContainsKey(sourceId) || !nodes.ContainsKey(targetId))
            throw new ArgumentException("Node IDs are out of range.");

        int weight = random.Next(MinWeight, MaxWeight + 1);
        Connection connection = new Connection(nodes[sourceId], nodes[targetId], weight);
        connections.Add(connection);
    }

    public float NextFloat(float min, float max)
    {
        return (float)random.NextDouble() * (max - min) + min;
    }

    public void CalculateMetrics()
    {
        // Implement metric calculations
    }

    public override string ToString()
    {
        var metrics = new Dictionary<string, double>
        {
            { "Average Path Length", 0.0 },
            { "Clustering Coefficient", 0.0 },
            { "Degree Distribution", 0.0 }
        };

        return $"Node ID Range: [{MinNodeId}, {MaxNodeId}], Coordinate Range: [{MinCoordinate}, {MaxCoordinate}], Weight Range: [{MinWeight}, {MaxWeight}]" +
               $"\nNetwork Metrics: {string.Join(", ", metrics.Select(kv => $"{kv.Key}: {kv.Value}"))}";
    }
}

