```java
import org.mindrot.jbcrypt.BCrypt;
import java.security.SecureRandom;

public class PasswordHasher {

    private static final int BCRYPT_WORK_FACTOR = 12;

    public static String hashPassword(String password, byte[] salt) {
        if (salt == null || salt.length == 0) {
            salt = generateSalt();
        }
        return BCrypt.hashpw(password, BCrypt.gensalt(BCRYPT_WORK_FACTOR, new SecureRandom(salt)));
    }

    private static byte[] generateSalt() {
        byte[] salt = new byte[16];
        new SecureRandom().nextBytes(salt);
        return salt;
    }

    public static boolean verifyPassword(String password, String storedHash) {
        try {
            return BCrypt.checkpw(password, storedHash);
        } catch (Exception e) {
            // Handle exception gracefully
            System.err.println("Error verifying password: " + e.getMessage());
            return false;
        }
    }

    public static void main(String[] args) {
        String password = "userPassword123";
        byte[] salt = generateSalt();
        String hashedPassword = hashPassword(password, null);
        System.out.println("Hashed Password: " + hashedPassword);

        boolean isVerified = verifyPassword(password, hashedPassword);
        System.out.println("Verification Result: " + isVerified);
    }
}
