import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class NamedEntityExtractor {

    private static final String[] IGNORED_WORDS = {"the", "of", "and", "in", "with", "on"};
    private static final String API_URL = "https://api.namedentityrecognition.com";

    public Map<String, Integer> extractNamedEntities(String filePath, Pattern... entityPatterns) {
        Map<String, Integer> entityCounts = new HashMap<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                for (Pattern pattern : entityPatterns) {
                    Matcher matcher = pattern.matcher(line.toLowerCase());
                    while (matcher.find()) {
                        String entity = matcher.group().trim();
                        if (!isIgnoredWord(entity)) {
                            entityCounts.put(entity, entityCounts.getOrDefault(entity, 0) + 1);
                        }
                    }
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading file: " + e.getMessage());
        }

        // Fallback to local processing if API is unavailable
        if (entityCounts.isEmpty()) {
            for (Pattern pattern : entityPatterns) {
                try {
                    BufferedReader reader = new BufferedReader(new FileReader(filePath));
                    String line;
                    while ((line = reader.readLine()) != null) {
                        Matcher matcher = pattern.matcher(line.toLowerCase());
                        while (matcher.find()) {
                            String entity = matcher.group().trim();
                            if (!isIgnoredWord(entity)) {
                                entityCounts.put(entity, entityCounts.getOrDefault(entity, 0) + 1);
                            }
                        }
                    }
                    reader.close();
                } catch (IOException e) {
                    System.err.println("Error reading file: " + e.getMessage());
                }
            }
        }

        return entityCounts;
    }

    private boolean isIgnoredWord(String word) {
        for (String ignored : IGNORED_WORDS) {
            if (word.equalsIgnoreCase(ignored)) {
                return true;
            }
        }
        return false;
    }

    // Example usage
    public static void main(String[] args) {
        NamedEntityExtractor extractor = new NamedEntityExtractor();
        String filePath = "path/to/your/file.txt";

        Pattern personPattern = Pattern.compile("\\b[A-Z][a-z]+\\b");
        Pattern organizationPattern = Pattern.compile("\\b[A-Z][a-z]*\\b");

        Map<String, Integer> entityCounts = extractor.extractNamedEntities(filePath, personPattern, organizationPattern);
        System.out.println(entityCounts);
    }
}
