import org.eclipse.jgit.api.*;
import org.eclipse.jgit.lib.Repository;
import java.io.File;
import java.io.IOException;

public class GitRepositoryManager {

    private static final String CACHE_DIR = "repository_cache";

    public void manageGitRepository(String repositoryUrl, String branchName) {
        try {
            File cacheDir = new File(CACHE_DIR);
            if (!cacheDir.exists()) {
                cacheDir.mkdirs();
            }

            // Check if the repository is already cloned
            File localRepoDir = findLocalRepo(cacheDir, repositoryUrl);
            Repository repo;
            if (localRepoDir != null) {
                repo = Git.open(localRepoDir);
            } else {
                // Clone the repository
                repo = Git.cloneRepository()
                        .setURI(repositoryUrl)
                        .setDirectory(new File(cacheDir, extractRepoName(repositoryUrl)))
                        .call();
                System.out.println("Cloned repository: " + repo.getDirectory());
            }

            // Checkout branch
            Git git = new Git(repo);
            git.checkout().setName(branchName).call();
            System.out.println("Switched to branch: " + branchName);

            // Pull latest changes
            git.pull().call();
            System.out.println("Pulled latest changes");

        } catch (GitAPIException | IOException e) {
            System.err.println("Error managing Git repository: " + e.getMessage());
        }
    }

    private File findLocalRepo(File cacheDir, String repositoryUrl) {
        for (File repoDir : cacheDir.listFiles()) {
            try {
                Repository repo = Git.open(repoDir);
                if (repo.getConfig().getString("remote", "origin", "url").equals(repositoryUrl)) {
                    return repoDir;
                }
            } catch (IOException e) {
                // Ignore and continue
            }
        }
        return null;
    }

    private String extractRepoName(String repositoryUrl) {
        int lastSlashIndex = repositoryUrl.lastIndexOf("/");
        int fileExtensionIndex = repositoryUrl.lastIndexOf(".");
        return repositoryUrl.substring(lastSlashIndex + 1, fileExtensionIndex);
    }

    public static void main(String[] args) {
        GitRepositoryManager manager = new GitRepositoryManager();
        manager.manageGitRepository("https://github.com/user/repo.git", "feature-branch");
    }
}
