#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define DEFAULT_BUFFER_SIZE 1024

typedef struct {
    int* array;
    size_t length;
    size_t capacity;
} IntegerArray;

void initIntegerArray(IntegerArray* arr) {
    arr->array = NULL;
    arr->length = 0;
    arr->capacity = 0;
}

void resizeIntegerArray(IntegerArray* arr, size_t new_capacity) {
    int* new_array = realloc(arr->array, new_capacity * sizeof(int));
    if (new_array == NULL) {
        perror("Failed to resize integer array");
        exit(EXIT_FAILURE);
    }
    arr->array = new_array;
    arr->capacity = new_capacity;
}

void appendToIntegerArray(IntegerArray* arr, int value) {
    if (arr->length >= arr->capacity) {
        size_t new_capacity = arr->capacity > 0 ? arr->capacity * 2 : DEFAULT_BUFFER_SIZE;
        resizeIntegerArray(arr, new_capacity);
    }
    arr->array[arr->length++] = value;
}

void freeIntegerArray(IntegerArray* arr) {
    free(arr->array);
    arr->array = NULL;
    arr->length = 0;
    arr->capacity = 0;
}

int findLargestInteger(const IntegerArray* arr) {
    if (arr->length == 0) {
        fprintf(stderr, "Array is empty\n");
        exit(EXIT_FAILURE);
    }
    int largest = arr->array[0];
    for (size_t i = 1; i < arr->length; i++) {
        if (arr->array[i] > largest) {
            largest = arr->array[i];
        }
    }
    return largest;
}

void processNetworkData(int sockfd, IntegerArray* arr, size_t buffer_size) {
    char buffer[buffer_size];
    ssize_t bytes_received;
    int value;

    while ((bytes_received = recv(sockfd, buffer, buffer_size, 0)) > 0) {
        for (ssize_t i = 0; i < bytes_received; i++) {
            if (buffer[i] >= '0' && buffer[i] <= '9') {
                value = 0;
                while (i < bytes_received && buffer[i] >= '0' && buffer[i] <= '9') {
                    value = value * 10 + (buffer[i] - '0');
                    i++;
                }
                appendToIntegerArray(arr, value);
            } else if (buffer[i] == '\n') {
                break;
            }
        }
    }

    if (bytes_received < 0) {
        perror("Failed to receive data from network");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to connect to server");
        close(sockfd);
        return EXIT_FAILURE;
    }

    IntegerArray arr;
    initIntegerArray(&arr);

    size_t buffer_size = DEFAULT_BUFFER_SIZE;
    processNetworkData(sockfd, &arr, buffer_size);

    int largest_value = findLargestInteger(&arr);
    printf("Largest integer: %d\n", largest_value);

    freeIntegerArray(&arr);
    close(sockfd);

    return EXIT_SUCCESS;
}
