import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.File;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;

public class GameConfigLoader {

    private static final String DEFAULT_CONFIG_URL = "https://api.example.com/default_config.json";
    private static GameConfig config;

    public static void main(String[] args) {
        loadConfigAsync();
        // The game loop would use the values from GameConfig
    }

    public static void loadConfigSync() {
        try {
            File configFile = new File("config.json");
            if (configFile.exists()) {
                ObjectMapper mapper = new ObjectMapper();
                config = mapper.readValue(configFile, GameConfig.class);
                validateConfig(config);
            } else {
                System.out.println("No local configuration file found. Fetching default settings from API...");
                fetchDefaultConfig();
            }
        } catch (IOException e) {
            System.err.println("Error loading or parsing the configuration file: " + e.getMessage());
            // Optionally, fall back to a predefined set of defaults
        }
    }

    public static void loadConfigAsync() {
        CompletableFuture.runAsync(() -> {
            try {
                File configFile = new File("config.json");
                if (configFile.exists()) {
                    ObjectMapper mapper = new ObjectMapper();
                    config = mapper.readValue(configFile, GameConfig.class);
                    validateConfig(config);
                } else {
                    System.out.println("No local configuration file found. Fetching default settings from API...");
                    fetchDefaultConfigAsync();
                }
            } catch (IOException e) {
                System.err.println("Error loading or parsing the configuration file: " + e.getMessage());
                // Optionally, fall back to a predefined set of defaults
            }
        });
    }

    private static void validateConfig(GameConfig config) throws IOException {
        if (config.getGameWorld().getWidth() <= 0 || config.getGameWorld().getHeight() <= 0) {
            throw new IllegalArgumentException("Invalid game world dimensions");
        }
        for (GameObject obj : config.getObjects()) {
            if (obj.getInitialPosition().getX() < 0 || obj.getInitialPosition().getY() < 0 ||
                obj.getVelocity().getSpeed() <= 0) {
                throw new IllegalArgumentException("Invalid object initial position or velocity");
            }
        }
    }

    private static void fetchDefaultConfig() throws IOException {
        // Fetch default config from the API
        GameConfig defaultConfig = new ObjectMapper().readValue(DEFAULT_CONFIG_URL, GameConfig.class);
        validateConfig(defaultConfig);
        config = defaultConfig;
    }

    private static void fetchDefaultConfigAsync() {
        CompletableFuture.runAsync(() -> {
            try {
                GameConfig defaultConfig = new ObjectMapper().readValue(DEFAULT_CONFIG_URL, GameConfig.class);
                validateConfig(defaultConfig);
                config = defaultConfig;
            } catch (IOException e) {
                System.err.println("Error fetching default configuration from API: " + e.getMessage());
                // Optionally, fall back to a predefined set of defaults
            }
        });
    }

    public static class GameConfig {
        private GameWorld gameWorld;
        private List<GameObject> objects;
        private int frameRateLimit;

        // Getters and setters
        public GameWorld getGameWorld() { return gameWorld; }
        public void setGameWorld(GameWorld gameWorld) { this.gameWorld = gameWorld; }

        public List<GameObject> getObjects() { return objects; }
        public void setObjects(List<GameObject> objects) { this.objects = objects; }

        public int getFrameRateLimit() { return frameRateLimit; }
        public void setFrameRateLimit(int frameRateLimit) { this.frameRateLimit = frameRateLimit; }
    }

    public static class GameWorld {
        private int width;
        private int height;

        // Getters and setters
        public int getWidth() { return width; }
        public void setWidth(int width) { this.width = width; }

        public int getHeight() { return height; }
        public void setHeight(int height) { this.height = height; }
    }

    public static class GameObject {
        private Position initialPosition;
        private Velocity velocity;

        // Getters and setters
        public Position getInitialPosition() { return initialPosition; }
        public void setInitialPosition(Position initialPosition) { this.initialPosition = initialPosition; }

        public Velocity getVelocity() { return velocity; }
        public void setVelocity(Velocity velocity) { this.velocity = velocity; }
    }

    public static class Position {
        private int x;
        private int y;

        // Getters and setters
        public int getX() { return x; }
        public void setX(int x) { this.x = x; }

        public int getY() { return y; }
        public void setY(int y) { this.y = y; }
    }

    public static class Velocity {
        private double speed;
        // Other properties and methods

        // Getters and setters
        public double getSpeed() { return speed; }
        public void setSpeed(double speed) { this.speed = speed; }
    }
}
