# Java code for managing a fleet of background services
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(Runtime.getRuntime().availableProcessors());

    public void startServices(List<Runnable> services) {
        for (int i = 0; i < services.size(); i++) {
            int delay = (i * 10) + ThreadLocalRandom.current().nextInt(5); // Delay between 5 and 15 seconds
            scheduler.schedule(services.get(i), delay, TimeUnit.SECONDS);
        }
    }

    public void stopServices() {
        scheduler.shutdown();
    }

    public static void main(String[] args) {
        List<Runnable> services = new ArrayList<>();
        services.add(() -> System.out.println("Service 1 running"));
        services.add(() -> System.out.println("Service 2 running"));

        ServiceManager manager = new ServiceManager();
        manager.startServices(services);

        // Simulate graceful shutdown
        try {
            Thread.sleep(30000); // Run for 30 seconds
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        manager.stopServices();
    }
}
