import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.security.KeyStore;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ServerConnector {

    private final ExecutorService executorService;
    private final AsynchronousChannelGroup channelGroup;
    private final KeyStore keyStore;

    public ServerConnector(String keystorePath, String keystorePassword) throws Exception {
        this.keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        this.keyStore.load(new java.io.FileInputStream(keystorePath), keystorePassword.toCharArray());

        this.executorService = Executors.newCachedThreadPool();
        this.channelGroup = AsynchronousChannelGroup.withFixedThreadPool(10, executorService);
    }

    public void connect(String host, int port) {
        try (AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(channelGroup)) {
            InetSocketAddress serverAddress = new InetSocketAddress(host, port);

            channel.connect(serverAddress, null, new CompletionHandler<Void, Object>() {

                @Override
                public void completed(Void result, Object attachment) {
                    System.out.println("Connection established successfully.");
                    // Proceed with authentication and data transmission here.
                }

                @Override
                public void failed(Throwable exc, Object attachment) {
                    if (exc instanceof IOException && "ECONNREFUSED".equals(((IOException) exc).getMessage())) {
                        System.err.println("Connection refused. Retrying...");
                        connect(host, port);
                    } else {
                        System.err.println("Failed to establish connection: " + exc.getMessage());
                    }
                }
            });
        } catch (Exception e) {
            System.err.println("Error initializing channel group or connecting: " + e.getMessage());
        }
    }

    // Method for sending data
    public void sendData(AsynchronousSocketChannel channel, byte[] data) {
        ByteBuffer buffer = ByteBuffer.wrap(data);
        channel.write(buffer, null, new CompletionHandler<Integer, Object>() {

            @Override
            public void completed(Integer result, Object attachment) {
                System.out.println("Data sent successfully.");
                // Handle post-send operations here.
            }

            @Override
            public void failed(Throwable exc, Object attachment) {
                System.err.println("Failed to send data: " + exc.getMessage());
            }
        });
    }

    // Method for receiving data
    public void receiveData(AsynchronousSocketChannel channel) {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        channel.read(buffer, null, new CompletionHandler<Integer, Object>() {

            @Override
            public void completed(Integer result, Object attachment) {
                if (result == -1) {
                    System.out.println("Connection closed by remote server.");
                } else {
                    buffer.flip();
                    byte[] data = new byte[buffer.remaining()];
                    buffer.get(data);
                    System.out.println("Received data: " + new String(data));
                    receiveData(channel); // Continue receiving
                }
            }

            @Override
            public void failed(Throwable exc, Object attachment) {
                System.err.println("Failed to receive data: " + exc.getMessage());
            }
        });
    }

    // Close resources
    public void close() {
        channelGroup.shutdown();
        executorService.shutdown();
    }

    public static void main(String[] args) {
        try {
            ServerConnector connector = new ServerConnector("path/to/keystore", "password");
            connector.connect("remote.server.host", 12345);
            // Simulate sending and receiving data
            byte[] testData = "Hello, server!".getBytes();
            connector.sendData(connector.channel, testData);
            connector.receiveData(connector.channel);
        } catch (Exception e) {
            System.err.println("Main method error: " + e.getMessage());
        }
    }
}
```

This Java code snippet demonstrates how to establish a connection to a remote server using Java NIO Channels. It includes methods for connecting, sending data, and receiving data with appropriate handling of failures and retries. The solution uses an asynchronous channel group and custom completion handlers to manage connections efficiently. The code is designed to be modular, easy to maintain, and can be extended with more complex authentication and data integrity mechanisms as needed.

