    int id;
    double weighted_sum;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction buffer[TRANSACTION_BUFFER_SIZE];
    int front, rear, size;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty, not_full;
} TransactionQueue;

void init_transaction_queue(TransactionQueue *queue) {
    queue->front = queue->rear = queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
}

int enqueue_transaction(TransactionQueue *queue, Transaction transaction) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == TRANSACTION_BUFFER_SIZE) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    queue->buffer[queue->rear] = transaction;
    queue->rear = (queue->rear + 1) % TRANSACTION_BUFFER_SIZE;
    queue->size++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int dequeue_transaction(TransactionQueue *queue, Transaction *transaction) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    *transaction = queue->buffer[queue->front];
    queue->front = (queue->front + 1) % TRANSACTION_BUFFER_SIZE;
    queue->size--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

void process_transaction(TransactionQueue *queue, int transaction_count_limit, double weighted_sum_threshold) {
    Transaction highest_weighted_transaction;
    highest_weighted_transaction.id = -1;
    highest_weighted_transaction.weighted_sum = 0.0;

    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        Transaction transaction;
        if (dequeue_transaction(queue, &transaction) == 0) {
            if ((time(NULL) - transaction.timestamp) <= 60 && i <= transaction_count_limit && transaction.weighted_sum > weighted_sum_threshold) {
                if (highest_weighted_transaction.weighted_sum < transaction.weighted_sum) {
                    highest_weighted_transaction = transaction;
                }
            }
        }
    }

    printf("Highest Weighted Transaction ID: %d, Weighted Sum: %.2f\n", highest_weighted_transaction.id, highest_weighted_transaction.weighted_sum);
}

void *transaction_processor(void *arg) {
    TransactionQueue *queue = (TransactionQueue *)arg;
    int transaction_count_limit = *(int *)malloc(sizeof(int));
    double weighted_sum_threshold = *(double *)malloc(sizeof(double));

    // Simulate dynamic threshold adjustment
    *transaction_count_limit = 500;
    *weighted_sum_threshold = 1000.0;

    process_transaction(queue, *transaction_count_limit, *weighted_sum_threshold);

    free(transaction_count_limit);
    free(weighted_sum_threshold);
    return NULL;
}

int main() {
    TransactionQueue queue;
    init_transaction_queue(&queue);

    pthread_t threads[5];
    int transaction_count_limits[5] = {500, 700, 400, 600, 300};
    double weighted_sum_thresholds[5] = {1000.0, 1200.0, 900.0, 1100.0, 800.0};

    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, transaction_processor, &queue);
    }

    // Simulate transaction processing
    for (int i = 0; i < MAX_TRANSACTIONS * 2; i++) {
        Transaction transaction;
        transaction.id = i + 1;
        transaction.weighted_sum = rand() % 5000;
        transaction.timestamp = time(NULL);
        enqueue_transaction(&queue, transaction);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
