import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class FileHasher {
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static final int CACHE_SIZE = 1000;
    private static CacheEvictionPolicy evictionPolicy = CacheEvictionPolicy.LRU;

    public enum HashAlgorithm {
        MD5,
        SHA_256,
        SHA_512
    }

    public enum CacheEvictionPolicy {
        LRU,
        TTL
    }

    public static String computeHash(String filePath, HashAlgorithm algorithm) throws IOException, NoSuchAlgorithmException {
        if (cache.containsKey(filePath)) {
            return cache.get(filePath);
        }

        MessageDigest md = MessageDigest.getInstance(algorithm.toString());
        FileInputStream fis = new FileInputStream(filePath);
        byte[] buffer = new byte[4096];
        int bytesRead;
        while ((bytesRead = fis.read(buffer)) != -1) {
            md.update(buffer, 0, bytesRead);
        }
        fis.close();

        String hash = bytesToHex(md.digest());
        cache.put(filePath, hash);

        if (cache.size() > CACHE_SIZE) {
            evictCacheEntry();
        }

        return hash;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static void evictCacheEntry() {
        if (evictionPolicy == CacheEvictionPolicy.LRU) {
            // Implement LRU eviction logic here
        } else if (evictionPolicy == CacheEvictionPolicy.TTL) {
            // Implement TTL eviction logic here
        }
    }

    public static void setCacheSize(int size) {
        CACHE_SIZE = size;
    }

    public static void setCacheEvictionPolicy(CacheEvictionPolicy policy) {
        evictionPolicy = policy;
    }
}
```

