#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <semaphore.h>

#define MAX_TRANSACTIONS 1000
#define SEMAPHORES_COUNT 5

typedef struct {
    int id;
    double amount;
    time_t timestamp;
} Transaction;

typedef struct {
    sem_t semaphores[SEMAPHORES_COUNT];
    Transaction transactions[MAX_TRANSACTIONS];
    size_t transaction_count;
    double total_weighted_sum;
    time_t last_5_seconds_start;
    size_t transactions_last_5_seconds;
} TransactionProcessingModule;

void init_module(TransactionProcessingModule *module) {
    for (int i = 0; i < SEMAPHORES_COUNT; ++i) {
        sem_init(&module->semaphores[i], 0, 1);
    }
    module->transaction_count = 0;
    module->total_weighted_sum = 0.0;
    module->last_5_seconds_start = time(NULL);
    module->transactions_last_5_seconds = 0;
}

void add_transaction(TransactionProcessingModule *module, Transaction transaction) {
    sem_wait(&module->semaphores[0]);
    if (module->transaction_count >= MAX_TRANSACTIONS) {
        sem_post(&module->semaphores[0]);
        fprintf(stderr, "Transaction processing module is full.\n");
        return;
    }
    module->transactions[module->transaction_count++] = transaction;
    module->total_weighted_sum += transaction.amount * (time(NULL) - transaction.timestamp);
    sem_post(&module->semaphores[0]);
}

double process_transactions(TransactionProcessingModule *module, int max_age_seconds) {
    double max_weighted_sum = 0.0;
    int max_id = -1;

    for (int i = 0; i < module->transaction_count; ++i) {
        sem_wait(&module->semaphores[1]);
        if ((time(NULL) - module->transactions[i].timestamp > max_age_seconds)) {
            add_transaction(module, module->transactions[i]);
            if (module->transactions[i].amount * (time(NULL) - module->transactions[i].timestamp) > max_weighted_sum) {
                max_weighted_sum = module->transactions[i].amount * (time(NULL) - module->transactions[i].timestamp);
                max_id = module->transactions[i].id;
            }
        } else {
            sem_post(&module->semaphores[1]);
        }
    }

    return max_weighted_sum + max_id;
}

void update_metrics(TransactionProcessingModule *module) {
    // Update metrics code here
}

int main() {
    TransactionProcessingModule module;
    init_module(&module);

    // Test cases go here

    return 0;
}
