import importlib
import pytest
import concurrent.futures

def execute_module_tests(test_functions, module_label=None, parallel=False):
    def run_test(test_func):
        try:
            test_func()
            return (test_func.__name__, "PASS")
        except AssertionError as e:
            return (test_func.__name__, f"FAIL: {str(e)}")
        except Exception as e:
            return (test_func.__name__, f"ERROR: {str(e)}")

    if parallel and len(test_functions) > 1:
        with concurrent.futures.ThreadPoolExecutor() as executor:
            results = list(executor.map(run_test, test_functions))
    else:
        results = [run_test(test_func) for test_func in test_functions]

    for result in results:
        test_name, status = result
        if module_label:
            print(f"{module_label} - {test_name}: {status}")
        else:
            print(f"{test_name}: {status}")

# Example usage:
# Assuming 'my_module' has a test function named 'test_example'
# and it's located in 'path/to/my_module.py'
import importlib.util
spec = importlib.util.spec_from_file_location("my_module", "path/to/my_module.py")
my_module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(my_module)

test_function = getattr(my_module, 'test_example')
execute_module_tests([test_function], module_label='MyModule', parallel=True)
