std::string updateWebPageContent(const std::vector<std::string>& elements, const std::string& sectionId, const std::string& elementId, const std::string& newContent) {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    HtmlService* service = HtmlServiceManager::getInstance().getService();

    try {
        for (const auto& element : elements) {
            if (element.find(sectionId) != std::string::npos) {
                bool updated = service->updateElementContent(elementId, newContent);
                if (!updated) {
                    return "DoNotRefreshPage";
                }
            }
        }
        return "RefreshPage";
    } catch (const std::exception& e) {
        // Log error and return response
        std::cerr << "Error updating web page content: " << e.what() << std::endl;
        return "DoNotRefreshPage";
    }
}
