<?php

class PasswordValidator {
    private $commonPasswords;

    public function __construct($commonPasswordsUrl) {
        $this->commonPasswords = file($commonPasswordsUrl, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
    }

    public function validatePasswordStrength($password) {
        if (strlen($password) < 8 || strlen($password) > 64) {
            return "Password must be between 8 and 64 characters.";
        }
        if (!preg_match('/[A-Z]/', $password)) {
            return "Password must contain at least one uppercase letter.";
        }
        if (!preg_match('/[a-z]/', $password)) {
            return "Password must contain at least one lowercase letter.";
        }
        if (!preg_match('/\d/', $password)) {
            return "Password must contain at least one digit.";
        }
        if (!preg_match('/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/', $password)) {
            return "Password must contain at least one special character.";
        }
        if (in_array($password, $this->commonPasswords)) {
            return "Password is too common.";
        }
        return true;
    }
}

class UserDAO {
    private $db;

    public function __construct($dsn, $username, $password) {
        try {
            $this->db = new PDO($dsn, $username, $password);
            $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            die("Database connection failed: " . $e->getMessage());
        }
    }

    public function updateUserPassword($userId, $newPassword) {
        $stmt = $this->db->prepare("UPDATE users SET password = :password WHERE id = :id");
        return $stmt->execute(['password' => password_hash($newPassword, PASSWORD_DEFAULT), 'id' => $userId]);
    }
}

function updateUserPassword($userId, $currentPassword, $newPassword) {
    $commonPasswordsUrl = "https://example.com/common_passwords.txt";
    $validator = new PasswordValidator($commonPasswordsUrl);
    $dao = new UserDAO("mysql:host=localhost;dbname=test", "username", "password");

    $error = $validator->validatePasswordStrength($newPassword);
    if ($error !== true) {
        return json_encode(['success' => false, 'message' => $error]);
    }

    if (!$dao->updateUserPassword($userId, $newPassword)) {
        return json_encode(['success' => false, 'message' => "Failed to update password. Please try again later."]);
    }

    return json_encode(['success' => true, 'message' => "Password updated successfully."]);
}

// Example usage:
// echo updateUserPassword(1, "current_password", "new_secure_password");
