#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    long timestamp;
    double weighted_sum;
} Transaction;

typedef struct {
    Transaction *transactions;
    int front, rear;
    int size;
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_non_full, cond_non_empty;
} SlidingWindowQueue;

SlidingWindowQueue* create_queue(int capacity) {
    SlidingWindowQueue *queue = (SlidingWindowQueue*)malloc(sizeof(SlidingWindowQueue));
    queue->transactions = (Transaction*)malloc(capacity * sizeof(Transaction));
    queue->front = queue->rear = -1;
    queue->size = capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond_non_full, NULL);
    pthread_cond_init(&queue->cond_non_empty, NULL);
    return queue;
}

void enqueue(SlidingWindowQueue *queue, Transaction transaction) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->count == queue->size) {
        pthread_cond_wait(&queue->cond_non_full, &queue->mutex);
    }
    if (queue->front == -1)
        queue->front = 0;
    queue->rear = (queue->rear + 1) % queue->size;
    queue->transactions[queue->rear] = transaction;
    queue->count++;
    pthread_cond_signal(&queue->cond_non_empty);
    pthread_mutex_unlock(&queue->mutex);
}

Transaction dequeue(SlidingWindowQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond_non_empty, &queue->mutex);
    }
    Transaction transaction = queue->transactions[queue->front];
    if (queue->front == queue->rear)
        queue->front = queue->rear = -1;
    else
        queue->front = (queue->front + 1) % queue->size;
    queue->count--;
    pthread_cond_signal(&queue->cond_non_full);
    pthread_mutex_unlock(&queue->mutex);
    return transaction;
}

int is_empty(SlidingWindowQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    int result = (queue->count == 0);
    pthread_mutex_unlock(&queue->mutex);
    return result;
}

int filter_transactions(int id, long timestamp, double weighted_sum, SlidingWindowQueue *queue, 
                        int *total_transactions, double *average_weighted_sum, 
                        double *max_weighted_sum, double *min_weighted_sum) {
    pthread_mutex_lock(&queue->mutex);
    while (!is_empty(queue) && queue->transactions[queue->front].timestamp < timestamp - 5000) {
        dequeue(queue);
    }
    if (queue->count >= 1000) {
        dequeue(queue);
    }
    enqueue(queue, (Transaction){id, timestamp, weighted_sum});
    pthread_mutex_unlock(&queue->mutex);

    (*total_transactions)++;
    *max_weighted_sum = fmax(*max_weighted_sum, weighted_sum);
    *min_weighted_sum = fmin(*min_weighted_sum, weighted_sum);
    if (*average_weighted_sum == 0)
        *average_weighted_sum = weighted_sum;
    else
        *average_weighted_sum = ((*average_weighted_sum * (*total_transactions - 1)) + weighted_sum) / (*total_transactions);

    return id;
}

int main() {
    SlidingWindowQueue *queue = create_queue(2000);
    int total_transactions = 0;
    double average_weighted_sum = 0, max_weighted_sum = -1, min_weighted_sum = -1;

    // Simulate transaction processing
    for (int i = 0; i < 3000; i++) {
        filter_transactions(i, i * 1000, rand() % 100, queue, 
                            &total_transactions, &average_weighted_sum, 
                            &max_weighted_sum, &min_weighted_sum);
    }

    printf("Total Transactions: %d\n", total_transactions);
    printf("Average Weighted Sum: %.2f\n", average_weighted_sum);
    printf("Max Weighted Sum: %.2f\n", max_weighted_sum);
    printf("Min Weighted Sum: %.2f\n", min_weighted_sum);

    free(queue->transactions);
    free(queue);

    return 0;
}
