# Python with Flask
from flask import Flask, request, jsonify

app = Flask(__name__)

data_store = {
    '1': {'name': 'Resource 1', 'value': 10},
    '2': {'name': 'Resource 2', 'value': 20}
}

@app.route('/update/<id>', methods=['PUT'])
def update_resource(id):
    new_data = request.json

    if id not in data_store:
        return jsonify({'message': 'Resource not found'}), 404

    # Optimistic concurrency control
    if new_data['version'] != data_store[id]['version']:
        return jsonify({'message': 'Conflict: Resource version mismatch'}), 409

    new_data['version'] += 1
    data_store[id] = new_data

    return jsonify(data_store[id]), 200

@app.route('/delete/<id>', methods=['DELETE'])
def delete_resource(id):
    if id not in data_store:
        return jsonify({'message': 'Resource not found'}), 404

    del data_store[id]

    return jsonify({'message': 'Resource deleted'}), 200

if __name__ == '__main__':
    app.run(port=3000)
