        var updatedResource = await UpdateResourceInStorage(id, resource);
        if (updatedResource == null)
            return NotFound();

        return Ok(updatedResource);
    }

    private async Task<ResourceData> UpdateResourceInStorage(int id, ResourceData resource)
    {
