    public string Data { get; set; }
}

public static class EncryptionHelper
{
    public static string DecryptString(string base64EncodedEncryptedMessage)
    {
        try
        {
            using (var tripleDES = new TripleDESCryptoServiceProvider())
            {
                tripleDES.Key = Encoding.UTF8.GetBytes("YourDesKey123"); // 24 bytes for Triple DES
                tripleDES.IV = Encoding.UTF8.GetBytes("YourDesIv123"); // 8 bytes for IV
                tripleDES.Mode = CipherMode.CBC;
                tripleDES.Padding = PaddingMode.PKCS7;

                using (var msDecrypt = new MemoryStream(Convert.FromBase64String(base64EncodedEncryptedMessage)))
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (var srDecrypt = new StreamReader(csDecrypt))
                        {
                            return srDecrypt.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Handle decryption errors, e.g., invalid Base64 string or key/IV issues
            Console.WriteLine($"Decryption failed: {ex.Message}");
            throw;
        }
    }
}
