```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define MAX_LINE_LENGTH 1024

void parse_log_line(const char *line, double *bandwidth, int *packet_loss, double *latency) {
    // Regular expression to extract relevant fields
    regex_t bandwidth_regex;
    regcomp(&bandwidth_regex, "Bandwidth: ([0-9.]+)", REG_EXTENDED);

    regmatch_t matches[2];
    if (regexec(&bandwidth_regex, line, 2, matches, 0) == 0) {
        char *bandwidth_str = strndup(line + matches[1].rm_so, matches[1].rm_eo - matches[1].rm_so);
        *bandwidth = atof(bandwidth_str);
        free(bandwidth_str);
    }

    regcomp(&bandwidth_regex, "Packet Loss: ([0-9]+)", REG_EXTENDED);
    if (regexec(&bandwidth_regex, line, 2, matches, 0) == 0) {
        *packet_loss = atoi(strndup(line + matches[1].rm_so, matches[1].rm_eo - matches[1].rm_so));
    }

    regcomp(&bandwidth_regex, "Latency: ([0-9.]+)", REG_EXTENDED);
    if (regexec(&bandwidth_regex, line, 2, matches, 0) == 0) {
        char *latency_str = strndup(line + matches[1].rm_so, matches[1].rm_eo - matches[1].rm_so);
        *latency = atof(latency_str);
        free(latency_str);
    }
}

void process_log_file(const char *input_path) {
    FILE *file = fopen(input_path, "r");
    if (!file) {
        perror("Error opening input file");
        return;
    }

    double total_bandwidth = 0;
    int total_packets = 0;
    double total_latency = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        double bandwidth;
        int packet_loss;
        double latency;
        parse_log_line(line, &bandwidth, &packet_loss, &latency);

        total_bandwidth += bandwidth;
        total_packets += packet_loss;
        total_latency += latency;
    }

    fclose(file);

    printf("Total Bandwidth: %.2f\n", total_bandwidth);
    printf("Total Packets Lost: %d\n", total_packets);
    printf("Average Latency: %.2f\n", total_latency / 10); // Assuming each entry is a new packet
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    process_log_file(argv[1]);

    return 0;
}
```

