    public function handleRequest($_REQUEST) {
        if (!isset($_REQUEST['tenant_id'])) {
            return json_encode(['message' => 'error', 'reason' => 'missing tenant_id']);
        }

        $tenantId = $_REQUEST['tenant_id'];
        $action = isset($_REQUEST['action']) ? $_REQUEST['action'] : null;
        $userId = isset($_REQUEST['user_id']) ? $_REQUEST['user_id'] : null;

        if ($action === 'delete') {
            // Rate limiting logic for delete action
            if (!$this->isRateLimitExceeded($tenantId, 'delete')) {
                return json_encode(['message' => 'error', 'reason' => 'rate limit exceeded']);
            }
        }

        $userData = [
            'name' => $_REQUEST['name'],
            'email' => $_REQUEST['email'],
            'password' => $_REQUEST['password']
        ];

        if (!$this->Validate($tenantId, $userData)) {
            return json_encode(['message' => 'error', 'reason' => 'validation failed']);
        }

        try {
            $dbTransaction = $this->db->beginTransaction();
            if ($action === 'create') {
                if ($userId) {
                    // Update user logic
                    $this->Update($tenantId, $userData, $userId);
                } else {
                    // Create user logic
                    $userId = $this->Create($tenantId, $userData);
                }
            } elseif ($action === 'delete') {
                // Delete user logic
                $this->Delete($tenantId, $userId);
            }
            $dbTransaction->commit();
        } catch (Exception $e) {
            $dbTransaction->rollBack();
            return json_encode(['message' => 'error', 'reason' => $e->getMessage()]);
