#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 300 // 100 transactions/sec * 3 sec

typedef struct {
    int id;
    double weighted_sum;
    time_t timestamp;
} Transaction;

double process_transactions(Transaction* transactions, int count) {
    if (count == 0) return -1; // No transactions to process

    static Transaction sliding_window[MAX_TRANSACTIONS];
    static int window_index = 0;
    static double cumulative_weighted_sum = 0;
    static time_t last_reset_time = time(NULL);

    // Reset the sliding window and cumulative sum if it's been more than 10 seconds
    if (time(NULL) - last_reset_time > 10) {
        for (int i = 0; i < MAX_TRANSACTIONS; i++) {
            sliding_window[i].id = -1;
        }
        cumulative_weighted_sum = 0;
        window_index = 0;
        last_reset_time = time(NULL);
    }

    // Process each transaction
    for (int i = 0; i < count; i++) {
        if (time(NULL) - transactions[i].timestamp > 10) continue; // Ignore old transactions

        if (window_index >= MAX_TRANSACTIONS) {
            window_index = 0; // Reset index if it reaches the max size
        }

        sliding_window[window_index] = transactions[i];
        cumulative_weighted_sum += transactions[i].weighted_sum;

        if (time(NULL) - sliding_window[window_index].timestamp <= 3) {
            // Update the maximum weighted sum within the last 3 seconds
            static double max_weighted_sum = -1;
            static int max_id = -1;

            for (int j = window_index; j < MAX_TRANSACTIONS && sliding_window[j].id != -1; j++) {
                if (sliding_window[j].weighted_sum > max_weighted_sum) {
                    max_weighted_sum = sliding_window[j].weighted_sum;
                    max_id = sliding_window[j].id;
                }
            }

            return max_weighted_sum; // Return the maximum weighted sum
        }

        window_index++;
    }

    return cumulative_weighted_sum; // Return the total weighted sum if no valid transactions found
}

int main() {
    Transaction transactions[MAX_TRANSACTIONS];

    // Simulate processing transactions from an external data source
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transactions[i].id = i;
        transactions[i].weighted_sum = rand() % 100;
        transactions[i].timestamp = time(NULL) - (MAX_TRANSACTIONS - i); // Simulate transaction timestamps
    }

    double result = process_transactions(transactions, MAX_TRANSACTIONS);
    printf("Maximum weighted sum within the last 3 seconds: %.2f\n", result);

    return 0;
}
```

