namespace SecureRandomGenerator {
    class MT19937ThreadSafe {
    public:
        static std::mutex mtx;

        MT19937ThreadSafe(uint64_t seed) : generator(seed), distribution(0, 2147483647) {}

        ~MT19937ThreadSafe() {}

        int generateRandomNumber(int min, int max) {
            std::lock_guard<std::mutex> lock(mtx);
            return distribution(generator) % (max - min + 1) + min;
        }

    private:
        std::mt19937 generator;
        std::uniform_int_distribution<int> distribution;
    };

    std::mutex MT19937ThreadSafe::mtx;
}

int main() {
    // Example usage
    SecureRandomGenerator::MT19937ThreadSafe rng(42);
    for (int i = 0; i < 10; ++i) {
        std::cout << "Random Number: " << rng.generateRandomNumber(1, 100) << std::endl;
    }
    return 0;
}
