#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_FILENAME_LEN 256

struct RenameConfig {
    int numDigits;
    char fileType[10];
    int appendTimestamp;
};

int renameFileWithDynamicExtension(const char *originalFilename, const struct RenameConfig *config, char *newFilename, size_t newFilenameLen) {
    if (originalFilename == NULL || newFilename == NULL || newFilenameLen < MAX_FILENAME_LEN) {
        return -1; // Invalid input
    }

    if (strlen(originalFilename) == 0) {
        return -2; // Empty filename
    }

    char baseName[MAX_FILENAME_LEN];
    char ext[10];
    int pos = strcspn(originalFilename, ".");
    strncpy(baseName, originalFilename, pos);
    baseName[pos] = '\0';

    if (strlen(originalFilename) <= pos + 4 || strncmp(&originalFilename[pos], config->fileType, 4) != 0) {
        return -3; // Invalid file type
    }

    strcpy(ext, config->fileType);

    if (config->appendTimestamp) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(newFilename, newFilenameLen, "%s", tm_info);
    } else {
        snprintf(newFilename, newFilenameLen, "%s.%s", baseName, ext);
    }

    if (strlen(newFilename) >= newFilenameLen) {
        return -4; // New filename too long
    }

    return 0;
}
