// Define the EmployeeRecord structure
struct EmployeeRecord {
    int id;
    char* name;
    float salary;

    // Constructor for initialization
    EmployeeRecord(int id, const std::string& name, float salary) : id(id), salary(salary) {
        this->name = new char[name.length() + 1];
        strcpy(this->name, name.c_str());
    }

    // Destructor to free dynamically allocated memory
    ~EmployeeRecord() {
        delete[] name;
    }
};

// Function to create employee records from vectors
std::vector<EmployeeRecord*> createEmployeeRecords(const std::vector<int>& ids, 
                                                     const std::vector<std::string>& names,
                                                     const std::vector<float>& salaries) {
    if (ids.size() != names.size() || ids.size() != salaries.size()) {
        throw std::invalid_argument("All input vectors must have the same size.");
    }

    std::vector<EmployeeRecord*> records;
    try {
        for (size_t i = 0; i < ids.size(); ++i) {
            records.push_back(new EmployeeRecord(ids[i], names[i], salaries[i]));
        }
    } catch (...) {
        // Clean up if an exception occurs
        for (EmployeeRecord* record : records) {
            delete record;
        }
        throw;
    }

    return records;
}

// Function to free allocated memory for employee records
void freeEmployeeRecords(std::vector<EmployeeRecord*>& records) {
    for (EmployeeRecord* record : records) {
        delete record;
    }
    records.clear();
}
