#include <mutex>

class SafeForwardList {
private:
    std::forward_list<std::string> list;
    std::mutex mutex;

public:
    bool insertAfterFirstOccurrence(const std::string& search, const std::string& toInsert, bool caseInsensitive = false) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = list.begin();
        while (it != list.end()) {
            if ((caseInsensitive && !search.compare(iota, search.size(), *it)) || (!caseInsensitive && search == *it)) {
                list.insert_after(it, toInsert);
                logOperation("Inserted after first occurrence", search, toInsert);
                return true;
            }
            ++it;
        }
        list.push_back(toInsert);
        logOperation("Inserted at end", search, toInsert);
        return true;
    }

private:
    void logOperation(const std::string& action, const std::string& search, const std::string& toInsert) {
        std::time_t now = std::time(nullptr);
        std::ofstream logFile("list_operations.log", std::ios_base::app);
        if (logFile.is_open()) {
            logFile << std::ctime(&now) << action << ": " << search << " -> " << toInsert << std::endl;
            logFile.close();
        }
    }
};
