import aiohttp
import asyncio
from datetime import datetime, timedelta
from functools import lru_cache
from typing import Dict, Any

class UserProfileImageCache:
    def __init__(self, max_size: int = 1000):
        self.cache: Dict[str, Any] = {}
        self.max_size = max_size
        self.access_times = {}

    @lru_cache(maxsize=512)
    async def download_image(self, url: str) -> bytes:
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as response:
                    if response.status == 200:
                        return await response.read()
                    else:
                        raise Exception(f"Failed to download image from {url}")
        except Exception as e:
            print(f"Error downloading image from {url}: {e}")
            raise

    async def get_image(self, url: str) -> bytes:
        if url in self.cache and datetime.now() - self.access_times[url] < timedelta(hours=1):
            return self.cache[url]
        else:
            image = await self.download_image(url)
            self.cache[url] = image
            self.access_times[url] = datetime.now()
            while len(self.cache) > self.max_size:
                oldest_key = min(self.access_times, key=self.access_times.get)
                del self.cache[oldest_key]
                del self.access_times[oldest_key]
            return image

async def fetch_profile_images(user_ids: list):
    cache = UserProfileImageCache()
    tasks = [cache.get_image(f"https://example.com/images/{user_id}.jpg") for user_id in user_ids]
    images = await asyncio.gather(*tasks)
