```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class FileHashService {

    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static final Object cacheLock = new Object();

    public static String computeFileHash(String filePath) {
        try {
            File file = new File(filePath);
            if (!file.exists()) {
                throw new FileNotFoundException("File not found: " + filePath);
            }

            String cachedHash = getCachedHash(file);
            if (cachedHash != null) {
                return cachedHash;
            }

            String md5Hash = computeMD5(file);
            storeInCache(file, md5Hash);

            validateWithExternalService(md5Hash, file);

            return md5Hash;
        } catch (Exception e) {
            System.err.println("Error computing hash for " + filePath + ": " + e.getMessage());
            return null; // Fallback to local computation
        }
    }

    private static String getCachedHash(File file) {
        synchronized (cacheLock) {
            return cache.get(file.getAbsolutePath());
        }
    }

    private static void storeInCache(File file, String hash) {
        synchronized (cacheLock) {
            cache.put(file.getAbsolutePath(), hash);
        }
    }

    private static String computeMD5(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(digest.digest());
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static void validateWithExternalService(String md5Hash, File file) {
        // Placeholder for external service validation
        System.out.println("Validating hash " + md5Hash + " for file " + file.getAbsolutePath() + " with external service...");
    }

    public static void main(String[] args) {
        String filePath = "path/to/large/file.txt";
        String hash = computeFileHash(filePath);
        if (hash != null) {
            System.out.println("Computed hash: " + hash);
        } else {
            System.out.println("Failed to compute hash for " + filePath);
        }
    }
}
