using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Data.SqlClient;

public class DataHandler
{
    private string connectionString = "your_connection_string_here";

    public void LoadAndStoreData(string filePath)
    {
        try
        {
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                BinaryFormatter binaryFormatter = new BinaryFormatter();
                var dataStructure = (YourCustomDataType)binaryFormatter.Deserialize(fileStream);

                StoreDataInDatabase(dataStructure);
            }
        }
        catch (IOException ex)
        {
            Console.WriteLine("An error occurred while reading the file: " + ex.Message);
        }
        catch (SerializationException ex)
        {
            Console.WriteLine("An error occurred during deserialization: " + ex.Message);
        }
        catch (Exception ex)
        {
            Console.WriteLine("A general error occurred: " + ex.Message);
        }
    }

    private void StoreDataInDatabase(YourCustomDataType dataStructure)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();
                string query = "INSERT INTO YourTable (Column1, Column2) VALUES (@Value1, @Value2)";
                using (SqlCommand command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@Value1", dataStructure.Property1);
                    command.Parameters.AddWithValue("@Value2", dataStructure.Property2);

                    int rowsAffected = command.ExecuteNonQuery();
                    Console.WriteLine($"{rowsAffected} row(s) affected.");
                }
            }
            catch (SqlException ex)
            {
                Console.WriteLine("An error occurred while storing data in the database: " + ex.Message);
            }
        }
    }
}
