    public void validateFile(String filePath, List<String> apis, int chunkSize, long apiTimeout)
            throws IOException, InterruptedException, ExecutionException, TimeoutException {

        long startTime = System.currentTimeMillis();
        String fileHash = computeFileHash(filePath, chunkSize);

        Map<String, Boolean> validationResults = new ConcurrentHashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(apis.size());

        for (String api : apis) {
