```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char **fields;
    int field_count;
} LineData;

LineData* read_line(char *line, int max_length) {
    LineData *data = malloc(sizeof(LineData));
    data->fields = malloc(max_length * sizeof(char *));
    data->field_count = 0;

    char *token = strtok(line, " \t");
    while (token != NULL && data->field_count < max_length) {
        data->fields[data->field_count++] = token;
        token = strtok(NULL, " \t");
    }

    return data;
}

void process_line(LineData *line_data, FILE *log_file) {
    for (int i = 0; i < line_data->field_count - 1; i++) {
        printf("%s,", line_data->fields[i]);
        fprintf(log_file, "%s,", line_data->fields[i]);
    }

    double last_field = atof(line_data->fields[line_data->field_count - 2]);
    double second_last_field = atof(line_data->fields[line_data->field_count - 1]);
    double average = (last_field + second_last_field) / 2.0;

    printf("%.2f\n", average);
    fprintf(log_file, "%.2f\n", average);
}

void free_line(LineData *line_data) {
    for (int i = 0; i < line_data->field_count; i++) {
        free(line_data->fields[i]);
    }
    free(line_data->fields);
    free(line_data);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_log_file> <parallel/sequential>\n", argv[0]);
        return 1;
    }

    FILE *input_file = fopen(argv[1], "r");
    if (!input_file) {
        perror("Failed to open input file");
        return 1;
    }

    FILE *log_file = fopen(argv[2], "w");
    if (!log_file) {
        perror("Failed to open log file");
        fclose(input_file);
        return 1;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), input_file)) {
        LineData *line_data = read_line(line, MAX_LINE_LENGTH);
        process_line(line_data, log_file);
        free_line(line_data);
    }

    fclose(input_file);
    fclose(log_file);

    return 0;
}
```

