import threading
import queue
import time

class ConnectionPool:
    def __init__(self, db_uri, min_connections, max_connections, timeout):
        self.db_uri = db_uri
        self.min_connections = min_connections
        self.max_connections = max_connections
        self.timeout = timeout
        self.pool = queue.Queue(maxsize=max_connections)
        self.lock = threading.Lock()
        self.init_pool()

    def init_pool(self):
        for _ in range(self.min_connections):
            connection = self.create_connection()
            if connection:
                self.pool.put(connection)

    def create_connection(self):
        # Placeholder for actual connection creation logic
        return "DatabaseConnection"

    def get_connection(self, timeout=None):
        try:
            with self.lock:
                return self.pool.get(block=True, timeout=timeout or self.timeout)
        except queue.Empty:
            if self.pool.qsize() < self.max_connections:
                connection = self.create_connection()
                if connection:
                    return connection
            raise Exception("No available connections")

    def release_connection(self, connection):
        with self.lock:
            if self.pool.qsize() < self.max_connections:
                self.pool.put(connection)
            else:
                # Handle overflow or delete old connections
                pass

    def close_all_connections(self):
        while not self.pool.empty():
            connection = self.pool.get()
            # Placeholder for actual connection closing logic
            print(f"Closing connection: {connection}")

def test_connection_pool():
    pool = ConnectionPool("db://example.com", min_connections=5, max_connections=10, timeout=3)
    conn1 = pool.get_connection()
    assert isinstance(conn1, str), "Connection should be a string"
    pool.release_connection(conn1)
    try:
        conn2 = pool.get_connection(timeout=1)
        assert isinstance(conn2, str), "Connection should be a string"
        pool.release_connection(conn2)
        conn3 = pool.get_connection()
        assert isinstance(conn3, str), "Connection should be a string"
        pool.close_all_connections()
    except Exception as e:
        print(f"Error: {e}")

test_connection_pool()
