        IncrementalIRCompiler {
            grammar_service_url,
            cache: GrammarCache::new(),
            semaphore: Semaphore::new(5),
            client: Client::new(),
            context: Context::create(),
        }
    }

    async fn compile_file(&self, file_path: &Path) -> Result<Module, Error> {
        // Validate the input file path
        if !file_path.exists() {
            return Err(Error::InvalidFilePath);
        }

        // Fetch the latest grammar definition from the service if necessary
        let grammar_definition = self.fetch_grammar_definition().await?;

        // Parse the input file using the grammar and perform incremental compilation
        // (Code to parse file and recompile only modified parts)

        Ok(Module::new("compiled_module", &self.context))
    }

    async fn fetch_grammar_definition(&self) -> Result<GrammarDefinition, Error> {
        let permit = self.semaphore.acquire().await.map_err(|_| Error::CacheFull)?;

        // Check if the grammar definition is already in the cache
        if let Some(grammar) = self.cache.get() {
            return Ok(grammar);
        }

        // Fetch the latest grammar definition from the external service
        let response = self.client.get(&self.grammar_service_url).timeout(Duration::from_secs(10)).send().await.map_err(|_| Error::NetworkError(reqwest::Error::new(reqwest::StatusCode::RequestTimeout, "Request timed out")))?;

        // Validate the fetched grammar definition
        if !response.status().is_success() {
            return Err(Error::MalformedGrammarDefinition(response.text().await.unwrap()));
        }

        let grammar_definition: GrammarDefinition = response.json().await.map_err(|_| Error::MalformedGrammarDefinition("Invalid JSON".to_string()))?;

        // Store the fetched grammar definition in the cache
        self.cache.set(grammar_definition.clone());

        drop(permit);

        Ok(grammar_definition)
    }
}

struct GrammarCache {
    data: Option<GrammarDefinition>,
    last_updated: Utc,
    expiration_time: Duration,
}

impl GrammarCache {
    fn new() -> Self {
        GrammarCache {
            data: None,
            last_updated: Utc::now(),
            expiration_time: Duration::hours(24),
        }
    }

    fn get(&self) -> Option<GrammarDefinition> {
        if let Some(data) = self.data {
            if Utc::now() < self.last_updated + self.expiration_time {
                return Some(data);
            }
        }
        None
    }

    fn set(&mut self, grammar: GrammarDefinition) {
        self.data = Some(grammar);
        self.last_updated = Utc::now();
    }
}

