import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private ConcurrentHashMap<String, BackgroundService> serviceMap = new ConcurrentHashMap<>();
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(10);

    public void startService(String serviceName, int delay, int interval) {
        if (serviceMap.containsKey(serviceName)) {
            throw new IllegalArgumentException("Service already exists: " + serviceName);
        }

        BackgroundService service = new BackgroundService(serviceName, delay, interval);
        serviceMap.put(serviceName, service);
        scheduler.scheduleAtFixedRate(() -> service.run(), delay, interval, TimeUnit.SECONDS);
    }

    public void stopService(String serviceName) {
        BackgroundService service = serviceMap.get(serviceName);
        if (service != null) {
            service.stop();
            scheduler.shutdownNow();
            scheduler = Executors.newScheduledThreadPool(10); // Reset scheduler
        }
    }

    public void restartService(String serviceName) {
        stopService(serviceName);
        startService(serviceName, 0, 0); // Restart with default delay and interval
    }

    private class BackgroundService {
        private String name;
        private int delay;
        private int interval;
        private boolean running;

        public BackgroundService(String name, int delay, int interval) {
            this.name = name;
            this.delay = delay;
            this.interval = interval;
            this.running = true;
        }

        public void run() {
            if (running) {
                try {
                    // Simulate service operation
                    System.out.println("Service " + name + " is running.");
                    // Send status update to messaging system
                    sendStatusUpdate(name, "Running");
                } catch (Exception e) {
                    handleException(e);
                }
            }
        }

        public void stop() {
            running = false;
            // Notify messaging system about the service stopping
            sendStatusUpdate(name, "Stopped");
        }

        private void handleException(Exception e) {
            // Log exception and notify messaging system about failure
            System.err.println("Service " + name + " encountered an error: " + e.getMessage());
            sendStatusUpdate(name, "Failed");
        }
    }

    private void sendStatusUpdate(String serviceName, String status) {
        // Simulate sending status update to external messaging system
        System.out.println("Sending status update for service " + serviceName + ": " + status);
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        manager.startService("Service1", 5, 10);
        manager.startService("Service2", 3, 8);
    }
}
