int main(int argc, char* argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s [encrypt/decrypt] <key_file> <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    char mode[10];
    strcpy(mode, argv[1]);

    if (strcmp(mode, "encrypt") != 0 && strcmp(mode, "decrypt") != 0) {
        fprintf(stderr, "Invalid mode. Use 'encrypt' or 'decrypt'.\n");
        return 1;
    }

    char* key_file = argv[2];
    char* input_file = argv[3];
    char* output_file = argv[4];

    // Open key file and read key
    FILE* key_fp = fopen(key_file, "rb");
    if (!key_fp) {
        fprintf(stderr, "Failed to open key file: %s\n", key_file);
        return 1;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH];
    size_t key_len = fread(key, 1, EVP_MAX_KEY_LENGTH, key_fp);
    fclose(key_fp);

    if (key_len == 0) {
        fprintf(stderr, "Failed to read key from file: %s\n", key_file);
        return 1;
    }

    // Open input and output files
    FILE* input_fp = fopen(input_file, mode[0] == 'e' ? "rb" : "rb");
    if (!input_fp) {
        fprintf(stderr, "Failed to open input file: %s\n", input_file);
        return 1;
    }

    FILE* output_fp = fopen(output_file, mode[0] == 'e' ? "wb" : "wb");
    if (!output_fp) {
        fprintf(stderr, "Failed to open output file: %s\n", output_file);
        fclose(input_fp);
        return 1;
    }

    // Perform encryption or decryption
    if (strcmp(mode, "encrypt") == 0) {
        encrypt_file(input_fp, output_fp, key, key_len);
    } else {
        decrypt_file(input_fp, output_fp, key, key_len);
    }

    // Close files and clean up
    fclose(input_fp);
    fclose(output_fp);

    return 0;
}
