const axios = require('axios');
const fs = require('fs');
const path = require('path');

class BibleMentionsExtractor {
  constructor(configUrl) {
    this.configUrl = configUrl;
    this.bookNames = {};
    this.loadBookConfig();
  }

  async loadBookConfig() {
    try {
      const response = await axios.get(this.configUrl, { responseType: 'json' });
      this.bookNames = response.data;
    } catch (error) {
      console.error('Failed to load book name configuration:', error);
    }
  }

  updateBookConfig(newConfig) {
    fs.writeFileSync(path.resolve(__dirname, 'book_config.json'), JSON.stringify(newConfig, null, 2));
    this.loadBookConfig();
  }

  extractBookMentions(text) {
    const regex = new RegExp(`(${Object.values(this.bookNames).join('|')})`, 'gi');
    const mentions = text.match(regex);
    return mentions ? Array.from(new Set(mentions)).map(m => m.toLowerCase()) : [];
  }

  async processTexts(texts, batchSize = 10) {
    const results = [];
    for (let i = 0; i < texts.length; i += batchSize) {
      const batch = texts.slice(i, i + batchSize);
      await Promise.all(batch.map(async text => {
        try {
          const mentions = this.extractBookMentions(text);
          results.push({ text, mentions });
        } catch (error) {
          console.error('Error processing text:', error);
        }
      }));
    }
    return results;
  }

  logExtractedMentions(mentions) {
    const logEntry = JSON.stringify(mentions, null, 2);
    fs.appendFileSync(path.resolve(__dirname, 'extracted_mentions.log'), `${new Date()}: ${logEntry}\n`);
  }
}

// Example usage:
const extractor = new BibleMentionsExtractor('https://api.example.com/book_config.json');
const texts = [
  "Jesus taught in the Gospels and Paul wrote Epistles.",
  "The book of Revelation is part of the New Testament.",
  "David is mentioned in the Old Testament."
];

extractor.processTexts(texts).then(results => {
  results.forEach(result => extractor.logExtractedMentions({ text: result.text, mentions: result.mentions }));
}).catch(error => console.error('Error processing texts:', error));
```

