```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENT_SIZE 1024

typedef struct {
    long timestamp;
    int event_type;
    char description[MAX_EVENT_SIZE];
    void* metadata; // Placeholder for variable-length metadata
} Event;

typedef struct {
    Event* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventBuffer;

EventBuffer* create_event_buffer(size_t initial_capacity) {
    EventBuffer* buffer = (EventBuffer*)malloc(sizeof(EventBuffer));
    if (buffer == NULL) {
        return NULL;
    }
    buffer->events = (Event*)calloc(initial_capacity, sizeof(Event));
    if (buffer->events == NULL) {
        free(buffer);
        return NULL;
    }
    buffer->capacity = initial_capacity;
    buffer->size = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void destroy_event_buffer(EventBuffer* buffer) {
    for (size_t i = 0; i < buffer->size; ++i) {
        free(buffer->events[i].metadata);
    }
    free(buffer->events);
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
}

void resize_event_buffer(EventBuffer* buffer, size_t new_capacity) {
    Event* new_events = (Event*)realloc(buffer->events, new_capacity * sizeof(Event));
    if (new_events == NULL) {
        return;
    }
    buffer->events = new_events;
    buffer->capacity = new_capacity;
}

void add_event_to_buffer(EventBuffer* buffer, Event event) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->size >= buffer->capacity) {
        resize_event_buffer(buffer, buffer->capacity * 2);
    }
    buffer->events[buffer->size++] = event;
    pthread_mutex_unlock(&buffer->lock);
}

void* validate_and_process_events(void* arg) {
    EventBuffer* buffer = (EventBuffer*)arg;
    while (1) {
        pthread_mutex_lock(&buffer->lock);
        if (buffer->size == 0) {
            pthread_mutex_unlock(&buffer->lock);
            break;
        }
        Event event = buffer->events[--buffer->size];
        pthread_mutex_unlock(&buffer->lock);

        // Validate and process the event
        // Example: if (!validate_event(event)) continue;

        // Simulate processing by printing details
        printf("Timestamp: %ld, Type: %d, Description: %s\n", event.timestamp, event.event_type, event.description);
    }
    return NULL;
}

int main() {
    EventBuffer* buffer = create_event_buffer(100);

    pthread_t thread;
    pthread_create(&thread, NULL, validate_and_process_events, (void*)buffer);

    // Simulate adding events to the buffer
    for (size_t i = 0; i < 200; ++i) {
        Event event = { time(NULL), rand() % 10, "Event Description", NULL };
        add_event_to_buffer(buffer, event);
    }

    pthread_join(thread, NULL);

    destroy_event_buffer(buffer);

    return 0;
}
