struct Employee {
    int id;
    char* name;
    float salary;
};

class BinaryEmployeeSerializer {
public:
    void serialize(const std::vector<Employee>& employees, const std::string& filename);
    std::vector<Employee> deserialize(const std::string& filename);
    ~BinaryEmployeeSerializer();
private:
    void writeInt(std::ofstream& file, int value);
    int readInt(std::ifstream& file);
    void writeFloat(std::ofstream& file, float value);
    float readFloat(std::ifstream& file);
};

void BinaryEmployeeSerializer::serialize(const std::vector<Employee>& employees, const std::string& filename) {
    std::ofstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Failed to open file for writing: " << filename << std::endl;
        return;
    }
    int size = employees.size();
    writeInt(file, size);
    for (const auto& employee : employees) {
        writeInt(file, employee.id);
        int nameLength = strlen(employee.name) + 1;
        writeInt(file, nameLength);
        file.write(employee.name, nameLength);
        writeFloat(file, employee.salary);
    }
    file.close();
}

std::vector<Employee> BinaryEmployeeSerializer::deserialize(const std::string& filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Failed to open file for reading: " << filename << std::endl;
        return {};
    }
    int size = readInt(file);
    std::vector<Employee> employees(size);
    for (auto& employee : employees) {
        employee.id = readInt(file);
        int nameLength = readInt(file);
        employee.name = new char[nameLength];
        file.read(employee.name, nameLength);
        employee.salary = readFloat(file);
    }
    file.close();
    return employees;
}

BinaryEmployeeSerializer::~BinaryEmployeeSerializer() {
    // No need for cleanup in this simple example
}

void BinaryEmployeeSerializer::writeInt(std::ofstream& file, int value) {
    file.write(reinterpret_cast<char*>(&value), sizeof(value));
}

int BinaryEmployeeSerializer::readInt(std::ifstream& file) {
    int value;
    file.read(reinterpret_cast<char*>(&value), sizeof(value));
    return value;
}

void BinaryEmployeeSerializer::writeFloat(std::ofstream& file, float value) {
    file.write(reinterpret_cast<char*>(&value), sizeof(value));
}

float BinaryEmployeeSerializer::readFloat(std::ifstream& file) {
    float value;
    file.read(reinterpret_cast<char*>(&value), sizeof(value));
    return value;
}
