```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define transaction structure
typedef struct {
    int id;
    double weight_sum;
    time_t timestamp;
    char type[20];
} Transaction;

// Global variables for transaction processing
Transaction* transactions[1000]; // Array to hold transactions
int current_index = 0;           // Current index in the transaction array
time_t sliding_window_start;     // Start of the sliding window

// Mutex for thread-safe access to shared resources
pthread_mutex_t mutex;

// Function to process a transaction
void* process_transaction(void* arg) {
    Transaction* new_transaction = (Transaction*)arg;

    pthread_mutex_lock(&mutex);

    // Remove transactions older than 10 seconds from the sliding window
    time_t now = time(NULL);
    while (current_index > 0 && now - transactions[current_index-1]->timestamp > 10) {
        free(transactions[current_index-1]);
        current_index--;
    }

    // Check for duplicate transactions within the last 3 seconds
    int duplicate_found = 0;
    for (int i = 0; i < current_index && !duplicate_found; i++) {
        if (transactions[i]->id == new_transaction->id) {
            duplicate_found = 1;
        }
    }

    // Process transactions within the last 3 seconds
    if (!duplicate_found && now - sliding_window_start <= 3) {
        // Validate transaction based on type
        if (strcmp(new_transaction->type, "buy") == 0) {
            // Buy-specific validation logic
        } else if (strcmp(new_transaction->type, "sell") == 0) {
            // Sell-specific validation logic
        } else if (strcmp(new_transaction->type, "transfer") == 0) {
            // Transfer-specific validation logic
        }

        // Process valid transaction
        transactions[current_index++] = new_transaction;
    } else {
        // Discard invalid or duplicate transaction
        free(new_transaction);
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Initialize the transaction processing system
void init_transaction_processing() {
    sliding_window_start = time(NULL);
    pthread_mutex_init(&mutex, NULL);
}

// Main function to simulate transaction processing
int main() {
    init_transaction_processing();

    // Simulate transaction processing
    for (int i = 0; i < 1500; i++) {
        Transaction* new_transaction = malloc(sizeof(Transaction));
        new_transaction->id = i;
        new_transaction->weight_sum = rand() % 1000.0;
        new_transaction->timestamp = time(NULL);
        strcpy(new_transaction->type, "buy");

        pthread_t thread_id;
        pthread_create(&thread_id, NULL, process_transaction, new_transaction);
    }

    return 0;
}
