                    metadata.update(data)
                except (requests.RequestException, ValueError):
                    print(f"Failed to fetch properties for vertex {vertex_id}. Using default metadata.")
            self.client.create_vertex(vertex_id, timestamp=timestamp, metadata=metadata)

        # Create edges with weights based on specified distribution
        for _ in range(num_edges):
            src_vertex = random.choice(self.client.get_vertices())
            dest_vertex = random.choice([v for v in self.client.get_vertices() if v != src_vertex])
            weight = self._generate_weight(weight_distribution)
            edge_id = f"edge_{src_vertex}_{dest_vertex}"
            self.client.create_edge(edge_id, src_vertex, dest_vertex, weight=weight)

    def _generate_weight(self, distribution):
        if distribution == 'uniform':
            return random.uniform(1, 10)
        elif distribution == 'exponential':
            return random.expovariate(1.0 / 5)
        elif distribution == 'normal':
            return random.gauss(5, 2)
        else:
            raise ValueError("Invalid weight distribution specified.")
```

Note: This code assumes the existence of a `GraphDBClient` class with methods for creating vertices and edges, as well as retrieving existing vertices. The `_generate_weight` method is responsible for generating edge weights based on the specified distribution.

