function asyncReduce(arr, initialValue, callback, cb) {
  let result = initialValue;
  arr.forEach((num, index) => {
    setTimeout(() => {
      result = callback(result, num);
      if (index === arr.length - 1) {
        cb(null, result);
      }
    }, Math.random() * 500); // Simulate asynchronous operation with random delay
  });
}

