import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.net.URL;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.HashMap;
import java.util.Map;

public class ImageDownloader {
    private static final ExecutorService executor = Executors.newSingleThreadExecutor();
    private static final Map<String, File> cache = new HashMap<>();
    private String authKey;
    private int maxDownloadsPerHour;

    public ImageDownloader(String authKey, int maxDownloadsPerHour) {
        this.authKey = authKey;
        this.maxDownloadsPerHour = maxDownloadsPerHour;
    }

    public void downloadImage(String imageUrl, String format, Quality quality) throws IOException {
        if (cache.containsKey(imageUrl)) {
            System.out.println("Serving image from cache: " + imageUrl);
            return;
        }

        if (!isValidDownload()) {
            throw new RuntimeException("Rate limit exceeded");
        }

        URL url = new URL(imageUrl);
        File file = new File("downloaded_images/" + generateFileName(imageUrl, format, quality));
        cache.put(imageUrl, file);

        try (FileOutputStream fos = new FileOutputStream(file)) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = url.openStream().read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
        }

        System.out.println("Image downloaded: " + imageUrl);
    }

    private String generateFileName(String imageUrl, String format, Quality quality) {
        return imageUrl.substring(imageUrl.lastIndexOf('/') + 1).replaceFirst("[.][^.]+$", "") + "_" + format + "_" + quality.name() + "." + format.toLowerCase();
    }

    private boolean isValidDownload() {
        // Logic to check if the download is within the rate limit
        return true;
    }

    public void clearCache() {
        cache.clear();
        System.out.println("Cache cleared");
    }

    public static void main(String[] args) {
        ImageDownloader downloader = new ImageDownloader("your_auth_key", 100);
        try {
            downloader.downloadImage("http://example.com/image.jpg", "JPEG", Quality.HIGH);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public enum Quality {
        LOW, MEDIUM, HIGH
    }
}
