#include <string>
#include <future>
#include <chrono>
#include <fstream>
#include <sstream>

void logOperation(const std::string& operation) {
    auto now = std::chrono::system_clock::now();
    auto time_str = std::chrono::system_clock::to_time_t(now);
    std::ofstream logfile("async_operations.log", std::ios_base::app);
    if (logfile.is_open()) {
        logfile << std::put_time(std::localtime(&time_str), "%Y-%m-%d %X") << " - " << operation << std::endl;
        logfile.close();
    }
}

std::string asyncReduce(const std::forward_list<std::string>& list, const std::string& initialValue, const std::function<std::string(const std::string&, const std::string&)>& lambda) {
    std::promise<std::string> resultPromise;
    auto future = resultPromise.get_future();

    std::async(std::launch::async, [&list, &initialValue, &lambda, &resultPromise]() {
        std::string accumulatedValue = initialValue;
        for (const auto& item : list) {
            accumulatedValue = lambda(accumulatedValue, item);
            logOperation("Reduced: " + accumulatedValue);
        }
        resultPromise.set_value(accumulatedValue);
    });

    return future.get();
}
