import logging

def modify_kickstart_config(params):
    lock = threading.Lock()
    log_file = 'config_modification.log'

    def secure_hash(password):
        salt = bcrypt.gensalt()
        return bcrypt.hashpw(password.encode('utf-8'), salt)

    try:
        with open(params['kickstart_path'], 'r') as file:
            content = file.read()

        for key, value in params.items():
            if key.startswith('password'):
                hashed_value = secure_hash(value)
                content = content.replace(f'{key} {value}', f'{key} {hashed_value}')

        with lock:
            with open(params['kickstart_path'], 'w') as file:
                file.write(content)

        logging.basicConfig(filename=log_file, level=logging.INFO)
        logging.info('Kickstart configuration modified and encrypted successfully.')

    except Exception as e:
        logging.error(f'Failed to modify Kickstart configuration: {e}')

# Example usage
