using System.Collections.Generic;
using UnityEngine;

public class ValueGenerator
{
    private int min;
    private int max;

    public ValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }
        min = minValue;
        max = maxValue;
    }

    public void SeedRandom(int seed)
    {
        UnityEngine.Random.InitState(seed);
    }

    public float GetRandomFloat(float minValue, float maxValue)
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public int GetRandomInteger(int minValue, int maxValue)
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public List<int> GetUniqueRandomIntegers(int count, int rangeMin, int rangeMax)
    {
        if (count > (rangeMax - rangeMin + 1))
        {
            throw new ArgumentException("Cannot generate more unique values than are available in the range.");
        }
        HashSet<int> uniqueNumbers = new HashSet<int>();
        while (uniqueNumbers.Count < count)
        {
            uniqueNumbers.Add(UnityEngine.Random.Range(rangeMin, rangeMax + 1));
        }
        return new List<int>(uniqueNumbers);
    }

    public bool IsValueInSubset(int value, int subsetMin, int subsetMax)
    {
        return value >= subsetMin && value <= subsetMax;
    }

    public override string ToString()
    {
        return $"Range: {min} to {max}";
    }
}
