#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>

#define MAX_COMMANDS 100

typedef struct {
    char *command[MAX_COMMANDS];
    int priority;
} Command;

Command commands[] = {
    {"ls", "-l"},
    {"sleep", "5"},
    {"echo", "Hello, World!"},
};

int command_count = sizeof(commands) / sizeof(commands[0]);

void execute_command(Command cmd) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    } else if (pid == 0) {
        // Child process
        execvp(cmd.command[0], cmd.command);
        perror("execvp");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            printf("Command %s exited with status %d\n", cmd.command[0], WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("Command %s terminated by signal %d\n", cmd.command[0], WTERMSIG(status));
        }
    }
}

int main() {
    time_t start_time, end_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    for (int i = 0; i < command_count; i++) {
        execute_command(commands[i]);
    }

    clock_gettime(CLOCK_REALTIME, &end_time);
    double elapsed_time = (double)(end_time.tv_sec - start_time.tv_sec) +
                           (double)(end_time.tv_nsec - start_time.tv_nsec) / 1e9;
    printf("Total execution time: %f seconds\n", elapsed_time);

    return 0;
}
