from flask import Flask, request, jsonify
import requests
from functools import lru_cache
import time

app = Flask(__name__)

# Configuration
CMS_API_URL = "https://api.certificatemanagement.com/v1"
OAUTH_TOKEN_URL = "https://oauth.certificatemanagement.com/token"

# OAuth2 token cache with TTL of 3600 seconds (1 hour)
@lru_cache(maxsize=None, typed=False)
def get_oauth_token(client_id: str, client_secret: str) -> str:
    response = requests.post(
        OAUTH_TOKEN_URL,
        data={
            "grant_type": "client_credentials",
            "client_id": client_id,
            "client_secret": client_secret
        }
    )
    if response.status_code == 200:
        return response.json().get("access_token")
    else:
        raise Exception("Failed to fetch OAuth token")

# Certificate cache with TTL of 3600 seconds (1 hour)
@lru_cache(maxsize=None, typed=False)
def get_certificate(oauth_token: str, resource_id: str) -> str:
    headers = {
        "Authorization": f"Bearer {oauth_token}"
    }
    response = requests.get(
        f"{CMS_API_URL}/certificates/{resource_id}",
        headers=headers
    )
    if response.status_code == 200:
        return response.json().get("certificate_pem")
    else:
        raise Exception("Failed to fetch certificate")

@app.route('/generate-certificate', methods=['POST'])
def generate_certificate():
    data = request.get_json()
    client_id = data.get('client_id')
    scope = data.get('scope')
    resource_id = data.get('resource_id')

    if not all([client_id, scope, resource_id]):
        return jsonify({"error": "Missing required parameters"}), 400

    try:
        oauth_token = get_oauth_token(client_id, client_secret)
        certificate_pem = get_certificate(oauth_token, resource_id)
        return jsonify({"certificate_pem": certificate_pem}), 200
    except Exception as e:
        app.logger.error(f"Error generating certificate: {e}")
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
