// Define constants for the octree structure
const int MAX_CHILDREN = 8;
const int LEAF_NODE_SIZE = 32;

// Define constants for the command-line arguments
const std::string TEXT_FORMAT = "--text";
const std::string BINARY_FORMAT = "--binary";
const std::string SERVER_LIST = "-s";
const std::string OUTPUT_FILE = "-o";

// Define constants for error handling and logging
const int MAX_RETRIES = 5;
const double BACKOFF_FACTOR = 2.0;

class Octree {
public:
    Octree(int featureSize, int leafNodes) : size(featureSize), leaves(leafNodes) {}

    void allocateMemory() {
        // Allocate memory for the octree structure
        nodes = new Node*[size];
        for (int i = 0; i < size; ++i) {
            nodes[i] = new Node[MAX_CHILDREN];
        }

        // Allocate memory for prefix leafs and data arrays
        prefixLeafs = new int[leafNodes * LEAF_NODE_SIZE];
        dataArray = new char[leafNodes * LEAF_NODE_SIZE];

        // Initialize the octree structure
        initializeOctree();
    }

private:
    struct Node {
        Node* children[MAX_CHILDREN] = {};
        bool isLeaf = false;
    };

    int size;
    int leaves;
    Node** nodes;
    int* prefixLeafs;
    char* dataArray;

    void initializeOctree() {
        // Initialize the octree structure with default values
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < MAX_CHILDREN; ++j) {
                nodes[i][j].isLeaf = true;
            }
        }

        // Populate the prefix leafs and data arrays with default values
        for (int i = 0; i < leaves * LEAF_NODE_SIZE; ++i) {
            prefixLeafs[i] = 0;
            dataArray[i] = '0';
        }
    }
};

