        } else if (std::string(argv[i]) == SERVER_LIST && i + 1 < argc) {
            // Parse server list
            std::string servers = argv[++i];
        } else if (std::string(argv[i]) == OUTPUT_FILE && i + 1 < argc) {
            outputFilePath = argv[++i];
        }
    }

    // Process messages concurrently
    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back([&]() {
