import java.util.*;

public class UserProfileManager {
    public static void main(String[] args) {
        // Example usage
        List<Integer> userIds = Arrays.asList(1, 2, 3);
        List<String> usernames = Arrays.asList("user1", "user2", "user3");
        List<String> emails = Arrays.asList("user1@example.com", "user2@example.com", "user3@example.com");
        List<Map<String, String>> preferencesList = Arrays.asList(
            new HashMap<>(Map.of("theme", "dark")),
            new HashMap<>(Map.of("notifications", "enabled")),
            new HashMap<>(Map.of("language", "en"))
        );
        List<byte[]> profileImages = Arrays.asList(new byte[1024], new byte[2048], new byte[512]);

        try {
            UserProfile[] profiles = createProfiles(userIds, usernames, emails, preferencesList, profileImages);
            for (UserProfile profile : profiles) {
                System.out.println(profile);
            }
        } catch (Exception e) {
            System.err.println("Error creating user profiles: " + e.getMessage());
        }
    }

    public static UserProfile[] createProfiles(List<Integer> userIds, List<String> usernames, List<String> emails, List<Map<String, String>> preferencesList, List<byte[]> profileImages) throws Exception {
        if (userIds.size() != usernames.size() || userIds.size() != emails.size() || userIds.size() != preferencesList.size() || userIds.size() != profileImages.size()) {
            throw new IllegalArgumentException("All input lists must have the same size.");
        }

        UserProfile[] profiles = new UserProfile[userIds.size()];
        for (int i = 0; i < userIds.size(); i++) {
            int userId = userIds.get(i);
            String username = usernames.get(i);
            String email = emails.get(i);
            Map<String, String> preferences = preferencesList.get(i);
            byte[] profileImage = profileImages.get(i);

            profiles[i] = new UserProfile(userId, username, email, preferences, profileImage);
        }

        return profiles;
    }
}

class UserProfile {
    private int userId;
    private char[] username;
    private String email;
    private Map<String, String> preferences;
    private byte[] profileImage;

    public UserProfile(int userId, String username, String email, Map<String, String> preferences, byte[] profileImage) {
        this.userId = userId;
        this.username = username.toCharArray();
        for (int i = username.length(); i < this.username.length; i++) {
            this.username[i] = '\0'; // Null-terminate the username
        }
        this.email = email;
        this.preferences = preferences;
        this.profileImage = profileImage;
    }

    @Override
    public String toString() {
        return "UserProfile{" +
                "userId=" + userId +
                ", username='" + new String(username) + '\'' +
                ", email='" + email + '\'' +
                ", preferences=" + preferences +
                ", profileImage length=" + profileImage.length +
                '}';
    }
}
