const express = require('express');
const bodyParser = require('body-parser');
const app = express();
app.use(bodyParser.json());

let resources = {}; // Simulated database
let resourceVersion = 0;

// Middleware for optimistic concurrency control
function checkConcurrency(req, res, next) {
    const { id } = req.params;
    if (resources[id] && resources[id].version !== parseInt(req.headers['if-match'], 10)) {
        return res.status(412).json({ error: 'Precondition failed' });
    }
    next();
}

// Middleware for authentication
function authenticateUser(req, res, next) {
    // Replace with actual authentication logic
    if (req.headers.authorization === 'Bearer valid_token') {
        next();
    } else {
        res.status(401).json({ error: 'Unauthorized' });
    }
}

app.put('/api/resource/:id', authenticateUser, checkConcurrency, (req, res) => {
    const { id } = req.params;
    resources[id] = { ...resources[id], ...req.body, version: ++resourceVersion };
    res.status(200).json(resources[id]);
});

app.delete('/api/resource/:id', authenticateUser, (req, res) => {
    const { id } = req.params;
    if (!resources[id]) {
        return res.status(404).json({ error: 'Resource not found' });
    }
    resources[id] = { ...resources[id], ...getDefaultValue(), version: ++resourceVersion };
    res.status(200).json(resources[id]);
});

app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
