from flask import Flask, request, jsonify, abort
import time

app = Flask(__name__)

resources = {}  # Simulated database
resource_version = 0

def check_concurrency(id, if_match):
    global resource_version
    current_resource = resources.get(id)
    if current_resource and current_resource['version'] != int(if_match):
        abort(412)

def authenticate_user(f):
    def wrapper(*args, **kwargs):
        if request.headers.get('Authorization') == 'Bearer valid_token':
            return f(*args, **kwargs)
        else:
            abort(401)
    return wrapper

@app.route('/api/resource/<int:id>', methods=['PUT'])
@authenticate_user
def update_resource(id):
    global resource_version
    data = request.json
    check_concurrency(id, request.headers.get('If-Match'))
    resources[id] = {**resources.get(id, {}), **data, 'version': resource_version}
    resource_version += 1
    return jsonify(resources[id]), 200

@app.route('/api/resource/<int:id>', methods=['DELETE'])
@authenticate_user
def delete_resource(id):
    global resource_version
    if id not in resources:
        abort(404)
    default_value = get_default_value()
    resources[id] = {**resources.get(id, {}), **default_value, 'version': resource_version}
    resource_version += 1
    return jsonify(resources[id]), 200

if __name__ == '__main__':
    app.run(port=3000)
