```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <cstdlib>
#include <ctime>

struct Record {
    int value;
};

int loadResourceBundle(const std::string& filename, size_t* count, long** offsets, int** keys, Record** records) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        return 1; // Error opening file
    }

    *count = 0;
    std::vector<Record> recordList;

    while (true) {
        int value;
        if (!(file >> value)) {
            break;
        }
        Record record = {value};
        recordList.push_back(record);
        (*count)++;
    }

    *offsets = new long[*count];
    *keys = new int[*count];
    *records = new Record[*count];

    for (size_t i = 0; i < *count; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = static_cast<int>(rand() % 100); // Example random key
        (*records)[i] = recordList[i];
    }

    file.close();
    return 0; // Success
}

int main() {
    srand(time(0)); // Seed for random number generation

    size_t count;
    long* offsets;
    int* keys;
    Record* records;

    int result = loadResourceBundle("resourcebundle.txt", &count, &offsets, &keys, &records);
    if (result != 0) {
        std::cerr << "Failed to load resource bundle with error code: " << result << std::endl;
        return result;
    }

    // Process and analyze data streams
    for (size_t i = 0; i < count; ++i) {
        std::cout << "Offset: " << offsets[i] << ", Key: " << keys[i] << ", Value: " << records[i].value << std::endl;
    }

    // Clean up dynamically allocated memory
    delete[] offsets;
    delete[] keys;
    delete[] records;

    return 0;
}
