// Define constants for command-line options
const std::string TEXT_OPTION = "--text";
const std::string BINARY_OPTION = "--binary";
const std::string SERVER_ADDRESS_OPTION = "-cs";
const std::string OUTPUT_FILE_OPTION = "-o";

// Function to parse command-line arguments and return configuration settings
struct Config {
    bool isText;
    boost::asio::ip::tcp::resolver::results_type endpoints;
    std::string outputFile;
};

Config parseCommandLine(int argc, char* argv[]) {
    Config config;
    for (int i = 1; i < argc; ++i) {
        if (argv[i] == TEXT_OPTION || argv[i] == BINARY_OPTION) {
            config.isText = (argv[i] == TEXT_OPTION);
        } else if (argv[i] == SERVER_ADDRESS_OPTION && i + 1 < argc) {
            boost::asio::ip::tcp::resolver resolver;
            config.endpoints = resolver.resolve(argv[++i]);
        } else if (argv[i] == OUTPUT_FILE_OPTION && i + 1 < argc) {
            config.outputFile = argv[++i];
        }
    }
    return config;
}

// Function to load a resource bundle from a file
