using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashingService : IDisposable
{
    private static readonly MD5 md5 = MD5.Create();
    private readonly object lockObject = new object();

    public string GenerateMd5Hash(string input, string salt = null)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentNullException(nameof(input));

        if (!IsValidEmailFormat(input) && !IsValidPasswordStrength(input))
            throw new ArgumentException("Invalid email or password format.");

        using (var cryptoProvider = new System.Security.Cryptography.MD5CryptoServiceProvider())
        {
            lock (lockObject)
            {
                byte[] inputBytes;
                if (salt != null)
                    inputBytes = Encoding.UTF8.GetBytes(salt + input);
                else
                    inputBytes = Encoding.UTF8.GetBytes(input);

                byte[] hashBytes = cryptoProvider.ComputeHash(inputBytes);
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
            }
        }
    }

    public void UpdateUserProfile(string userId, string email, string password, string address)
    {
        if (string.IsNullOrEmpty(userId) || string.IsNullOrEmpty(email) || string.IsNullOrEmpty(password))
            throw new ArgumentNullException("User ID, email or password cannot be null.");

        if (!IsValidEmailFormat(email) && !IsValidPasswordStrength(password))
            throw new ArgumentException("Invalid email or password format.");

        try
        {
            // Assume we have a method to interact with the external database
            UpdateDatabase(userId, email, GenerateMd5Hash(password), address);

            LogUpdate(userId, email);
        }
        catch (Exception ex)
        {
            HandleDbError(ex);
        }
    }

    private bool IsValidEmailFormat(string input)
    {
        // Simple regex for email validation
        return System.Text.RegularExpressions.Regex.IsMatch(input, @"^\S+@\S+\.\S+$");
    }

    private bool IsValidPasswordStrength(string input)
    {
        // Password strength criteria (e.g., at least 8 characters, one uppercase letter, etc.)
        return input.Length >= 8 && char.IsUpper(input[0]) && input.Any(char.IsDigit);
    }

    private void UpdateDatabase(string userId, string email, string passwordHash, string address)
    {
        // Simulated database update operation
        Console.WriteLine($"Updating user {userId} with email {email}, password hash {passwordHash}, and address {address}");
    }

    private void LogUpdate(string userId, string email)
    {
        // Simulated log operation
        Console.WriteLine($"Updated user {userId} at {DateTime.Now}");
    }

    private void HandleDbError(Exception ex)
    {
        // Simulated error handling
        Console.WriteLine($"Database error: {ex.Message}");
    }

    public void Dispose()
    {
        md5.Dispose();
    }
}
