void* load_data_thread(void* arg) {
    while (!stop_flag) {
        // Simulate data loading from file
        FILE* fp = fopen(FILE_PATH, "rb");
        if (fp == NULL) {
            perror("Failed to open file");
            continue;
        }

        int new_num_records = 0;
        record* new_records = malloc(MAX_RECORDS * sizeof(record));
        while (!feof(fp)) {
            char buffer[256];
            size_t bytes_read = fread(buffer, 1, sizeof(buffer), fp);
            if (bytes_read > 0) {
                record r;
                r.transaction_details = strndup(buffer, bytes_read);
                new_records[new_num_records++] = r;

                // Simulate rate limiting
                usleep(100 * 1000); // Sleep for 100ms
            }
        }

        fclose(fp);

        if (new_num_records > 0) {
            sem_wait(&records_mutex);
            records = realloc(records, new_num_records * sizeof(record));
            memcpy(records, new_records, new_num_records * sizeof(record));
            num_records = new_num_records;
            sem_post(&records_mutex);
            pthread_cond_signal(&records_cv);
        }

        free(new_records);
    }
    return NULL;
}

void* validate_data_thread(void* arg) {
