                // Handle validation failure
            }
        }

        sem_post(&records_mutex);

        // Simulate rate limiting
        usleep(10 * 1000 * 1000); // Sleep for 10 seconds
    }
    return NULL;
}

int validate_record(const char* details) {
    // Implement API call to validate record
    // Return 1 if valid, 0 otherwise
    return 1; // Placeholder
}

void* resize_records_thread(void* arg) {
    while (!stop_flag) {
        sem_wait(&records_mutex);
        int new_capacity = num_records * 2;
        records = realloc(records, new_capacity * sizeof(record));
        sem_post(&records_mutex);

        // Simulate rate limiting
        usleep(10 * 1000 * 1000); // Sleep for 10 seconds
    }
    return NULL;
}

int main() {
    records = malloc(MAX_RECORDS * sizeof(record));
    sem_init(&records_mutex, 0, 1);
    pthread_cond_init(&records_cv, NULL);

    pthread_t load_thread, validate_thread, resize_thread;
    pthread_create(&load_thread, NULL, load_data_thread, NULL);
    pthread_create(&validate_thread, NULL, validate_data_thread, NULL);
    pthread_create(&resize_thread, NULL, resize_records_thread, NULL);

    // Simulate running for some time
