    stop_flag = 1;
    sem_post(&records_mutex);
    pthread_cond_broadcast(&records_cv);
    pthread_join(load_thread, NULL);
    pthread_join(validate_thread, NULL);
    pthread_join(resize_thread, NULL);

    free(records);
    sem_destroy(&records_mutex);
    pthread_cond_destroy(&records_cv);

    return 0;
