using System;
using System.Data;
using System.Data.Common;
using System.Data.SqlClient;

public class DatabaseConnectionPool
{
    private DbProviderFactory _factory;
    private string _connectionString;
    private int _maxConnections;
    private int _timeout;
    private Queue<DbConnection> _pool;
    private object _lock = new object();

    public DatabaseConnectionPool(DbProviderFactory factory, string connectionString, int maxConnections, int timeout)
    {
        _factory = factory;
        _connectionString = connectionString;
        _maxConnections = maxConnections;
        _timeout = timeout;
        _pool = new Queue<DbConnection>();
    }

    public DataTableReader ExecuteQuery(byte[] data)
    {
        DbConnection connection = GetConnection();
        try
        {
            DbCommand command = connection.CreateCommand();
            // Set up command based on data
            return (DataTableReader)command.ExecuteReader();
        }
        finally
        {
            ReleaseConnection(connection);
        }
    }

    private DbConnection GetConnection()
    {
        lock (_lock)
        {
            if (_pool.Count > 0)
            {
                DbConnection connection = _pool.Dequeue();
                if (!connection.State.Equals(ConnectionState.Open))
                    connection.Open();
                return connection;
            }
            else if (_pool.Count < _maxConnections)
            {
                DbConnection connection = _factory.CreateConnection();
                connection.ConnectionString = _connectionString;
                connection.Open();
                return connection;
            }
        }

        throw new InvalidOperationException("Maximum number of connections reached.");
    }

    private void ReleaseConnection(DbConnection connection)
    {
        lock (_lock)
        {
            if (connection.State.Equals(ConnectionState.Open))
                _pool.Enqueue(connection);
        }
    }

    public void Shutdown()
    {
        lock (_lock)
        {
            while (_pool.Count > 0)
            {
                DbConnection connection = _pool.Dequeue();
                try
                {
                    connection.Close();
                }
                catch { } // Ignore errors during shutdown
            }
        }
    }
}
