#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

// Function to parse line and compute average of last two measurements
void process_line(char *line, FILE *output_file) {
    char *token;
    float sum = 0.0f;
    int count = 0;

    // Tokenize the line by space
    token = strtok(line, " ");
    while (token != NULL) {
        // Convert each token to a float and add to sum
        if (count >= 2) { // Only consider last two measurements
            char *endptr;
            float value = strtof(token, &endptr);
            if (*endptr == '\0') { // Check if conversion was successful
                sum += value;
                count++;
            } else {
                fprintf(stderr, "Non-numerical data encountered: %s\n", token);
                return;
            }
        }
        token = strtok(NULL, " ");
    }

    // Calculate average and append to line
    float average = (count == 0) ? 0.0f : sum / count;

    // Write processed line back to file
    fprintf(output_file, "%s %.2f\n", line, average);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *input_file = fopen(argv[1], "r");
    if (input_file == NULL) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    FILE *output_file = fopen(argv[2], "w");
    if (output_file == NULL) {
        perror("Failed to open output file");
        fclose(input_file);
        return EXIT_FAILURE;
    }

    char line[MAX_LINE_LENGTH];

    // Read and process each line
    while (fgets(line, sizeof(line), input_file) != NULL) {
        process_line(line, output_file);
    }

    // Close files
    fclose(input_file);
    fclose(output_file);

    return EXIT_SUCCESS;
}
