using System;
using System.Data.Common;
using System.Data.SqlClient;

class EmployeeConnectionPool
{
    private string _connectionString;
    private int _maxConnections;
    private int _connectionTimeout;
    private Queue<DbConnection> _connectionQueue;

    public EmployeeConnectionPool(string connectionString, int maxConnections, int connectionTimeout)
    {
        _connectionString = connectionString;
        _maxConnections = maxConnections;
        _connectionTimeout = connectionTimeout;
        _connectionQueue = new Queue<DbConnection>(maxConnections);
    }

    public DbConnection GetConnection()
    {
        if (_connectionQueue.Count > 0)
        {
            return _connectionQueue.Dequeue();
        }
        else if (_connectionQueue.Count < _maxConnections)
        {
            var connection = new SqlConnection(_connectionString)
            {
                ConnectionTimeout = _connectionTimeout
            };
            connection.Open();
            return connection;
        }
        else
        {
            throw new InvalidOperationException("Connection pool is full.");
        }
    }

    public void ReleaseConnection(DbConnection connection)
    {
        if (connection.State == System.Data.ConnectionState.Closed)
        {
            connection.Close();
        }
        _connectionQueue.Enqueue(connection);
    }
}

class Program
{
    static void Main(string[] args)
    {
        string connectionString = "your_connection_string_here";
        int maxConnections = 10;
        int connectionTimeout = 30;

        EmployeeConnectionPool pool = new EmployeeConnectionPool(connectionString, maxConnections, connectionTimeout);

        using (DbConnection connection = pool.GetConnection())
