import os
from collections import Counter
from concurrent.futures import ThreadPoolExecutor, as_completed
import time

def get_device_identifier(file_path):
    try:
        stat_info = os.stat(file_path)
        return stat_info.st_dev
    except (FileNotFoundError, PermissionError) as e:
        print(f"Error processing {file_path}: {e}")
        return None

def count_unique_file_systems(file_paths):
    device_identifiers = Counter()

    with ThreadPoolExecutor() as executor:
        future_to_file = {executor.submit(get_device_identifier, path): path for path in file_paths}
        for future in as_completed(future_to_file):
            file_path = future_to_file[future]
            try:
                device_id = future.result()
                if device_id is not None:
                    device_identifiers[device_id] += 1
            except Exception as e:
                print(f"Error processing {file_path}: {e}")

    return len(device_identifiers)

# Example usage:
file_paths = ["/path/to/file1", "/path/to/file2", ...]
