import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;

public class FileHasher {

    private static final String MD5 = "MD5";

    public synchronized String hashFile(String filePath) {
        Path path = Path.of(filePath);
        try {
            BasicFileAttributes attributes = Files.readAttributes(path, BasicFileAttributes.class);
            long fileSize = attributes.size();
            long lastModifiedTime = attributes.lastModifiedTime().toMillis();

            // Check if the file has been modified
            FileHashEntry entry = getFileHashEntry(filePath);
            if (entry != null && entry.getFileSize() == fileSize && entry.getLastModifiedTime() == lastModifiedTime) {
                return entry.getHash();
            }

            byte[] fileBytes = Files.readAllBytes(path);
            MessageDigest md = MessageDigest.getInstance(MD5);
            byte[] hashBytes = md.digest(fileBytes);
            String hash = bytesToHex(hashBytes);

            // Store the new hash in a thread-safe manner
            putFileHashEntry(filePath, fileSize, lastModifiedTime, hash);
            return hash;
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
            return null;
        }
    }

    private FileHashEntry getFileHashEntry(String filePath) {
        // Implement logic to retrieve file hash entry from a thread-safe data structure
        // For example, using a ConcurrentHashMap
        return new FileHashEntry(filePath);
    }

    private void putFileHashEntry(String filePath, long fileSize, long lastModifiedTime, String hash) {
        // Implement logic to store file hash entry in a thread-safe manner
        // For example, using a ConcurrentHashMap
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        FileHasher hasher = new FileHasher();
        String hash1 = hasher.hashFile("path/to/your/file.txt");
        String hash2 = hasher.hashFile("path/to/your/file.txt");
        System.out.println("Hash 1: " + hash1);
        System.out.println("Hash 2: " + hash2);
    }
}

