import pytest
from multiprocessing import Pool
import time

def execute_module_tests(test_functions, label=None, parallel=False):
    def run_test(func):
        try:
            start_time = time.time()
            result = func()
            end_time = time.time()
            print(f"{label} - Test: {func.__name__}, Result: PASS, Time: {end_time - start_time:.2f}s")
        except Exception as e:
            print(f"{label} - Test: {func.__name__}, Result: FAIL, Error: {e}")

    def run_tests_in_parallel(tests):
        with Pool(processes=min(len(tests), 10)) as pool:
            pool.map(run_test, tests)

    if parallel:
        run_tests_in_parallel(test_functions)
    else:
        for test in test_functions:
            run_test(test)

# Example usage
def test_example_1():
    assert 1 + 1 == 2

def test_example_2():
    assert "Hello" == "Hello"

execute_module_tests([test_example_1, test_example_2], label="Module 1", parallel=True)
