```java
import java.io.IOException;
import java.nio.file.*;
import java.time.Duration;
import java.util.List;
import java.util.concurrent.*;

public class FileSizeCalculator {

    private static final int MAX_CONCURRENCY = Runtime.getRuntime().availableProcessors();
    private static long totalFileSize;
    private static int errorCount;

    public static void main(String[] args) {
        Path folderPath = Paths.get("path/to/folder");
        List<String> supportedMimeTypes = List.of("image/jpeg", "image/png");

        try (ForkJoinPool pool = new ForkJoinPool(MAX_CONCURRENCY)) {
            long startTime = System.nanoTime();
            processFiles(folderPath, supportedMimeTypes, pool);
            long endTime = System.nanoTime();

            Duration processingTime = Duration.ofNanos(endTime - startTime);
            System.out.println("Total file size: " + totalFileSize + " bytes");
            System.out.println("Processing time: " + processingTime.toMillis() + " ms");
        }
    }

    private static void processFiles(Path folderPath, List<String> supportedMimeTypes, ForkJoinPool pool) {
        FileSizeTask task = new FileSizeTask(folderPath, supportedMimeTypes);
        pool.invoke(task);
    }

    private static class FileSizeTask extends RecursiveAction {

        private final Path path;
        private final List<String> supportedMimeTypes;

        public FileSizeTask(Path path, List<String> supportedMimeTypes) {
            this.path = path;
            this.supportedMimeTypes = supportedMimeTypes;
        }

        @Override
        protected void compute() {
            try {
                if (Files.isDirectory(path)) {
                    Files.walkFileTree(path, new SimpleFileVisitor<Path>() {
                        @Override
                        public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                            checkMimeAndSize(file, attrs);
                            return FileVisitResult.CONTINUE;
                        }

                        @Override
                        public FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
                            if (exc != null)
                                throw exc;
                            return FileVisitResult.CONTINUE;
                        }
                    });
                } else {
                    checkMimeAndSize(path, Files.readAttributes(path, BasicFileAttributes.class));
                }
            } catch (IOException e) {
                errorCount++;
                System.err.println("Error processing file: " + path + ", Error: " + e.getMessage());
            }
        }

        private void checkMimeAndSize(Path file, BasicFileAttributes attrs) throws IOException {
            String mimeType = Files.probeContentType(file);
            if (mimeType != null && supportedMimeTypes.contains(mimeType)) {
                totalFileSize += attrs.size();
            }
        }
    }
}
