use threadpool::ThreadPool;

// Define the main function that processes input strings and compiles them
fn process_and_compile(input_strings: Vec<String>, size_limit: usize, max_concurrency: u32, max_rss_mb: u32, retry_count: usize) -> Result<Vec<String>, String> {
    // Initialize global logger using SyncLazy for thread-safe access
    static LOGGER: SyncLazy<GlobalLogger> = SyncLazy::new(|| GlobalLogger::new());

    // Create a thread pool to manage compilation tasks concurrently
    let pool = ThreadPool::with_num_threads(max_concurrency as usize);

    // Initialize variables for error aggregation and RSS monitoring
    let mut error_count = 0;
    let rss_threshold = max_rss_mb * 1024 * 1024; // Convert MB to bytes

    // Iterate over input strings and submit compilation tasks to the thread pool
    for string in input_strings {
        if string.len() <= size_limit {
            continue;
        }
        pool.execute(move || {
            let start_time = Instant::now();
            let result = compile_string(&string, &LOGGER);
            match result {
                Ok(_) => println!("Compilation succeeded: {}", string),
                Err(e) => {
                    println!("Compilation failed for {}: {}", string, e);
                    error_count += 1;
                }
            }
            let duration = start_time.elapsed();
            LOGGER.log_compilation_duration(&string, duration);
        });
    }

    // Wait for all compilation tasks to complete
    pool.join();

    if error_count > 0 {
        return Err(format!("{} compilations failed", error_count));
    }

    Ok(input_strings)
}

