class NfapiCrcIndicationPdu {
private:
    int RxUeInformationTag;
    int Rnti;
    bool CrcIndicationRel8Tag;

public:
    NfapiCrcIndicationPdu(int rxUeInfoTag, int rnti, bool crcFlag)
        : RxUeInformationTag(rxUeInfoTag), Rnti(rnti), CrcIndicationRel8Tag(crcFlag) {}

    void serializeForNetwork() {
        // Placeholder for network serialization logic
        std::cout << "Serializing PDU with RxUeInfoTag: " << RxUeInformationTag 
                  << ", RNTI: " << Rnti << ", CRC Flag: " << (CrcIndicationRel8Tag ? "True" : "False") << std::endl;
    }
};

std::vector<NfapiCrcIndicationPdu> initializeAndPopulatePDUs(int N) {
    if (N < 0) {
        throw std::invalid_argument("Number of PDUs must be non-negative.");
    }

    std::mt19937 generator(static_cast<unsigned int>(time(0)));
    std::uniform_int_distribution<int> distribution(1, 1000);

    std::vector<NfapiCrcIndicationPdu> pdus;
    pdus.reserve(N); // Efficient memory allocation

    for (int i = 0; i < N; ++i) {
        int rxUeInfoTag = distribution(generator);
        int rnti = distribution(generator);
        bool crcFlag = generator() % 2 == 0; // Randomly set CRC flag
        pdus.emplace_back(rxUeInfoTag, rnti, crcFlag);
    }

    return pdus;
}

int main() {
    try {
        int numPDUs = 10; // Example number of PDUs to create
        auto pdus = initializeAndPopulatePDUs(numPDUs);

        for (const auto& pdu : pdus) {
            pdu.serializeForNetwork();
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
