// Import necessary modules
const express = require('express');
const axios = require('axios');
const redis = require('redis');
const pg = require('pg');
const rateLimit = require('express-rate-limit');
const bodyParser = require('body-parser');

// Initialize Express app
const app = express();
app.use(bodyParser.json());
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

// Connect to Redis
const redisClient = redis.createClient();

// Connect to PostgreSQL
const pool = new pg.Pool({
  user: 'your_username',
  host: 'localhost',
  database: 'your_database',
  password: 'your_password',
  port: 5432,
});

// Function to fetch financial transactions
async function fetchTransactions(userId) {
  try {
    const response = await axios.get(`https://third-party-api.com/transactions?userId=${userId}`);
    return response.data;
  } catch (error) {
    console.error('Error fetching transactions:', error);
    throw error;
  }
}

// Function to aggregate transaction amounts
function reduceTransactions(transactions) {
  return transactions.reduce((acc, transaction) => acc + transaction.amount, 0);
}

// Route to process transactions
app.post('/process-transactions', async (req, res) => {
  const { userId } = req.body;
  try {
    // Fetch transactions from third-party API
    const transactions = await fetchTransactions(userId);

    // Aggregate transaction amounts
    const totalAmount = reduceTransactions(transactions);

    // Store aggregated data in Redis cache
    redisClient.set(`user:${userId}:total`, totalAmount);

    // Log processing details
    console.log('Transaction processed:', { userId, totalAmount });

    res.status(200).json({ totalAmount });
  } catch (error) {
    res.status(500).json({ error: 'Failed to process transactions' });
  }
});

// Route to fetch aggregated transaction data from Redis
app.get('/user/:userId/total', async (req, res) => {
  const { userId } = req.params;
  try {
    // Retrieve total amount from Redis cache
    redisClient.get(`user:${userId}:total`, (err, totalAmount) => {
      if (err || !totalAmount) {
        res.status(404).json({ error: 'Total amount not found' });
      } else {
        res.json({ userId, totalAmount });
      }
    });
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch total amount' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

This code sets up a Node.js microservice that processes financial transactions from a third-party API. It uses Redis for caching and PostgreSQL for data storage. The service includes rate limiting, error handling, logging, and provides routes to process and fetch aggregated transaction data.

