    if (strlen($newPassword) < 8 || strlen($newPassword) > 64) {
        return json_encode(['error' => 'Password length must be between 8 and 64 characters.']);
    }

    if (!preg_match('/[A-Z]/', $newPassword)) {
        return json_encode(['error' => 'Password must contain at least one uppercase letter.']);
    }

    if (!preg_match('/[a-z]/', $newPassword)) {
        return json_encode(['error' => 'Password must contain at least one lowercase letter.']);
    }

    if (!preg_match('/\d/', $newPassword)) {
        return json_encode(['error' => 'Password must contain at least one digit.']);
    }

    if (!preg_match('/[!@#$%^&*()_+\-=[\]{};':"\\|,.<>/?]/', $newPassword)) {
        return json_encode(['error' => 'Password must contain at least one special character.']);
    }

    // Check if the new password is a common password
    if ($securityService->isCommonPassword($newPassword)) {
        return json_encode(['error' => 'Password cannot be a common password.']);
    }

    // Check if the new password has a simple pattern
    if ($securityService->hasSimplePattern($newPassword)) {
        return json_encode(['error' => 'Password must not be a simple pattern.']);
    }

    // Fetch the user's current password from the database
    $currentUserPassword = $userDAO->getUserPassword($userId);

    // Check if the provided current password matches the stored one
    if ($currentPassword !== $currentUserPassword) {
        return json_encode(['error' => 'Incorrect credentials.']);
    }

    // Update the user's password in the database
    if ($userDAO->updateUser($userId, $newPassword)) {
        return json_encode(['message' => 'Password updated successfully.']);
    } else {
        return json_encode(['error' => 'Database error occurred while updating password.']);
    }
}

// Example usage
echo updateUserPassword(123, 'oldPassword', 'newPassword123!');
