    public CompletableFuture<PokemonAnalysis> getPokemonAnalysis(String name) {
        return CompletableFuture.supplyAsync(() -> {
            PokemonDetails cachedPokemon = pokemonCache.getIfPresent(name);
            if (cachedPokemon != null) {
                return analyzePokemon(cachedPokemon);
            } else {
                try {
                    PokemonResponse response = pokemonApiClient.getPokemon(name);
                    List<MoveResponse> moves = CompletableFuture.allOf(
                            response.moves.stream()
                                    .map(move -> movesApiClient.getMove(move.move.url.split("/")[6]))
                                    .toArray(CompletableFuture[]::new)
                    ).join();
                    List<TypeResponse> types = CompletableFuture.allOf(
                            response.types.stream()
                                    .map(type -> typesApiClient.getType(type.type.url.split("/")[6]))
                                    .toArray(CompletableFuture[]::new)
                    ).join();

                    PokemonDetails pokemonDetails = new PokemonDetails(response, moves, types);
                    pokemonCache.put(name, pokemonDetails);
                    return analyzePokemon(pokemonDetails);
                } catch (Exception e) {
                    // Handle partial data availability and fallback strategies
                    return null;
                }
            }
        });
    }

