from PIL import Image

def extract_png_info(file_path):
    try:
        with Image.open(file_path) as img:
            image_info_list = []
            while True:
                info_dict = {
                    'width': img.width,
                    'height': img.height,
                    'bit_depth': img.mode[1] if len(img.mode) > 1 else 8,
                    'color_type': img.mode
                }
                image_info_list.append(info_dict)

                try:
                    img.seek(img.tell() + 1)
                except EOFError:
                    break

            return image_info_list
    except FileNotFoundError:
        return "Error: File not found."
    except IOError as e:
        return f"IO Error: {e}"
    except Exception as e:
        return f"An unexpected error occurred: {e}"

# Example usage:
file_path = 'path_to_your_png_file.png'
info_list = extract_png_info(file_path)
for info in info_list:
    print(info)
