```javascript
// module-loader.js

class ModuleLoader {
  constructor() {
    this.pendingRequests = [];
    this.loadedModules = {};
    this.maxConcurrentRequests = 5;
  }

  async loadModule(moduleName) {
    if (this.loadedModules[moduleName]) {
      return this.loadedModules[moduleName];
    }

    let moduleUrl = await this.fetchModuleUrl(moduleName);
    if (!moduleUrl) {
      throw new Error(`Module ${moduleName} not found`);
    }

    try {
      const response = await fetch(moduleUrl, { cache: 'no-cache' });
      if (!response.ok) {
        throw new Error(`Failed to load module ${moduleName}`);
      }
      const scriptContent = await response.text();
      const moduleFunction = this.createModuleFunction(scriptContent);
      this.loadedModules[moduleName] = moduleFunction;
      return moduleFunction;
    } catch (error) {
      console.error(`Error loading module ${moduleName}:`, error);
      throw error;
    }
  }

  async fetchModuleUrl(moduleName) {
    // Fetch the URL for the module from an external API or a manifest file
    try {
      const response = await fetch('/api/module-url', { method: 'POST', body: JSON.stringify({ moduleName }) });
      if (!response.ok) {
        throw new Error(`Failed to fetch module URL for ${moduleName}`);
      }
      return await response.json().url;
    } catch (error) {
      console.error('Error fetching module URL:', error);
      // Fallback mechanism for local file loading
      return `/path/to/local/modules/${moduleName}.js`;
    }
  }

  createModuleFunction(scriptContent) {
    const script = document.createElement('script');
    script.type = 'module';
    script.text = scriptContent;
    document.head.appendChild(script);

    return new Promise((resolve, reject) => {
      script.onload = () => resolve();
      script.onerror = (event) => reject(event);
    });
  }

  async loadModules(moduleNames) {
    for (const moduleName of moduleNames) {
      await this.loadModule(moduleName);
    }
  }

  setMaxConcurrentRequests(max) {
    this.maxConcurrentRequests = max;
  }

  getLoadedModules() {
    return Object.keys(this.loadedModules).map((key) => this.loadedModules[key]);
  }
}

export default new ModuleLoader();
```

