import loader from './module-loader';

describe('ModuleLoader', () => {
  it('should load a module and execute its code', async () => {
    const moduleName = 'example';
    const scriptContent = `
      export function exampleFunction() {
        return 'Hello, world!';
      }
    `;

    fetch.mockImplementationOnce(() => Promise.resolve({ text: () => Promise.resolve(scriptContent) }));

    await loader.loadModule(moduleName);
    expect(loader.getLoadedModules().length).toBe(1);
    const module = loader.loadedModules[moduleName];
    expect(typeof module.exampleFunction).toBe('function');
    expect(module.exampleFunction()).toBe('Hello, world!');
  });

  it('should handle loading errors', async () => {
    const moduleName = 'example';

    fetch.mockImplementationOnce(() => Promise.reject(new Error('Network error')));

    await expect(loader.loadModule(moduleName)).rejects.toThrowError('Failed to load module example');
  });
});
