    // Create threads to process each transaction
    for (int i = 0; i < 10; i++) {
        pthread_create(&thread_ids[i], NULL, (void *)processTransaction, &transactions[i]);
    }

    // Join threads after processing is complete
    for (int i = 0; i < 10; i++) {
        pthread_join(thread_ids[i], NULL);
    }

    // Clean up semaphore
    sem_destroy(&sem);

    return 0;
}
