import java.io.*;
import java.net.URL;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.eclipse.jgit.api.*;
import org.eclipse.jgit.lib.*;

public class GitRepositoryManager {

    private static final String REPOS_CACHE_DIR = "/path/to/repos_cache";
    private static final int THREAD_POOL_SIZE = 10;

    public static void main(String[] args) {
        List<String> repoUrls = Arrays.asList("https://github.com/user/repo1.git", "https://github.com/user/repo2.git");
        Set<CompletableFuture<Void>> tasks = new HashSet<>();

        for (String repoUrl : repoUrls) {
            CompletableFuture<Void> task = CompletableFuture.runAsync(() -> cloneOrPullRepo(repoUrl), Executors.newFixedThreadPool(THREAD_POOL_SIZE));
            tasks.add(task);
        }

        CompletableFuture.allOf(tasks.toArray(new CompletableFuture[0])).join();
    }

    private static void cloneOrPullRepo(String repoUrl) {
        Path cacheDir = Paths.get(REPOS_CACHE_DIR, repoUrl.substring(repoUrl.lastIndexOf("/") + 1));

        if (Files.exists(cacheDir)) {
            try {
                Repository repository = Git.open(cacheDir.toFile());
                PullCommand pullResult = repository.pull();
                pullResult.call();
                System.out.println("Updated " + repoUrl);
            } catch (GitAPIException | IOException e) {
                System.err.println("Failed to update " + repoUrl + ": " + e.getMessage());
            }
        } else {
            try {
                Git.cloneRepository()
                    .setURI(repoUrl)
                    .setDirectory(cacheDir.toFile())
                    .call();
                System.out.println("Cloned " + repoUrl);
            } catch (GitAPIException e) {
                System.err.println("Failed to clone " + repoUrl + ": " + e.getMessage());
            }
        }
    }
}
