import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class PokemonService {
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static final long CACHE_EXPIRY_TIME = TimeUnit.MINUTES.toMillis(10);

    public CompletableFuture<PokemonInfo> getPokemonInfo(String name) {
        // Check cache
        String cachedValue = cache.get(name);
        if (cachedValue != null) {
            return CompletableFuture.completedFuture(PokemonInfo.fromCached(cachedValue));
        }

        // Fetch from API asynchronously
        return CompletableFuture.supplyAsync(() -> fetchFromApi(name))
                              .thenApply(this::cacheResult)
                              .exceptionally(ex -> handleFallback(name, ex));
    }

    private String fetchFromApi(String name) {
        // Simulate API call to get Pokemon details
        // This method should include logic to respect rate limits and handle failures
        return "{\"name\":\"" + name + "\", \"type\":\"Fire\", \"weaknesses\":\"Water\"}";
    }

    private PokemonInfo cacheResult(String result) {
        String key = PokemonInfo.fromApi(result).getName();
        cache.put(key, result);
        // Set expiration time for cache entry
        new Thread(() -> {
            try {
                TimeUnit.MILLISECONDS.sleep(CACHE_EXPIRY_TIME);
                cache.remove(key);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }).start();
        return PokemonInfo.fromApi(result);
    }

    private PokemonInfo handleFallback(String name, Throwable ex) {
        // Log error and provide fallback result
        System.err.println("Error fetching Pokemon info for " + name + ": " + ex.getMessage());
        return new PokemonInfo(name, "Unknown", "Unknown");
    }
}

class PokemonInfo {
    private String name;
    private String type;
    private String weaknesses;

    public PokemonInfo(String name, String type, String weaknesses) {
        this.name = name;
        this.type = type;
