    public static PokemonInfo fromCached(String cachedValue) {
        // Parse cached value and create a PokemonInfo object
        return new PokemonInfo("name", "type", "weaknesses");
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }

    public String getWeaknesses() {
