import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.ResponseEntity;
import org.springframework.web.client.RestTemplate;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import java.net.MalformedURLException;
import java.net.URL;

public class StreamingDataHandler {

    private final RestTemplate restTemplate = new RestTemplate();

    @Retryable(
        value = {Exception.class},
        maxAttemptsExpression = "#{${retry.maxAttempts}}",
        backoff = @Backoff(delayExpression = "#{${retry.backoffInterval}}")
    )
    public String handleStreamingData(String dataSourceUrl, HttpHeaders headers) {
        try {
            URL url = new URL(dataSourceUrl);
            ResponseEntity<String> response = restTemplate.exchange(url.toString(), HttpMethod.GET, new HttpEntity<>(headers), String.class);

            if (response.getStatusCode().is2xxSuccessful()) {
                // Process the data here
                return "Data processed at: " + System.currentTimeMillis();
            } else {
                throw new RuntimeException("Failed to process data with status code: " + response.getStatusCodeValue());
            }
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid URL format", e);
        } catch (Exception e) {
            // Log the exception and retry
            return null;
        }
    }
}
