// Import necessary libraries
import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.concurrent.*;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class FileIntegrityCheck {

    private static final String CACHING_ALGORITHM = "LRU"; // Least Recently Used
    private static final int CACHE_CAPACITY = 1000;
    private static final int RETRY_ATTEMPTS = 3;
    private static final long RATE_LIMIT_MILLIS = 60000; // 1 minute

    private HashMap<String, String> fileHashCache;
    private ExecutorService hashThreadPool;
    private Semaphore rateLimiter;

    public FileIntegrityCheck() {
        this.fileHashCache = new ConcurrentHashMap<>();
        this.hashThreadPool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.rateLimiter = new Semaphore(10); // Allow 10 concurrent requests
    }

    public String hashFile(File file, String algorithm) throws IOException, NoSuchAlgorithmException {
        if (fileHashCache.containsKey(file.getAbsolutePath())) {
            return fileHashCache.get(file.getAbsolutePath());
        }

        rateLimiter.acquire();
        Future<String> future = hashThreadPool.submit(() -> computeHash(file, algorithm));
        try {
            String hash = future.get();
            cacheFileHash(file.getAbsolutePath(), hash);
            return hash;
        } catch (InterruptedException | ExecutionException e) {
            retryHashing(file, algorithm);
        } finally {
            rateLimiter.release();
        }
        throw new IOException("Failed to compute hash after retries");
    }

    private String computeHash(File file, String algorithm) throws NoSuchAlgorithmException, IOException {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        byte[] buffer = new byte[8192];
        try (InputStream in = new FileInputStream(file)) {
            int bytesRead;
            while ((bytesRead = in.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(digest.digest());
    }

    private void cacheFileHash(String filePath, String hash) {
        fileHashCache.putIfAbsent(filePath, hash);
        if (fileHashCache.size() > CACHE_CAPACITY) {
            removeLeastRecentlyUsed();
        }
    }

    private void removeLeastRecentlyUsed() {
        // Implement LRU logic to remove least recently used item
    }

    private void retryHashing(File file, String algorithm) throws IOException, NoSuchAlgorithmException {
        for (int i = 1; i <= RETRY_ATTEMPTS; i++) {
            try {
                return hashFile(file, algorithm);
            } catch (IOException | NoSuchAlgorithmException e) {
                if (i == RETRY_ATTEMPTS) throw e;
            }
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    // RESTful API endpoint to handle file integrity checks
    public void checkFileIntegrity(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String filePath = request.getParameter("file");
        String algorithm = request.getParameter("algorithm");

        try {
            String hash = hashFile(new File(filePath), algorithm);
            response.getWriter().write("Hash: " + hash);
        } catch (IOException | NoSuchAlgorithmException e) {
            response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            response.getWriter().write("Failed to compute file hash");
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        FileIntegrityCheck app = new FileIntegrityCheck();
        // Simulate processing multiple files
        for (int i = 0; i < 1000; i++) {
            new Thread(() -> {
                try {
                    app.hashFile(new File("path/to/file" + i), "SHA-256");
                } catch (IOException | NoSuchAlgorithmException e) {
                    System.err.println(e.getMessage());
                }
            }).start();
        }

        // Shutdown the thread pool after processing
        app.hashThreadPool.shutdown();
        app.hashThreadPool.awaitTermination(1, TimeUnit.HOURS);
    }
}
