using System;
using System.Data;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;

public enum EncryptionAlgorithm
{
    TripleDES,
    AES
}

public class SecureDataHandler
{
    private readonly string _connectionString;
    private readonly int _timeout;
    private readonly int _retryPolicy;
    private readonly Dictionary<string, object> _encryptionSettings;

    public SecureDataHandler(string configFilePath)
    {
        var config = JsonConvert.DeserializeObject<Dictionary<string, object>>(File.ReadAllText(configFilePath));
        _connectionString = (string)config["ConnectionString"];
        _timeout = (int)config["Timeout"];
        _retryPolicy = (int)config["RetryPolicy"];
        _encryptionSettings = (Dictionary<string, object>)config["EncryptionSettings"];
    }

    public string EncryptMessage(string algorithmName, string message, string keyIV)
    {
        var algorithm = (EncryptionAlgorithm)Enum.Parse(typeof(EncryptionAlgorithm), algorithmName);
        byte[] encryptedBytes;
        switch (algorithm)
        {
            case EncryptionAlgorithm.TripleDES:
                using (var tripleDES = TripleDES.Create())
                {
                    tripleDES.Key = Encoding.UTF8.GetBytes(keyIV.Substring(0, 24));
                    tripleDES.IV = Encoding.UTF8.GetBytes(keyIV.Substring(24, 16));
                    encryptedBytes = tripleDES.CreateEncryptor().TransformFinalBlock(Encoding.UTF8.GetBytes(message), 0, message.Length);
                }
                break;
            case EncryptionAlgorithm.AES:
                using (var aes = Aes.Create())
                {
                    aes.Key = Encoding.UTF8.GetBytes(keyIV.Substring(0, 32));
                    aes.IV = Encoding.UTF8.GetBytes(keyIV.Substring(32, 16));
                    encryptedBytes = aes.CreateEncryptor().TransformFinalBlock(Encoding.UTF8.GetBytes(message), 0, message.Length);
                }
                break;
            default:
                throw new ArgumentException("Unsupported encryption algorithm.");
        }
        return Convert.ToBase64String(encryptedBytes);
    }

    public async Task ExecuteQuery(string sql, Dictionary<string, object> parameters = null)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            var command = new SqlCommand(sql, connection) { CommandTimeout = _timeout };
            if (parameters != null)
            {
                foreach (var param in parameters)
                    command.Parameters.AddWithValue(param.Key, param.Value);
            }

            try
            {
                await command.ExecuteNonQueryAsync();
            }
            catch (Exception ex)
            {
                LogError(ex.Message);
            }
        }
    }

    private void LogError(string message)
    {
        // Implement logging mechanism here
        Console.WriteLine($"Error: {message}");
    }
}

// Example usage:
var handler = new SecureDataHandler("config.json");
string encryptedMessage = handler.EncryptMessage("AES", "Hello, World!", "12345678901234567890123456789012");
await handler.ExecuteQuery("INSERT INTO Users (Name) VALUES (@Name)", new Dictionary<string, object> { { "@Name", encryptedMessage } });
