#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/time.h>

#define MAX_INSTRUMENTS 10
#define MAX_SERVERS 10000
#define MAX_THREADS 50

typedef struct {
    int instrument_id;
    float price;
} FinancialData;

typedef struct {
    pthread_t thread_id;
    int server_id;
    FinancialData *data_buffer;
    int buffer_size;
    sem_t data_ready;
    sem_t space_available;
} ServerThread;

ServerThread server_threads[MAX_SERVERS];

void* process_server_data(void* arg) {
    ServerThread *st = (ServerThread*)arg;
    while (1) {
        // Wait for new data
        sem_wait(&st->data_ready);

        // Process data
        printf("Processing instrument %d from server %d\n", st->data_buffer[0].instrument_id, st->server_id);

        // Signal that the buffer is available again
        sem_post(&st->space_available);
    }
}

int main() {
    // Initialize threads for each server
    for (int i = 0; i < MAX_SERVERS; i++) {
        server_threads[i].data_buffer = (FinancialData*)malloc(100 * sizeof(FinancialData));
        server_threads[i].buffer_size = 100;
        sem_init(&server_threads[i].data_ready, 0, 0);
        sem_init(&server_threads[i].space_available, 0, server_threads[i].buffer_size);
        pthread_create(&server_threads[i].thread_id, NULL, process_server_data, &server_threads[i]);
    }

    // Simulate data reception from servers
    while (1) {
        for (int i = 0; i < MAX_SERVERS; i++) {
            // Wait for buffer space to become available
            sem_wait(&server_threads[i].space_available);

            // Fill the buffer with new data
            FinancialData new_data[MAX_INSTRUMENTS];
            for (int j = 0; j < MAX_INSTRUMENTS; j++) {
                new_data[j].instrument_id = i % MAX_INSTRUMENTS;
                new_data[j].price = rand() * 10.0f / RAND_MAX;
            }
            memcpy(server_threads[i].data_buffer, new_data, sizeof(FinancialData) * MAX_INSTRUMENTS);

            // Signal that data is ready
            sem_post(&server_threads[i].data_ready);
        }

        // Sleep for a short period to simulate continuous operation
        sleep(1);
    }

    return 0;
}
