import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.concurrent.ConcurrentHashMap;

public class WeatherApiClient {
    private final HttpClient client;
    private final String apiKey;
    private final String baseUrl;
    private final int timeout;
    private final ConcurrentHashMap<String, HttpResponse<String>> cache = new ConcurrentHashMap<>();
    private static final int MAX_CALLS_PER_MINUTE = 10;
    private static final int RETRY_COUNT = 3;

    public WeatherApiClient(String baseUrl, String apiKey, int timeout) {
        this.baseUrl = baseUrl;
        this.apiKey = apiKey;
        this.timeout = timeout;
        this.client = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(timeout))
                .build();
    }

    public HttpResponse<String> getWeatherData(String endpoint, String format) throws IOException, InterruptedException {
        return executeRequest("GET", endpoint, format);
    }

    public HttpResponse<String> postWeatherData(String endpoint, String format, String data) throws IOException, InterruptedException {
        return executeRequest("POST", endpoint, format, data);
    }

    private HttpResponse<String> executeRequest(String method, String endpoint, String format) throws IOException, InterruptedException {
        return executeRequest(method, endpoint, format, null);
    }

    private HttpResponse<String> executeRequest(String method, String endpoint, String format, String data) throws IOException, InterruptedException {
        if (cache.containsKey(endpoint)) {
            return cache.get(endpoint);
        }

        // Rate limiting
        synchronized (WeatherApiClient.class) {
            int calls = 0;
            for (HttpResponse<String> response : cache.values()) {
                if (response.request().method().equals(method)) {
                    calls++;
                }
            }
            if (calls >= MAX_CALLS_PER_MINUTE) {
                throw new IOException("Rate limit exceeded");
            }
        }

        // Logging
        System.out.println("Making " + method + " request to " + endpoint);

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + endpoint))
                .header("Authorization", "Bearer " + apiKey)
                .header("Accept", format)
                .method(method, HttpRequest.BodyPublishers.ofString(data == null ? "" : data))
                .timeout(Duration.ofSeconds(timeout))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        // Caching
        cache.put(endpoint, response);

        // Retry policy
        int attempts = 0;
        while (response.statusCode() == 503 && attempts < RETRY_COUNT) {
            System.out.println("Retrying request: " + method + " to " + endpoint);
            attempts++;
            response = client.send(request, HttpResponse.BodyHandlers.ofString());
        }

        // Logging
        if (response.statusCode() >= 200 && response.statusCode() < 300) {
            System.out.println("Successful response from API");
        } else {
            System.err.println("Error response from API: " + response.statusCode());
        }
        System.out.println("Request took " + response.duration().toMillis() + " ms");

        return response;
    }
}
