using System;
using System.Collections.Generic;
using System.Xml.Linq;

class ConfigLoader
{
    private Dictionary<string, string> configSettings;

    public ConfigLoader(string xmlFilePath)
    {
        XDocument doc = XDocument.Load(xmlFilePath);
        configSettings = doc.Root.Elements()
                                .ToDictionary(element => element.Name.LocalName, 
                                             element => element.Value);
    }

    public int GetTileSize() => int.Parse(configSettings["tileSize"]);
    public int GetWorldWidth() => int.Parse(configSettings["worldWidth"]);
    public int GetWorldHeight() => int.Parse(configSettings["worldHeight"]);
