class DataChunk
{
    public byte[] Buffer { get; set; }
    public int Length { get; set; }

    public DataChunk(int length)
    {
        Buffer = new byte[length];
        Length = length;
    }
}

class DataCopier
{
    public static void CopyBytes(List<DataChunk> dataChunks, long startByte, long endByte, ref byte[] destinationBuffer, int destinationOffset)
    {
        if (startByte < 0 || endByte > GetTotalDataLength(dataChunks))
        {
            throw new ArgumentException("Start or end position exceeds available data length.");
        }

        int totalBytesToCopy = (int)(endByte - startByte);
        int bytesCopied = 0;

        foreach (var chunk in dataChunks)
        {
            long chunkEndPosition = GetChunkEndPosition(chunk);

            if (startByte < chunkEndPosition && endByte > chunkStartPosition())
            {
                int bytesInThisChunk = Math.Min((int)(endByte - Math.Max(startByte, chunkStartPosition())), chunk.Length);
                Array.Copy(chunk.Buffer, (int)Math.Max(startByte, chunkStartPosition()) - chunkStartPosition(), destinationBuffer, destinationOffset + bytesCopied, bytesInThisChunk);
                bytesCopied += bytesInThisChunk;
            }

            if (bytesCopied >= totalBytesToCopy)
            {
                break;
            }
        }

        Array.Resize(ref destinationBuffer, destinationOffset + bytesCopied);
    }

    private static long GetTotalDataLength(List<DataChunk> dataChunks)
    {
        return dataChunks.Sum(chunk => chunk.Length);
    }

    private static long GetChunkEndPosition(DataChunk chunk) => chunkStartPosition() + chunk.Length - 1;

    private static long chunkStartPosition() => 0; // Assuming chunks start at position 0
}
```

This code includes a `ConfigLoader` class to load configuration settings from an XML file, a `DataChunk` class to represent buffered data chunks, and a `DataCopier` class with a static method `CopyBytes` to efficiently copy bytes from multiple chunks into a new buffer. The program handles large datasets gracefully and ensures optimal memory usage by dynamically resizing the destination buffer as needed. It also includes robust error handling for situations where the start or end positions exceed the available data length.

