using System;
using System.Collections.Generic;

public class AdvancedNetworkSimulator
{
    private Dictionary<int, Node> nodes;
    private List<Connection> connections;

    public AdvancedNetworkSimulator()
    {
        nodes = new Dictionary<int, Node>();
        connections = new List<Connection>();
    }

    // Methods for dynamic node and connection management
    public void AddNode(int nodeId)
    {
        if (!nodes.ContainsKey(nodeId))
        {
            nodes[nodeId] = new Node(nodeId);
        }
    }

    public void RemoveNode(int nodeId)
    {
        if (nodes.ContainsKey(nodeId))
        {
            foreach (var conn in connections.ToList())
            {
                if (conn.Node1 == nodeId || conn.Node2 == nodeId)
                {
                    connections.Remove(conn);
                }
            }
            nodes.Remove(nodeId);
        }
    }

    public void AddConnection(int node1, int node2, double weight = 1.0)
    {
        if (nodes.ContainsKey(node1) && nodes.ContainsKey(node2))
        {
            connections.Add(new Connection(node1, node2, weight));
        }
    }

    public void RemoveConnection(int node1, int node2)
    {
        connections.RemoveAll(conn => (conn.Node1 == node1 && conn.Node2 == node2) || (conn.Node1 == node2 && conn.Node2 == node1));
    }

    // Other methods for hierarchical network structure, real-time monitoring, resource allocation,
    // external data source integration, advanced property settings, network resilience testing,
    // security and encryption, visualization, and simulation speed control.
}

