using System;
using UnityEngine;

public class ValueGenerator
{
    private int minValue;
    private int maxValue;
    private Random random;

    public ValueGenerator(int min, int max)
    {
        SetRange(min, max);
        random = new Random();
    }

    public void SeedRandom(int seed)
    {
        random = new Random(seed);
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int[] GenerateUniqueRandomIntegers(int count)
    {
        if (count > (maxValue - minValue + 1))
            throw new ArgumentException("Count cannot be greater than the range of values.");

        HashSet<int> uniqueNumbers = new HashSet<int>();
        while (uniqueNumbers.Count < count)
        {
            uniqueNumbers.Add(GetRandomInt());
        }
        return uniqueNumbers.ToArray();
    }

    public bool IsWithinRange(int value, int min, int max)
    {
        return value >= min && value <= max;
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}";
    }

    private void SetRange(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Min value cannot be greater than Max value.");
        minValue = min;
        maxValue = max;
    }
}
