import threading
import queue
import serial
import time

class SerialDataProcessor:
    def __init__(self, port, baud_rate=9600, timeout=1, buffer_size=1024, anomaly_threshold=3):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.buffer_size = buffer_size
        self.anomaly_threshold = anomaly_threshold
        self.data_queue = queue.Queue()
        self.serial_thread = threading.Thread(target=self._read_serial_data)
        self.serial_thread.daemon = True
        self.running = False

    def start(self):
        if not self.running:
            self.running = True
            self.serial_thread.start()

    def stop(self):
        self.running = False
        self.serial_thread.join()

    def _read_serial_data(self):
        try:
            ser = serial.Serial(self.port, self.baud_rate, timeout=self.timeout)
            while self.running:
                data = ser.read(self.buffer_size).decode('utf-8').strip()
                if data:
                    try:
                        value = float(data)
                        self.data_queue.put(value)
                    except ValueError:
                        print(f"Invalid data received: {data}")
        except serial.SerialException as e:
            print(f"Error opening or using serial port: {e}")

    def process_data(self):
        while True:
            if not self.running:
                break
            try:
                value = self.data_queue.get(timeout=1)
                mean_value = sum(self.data_queue.queue) / len(self.data_queue.queue)
                if abs(value - mean_value) > self.anomaly_threshold * mean_value:
                    print(f"Anomaly detected: {value} (mean: {mean_value})")
            except queue.Empty:
                time.sleep(0.1)

# Usage example
processor = SerialDataProcessor('COM3', baud_rate=9600, timeout=1, buffer_size=1024)
processor.start()

try:
    while True:
        processor.process_data()
except KeyboardInterrupt:
    pass

processor.stop()
