```csharp
using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;

class FileTransferService
{
    private static readonly int MaxRetransmissions = 5;
    private static readonly int WindowSize = 3;

    public void TransferFile(string mode, string address, int port, string filePath)
    {
        if (mode == "unicast")
        {
            UnicastSend(filePath, address, port);
        }
        else if (mode == "multicast")
        {
            MulticastSend(filePath, address, port);
        }
        else
        {
            Console.WriteLine("Invalid mode. Please specify 'unicast' or 'multicast'.");
        }
    }

    private void UnicastSend(string filePath, string address, int port)
    {
        using (var client = new UdpClient())
        {
            var remoteEndPoint = new IPEndPoint(IPAddress.Parse(address), port);
            byte[] fileData = File.ReadAllBytes(filePath);
            SHA256 sha256Hash = SHA256.Create();
            byte[] hashBytes = sha256Hash.ComputeHash(fileData);

            // Send the hash first
            client.Send(hashBytes, hashBytes.Length, remoteEndPoint);

            // Then send the file data
            int sentBytes = 0;
            int packetSize = 1472; // UDP MTU minus IP/UDP headers
            while (sentBytes < fileData.Length)
            {
                byte[] packet = new byte[Math.Min(packetSize, fileData.Length - sentBytes)];
                Buffer.BlockCopy(fileData, sentBytes, packet, 0, packet.Length);
                client.Send(packet, packet.Length, remoteEndPoint);
                sentBytes += packet.Length;
            }

            Console.WriteLine($"File sent: {filePath}");
        }
    }

    private void MulticastSend(string filePath, string address, int port)
    {
        using (var client = new UdpClient())
        {
            var groupIp = IPAddress.Parse(address);
            client.JoinMulticastGroup(groupIp);

            byte[] fileData = File.ReadAllBytes(filePath);
            SHA256 sha256Hash = SHA256.Create();
            byte[] hashBytes = sha256Hash.ComputeHash(fileData);

            // Send the hash first
            client.Send(hashBytes, hashBytes.Length, new IPEndPoint(groupIp, port));

            // Then send the file data
            int sentBytes = 0;
            int packetSize = 1472; // UDP MTU minus IP/UDP headers
            while (sentBytes < fileData.Length)
            {
                byte[] packet = new byte[Math.Min(packetSize, fileData.Length - sentBytes)];
                Buffer.BlockCopy(fileData, sentBytes, packet, 0, packet.Length);
                client.Send(packet, packet.Length, new IPEndPoint(groupIp, port));
                sentBytes += packet.Length;
            }

            Console.WriteLine($"File multicast sent: {filePath}");
        }
    }

    public static byte[] CalculateSHA256(string filePath)
    {
        using (var sha256 = SHA256.Create())
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                return sha256.ComputeHash(fileStream);
            }
        }
    }
}

class Program
{
    static void Main(string[] args)
    {
        if (args.Length < 4)
        {
            Console.WriteLine("Usage: FileTransferService <mode> <address> <port> <filePath>");
            return;
        }

        string mode = args[0];
        string address = args[1];
        int port = int.Parse(args[2]);
        string filePath = args[3];

        var service = new FileTransferService();
        service.TransferFile(mode, address, port, filePath);
    }
}
```

This code snippet provides a basic structure for a C# application that can perform unicast and multicast UDP-based file transfers. It includes methods to calculate the SHA-256 hash of a file and to transfer files using the specified mode, IP address, port, and file path from command-line arguments. The code does not include error handling, retransmission strategy with sliding window mechanism, test double for socket operations, custom C function loading, or external logging system integration as requested.

