using System;
using System.Data;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("api/[controller]")]
public class HtmlContentController : ControllerBase
{
    private readonly string _connectionString;
    private readonly string _salt;

    public HtmlContentController(IConfiguration configuration)
    {
        _connectionString = configuration.GetConnectionString("DefaultConnection");
        _salt = configuration.GetValue<string>("Salt");
    }

    [HttpPost]
    public async Task<IActionResult> UpdateHtml(string pageSectionId, string elementId, string htmlContent)
    {
        try
        {
            if (!IsValidPasswordAndSalt(htmlContent))
                return BadRequest("Invalid password or salt provided.");

            var encryptedHtml = EncryptHtml(htmlContent);
            await SaveToDatabase(pageSectionId, elementId, encryptedHtml);

            return Ok(new { message = "HTML content updated successfully." });
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            return StatusCode(500, new { error = "Internal server error. Please try again later." });
        }
    }

    private bool IsValidPasswordAndSalt(string password)
    {
        // Implement your validation logic here
        return password.Length >= 8 && _salt.Length > 0;
    }

    private string EncryptHtml(string htmlContent)
    {
        using (var aes = Aes.Create("AES-256-CBC"))
        {
            var iv = GenerateRandomIV();
            aes.Key = DeriveKey(_salt);
            aes.IV = iv;

            using (var encryptor = aes.CreateEncryptor(aes.Key, aes.IV))
            {
                using (var msEncrypt = new MemoryStream())
                {
                    using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        using (var swEncrypt = new StreamWriter(csEncrypt))
                        {
                            swEncrypt.Write(htmlContent);
                        }
                        return Convert.ToBase64String(msEncrypt.ToArray());
                    }
                }
            }
        }
    }

    private byte[] DeriveKey(string password)
    {
        using (var sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(Encoding.UTF8.GetBytes(_salt + password));
        }
    }

    private byte[] GenerateRandomIV()
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            var iv = new byte[16];
            rng.GetBytes(iv);
            return iv;
        }
    }

    private async Task SaveToDatabase(string pageSectionId, string elementId, string encryptedHtml)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand("INSERT INTO HtmlContent (PageSectionId, ElementId, EncryptedHtml) VALUES (@PageSectionId, @ElementId, @EncryptedHtml)", connection);
            command.Parameters.AddWithValue("@PageSectionId", pageSectionId);
            command.Parameters.AddWithValue("@ElementId", elementId);
            command.Parameters.AddWithValue("@EncryptedHtml", encryptedHtml);
            await command.ExecuteNonQueryAsync();
        }
    }

    private void LogError(string message)
    {
        // Implement your logging logic here
        Console.WriteLine($"ERROR: {message}");
    }
}
