using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;

class SecureDataHandler
{
    private readonly string _key;
    private readonly string _iv;
    private long[] _offsets;
    private int[] _keys;
    private record MyRecord(long Offset, int Key);
    private MyRecord[] _records;
    private readonly Mutex _mutex = new Mutex();

    public SecureDataHandler(string key, string iv)
    {
        _key = key;
        _iv = iv;
    }

    public string DecryptMessage(string encryptedMessage)
    {
        using (var msDecrypt = new MemoryStream(Convert.FromBase64String(encryptedMessage)))
        {
            using (var aesAlg = Aes.Create())
            {
                aesAlg.Key = Convert.FromBase64String(_key);
                aesAlg.IV = Convert.FromBase64String(_iv);

                aesAlg.Mode = CipherMode.CBC;
                aesAlg.Padding = PaddingMode.PKCS7;

                using (var csDecrypt = new CryptoStream(msDecrypt, aesAlg.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    using (var srDecrypt = new StreamReader(csDecrypt))
                    {
                        return srDecrypt.ReadToEnd();
                    }
                }
            }
        }
    }

    public void InitializeDataArrays()
    {
        try
        {
            string[] lines = File.ReadAllLines("data.csv");
            _offsets = new long[lines.Length];
            _keys = new int[lines.Length];

            for (int i = 0; i < lines.Length; i++)
            {
                string[] parts = lines[i].Split(',');
                if (parts.Length != 2)
                {
                    throw new FormatException("Invalid CSV format.");
                }

                if (!long.TryParse(parts[0], out _offsets[i]) || !int.TryParse(parts[1], out _keys[i]))
                {
                    throw new FormatException("Non-numeric values found in CSV.");
                }
            }

            _records = Array.ConvertAll(_offsets, o => new MyRecord(o, 0));
        }
        catch (IOException ex)
        {
            Console.WriteLine($"Error reading file: {ex.Message}");
        }
        catch (FormatException ex)
        {
            Console.WriteLine($"Invalid format in CSV data: {ex.Message}");
        }
    }

    public void PopulateRecords()
    {
        _mutex.WaitOne();
        try
        {
            for (int i = 0; i < _records.Length; i++)
            {
                int randomValue = GenerateRandomValue(_keys[i]);
                _records[i] = new MyRecord(_offsets[i], randomValue);
            }
        }
        finally
        {
            _mutex.ReleaseMutex();
        }
    }

    private int GenerateRandomValue(int seed)
    {
        Random rnd = new Random(seed);
        return rnd.Next(0, 1000); // Example range, adjust as needed
    }
}
```

