// Node.js/Express web API example with optimistic concurrency control

const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const { v4: uuidv4 } = require('uuid');

app.use(bodyParser.json());
app.use(express.static('public'));

let resources = {};

app.put('/resource/:id', async (req, res) => {
    const id = req.params.id;
    const updatedData = req.body;

    if (!resources[id]) {
        return res.status(404).json({ error: 'Resource not found' });
    }

    // Optimistic concurrency control
    if (updatedData.version !== resources[id].version) {
        return res.status(409).json({ error: 'Conflict, data has been modified' });
    }

    updatedData.id = id;
    updatedData.version += 1;

    resources[id] = updatedData;
    res.json(updatedData);
});

