    const id = req.params.id;
    const updatedData = req.body;

    if (!resources[id]) {
        return res.status(404).json({ error: 'Resource not found' });
    }

    if (!(await authenticateUser(req.headers['user-id'], req.headers['auth-token']))) {
        return res.status(401).json({ error: 'Unauthorized' });
    }

    // Optimistic concurrency control
    if (updatedData.version !== resources[id].version) {
        return res.status(409).json({ error: 'Conflict, data has been modified' });
    }

    updatedData.id = id;
    updatedData.version += 1;

    resources[id] = updatedData;
    res.json(updatedData);
});
