import subprocess
import bcrypt
import logging

# Set up logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def modify_kickstart(kickstart_file, replacements):
    try:
        for old, new in replacements.items():
            command = f"sed -i 's|{old}|{new}|g' {kickstart_file}"
            subprocess.run(command, shell=True, check=True)
            logging.info(f"Modified '{old}' to '{new}' in Kickstart file.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Error modifying Kickstart file: {e}")
        raise

def encrypt_password(password):
    salt = bcrypt.gensalt()
    hashed_password = bcrypt.hashpw(password.encode('utf-8'), salt)
    return hashed_password.decode('utf-8')

# Example usage
replacements = {'placeholder': 'new_value'}
modify_kickstart('path/to/kickstart/file', replacements)
password = encrypt_password('user_password')
logging.info(f"Encrypted password: {password}")
