#include <forward_list>
#include <string>

void insertAfterString(std::forward_list<std::string>& list, 
                        const std::string& target, 
                        const std::string& insertStr,
                        std::forward_list<std::string>::iterator position = std::forward_list<std::string>::iterator()) {
    if(position == std::forward_list<std::string>::iterator()) {
        for(auto it = list.begin(); it != list.end(); ++it) {
            if(*it == target) {
                position = it;
                break;
            }
        }
    }

    if(position != std::forward_list<std::string>::iterator()) {
        list.insert_after(position, insertStr);
    } else {
        list.push_back(insertStr);
    }
}
```

