    public function updatePassword($userId, $newPassword) {
        try {
            // Validate password strength
            if ($this->isPasswordStrong($newPassword)) {
                // Verify password with external service
                if ($this->externalAuth->verifyPassword($newPassword)) {
                    // Update password in the database
                    $this->passwordDAO->updatePassword($userId, $newPassword);
                    return "Password updated successfully.";
                } else {
                    return "Invalid password verification from external service.";
                }
            } else {
                return "Weak password. Please choose a stronger one.";
            }
        } catch (Exception $e) {
            return "An error occurred: " . $e->getMessage();
        }
    }

    private function isPasswordStrong($password) {
        // Define password strength rules
        if (strlen($password) < 8 || !preg_match('/[a-z]/', $password) || !preg_match('/[A-Z]/', $password) || !preg_match('/\d/', $password)) {
            return false;
        }
        return true;
    }
}

