// Function to insert string after first occurrence in forward list
bool insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& searchStr, const std::string& insertStr, bool caseInsensitive = false) {
    auto it = list.before_begin();
    auto endIt = list.end();

    if (caseInsensitive) {
        for (; it != endIt; ++it) {
            if (!strcasecmp(it->c_str(), searchStr.c_str())) break;
        }
    } else {
        for (; it != endIt; ++it) {
            if (*it == searchStr) break;
        }
    }

    if (it == endIt) {
        list.push_back(insertStr);
    } else {
        list.insert_after(it, insertStr);
    }

    return true;
}

