use Redis;
use GuzzleHttp\Client;

class UserAccountManager {
    private $redis;
    private $authService;
    private $rateLimiter;

    public function __construct(Redis $redis, Client $authService, RateLimiter $rateLimiter) {
        $this->redis = $redis;
        $this->authService = $authService;
        $this->rateLimiter = $rateLimiter;
    }

    public function manageUserAccount() {
        if (!$this->rateLimiter->allowRequest($_SERVER['REMOTE_ADDR'])) {
            return json_encode(['status' => 'error', 'message' => 'Too many requests']);
        }

        $postData = $_POST;

        if (!isset($postData['sub_action']) || !in_array($postData['sub_action'], ['create', 'update', 'delete'])) {
            return json_encode(['status' => 'error', 'message' => 'Invalid sub_action']);
        }

        try {
            switch ($postData['sub_action']) {
                case 'create':
                    $response = $this->createUserAccount($postData);
                    break;
                case 'update':
                    if (!isset($postData['id'])) {
                        return json_encode(['status' => 'error', 'message' => 'ID is required for update']);
                    }
                    $response = $this->updateUserAccount($postData['id'], $postData);
                    break;
                case 'delete':
                    if (!isset($postData['id'])) {
                        return json_encode(['status' => 'error', 'message' => 'ID is required for delete']);
                    }
                    $response = $this->deleteUserAccount($postData['id']);
                    break;
            }

            return $response;
        } catch (\Exception $e) {
            return json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    private function createUserAccount(array $data) {
        // Validate data
        if (!isset($data['name']) || !isset($data['email']) || !isset($data['password'])) {
            throw new \Exception('Name, email, and password are required');
        }

        // Check for duplicate email
        if ($this->redis->exists($data['email'])) {
            throw new \Exception('Email already exists');
        }

        // Validate password with external service
        $authResponse = $this->authService->validatePassword($data['password']);
        if (!$authResponse) {
            throw new \Exception('Invalid password');
        }

        // Save user data to Redis and database (simulated)
        $this->redis->set($data['email'], json_encode($data));
        // Database save logic here

        return json_encode(['status' => 'success', 'message' => 'User account created']);
    }

    private function updateUserAccount($id, array $data) {
        // Fetch user data from Redis (simulated)
        $userData = $this->redis->get($id);
        if (!$userData) {
            throw new \Exception('User not found');
        }
        $userData = json_decode($userData, true);

        // Update user data
        $userData = array_merge($userData, $data);

        // Validate updated data
        if (!isset($userData['name']) || !isset($userData['email']) || !isset($userData['password'])) {
            throw new \Exception('Name, email, and password are required');
        }

        // Check for duplicate email (excluding current user)
        if ($this->redis->exists($data['email']) && $id !== $data['email']) {
            throw new \Exception('Email already exists');
        }

        // Validate password with external service
        $authResponse = $this->authService->validatePassword($data['password']);
        if (!$authResponse) {
            throw new \Exception('Invalid password');
        }

        // Save updated user data to Redis and database (simulated)
        $this->redis->set($id, json_encode($userData));
        // Database update logic here

        return json_encode(['status' => 'success', 'message' => 'User account updated']);
    }

    private function deleteUserAccount($id) {
        // Fetch user data from Redis (simulated)
        $userData = $this->redis->get($id);
        if (!$userData) {
            throw new \Exception('User not found');
        }
        $userData = json_decode($userData, true);

        // Delete user data from Redis and database (simulated)
        $this->redis->del($id);
        // Database delete logic here

        return json_encode(['status' => 'success', 'message' => 'User account deleted']);
    }
}

