import java.io.FileInputStream;
import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;

public class FileHasher {

    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static final int CACHE_SIZE = 1000; // Example size

    public void hashFile(String filePath, String algorithm) throws Exception {
        if (cache.containsKey(filePath)) {
            System.out.println("Using cached hash for " + filePath);
            return;
        }

        try (FileInputStream fis = new FileInputStream(filePath)) {
            MessageDigest md = MessageDigest.getInstance(algorithm);

            byte[] buffer = new byte[1024 * 1024]; // 1MB chunk
            int bytesRead;

            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }

            String hash = bytesToHex(md.digest());
            cache.put(filePath, hash);

            validateHashWithAPI(hash, filePath, algorithm);
        } catch (Exception e) {
            System.err.println("Error hashing file: " + e.getMessage());
        }
    }

    private void validateHashWithAPI(String hash, String filePath, String algorithm) throws Exception {
        // Simulate API call
        System.out.println("Validating hash with external service for " + filePath);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        FileHasher hasher = new FileHasher();
        hasher.hashFile("path/to/large/file.txt", "MD5");
    }
}
```

