```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <json-c/json.h>

#define MAX_CONCURRENT_PROCESSES 5

typedef struct {
    char command[256];
} Command;

int run_command(const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return -1;
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    }
    return pid;
}

int wait_for_child(pid_t *child_pids, int *num_children_running) {
    int status, child_index = -1;
    while (waitpid(-1, &status, WNOHANG) > 0) {
        for (int i = 0; i < *num_children_running; i++) {
            if (child_pids[i] == getpid()) {
                child_index = i;
                break;
            }
        }
        if (child_index != -1) {
            (*num_children_running)--;
            child_pids[child_index] = 0;
            if (WIFEXITED(status)) {
                printf("Command exited with status %d\n", WEXITSTATUS(status));
            } else if (WIFSIGNALED(status)) {
                printf("Command terminated by signal %d\n", WTERMSIG(status));
            }
        }
    }
    return child_index;
}

int main() {
    const char *json_file = "commands.json";
    FILE *file = fopen(json_file, "r");
    if (!file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    struct json_object *parsed_json;
    parsed_json = json_tokener_parse_file(file);
    fclose(file);

    struct json_object *commands_array;
    if (json_object_object_get_ex(parsed_json, "commands", &commands_array)) {
        int num_commands = json_object_array_length(commands_array);
        pid_t child_pids[MAX_CONCURRENT_PROCESSES] = {0};
        int num_children_running = 0;

        for (int i = 0; i < num_commands; i++) {
            struct json_object *command_obj;
            json_object_array_get_ex(commands_array, i, &command_obj);
            const char *command_str = json_object_get_string(command_obj);

            while (num_children_running >= MAX_CONCURRENT_PROCESSES) {
                wait_for_child(child_pids, &num_children_running);
            }

            pid_t child_pid = run_command(command_str);
            if (child_pid > 0) {
                child_pids[num_children_running++] = child_pid;
            }
        }

        // Wait for all remaining children
        while (num_children_running > 0) {
            wait_for_child(child_pids, &num_children_running);
        }
    } else {
        fprintf(stderr, "Error: 'commands' key not found in JSON\n");
        json_object_put(parsed_json);
        return EXIT_FAILURE;
    }

    json_object_put(parsed_json);
    return EXIT_SUCCESS;
}
