from flask import Flask, request, jsonify
from functools import wraps
import time

app = Flask(__name__)

# In-memory database simulation
db = {}

# Rate limiting dictionary
rate_limit = {}

def rate_limiter(max_requests=10, period=60):
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            user_id = request.headers.get('User-ID', 'default_user')
            current_time = int(time.time())
            if user_id not in rate_limit:
                rate_limit[user_id] = [(current_time, 1)]
            else:
                rate_limit[user_id].append((current_time, 1))
                rate_limit[user_id] = [x for x in rate_limit[user_id] if current_time - x[0] < period]
                if len(rate_limit[user_id]) > max_requests:
                    return jsonify({'error': 'Rate limit exceeded'}), 429
            return f(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/update/<int:resource_id>', methods=['PUT'])
@rate_limiter(max_requests=5, period=60)  # Adjust as needed
def update_resource(resource_id):
    try:
        data = request.get_json()
        if resource_id not in db:
            return jsonify({'error': 'Resource not found'}), 404
        original_version = db[resource_id]['version']
        new_data = {**db[resource_id], **data}
        new_data['version'] = original_version + 1
        db[resource_id] = new_data
        return jsonify(new_data)
    except (KeyError, TypeError):
        return jsonify({'error': 'Invalid data format'}), 400

@app.route('/delete/<int:resource_id>', methods=['DELETE'])
@rate_limiter(max_requests=5, period=60)  # Adjust as needed
def delete_resource(resource_id):
    if resource_id not in db:
        return jsonify({'error': 'Resource not found'}), 404
    deleted_resource = db[resource_id]
    deleted_resource['active'] = False
    deleted_resource['deleted_at'] = int(time.time())
    # Log deletion for audit purposes
    print(f"Deleted resource {resource_id} at {time.ctime(deleted_resource['deleted_at'])}")
    return jsonify(deleted_resource)

@app.route('/recover/<int:resource_id>', methods=['GET'])
def recover_resource(resource_id):
    if resource_id not in db or not db[resource_id]['active']:
        return jsonify({'error': 'Resource not found or already active'}), 404
    db[resource_id]['active'] = True
    db[resource_id].pop('deleted_at', None)
    return jsonify(db[resource_id])

@app.route('/logs', methods=['GET'])
def get_logs():
    # This is a simple log implementation. In a real-world scenario, use a proper logging library.
    logs = []
    for resource_id, resource in db.items():
        if 'deleted_at' in resource:
            logs.append((resource_id, resource['deleted_at']))
    return jsonify(logs)

if __name__ == '__main__':
    app.run(debug=True)
```

