import java.io.*;
import java.nio.file.*;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.*;

public class LogProcessor {

    private static final String TIMESTAMP_PATTERN = "yyyy-MM-dd HH:mm:ss";
    private static final SimpleDateFormat dateFormat = new SimpleDateFormat(TIMESTAMP_PATTERN);
    private static final ConcurrentHashMap<String, File> fileLocks = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        try {
            processLogFile("path/to/logfile.log", "/path/to/api", "username", "password");
        } catch (IOException | InterruptedException | ParseException e) {
            e.printStackTrace();
        }
    }

    public static void processLogFile(String filePath, String apiPath, String username, String password)
            throws IOException, InterruptedException, ParseException {

        File logFile = new File(filePath);
        File lockFile = fileLocks.computeIfAbsent(filePath, k -> new File(filePath + ".lock"));

        if (lockFile.exists()) {
            throw new RuntimeException("Log file is currently being processed.");
        }

        try {
            Files.deleteIfExists(lockFile);

            List<String> lines = Files.readAllLines(logFile.toPath(), StandardCharsets.UTF_8);
            Collections.sort(lines, Comparator.comparing(line -> extractTimestamp(line)));

            String lastLine = lines.get(lines.size() - 1);
            int sequenceNumber = Integer.parseInt(lastLine.split(" ")[2]);

            executeCommand(apiPath, username, password, sequenceNumber);

        } finally {
            Files.createFile(lockFile.toPath());
        }
    }

    private static Date extractTimestamp(String line) throws ParseException {
        String[] parts = line.trim().split(" ");
        return dateFormat.parse(parts[1]);
    }

    private static void executeCommand(String apiPath, String username, String password, int sequenceNumber)
            throws IOException, InterruptedException {

        ProcessBuilder processBuilder = new ProcessBuilder("curl", "-X", "POST",
                "--data-urlencode", "sequence=" + sequenceNumber,
                "--user", username + ":" + password, apiPath);
        processBuilder.directory(new File("/path/to/command/directory"));

        Process process = processBuilder.start();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Command execution failed with exit code: " + exitCode);
        }
    }
}
