#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

#define MAX_INTS 1000
#define MIN_INT -1000
#define MAX_INT 1000

bool verify_json(const char *json_str) {
    struct json_object *parsed_json;
    parsed_json = json_tokener_parse(json_str);

    if (parsed_json == NULL) {
        fprintf(stderr, "Invalid JSON format.\n");
        return false;
    }

    struct json_object *token_type, *expires_in, *scope;

    if (!json_object_object_get_ex(parsed_json, "access_token", &token_type)) {
        fprintf(stderr, "Missing access_token field.\n");
        json_object_put(parsed_json);
        return false;
    }

    if (!json_object_object_get_ex(parsed_json, "expires_in", &expires_in)) {
        fprintf(stderr, "Missing expires_in field.\n");
        json_object_put(parsed_json);
        return false;
    }

    if (!json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        fprintf(stderr, "Missing token_type field.\n");
        json_object_put(parsed_json);
        return false;
    }

    if (!json_object_object_get_ex(parsed_json, "scope", &scope)) {
        fprintf(stderr, "Missing scope field.\n");
        json_object_put(parsed_json);
        return false;
    }

    const char *token_type_str = json_object_get_string(token_type);

    if (strcmp(token_type_str, "Bearer") != 0) {
        fprintf(stderr, "Invalid token_type value. Expected 'Bearer'.\n");
        json_object_put(parsed_json);
        return false;
    }

    int expires_in_val = json_object_get_int(expires_in);

    if (expires_in_val <= 0) {
        fprintf(stderr, "Invalid expires_in value. Must be a positive integer.\n");
        json_object_put(parsed_json);
        return false;
    }

    const char *scope_str = json_object_get_string(scope);

    if (strlen(scope_str) == 0) {
        fprintf(stderr, "Invalid scope value. Must not be empty.\n");
        json_object_put(parsed_json);
        return false;
    }

    json_object_put(parsed_json);
    return true;
}

int find_max(int *array, int count) {
    if (count <= 0) {
        return INT_MIN;
    }

    int max = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void free_array(int *array, size_t size) {
    free(array);
}

bool read_integers_and_verify_json(FILE *fd, const char *json_str) {
    int *int_array = malloc(sizeof(int) * MAX_INTS);
    if (int_array == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return false;
    }

    size_t count = 0;
    while (count < MAX_INTS && fscanf(fd, "%d", &int_array[count]) == 1) {
        count++;
    }

    if (ferror(fd)) {
        fprintf(stderr, "Error reading integers from file.\n");
        free_array(int_array, count);
        return false;
    }

    int max_value = find_max(int_array, count);

    printf("Largest integer: %d\n", max_value);

    bool json_valid = verify_json(json_str);

    free_array(int_array, count);

    return json_valid;
}

int main() {
    FILE *fd = stdin; // For demonstration purposes
    const char *json_str = "{\"access_token\":\"token123\",\"expires_in\":3600,\"token_type\":\"Bearer\",\"scope\":\"read write\"}";

    if (!read_integers_and_verify_json(fd, json_str)) {
        fprintf(stderr, "JSON verification failed.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
