// Import necessary libraries
import java.util.*;
import java.io.*;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import org.json.JSONObject;

public class DisjointPairProcessor {

    // Union-Find data structure implementation
    private int[] parent;
    private int[] rank;

    public DisjointPairProcessor(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    private int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    private void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY])
                parent[rootY] = rootX;
            else if (rank[rootX] < rank[rootY])
                parent[rootX] = rootY;
            else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    // Method to process the input array and find disjoint pairs
    public int countDisjointPairs(int[] arr) {
        Set<Integer> uniqueElements = new HashSet<>();
        for (int num : arr) {
            if (!uniqueElements.contains(num)) {
                uniqueElements.add(num);
            }
        }
        DisjointPairProcessor processor = new DisjointPairProcessor(uniqueElements.size());
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            int rootX = processor.find(arr[i]);
            if (rootX != processor.find(arr[i + 1])) {
                processor.union(rootX, processor.find(arr[i + 1]));
                count++;
            }
        }
        return count;
    }

    // REST API endpoint implementation
    @POST
    @Path("/process")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public String processArray(String input) {
        try {
            JSONObject json = new JSONObject(input);
            int[] arr = Arrays.stream(json.getJSONArray("array").toString().replaceAll("\\[|\\]", "").split(","))
                               .mapToInt(Integer::parseInt)
                               .toArray();
            int result = countDisjointPairs(arr);
            return "{\"result\": " + result + "}";
        } catch (Exception e) {
            return "{\"error\": \"" + e.getMessage() + "\"}";
        }
    }

    // Unit tests for the module
    public static void main(String[] args) {
        DisjointPairProcessor processor = new DisjointPairProcessor(10);
        int[] testArray = {1, 2, 3, 4, 5};
        System.out.println(processor.countDisjointPairs(testArray)); // Expected output: 4

        int[] emptyArray = {};
        System.out.println(processor.countDisjointPairs(emptyArray)); // Expected output: 0

        int[] singleElementArray = {1};
        System.out.println(processor.countDisjointPairs(singleElementArray)); // Expected output: 0
    }
}
```

This code snippet provides a Java module for processing an integer array and determining the number of disjoint pairs using the Union-Find data structure. It also includes a REST API endpoint for submitting arrays for processing and retrieving results, as well as unit tests to verify the correctness of the module under various conditions.

