    public void fetchAndAdjustSettings() {
        String apiKey = this.configProperties.getProperty("weather.api.key");
        // Fetch weather data from the third-party API
        WeatherData weatherData = fetchWeatherDataFromAPI(apiKey);

        if (weatherData != null) {
            int temperatureSetting = determineTemperatureSetting(weatherData.getWeatherDescription());

            // Adjust heating and cooling settings for multiple devices
            this.deviceExecutor.submit(() -> adjustDeviceSettings(temperatureSetting));
        }
    }

    private WeatherData fetchWeatherDataFromAPI(String apiKey) {
        // Simulate API call
        try {
            Thread.sleep(1000); // Simulate network delay
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Return dummy data for demonstration purposes
        return new WeatherData("clear sky", 20);
    }

    private int determineTemperatureSetting(String weatherDescription) {
        String temperatureRegex = this.configProperties.getProperty("temperature.regex");
        if (weatherDescription.matches(temperatureRegex)) {
