        try {
            if (!this.deviceExecutor.awaitTermination(60, TimeUnit.SECONDS)) {
                this.deviceExecutor.shutdownNow();
            }
        } catch (InterruptedException e) {
            this.deviceExecutor.shutdownNow();
        }
    }
