// Import necessary libraries
const axios = require('axios');
const { Queue } = require('queue-fifo');

class DataCollector {
  constructor(apiUrl, rateLimit, maxRetries) {
    this.apiUrl = apiUrl;
    this.rateLimit = rateLimit; // in ms
    this.maxRetries = maxRetries;
    this.queue = new Queue();
    this.paused = false;
  }

  async fetchData() {
    while (!this.paused && !this.queue.isEmpty()) {
      const { url, retries } = this.queue.dequeue();

      try {
        const response = await axios.get(url);
        // Process the data
        console.log('Data received:', response.data);

        // Schedule next request
        setTimeout(() => this.fetchData(), this.rateLimit);
        return;
      } catch (error) {
        if (retries < this.maxRetries) {
          this.queue.enqueue({ url, retries: retries + 1 });
          console.error(`Request failed. Retrying... (Attempt ${retries + 2})`);
        } else {
          console.error('Max retries reached. Aborting request.');
        }
      }
    }

    setTimeout(() => this.fetchData(), this.rateLimit);
  }

  enqueueRequest(url) {
    this.queue.enqueue({ url, retries: 0 });
    if (!this.paused) {
      this.fetchData();
    }
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
    this.fetchData();
  }
}

// Example usage
const collector = new DataCollector('https://api.example.com/data', 1000, 3);
collector.enqueueRequest(collector.apiUrl);

// Pausing and resuming functionality (for demonstration)
setTimeout(() => collector.pause(), 5000);
setTimeout(() => collector.resume(), 10000);
```

This code defines a `DataCollector` class that handles the collection of data from an API, manages rate limiting, error handling with retries, and provides pause/resume functionality. It uses a queue to manage requests efficiently and schedules them according to the specified rate limit. The example usage demonstrates how to enqueue requests and control the collector's state (pause and resume).

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class NIOConnectionManager {
    private static final Logger logger = LoggerFactory.getLogger(NIOConnectionManager.class);
    private AsynchronousSocketChannel channel;
    private ExecutorService executorService;
    private AsynchronousChannelGroup group;
    private MessageQueue messageQueue;

    public NIOConnectionManager(String host, int port, String mqType, String mqConfig) {
        this.executorService = Executors.newFixedThreadPool(10);
        this.group = AsynchronousChannelGroup.withFixedThreadPool(5, executorService);
        try {
            this.channel = AsynchronousSocketChannel.open(group);
            this.messageQueue = MessageQueueFactory.createMessageQueue(mqType, mqConfig);
        } catch (IOException e) {
            logger.error("Failed to initialize NIOConnectionManager", e);
        }
    }

    public void connectAndTransferData(String remoteHost, int remotePort, byte[] data, String correlationId) {
        try {
            channel.connect(new InetSocketAddress(remoteHost, remotePort), null, new CompletionHandler<Void, Void>() {
                @Override
                public void completed(Void result, Void attachment) {
                    transferData(data, correlationId);
                }

                @Override
                public void failed(Throwable exc, Void attachment) {
                    retryConnect(remoteHost, remotePort, data, correlationId, 1);
                }
            });
        } catch (IOException e) {
            logger.error("Failed to initiate connection", e);
        }
    }

    private void transferData(byte[] data, String correlationId) {
        ByteBuffer buffer = ByteBuffer.wrap(data);
        channel.write(buffer, null, new CompletionHandler<Integer, Void>() {
            @Override
            public void completed(Integer result, Void attachment) {
                processMessageQueue(correlationId);
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                logger.error("Failed to transfer data", e);
            }
        });
    }

    private void processMessageQueue(String correlationId) {
        try {
            messageQueue.processData(correlationId);
        } catch (Exception e) {
            logger.error("Failed to process message queue", e);
        }
    }

    private void retryConnect(String remoteHost, int remotePort, byte[] data, String correlationId, int attempt) {
        if (attempt <= 3) {
            try {
                Thread.sleep((long) Math.pow(2, attempt) * 100); // Exponential backoff
                channel.connect(new InetSocketAddress(remoteHost, remotePort), null, new CompletionHandler<Void, Void>() {
                    @Override
                    public void completed(Void result, Void attachment) {
                        transferData(data, correlationId);
                    }

                    @Override
                    public void failed(Throwable exc, Void attachment) {
                        retryConnect(remoteHost, remotePort, data, correlationId, attempt + 1);
                    }
                });
            } catch (InterruptedException | IOException e) {
                logger.error("Failed to retry connection", e);
            }
        } else {
            logger.warn("Failed to connect after multiple attempts");
        }
    }

    public void close() throws IOException {
        channel.close();
        group.shutdownNow().awaitTermination(5, TimeUnit.SECONDS);
        executorService.shutdownNow();
    }

    // RESTful API endpoint (example using Spring Boot)
    @RestController
    public class ConnectionController {
        @Autowired
        private NIOConnectionManager nioConnectionManager;

        @PostMapping("/test")
        public ResponseEntity<String> testConnection(@RequestBody TestRequest request) {
            try {
                nioConnectionManager.connectAndTransferData(request.getRemoteHost(), request.getRemotePort(),
                        request.getData().getBytes(), request.getCorrelationId());
                return ResponseEntity.ok("Test successful");
            } catch (Exception e) {
                return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(e.getMessage());
            }
        }
    }

    // Helper classes and interfaces
    interface MessageQueue {
        void processData(String correlationId) throws Exception;
    }

    static class MessageQueueFactory {
