import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private ExecutorService executorService;
    private MessagingSystem messagingSystem;
    private ConfigManager configManager;

    public ServiceManager(MessagingSystem messagingSystem, ConfigManager configManager) {
        this.messagingSystem = messagingSystem;
        this.configManager = configManager;
        this.executorService = Executors.newFixedThreadPool(configManager.getMaxThreads());
    }

    public void startService(Service service) {
        executorService.submit(() -> {
            try {
                int delay = (int) (Math.random() * 10);
                TimeUnit.SECONDS.sleep(delay);
                service.start();
                while (service.isRunning()) {
                    // Simulate health check and restart if necessary
                    if (!service.isHealthy()) {
                        service.restart();
                    }
                    TimeUnit.SECONDS.sleep(5);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                service.stop();
                retrySendMessage(service, "Stopped");
            }
        });
    }

    private void retrySendMessage(Service service, String message) {
        int maxRetries = configManager.getMaxRetries();
        int delay = 1;
        for (int i = 0; i < maxRetries; i++) {
            try {
                messagingSystem.sendMessage(service.getId(), message);
                break;
            } catch (Exception e) {
                if (i == maxRetries - 1) {
                    // Log error and notify admin
                    System.err.println("Failed to send status update for service " + service.getId());
                }
                delay *= 2;
                TimeUnit.SECONDS.sleep(delay);
            }
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}

interface MessagingSystem {
    void sendMessage(String serviceId, String message) throws Exception;
}

interface ConfigManager {
    int getMaxThreads();
    int getMaxRetries();
}

class Service {
    private String id;
    private boolean isRunning = false;

    public Service(String id) {
        this.id = id;
    }

    public void start() {
        // Simulate service startup logic
        System.out.println("Starting service " + id);
        isRunning = true;
    }

    public void stop() {
        // Simulate service shutdown logic
        System.out.println("Stopping service " + id);
        isRunning = false;
    }

    public boolean isRunning() {
        return isRunning;
    }

    public String getId() {
        return id;
    }

    public boolean isHealthy() {
        // Simulate health check logic
        return Math.random() > 0.2;
    }

    public void restart() {
        stop();
        start();
    }
}
