using System;
using System.Data.SqlClient;
using System.Security.Cryptography;

public class SecureDataHandler
{
    public string DecryptMessage(string encryptedMessage, string key, string iv)
    {
        using (TripleDES des = TripleDES.Create())
        {
            des.Key = Convert.FromBase64String(key);
            des.IV = Convert.FromBase64String(iv);
            des.Mode = CipherMode.CBC;
            des.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = des.CreateDecryptor();
            byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);
            byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            return System.Text.Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    public DataTableReader ExecuteQuery(byte[] data)
    {
        string connectionString = "your_database_connection_string";
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            SqlCommand command = new SqlCommand("your_query", connection);
            command.Parameters.Add(new SqlParameter("@data", SqlDbType.VarBinary).Value = data);
            SqlDataAdapter adapter = new SqlDataAdapter(command);
            DataTable table = new DataTable();
            adapter.Fill(table);
            return table.CreateDataReader();
        }
    }
}
