unsigned char* read_from_file(const char* filename, size_t size) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    unsigned char* data = (unsigned char*)malloc(size);
    if (!data) {
        fclose(file);
        perror("Memory allocation failed");
        return NULL;
    }

    size_t bytes_read = fread(data, 1, size, file);
    if (bytes_read != size) {
        free(data);
        fclose(file);
        fprintf(stderr, "Failed to read %zu bytes from file\n", size);
        return NULL;
    }

    fclose(file);
    return data;
}

void run_shell_command(const char* command, char** output_buffer, size_t* buffer_size) {
    FILE* pipe = popen(command, "r");
    if (!pipe) {
        perror("Failed to open pipe for shell command");
        *output_buffer = NULL;
        *buffer_size = 0;
        return;
    }

    const size_t initial_buffer_size = 128;
    char buffer[initial_buffer_size];
    *output_buffer = (char*)malloc(initial_buffer_size);
    if (!*output_buffer) {
        pclose(pipe);
        perror("Memory allocation failed");
        *buffer_size = 0;
        return;
    }

    size_t total_bytes_read = 0;
    while (fgets(buffer, sizeof(buffer), pipe)) {
        size_t bytes_to_copy = strlen(buffer);
        if (total_bytes_read + bytes_to_copy >= *buffer_size) {
            *buffer_size *= 2;
            *output_buffer = (char*)realloc(*output_buffer, *buffer_size);
            if (!*output_buffer) {
                pclose(pipe);
                perror("Memory reallocation failed");
                *buffer_size = total_bytes_read;
                return;
            }
        }

        memcpy(*output_buffer + total_bytes_read, buffer, bytes_to_copy);
        total_bytes_read += bytes_to_copy;
    }

    *buffer_size = total_bytes_read;
    pclose(pipe);
}
