        if (!arr) {
            perror("Memory allocation failed");
            break;
        }
        arr[size++] = num;
        memset(buffer, 0, BUFSIZE);
    }

    if (arr) {
        int largest = find_largest(arr, size);
        printf("Largest number: %d\n", largest);
        free(arr);
    }

    close(new_socket);
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }
        handle_client(new_socket);
    }

    close(server_fd);
    return 0;
}
```

This C program sets up a TCP server that listens for incoming connections on port 8080. Upon receiving a connection, it reads integers from the client, dynamically allocates memory to store them in an array, finds the largest integer using a helper function, and then prints it. The program handles potential network errors, ensures efficient memory usage by using `realloc`, and manages concurrent connections efficiently.

