public:
    OctreeSystem(int initialCapacity) : root(nullptr), maxLeafNodes(initialCapacity), mutex(PTHREAD_MUTEX_INITIALIZER) {}

    ~OctreeSystem() {
        destroyTree(root);
    }

    void destroyTree(OctTreeNode* node) {
        if (node != nullptr) {
            for (int i = 0; i < 8; ++i) {
                destroyTree(node->children[i]);
            }
            delete[] node;
        }
