        root = allocateMemory(numLeafNodes, dataCapacity);
        if (root == nullptr) {
            pthread_mutex_unlock(&mutex);
            return -2; // Memory allocation failed
        }
        maxLeafNodes = numLeafNodes;
        pthread_mutex_unlock(&mutex);

        return 0; // Initialization successful
    }

