import os
import json
import subprocess
from cryptography.fernet import Fernet
import boto3

class ConfigManager:
    def __init__(self, kms_key_id):
        self.kms_client = boto3.client('kms')
        self.cipher_suite = None
        self.load_encryption_key(kms_key_id)

    def load_encryption_key(self, kms_key_id):
        try:
            response = self.kms_client.get_secret_value(SecretId=kms_key_id)
            if 'SecretString' in response:
                key = bytes(response['SecretString'], 'utf-8')
                self.cipher_suite = Fernet(key)
        except Exception as e:
            raise EncryptionFailureError(str(e))

    def generate_config(self, template_path, output_path, env_vars):
        try:
            with open(template_path, 'r') as file:
                config_template = file.read()
                for key, value in env_vars.items():
                    config_template = config_template.replace(f'${{{key}}}', value)
            with open(output_path, 'w') as file:
                file.write(config_template)
        except FileNotFoundError:
            raise FileNotFoundError(f"Template file not found: {template_path}")
        except Exception as e:
            raise ConfigGenerationError(str(e))

    def encrypt_config(self, config_path):
        try:
            with open(config_path, 'r') as file:
                config_data = file.read()
                encrypted_data = self.cipher_suite.encrypt(config_data.encode())
            with open(config_path, 'wb') as file:
                file.write(encrypted_data)
        except Exception as e:
            raise EncryptionFailureError(str(e))

    def decrypt_config(self, config_path):
        try:
            with open(config_path, 'rb') as file:
                encrypted_data = file.read()
                decrypted_data = self.cipher_suite.decrypt(encrypted_data).decode()
            with open(config_path, 'w') as file:
                file.write(decrypted_data)
        except Exception as e:
            raise DecryptionFailureError(str(e))

    def parallel_process_configs(self, config_paths):
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.encrypt_config, path) for path in config_paths]
            for future in futures:
                try:
                    future.result()
                except Exception as e:
                    print(f"Error processing config: {e}")

    def log_changes(self, action, config_path):
        with open('config_changes.log', 'a') as file:
            file.write(f"{action} performed on {config_path}\n")

class EncryptionFailureError(Exception):
    pass

class FileNotFoundError(Exception):
    pass

class ConfigGenerationError(Exception):
    pass

class DecryptionFailureError(Exception):
    pass
```

