```cpp
#include <iostream>
#include <string>
#include <optional>
#include <memory>
#include <stdexcept>
#include <openssl/tripledes.h> // OpenSSL for Triple DES encryption

// Simulated Octree class for demonstration purposes
class Octree {
public:
    Octree(int featureSize, int numLeafNodes, int dataCapacity) 
        : m_featureSize(featureSize), m_numLeafNodes(numLeafNodes), m_dataCapacity(dataCapacity) {}

    ~Octree() {
        // Cleanup code here
        std::cout << "Octree destroyed" << std::endl;
    }
private:
    int m_featureSize, m_numLeafNodes, m_dataCapacity;
};

// Custom error handling mechanism
struct DecryptionError : public std::runtime_error {
    explicit DecryptionError(const std::string& message) : std::runtime_error(message) {}
};

std::optional<std::pair<std::string, std::shared_ptr<Octree>>> securelyDecryptAndInitializeOctree(
    const std::string& encodedMessage, 
    const std::string& key, 
    const std::string& iv, 
    int featureSize, 
    int numLeafNodes, 
    int dataCapacity
) {
    try {
        // Simulate decryption process using OpenSSL's Triple DES
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw DecryptionError("Failed to create cipher context");

        if (1 != EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()))) {
            EVP_CIPHER_CTX_free(ctx);
            throw DecryptionError("Decryption initialization failed");
        }

        std::string decryptedMessage;
        decryptedMessage.resize(encodedMessage.size());
        int len = 0;
        if (1 != EVP_DecryptUpdate(ctx, reinterpret_cast<unsigned char*>(&decryptedMessage[0]), &len, reinterpret_cast<const unsigned char*>(encodedMessage.c_str()), encodedMessage.size())) {
            EVP_CIPHER_CTX_free(ctx);
            throw DecryptionError("Decryption update failed");
        }

        int finalLen = 0;
        if (1 != EVP_DecryptFinal_ex(ctx, reinterpret_cast<unsigned char*>(&decryptedMessage[len]), &finalLen)) {
            EVP_CIPHER_CTX_free(ctx);
            throw DecryptionError("Decryption finalization failed");
        }

        decryptedMessage.resize(len + finalLen);
        EVP_CIPHER_CTX_free(ctx);

        // Simulate octree initialization
        auto octree = std::make_shared<Octree>(featureSize, numLeafNodes, dataCapacity);
        if (!octree) throw DecryptionError("Failed to allocate memory for Octree");

        return {{decryptedMessage, octree}};
    } catch (const DecryptionError& e) {
        std::cerr << "Decryption error: " << e.what() << std::endl;
        return {};
    } catch (const std::exception& e) {
        std::cerr << "General error: " << e.what() << std::endl;
        return {};
    }
}

int main() {
    // Example usage
    auto result = securelyDecryptAndInitializeOctree(
        "your_encrypted_message_base64",
        "your_key",
        "your_iv",
        3,
        10,
        100
    );

    if (result) {
        std::cout << "Decrypted message: " << result->first << std::endl;
        // Use the octree here
    } else {
        std::cerr << "Failed to decrypt or initialize octree" << std::endl;
    }

    return 0;
}
