using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using MassTransit;

public interface IServiceManager
{
    Task StartServicesAsync(List<string> values, string connectionString, string sqlCommand);
    Task StopServiceAsync(string serviceId);
}

public class ServiceManager : IServiceManager
{
    private readonly IServiceProvider _serviceProvider;
    private readonly IBusControl _busControl;

    public ServiceManager(IServiceProvider serviceProvider, IBusControl busControl)
    {
        _serviceProvider = serviceProvider;
        _busControl = busControl;
    }

    public async Task StartServicesAsync(List<string> values, string connectionString, string sqlCommand)
    {
        var tasks = values.Select(async (value, index) =>
        {
            await Task.Delay(new Random().Next(1000, 5000)); // Simulate random delay

            using (var connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand(sqlCommand, connection))
                {
                    command.Parameters.AddWithValue("@Value", value);
                    using (var reader = await command.ExecuteReaderAsync())
                    {
                        // Process the data reader
                    }
                }
            }

            var serviceId = $"Service-{index}";
            Console.WriteLine($"Service {serviceId} started");

            await _busControl.Publish(new ServiceStartedEvent(serviceId));
        });

        await Task.WhenAll(tasks);
    }

    public async Task StopServiceAsync(string serviceId)
    {
        try
        {
            // Perform any necessary cleanup

            Console.WriteLine($"Service {serviceId} stopped");
            await _busControl.Publish(new ServiceStoppedEvent(serviceId));
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error stopping service {serviceId}: {ex.Message}");
        }
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var services = new ServiceCollection();
        services.AddSingleton<IServiceManager, ServiceManager>();

        services.AddMassTransit(cfg =>
        {
            cfg.AddInMemoryMessageBroker();

            cfg.ReceiveEndpoint("service-status", ep =>
            {
                ep.ConfigureConsumer<ServiceStartedEventConsumer>();
                ep.ConfigureConsumer<ServiceStoppedEventConsumer>();
            });
        });

        var serviceProvider = services.BuildServiceProvider();
        var busControl = serviceProvider.GetService<IBusControl>();

        await busControl.StartAsync();

        var values = new List<string> { "Value1", "Value2", "Value3" };
        var connectionString = "YourConnectionStringHere";
        var sqlCommand = "SELECT * FROM YourTable WHERE Value = @Value";

        var serviceManager = serviceProvider.GetService<IServiceManager>();
        await serviceManager.StartServicesAsync(values, connectionString, sqlCommand);

        // Simulate stopping a service after some time
        await Task.Delay(10000);
        await serviceManager.StopServiceAsync("Service-1");

        await busControl.StopAsync();
    }
}

public class ServiceStartedEvent : IMessage
{
    public string ServiceId { get; }

    public ServiceStartedEvent(string serviceId)
    {
        ServiceId = serviceId;
    }
}

public class ServiceStoppedEvent : IMessage
{
    public string ServiceId { get; }

    public ServiceStoppedEvent(string serviceId)
    {
        ServiceId = serviceId;
    }
}

public class ServiceStartedEventConsumer : IConsumer<ServiceStartedEvent>
{
    public Task Consume(ConsumeContext<ServiceStartedEvent> context)
    {
        Console.WriteLine($"Service started: {context.Message.ServiceId}");
        return Task.CompletedTask;
    }
}

public class ServiceStoppedEventConsumer : IConsumer<ServiceStoppedEvent>
{
    public Task Consume(ConsumeContext<ServiceStoppedEvent> context)
    {
        Console.WriteLine($"Service stopped: {context.Message.ServiceId}");
        return Task.CompletedTask;
    }
}
