// Function prototypes
int process_csv_file(const char *input_file_path, const char *output_file_path);
void log_error(const char *message);

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file_path = argv[1];
    const char *output_file_path = argv[2];

    int result = process_csv_file(input_file_path, output_file_path);
    if (result != 0) {
        fprintf(stderr, "Error processing CSV file.\n");
        return EXIT_FAILURE;
    }

    printf("CSV file processed successfully.\n");
    return EXIT_SUCCESS;
}

int process_csv_file(const char *input_file_path, const char *output_file_path) {
    FILE *input_file = fopen(input_file_path, "r");
    if (input_file == NULL) {
        log_error("Failed to open input file.");
        return 1;
    }

    FILE *output_file = fopen(output_file_path, "w");
    if (output_file == NULL) {
