using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class ProductInventory
{
    public int ProductId { get; set; }
    public string ProductName { get; set; }
    public int Quantity { get; set; }
    public decimal Price { get; set; }
}

public class InventoryManager
{
    private List<ProductInventory> records = new List<ProductInventory>();
    private HttpClient client;

    public InventoryManager()
    {
        client = new HttpClient();
    }

    public void SerializeToFile(string filePath)
    {
        using (FileStream fs = new FileStream(filePath, FileMode.Create))
        {
            BinaryWriter writer = new BinaryWriter(fs);
            foreach (var record in records)
            {
                writer.Write(record.ProductId);
                byte[] nameBytes = Encoding.UTF8.GetBytes(record.ProductName);
                if (nameBytes.Length > 0)
                {
                    writer.Write(nameBytes);
                    writer.Write((byte)0); // Null terminator
                }
                else
                {
                    writer.Write((byte)0); // Empty string indicator
                }
                writer.Write(record.Quantity);
                writer.Write(record.Price);
            }
        }
    }

    public void DeserializeFromFile(string filePath)
    {
        records.Clear();
        using (FileStream fs = new FileStream(filePath, FileMode.Open))
        {
            BinaryReader reader = new BinaryReader(fs);
            while (fs.Position < fs.Length)
            {
                ProductInventory record = new ProductInventory
                {
                    ProductId = reader.ReadInt32(),
                    Quantity = reader.ReadInt32(),
                    Price = reader.ReadDecimal()
                };
                byte[] nameBytes;
                if ((byte)0 != reader.ReadByte()) // Check for null terminator or empty string indicator
                {
                    nameBytes = reader.ReadBytes(1024); // Assuming maximum product name length is 1024 bytes
                    record.ProductName = Encoding.UTF8.GetString(nameBytes, 0, Array.IndexOf(nameBytes, (byte)0));
                }
                else
                {
                    record.ProductName = string.Empty;
                }
                records.Add(record);
            }
        }
    }

    public async Task FetchInventoryFromAPI(string apiUrl)
    {
        try
        {
            HttpResponseMessage response = await client.GetAsync(apiUrl);
            if (response.IsSuccessStatusCode)
            {
                string content = await response.Content.ReadAsStringAsync();
                var apiRecords = JsonConvert.DeserializeObject<List<ProductInventory>>(content);
                records.AddRange(apiRecords);
            }
            else
            {
                Console.WriteLine($"Failed to fetch inventory. Status code: {response.StatusCode}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error during API interaction: {ex.Message}");
        }
    }

    public void FreeMemory()
    {
        records = null;
        GC.Collect();
    }

    public void Log(string message)
    {
        Console.WriteLine(message);
    }
}
