```python
from abc import ABC, abstractmethod
import json
import queue
import threading
import time
import hashlib

class LogEntry:
    def __init__(self, service_name, message, level='INFO', format='json'):
        self.service_name = service_name
        self.message = message
        self.level = level
        self.format = format
        self.timestamp = time.time()
        self.hash = self.calculate_hash()

    def calculate_hash(self):
        data = f"{self.service_name}{self.message}{self.level}{self.format}{self.timestamp}"
        return hashlib.sha256(data.encode()).hexdigest()

class ILogPublisher(ABC):
    @abstractmethod
    def publish(self, log_entry: LogEntry) -> None:
        pass

class JsonLogPublisher(ILogPublisher):
    def publish(self, log_entry: LogEntry) -> None:
        print(f"Publishing JSON log entry for service {log_entry.service_name}: {json.dumps(log_entry.__dict__)}")

class PlainTextLogPublisher(ILogPublisher):
    def publish(self, log_entry: LogEntry) -> None:
        print(f"Publishing plain text log entry for service {log_entry.service_name}: {log_entry.message}")

class IBackendStorage(ABC):
    @abstractmethod
    def store(self, log_entry: LogEntry) -> None:
        pass

class ElasticsearchBackendStorage(IBackendStorage):
    def store(self, log_entry: LogEntry) -> None:
        print(f"Storing log entry in Elasticsearch for service {log_entry.service_name}: {log_entry.message}")

class AWSCloudWatchBackendStorage(IBackendStorage):
    def store(self, log_entry: LogEntry) -> None:
        print(f"Storing log entry in AWS CloudWatch for service {log_entry.service_name}: {log_entry.message}")

class LogManager:
    def __init__(self):
        self.publisher = JsonLogPublisher()
        self.storage_backends = {'elasticsearch': ElasticsearchBackendStorage(), 'aws_cloudwatch': AWSCloudWatchBackendStorage()}
        self.log_queue = queue.Queue()

    def submit_log(self, log_entry: LogEntry) -> None:
        if not self.is_valid_log(log_entry):
            print("Invalid log entry. Skipping.")
            return
        self.log_queue.put(log_entry)

    def is_valid_log(self, log_entry: LogEntry) -> bool:
        # Implement log validation logic here
        return True

    def distribute_logs(self) -> None:
        while True:
            try:
                log_entry = self.log_queue.get(timeout=1)
                self.publisher.publish(log_entry)
                for storage_backend in self.storage_backends.values():
                    storage_backend.store(log_entry)
            except queue.Empty:
                continue
            except Exception as e:
                print(f"Error storing log entry: {e}")

class LogService:
    def __init__(self, log_manager):
        self.log_manager = log_manager

    def submit_log(self, message, level='INFO', format='json'):
        log_entry = LogEntry(service_name=self.__class__.__name__, message=message, level=level, format=format)
        self.log_manager.submit_log(log_entry)

if __name__ == "__main__":
    log_manager = LogManager()
    log_service1 = LogService(log_manager)
    log_service2 = LogService(log_manager)

    # Start distributing logs in a separate thread
    threading.Thread(target=log_manager.distribute_logs, daemon=True).start()

    # Submit some logs
    log_service1.submit_log("Service 1 is running")
    log_service2.submit_log("Service 2 is starting", level='DEBUG')
    time.sleep(2)
