#include <iostream>
#include <forward_list>
#include <functional>
#include <semaphore.h>
#include <fstream>
#include <ctime>

void asyncSemaphoreReduce(std::forward_list<std::string> list, int initialValue, std::function<int(int, const std::string&)> lambda) {
    sem_t* semaphore = static_cast<sem_t*>(malloc(sizeof(sem_t)));
    sem_init(semaphore, 0, initialValue);

    auto logOperation = [](const std::string& operation) {
        time_t now = time(0);
        char* dt = ctime(&now);
        std::ofstream logFile("async_operations.log", std::ios_base::app);
        logFile << "[" << dt << "] " << operation << std::endl;
    };

    int result = initialValue;
    for (const auto& item : list) {
        sem_wait(semaphore);
        logOperation("Waiting on semaphore");
        result = lambda(result, item);
        logOperation("Reducing with: " + item);
        sem_post(semaphore);
        logOperation("Releasing semaphore");
    }

    sem_destroy(semaphore);
    free(semaphore);
}
