        this.serviceInstances = new HashMap<>();
        this.resourceMonitor = new ResourceMonitor();
        this.loggingSystem = new LoggingSystem();
        this.monitoringDashboard = new MonitoringDashboard();

        for (int i = 1; i <= MAX_SERVICE_INSTANCES; i++) {
            String serviceName = "Service-" + i;
            serviceInstances.put(serviceName, new ServiceInstance(serviceName, minDelay, maxDelay));
            executor.submit(() -> manageService(serviceName));
        }
    }

    private void manageService(String serviceName) {
        while (true) {
            ServiceInstance service = serviceInstances.get(serviceName);
            try {
                if (!service.isRunning()) {
                    startService(serviceName);
                } else {
                    checkServiceHealth(serviceName);
                }
            } catch (Exception e) {
                logError(serviceName, "Unexpected error: " + e.getMessage());
            }
            try {
                Thread.sleep(HEALTH_CHECK_INTERVAL);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void startService(String serviceName) throws Exception {
        ServiceInstance service = serviceInstances.get(serviceName);
        if (!service.isRunning() && canStartNewService()) {
            service.start();
            logInfo(serviceName, "Started");
        } else {
            logDebug(serviceName, "Not starting due to current conditions");
        }
    }

    private boolean canStartNewService() {
        return resourceMonitor.canStartNewService();
    }

    private void checkServiceHealth(String serviceName) throws Exception {
        ServiceInstance service = serviceInstances.get(serviceName);
        if (service.isRunning()) {
            boolean isHealthy = service.checkHealth();
            if (!isHealthy) {
                stopService(serviceName, "Unhealthy");
            }
        }
    }

    private void stopService(String serviceName, String reason) throws Exception {
        ServiceInstance service = serviceInstances.get(serviceName);
        if (service.isRunning()) {
            service.stop();
            logInfo(serviceName, "Stopped: " + reason);
        } else {
            logDebug(serviceName, "Already stopped");
        }
    }

    private void logInfo(String serviceName, String message) {
        loggingSystem.log(serviceName + ": " + message);
        monitoringDashboard.updateStatus(serviceName, message);
    }

    private void logWarning(String serviceName, String message) {
        loggingSystem.log(serviceName + ": WARNING: " + message);
        monitoringDashboard.updateStatus(serviceName, "WARNING");
    }

    private void logError(String serviceName, String message) {
        loggingSystem.log(serviceName + ": ERROR: " + message);
        monitoringDashboard.updateStatus(serviceName, "ERROR");
    }

    private void logDebug(String serviceName, String message) {
        if (loggingSystem.isDebugEnabled()) {
            loggingSystem.log(serviceName + ": DEBUG: " + message);
        }
    }

    public static void main(String[] args) {
        int minDelay = 1000; // Example minimum delay in milliseconds
        int maxDelay = 5000; // Example maximum delay in milliseconds
        long healthCheckInterval = 5000; // Example health check interval in milliseconds

        DistributedServiceManager manager = new DistributedServiceManager(minDelay, maxDelay, healthCheckInterval);
    }
}

