#include <iostream>
#include <vector>
#include <random>
#include <mutex>

class NfapiCrcIndicationPdu {
public:
    // Constructor to initialize the PDU with random values
    NfapiCrcIndicationPdu(uint32_t rxUeInformationTag, uint16_t rnti, bool crcFlag)
        : rxUeInformationTag(rxUeInformationTag), rnti(rnti), crcFlag(crcFlag) {}

    // Method to serialize the PDU for network transmission
    std::string serialize() const {
        // Implementation for serialization
        return "Serialized Data";
    }

    // Getter methods
    uint32_t getRxUeInformationTag() const { return rxUeInformationTag; }
    uint16_t getRnti() const { return rnti; }
    bool getCrcFlag() const { return crcFlag; }

private:
    uint32_t rxUeInformationTag;
    uint16_t rnti;
    bool crcFlag;
};

class CrcPduManager {
public:
    // Function to initialize and populate a vector of NfapiCrcIndicationPdu objects
    static std::vector<NfapiCrcIndicationPdu> initializeAndPopulateCrcPDUs(int N) {
        if (N < 0) {
            throw std::invalid_argument("Number of PDUs must be non-negative.");
        }

        std::vector<NfapiCrcIndicationPdu> pdus;
        pdus.reserve(N); // Reserve memory to avoid frequent reallocations

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> rxUeInfoTagDist(0, 1000);
        std::uniform_int_distribution<> rntiDist(1, 4095);

        for (int i = 0; i < N; ++i) {
            uint32_t rxUeInformationTag = rxUeInfoTagDist(gen);
            uint16_t rnti = rntiDist(gen);
            bool crcFlag = gen() % 2 == 0; // Randomly set CRC flag
            pdus.emplace_back(rxUeInformationTag, rnti, crcFlag);
        }

        return pdus;
    }
};

int main() {
    try {
        int N = 10;
        std::vector<NfapiCrcIndicationPdu> pdus = CrcPduManager::initializeAndPopulateCrcPDUs(N);

        for (const auto& pdu : pdus) {
            std::cout << "RxUeInformationTag: " << pdu.getRxUeInformationTag()
                      << ", Rnti: " << pdu.getRnti()
                      << ", CRC Flag: " << (pdu.getCrcFlag() ? "True" : "False")
                      << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
