// Forward declaration for the insertAfterFirstOccurrence function
bool insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& search, const std::string& insert, bool caseInsensitive = false);

int main() {
    // Initialize Boost ASIO and SSL
    boost::asio::io_context io_context;
    boost::asio::ssl::context sslContext(boost::asio::ssl::context::sslv23);

    // Configure SSL context (e.g., set certificate files)
    sslContext.set_options(SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3);

    // Create a TCP client socket
    boost::asio::ip::tcp::resolver resolver(io_context);
    boost::asio::ssl::stream<boost::asio::ip::tcp::socket> socket(io_context, sslContext);

    // Connect to the server using the resolver
    boost::asio::connect(socket.lowest_layer(), resolver.resolve("example.com", "443"));

    // Upgrade the connection to SSL/TLS
    socket.handshake(boost::asio::ssl::stream_base::client);

    // Send a request or data
    const std::string message = "Hello, server!";
    boost::asio::write(socket, boost::asio::buffer(message));

    // Read the response
    boost::array<char, 128> buffer;
    boost::system::error_code error;
    size_t length = socket.read_some(boost::asio::buffer(buffer), error);

    if (error == boost::asio::error::eof) {
        // Connection closed cleanly by peer
    } else if (!error) {
        // Process the response
        std::string responseData(buffer.data(), length);
        std::cout << "Received data: " << responseData << std::endl;

        // Insert a new string after the first occurrence of a search string
        std::forward_list<std::string> list = {"apple", "banana", "cherry"};
        bool insertSuccessful = insertAfterFirstOccurrence(list, "banana", "grape");
        if (insertSuccessful) {
            std::cout << "Insert successful!" << std::endl;
        } else {
            std::cout << "Insert failed." << std::endl;
        }
    }

    // Close the socket
    socket.shutdown(boost::asio::ssl::stream_base::shutdown_both);
    socket.lowest_layer().close();

    return 0;
}

// Implementation of insertAfterFirstOccurrence function
bool insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& search, const std::string& insert, bool caseInsensitive) {
    auto insertIt = list.before_begin();
    for (auto it = list.begin(); it != list.end(); ++it) {
        if ((caseInsensitive && boost::iequals(*it, search)) || (*it == search)) {
            insertIt = it;
            break;
        }
    }

    std::lock_guard<std::mutex> lock(mutex);
    if (insertIt != list.before_begin()) {
        list.insert_after(insertIt, insert);
        logOperation("Inserted", *insertIt, insert, std::time(nullptr));
        return true;
    } else {
        list.push_front(insert);
        logOperation("Appended", "End of list", insert, std::time(nullptr));
        return false;
    }
}

// Function to log operations
void logOperation(const std::string& action, const std::string& item1, const std::string& item2, time_t timestamp) {
    std::ofstream logFile("list_operations.log", std::ios::app);
    if (logFile.is_open()) {
        logFile << "[" << ctime(&timestamp) << "] " << action << ": " << item1 << " after " << item2 << std::endl;
        logFile.close();
    }
}

