class PasswordHasher {
    public static function hashPassword($password) {
        return password_hash($password, PASSWORD_ARGON2ID);
    }

    public static function checkPassword($hashedPassword, $password) {
        return password_verify($password, $hashedPassword);
    }
}

class UserDao {
    private $pdo;

    public function __construct(PDO $pdo) {
        $this->pdo = $pdo;
    }

    public function getUserHashedPassword($userId) {
        $stmt = $this->pdo->prepare("SELECT hashed_password FROM users WHERE id = :id");
        $stmt->execute(['id' => $userId]);
        return $stmt->fetchColumn();
    }

    public function updatePassword($userId, $hashedNewPassword) {
        $stmt = $this->pdo->prepare("UPDATE users SET hashed_password = :newHash WHERE id = :id");
        $stmt->execute(['id' => $userId, 'newHash' => $hashedNewPassword]);
        return $stmt->rowCount() === 1;
    }
}

class PasswordUpdateService {
    private $passwordValidationService;
    private $userDao;

    public function __construct(PasswordValidationService $passwordValidationService, UserDao $userDao) {
        $this->passwordValidationService = $passwordValidationService;
        $this->userDao = $userDao;
    }

    public function updateUserPassword($userId, $currentPassword, $newPassword) {
        try {
            // Validate password strength
            if (!$this->passwordValidationService->isStrongPassword($newPassword)) {
                return json_encode(['success' => false, 'message' => 'Password does not meet the strength requirements']);
            }

            // Check current password
            $hashedCurrentPassword = $this->userDao->getUserHashedPassword($userId);
            if (!PasswordHasher::checkPassword($hashedCurrentPassword, $currentPassword)) {
                return json_encode(['success' => false, 'message' => 'Invalid current password']);
            }

            // Hash new password
            $hashedNewPassword = PasswordHasher::hashPassword($newPassword);

            // Update password in database
            if ($this->userDao->updatePassword($userId, $hashedNewPassword)) {
                return json_encode(['success' => true, 'message' => 'Password updated successfully']);
            } else {
                return json_encode(['success' => false, 'message' => 'Failed to update password']);
            }
        } catch (Exception $e) {
            return json_encode(['success' => false, 'message' => 'Internal server error', 'errorCode' => 500]);
        }
    }
}
