        if (elements.empty()) {
            return;
        }

        bool updateSuccess = false;
        try {
            updateSuccess = htmlService.updateElement(elements, sectionId, elementId, htmlContent);
            if (!updateSuccess) {
                throw std::runtime_error("Failed to update HTML element.");
            }
        } catch (const std::exception& e) {
            // Log error and retry mechanism
            // ...
        }

        bool dataCollectionSuccess = false;
        try {
            dataCollectionSuccess = dataStreamService.collectData();
            if (!dataCollectionSuccess) {
                throw std::runtime_error("Failed to collect data from streaming API.");
            }
        } catch (const std::exception& e) {
            // Log error and retry mechanism
            // ...
        }

        refreshPage = updateSuccess && dataCollectionSuccess;
    }

    std::string getResponse() const {
        return refreshPage ? "RefreshPage" : "DoNotRefreshPage";
    }
};
