    double timestamp;
    double value;
    double weightedSum;

    Transaction(int id, double timestamp, double value, double weightedSum)
        : id(id), timestamp(timestamp), value(value), weightedSum(weightedSum) {}
};

class FinancialDataProcessor {
public:
    FinancialDataProcessor() {}

    void addTransaction(const Transaction& transaction) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(transaction);
        condition_.notify_one();
    }

    Transaction processTransactions() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !queue_.empty(); });

            auto now = std::chrono::system_clock::now().time_since_epoch().count();
            queue_.erase(std::remove_if(queue_.begin(), queue_.end(),
                [now](const Transaction& t) {
                    return (now - static_cast<double>(t.timestamp)) > 60.0; // Filter transactions older than 1 minute
                }),
            queue_.end());

            if (queue_.size() > 500) { // Limit the number of transactions in the past 3 seconds to 500
                queue_.pop();
            }

            double totalWeightedSum = 0.0;
            for (const auto& t : queue_) {
                totalWeightedSum += t.weightedSum;
            }

            if (totalWeightedSum > 1000) { // Apply weighted sum threshold
                Transaction maxTransaction = *std::max_element(queue_.begin(), queue_.end(),
                    [](const Transaction& a, const Transaction& b) {
                        return a.weightedSum < b.weightedSum;
                    });

                for (auto it = queue_.begin(); it != queue_.end();) {
                    if (it->id == maxTransaction.id) {
                        ++it;
                        continue;
                    }
                    queue_.erase(it);
                }

                return maxTransaction;
            } else {
                // If the threshold is not met, clear the queue and wait for new transactions
                while (!queue_.empty()) {
                    queue_.pop();
                }
                condition_.wait(lock, [this] { return !queue_.empty(); });
            }
        }
    }

private:
    std::priority_queue<Transaction> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    FinancialDataProcessor processor;

    // Simulate adding transactions from multiple data streams
    for (int i = 0; i < 1000; ++i) {
        double timestamp = std::chrono::system_clock::now().time_since_epoch().count();
        Transaction transaction(i, timestamp, static_cast<double>(i), static_cast<double>(i * i));
        processor.addTransaction(transaction);
    }

    // Process transactions and get the one with the highest weighted sum
    Transaction result = processor.processTransactions();
    std::cout << "Highest Weighted Sum Transaction: ID=" << result.id
              << ", Weighted Sum=" << result.weightedSum << std::endl;

    return 0;
}
