import json
from typing import Dict, Any, Callable
import fcntl

class ConfigManager:
    factories: Dict[int, Callable[[Dict[str, Any]], 'Config']] = {}

    @staticmethod
    def add_factory(type_id: int, factory_func: Callable[[Dict[str, Any]], 'Config']):
        ConfigManager.factories[type_id] = factory_func

    @staticmethod
    def create_instance_from_json(json_str: str) -> 'Config':
        config_data = json.loads(json_str)
        if 'type_id' not in config_data:
            raise ValueError("Missing type_id in JSON data")
        factory_func = ConfigManager.factories.get(config_data['type_id'])
        if not factory_func:
            raise ValueError(f"No factory function found for type ID: {config_data['type_id']}")
        return factory_func(config_data)

    @staticmethod
    def load_from_file(file_path: str) -> 'Config':
        with open(file_path, 'r') as file:
            fcntl.flock(file.fileno(), fcntl.LOCK_EX)
            try:
                config_data = json.load(file)
                if 'type_id' not in config_data:
                    raise ValueError("Missing type_id in JSON data")
                factory_func = ConfigManager.factories.get(config_data['type_id'])
                if not factory_func:
                    raise ValueError(f"No factory function found for type ID: {config_data['type_id']}")
                return factory_func(config_data)
            finally:
                fcntl.flock(file.fileno(), fcntl.LOCK_UN)

    @staticmethod
    def save_to_file(config: 'Config', file_path: str):
        with open(file_path, 'w') as file:
            fcntl.flock(file.fileno(), fcntl.LOCK_EX)
            try:
                config_data = config.to_json()
                json.dump(config_data, file, indent=4)
            finally:
                fcntl.flock(file.fileno(), fcntl.LOCK_UN)

class Config:
    def __init__(self, data: Dict[str, Any]):
        self.data = data

    @property
    def type_id(self) -> int:
        raise NotImplementedError("Subclasses must implement type_id property")

    def to_json(self) -> str:
        return json.dumps(self.data, indent=4)

# Example usage
class DatabaseConfig(Config):
    def __init__(self, data: Dict[str, Any]):
        super().__init__(data)
        self.type_id = 1

    @property
    def type_id(self) -> int:
        return 1

ConfigManager.add_factory(1, lambda data: DatabaseConfig(data))

config_instance = ConfigManager.create_instance_from_json('{"type_id": 1, "host": "localhost", "port": 5432}')
ConfigManager.save_to_file(config_instance, 'config.json')
loaded_config = ConfigManager.load_from_file('config.json')
print(loaded_config.data)
