```python
import json
import threading
from queue import Queue, Empty

def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)
            # Process the JSON data here
            result = f"Processed {file_path}"
        return result
    except (FileNotFoundError, json.JSONDecodeError) as e:
        return f"Failed to process {file_path}: {e}"

def worker(queue, label):
    while True:
        try:
            file_path = queue.get(timeout=1)
        except Empty:
            break
        result = process_file(file_path)
        print(f"{label} - {result}")
        queue.task_done()

def batch_process_files(file_paths, label="Batch", parallel=True, max_workers=5):
    if not parallel:
        max_workers = 1

    queue = Queue()
    threads = []

    for _ in range(max_workers):
        t = threading.Thread(target=worker, args=(queue, label))
        t.start()
        threads.append(t)

    for file_path in file_paths:
        queue.put(file_path)

    queue.join()

    for t in threads:
        t.join()

# Example usage
file_paths = ['path/to/file1.json', 'path/to/file2.json']
batch_process_files(file_paths, label="MyBatch", parallel=True)
```

