#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>

#define MAX_LOGS 1000
#define API_KEY "your_api_key_here"

typedef struct {
    char ip[256];
    int count;
} Entity;

Entity entities[MAX_LOGS];

int process_logs(char* input_directory) {
    DIR *dir;
    struct dirent *entry;
    int log_count = 0;

    if ((dir = opendir(input_directory)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", input_directory, entry->d_name);
            FILE *file = fopen(path, "r");
            if (file != NULL) {
                char line[256];
                while (fgets(line, sizeof(line), file)) {
                    // Process each log line
                    for (int i = 0; i < log_count; i++) {
                        if (strcmp(entities[i].ip, line) == 0) {
                            entities[i].count++;
                            break;
                        }
                    }
                    if (i == log_count) {
                        strcpy(entities[log_count].ip, line);
                        entities[log_count++].count = 1;
                    }
                }
                fclose(file);
            } else {
                printf("Error opening file: %s\n", path);
            }
        }
        closedir(dir);
    } else {
        printf("Error opening directory: %s\n", input_directory);
    }

    return log_count;
}

