namespace quadtree {
    struct QuadTreeNode {
        int value;
        QuadTreeNode* topLeft;
        QuadTreeNode* topRight;
        QuadTreeNode* bottomLeft;
        QuadTreeNode* bottomRight;

        QuadTreeNode(int val) : value(val), topLeft(nullptr), topRight(nullptr), bottomLeft(nullptr), bottomRight(nullptr) {}
        ~QuadTreeNode() {
            delete topLeft;
            delete topRight;
            delete bottomLeft;
            delete bottomRight;
        }
    };

    class RandomQuadtree {
    public:
        static std::mt19937 rng;

        RandomQuadtree() {}
        ~RandomQuadtree() {}

        void insert(int value) {
            root = insert(root, value);
        }

        QuadTreeNode* findNearestNeighbor(int target) const {
            return findNearestNeighbor(root, target, root);
        }

    private:
        QuadTreeNode* root = nullptr;

        QuadTreeNode* insert(QuadTreeNode* node, int value) {
            if (!node) return new QuadTreeNode(value);
            // Implement the logic to insert a value in the quadtree
            return node;
        }

        QuadTreeNode* findNearestNeighbor(QuadTreeNode* node, int target, QuadTreeNode* best) const {
            // Implement the logic to find the nearest neighbor in the quadtree
            return best;
        }
    };

    std::mt19937 RandomQuadtree::rng;
}

int main() {
    quadtree::RandomQuadtree rqt;

    // Insert data points into the quadtree
    for (int i = 0; i < 10000000; ++i) {
        rqt.insert(quadtree::RandomQuadtree::rng());
    }

    // Query the nearest neighbor
    int target = quadtree::RandomQuadtree::rng();
    quadtree::QuadTreeNode* nearestNeighbor = rqt.findNearestNeighbor(target);

    return 0;
}
