#include <iostream>
#include <string>
#include <mutex>
#include <stdexcept>
#include <atomic>

class StringExtender {
private:
    static std::atomic<int> callCount;
    const std::string appendSequence;
    const size_t maxBufferSize;

    std::mutex bufferMutex;

public:
    StringExtender(const std::string& seq, size_t bufferSize)
        : appendSequence(seq), maxBufferSize(bufferSize) {}

    std::string extendString(const std::string& input) {
        std::lock_guard<std::mutex> lock(bufferMutex);

        if (input.length() >= maxBufferSize) {
            throw std::length_error("Input string exceeds maximum buffer size");
        }

        size_t availableSpace = maxBufferSize - input.length();
        if (appendSequence.length() > availableSpace) {
            throw std::length_error("Appending sequence would exceed buffer size");
        }

        std::string result(input);
        result.append(appendSequence, 0, availableSpace);

        callCount.fetch_add(1);
        logStringResult(result);

        return result;
    }

private:
    static void logStringResult(const std::string& result) {
        // Simulate logging by printing to console
        std::cout << "Function called: " << callCount.load() << " Result length: " << result.length() << std::endl;
    }
};

std::atomic<int> StringExtender::callCount(0);

// Unit tests (assuming Google Test framework)
TEST(StringExtenderTest, ExtendStringWithRoom) {
    StringExtender extender("abc", 20);
    std::string extended = extender.extendString("hello");
    EXPECT_EQ(extended, "helloabcabc");
}

TEST(StringExtenderTest, AppendSequenceExceedsBuffer) {
    StringExtender extender("xyz", 10);
    EXPECT_THROW(extender.extendString("short"), std::length_error);
}

TEST(StringExtenderTest, InputExceedsBuffer) {
    StringExtender extender("abc", 4);
    EXPECT_THROW(extender.extendString("very long string"), std::length_error);
}
