import requests
from datetime import datetime
import json

# Define a class to manage CDN metrics
class CdnMetricsManager:
    def __init__(self, cdn_urls):
        self.cdn_urls = cdn_urls

    # Function to fetch metrics from CDN servers
    def fetch_metrics(self):
        metrics_data = []
        for url in self.cdn_urls:
            response = requests.get(url)
            if response.status_code == 200:
                metrics_data.extend(response.json())
        return metrics_data

# Define a class to analyze the fetched metrics
class MetricAnalyzer:
    def __init__(self, thresholds):
        self.thresholds = thresholds

    # Function to analyze metrics and detect anomalies
    def analyze_metrics(self, metrics):
        results = []
        for metric in metrics:
            if metric['quality'] < self.thresholds['min_quality']:
                results.append({'timestamp': datetime.now(), 'cdn': metric['cdn'], 'issue': 'Quality Drop'})
        return results

# Define a class to handle alerts
class AlertHandler:
    def __init__(self, notification_channels):
        self.notification_channels = notification_channels

    # Function to send alerts based on analysis results
    def send_alerts(self, alerts):
        for alert in alerts:
            for channel in self.notification_channels:
                channel.send_notification(alert)

# Define an interface for notification channels
class NotificationChannel:
    def send_notification(self, message):
        pass

# Example of a simple email notification channel
class EmailNotificationChannel(NotificationChannel):
    def send_notification(self, message):
        print(f"Email sent: {message}")

# Example usage
cdn_urls = ['http://cdn1.example.com/metrics', 'http://cdn2.example.com/metrics']
thresholds = {'min_quality': 3}
notification_channels = [EmailNotificationChannel()]

metrics_manager = CdnMetricsManager(cdn_urls)
analyzer = MetricAnalyzer(thresholds)
alert_handler = AlertHandler(notification_channels)

metrics = metrics_manager.fetch_metrics()
analysis_results = analyzer.analyze_metrics(metrics)
if analysis_results:
    alert_handler.send_alerts(analysis_results)
```

