class ICache {
public:
    virtual ~ICache() = default;
    virtual void Store(const std::string& key, const std::string& value, std::chrono::seconds ttl) = 0;
    virtual bool Retrieve(const std::string& key, std::string& value) = 0;
};

// Implement a simple in-memory cache
class MemoryCache : public ICache {
private:
    std::unordered_map<std::string, std::pair<std::string, std::chrono::steady_clock::time_point>> cache;

public:
    void Store(const std::string& key, const std::string& value, std::chrono::seconds ttl) override {
        auto expiration = std::chrono::steady_clock::now() + ttl;
        cache[key] = {value, expiration};
    }

    bool Retrieve(const std::string& key, std::string& value) override {
        auto it = cache.find(key);
        if (it != cache.end()) {
            if (std::chrono::steady_clock::now() < it->second.second) {
                value = it->second.first;
                return true;
            }
            cache.erase(it);
        }
        return false;
    }
};

