#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "tiffio.h"
#include "oauth2_client.h"

#define MAX_THREADS 10
#define CACHE_SIZE 100

typedef struct {
    char *image_path;
    char **metadata;
    int metadata_count;
} ImageData;

typedef struct {
    char *token;
    time_t expiration_time;
} AuthToken;

AuthToken token_cache[CACHE_SIZE];
int cache_index = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* process_image(void* arg) {
    ImageData* data = (ImageData*)arg;

    // Check if the token is in the cache
    AuthToken* token;
    pthread_mutex_lock(&lock);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (time(NULL) < token_cache[i].expiration_time) {
            token = &token_cache[i];
            break;
        }
    }

    if (!token) {
        // If not in cache, fetch a new token
        token = oauth2_fetch_token();
        pthread_mutex_lock(&lock);
        token_cache[cache_index] = *token;
        cache_index = (cache_index + 1) % CACHE_SIZE;
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_unlock(&lock);

    // Parse TIFF image
    TIFF* tif = TIFFOpen(data->image_path, "r");
    if (!tif) {
        fprintf(stderr, "Error opening TIFF file: %s\n", data->image_path);
        return NULL;
    }

    // Extract metadata
    uint16_t bits_per_sample, samples_per_pixel, orientation;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);
    TIFFGetField(tif, TIFFTAG_ORIENTATION, &orientation);

    // Allocate memory for metadata
    data->metadata_count = 3;
    data->metadata = malloc(data->metadata_count * sizeof(char*));
    data->metadata[0] = strdup("Bits per sample:");
    data->metadata[1] = strdup("Samples per pixel:");
    data->metadata[2] = strdup("Orientation:");

    data->metadata[0] = realloc(data->metadata[0], strlen(data->metadata[0]) + snprintf(NULL, 0, " %d", bits_per_sample) + 1);
    data->metadata[1] = realloc(data->metadata[1], strlen(data->metadata[1]) + snprintf(NULL, 0, " %d", samples_per_pixel) + 1);
    data->metadata[2] = realloc(data->metadata[2], strlen(data->metadata[2]) + snprintf(NULL, 0, " %s", orientation_to_string(orientation)) + 1);

    TIFFClose(tif);
    return data;
}

int main() {
    pthread_t threads[MAX_THREADS];
    ImageData image_data[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        // Populate image_data[i] with actual image paths
        image_data[i].image_path = strdup("path_to_image.tif");

        if (pthread_create(&threads[i], NULL, process_image, &image_data[i]) != 0) {
            fprintf(stderr, "Error creating thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);

        // Use the results from image_data[i]
        printf("Metadata for %s:\n", image_data[i].image_path);
        for (int j = 0; j < image_data[i].metadata_count; j++) {
            printf("%s\n", image_data[i].metadata[j]);
        }

        free(image_data[i].metadata);
    }

    return 0;
}
```

### Explanation:
1. **Multithreading**: The program uses POSIX threads to process multiple TIFF files concurrently.
2. **Token Cache**: A simple token cache is implemented using a global array and mutex for thread safety.
3. **TIFF Parsing**: Basic TIFF parsing is performed using the `libtiff` library.
4. **OAuth 2.0 Token Management**: The program fetches tokens from an OAuth 2.0 server when necessary, caching them for reuse.

