#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Helper function to find the largest integer in an array
int find_largest(int* arr, int size) {
    if (size <= 0) return -1; // Return error value for invalid input

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to read integers from standard input and store them in a dynamically allocated array
int* read_integers(int* count) {
    int capacity = 1024; // Initial capacity of the array
    *count = 0;

    int* arr = (int*)malloc(capacity * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    while (scanf("%d", &arr[*count]) != EOF) {
        (*count)++;
        if (*count >= capacity) {
            capacity *= 2; // Double the array size
            arr = realloc(arr, capacity * sizeof(int));
            if (!arr) {
                fprintf(stderr, "Memory reallocation failed.\n");
                exit(1);
            }
        }
    }

    return arr;
}

// Function to parse a JSON object as a string and check for required fields and values
int parse_json(const char* json_str) {
    struct json_object* parsed_json = json_tokener_parse(json_str);
    if (!parsed_json || json_object_get_type(parsed_json) != json_type_object) {
        fprintf(stderr, "Invalid JSON format.\n");
        return 0;
    }

    struct json_object* access_token;
    struct json_object* expires_in;
    struct json_object* token_type;

    int ret = json_object_object_get_ex((struct json_object*)parsed_json, "access_token", &access_token);
    if (!ret) {
        fprintf(stderr, "Missing 'access_token' field.\n");
        return 0;
    }

    ret = json_object_object_get_ex((struct json_object*)parsed_json, "expires_in", &expires_in);
    if (!ret || !json_object_is_type(expires_in, json_type_int) || json_object_get_int(expires_in) <= 0) {
        fprintf(stderr, "Invalid 'expires_in' field.\n");
        return 0;
    }

    ret = json_object_object_get_ex((struct json_object*)parsed_json, "token_type", &token_type);
    if (!ret || strcmp(json_object_get_string(token_type), "Bearer") != 0) {
        fprintf(stderr, "Invalid 'token_type' field.\n");
        return 0;
    }

    json_object_put(parsed_json); // Free the JSON object
    return 1;
}

int main() {
    int count;
    int* numbers = read_integers(&count);
    if (numbers) {
        printf("Largest number: %d\n", find_largest(numbers, count));
        free(numbers); // Free dynamically allocated memory
    }

    const char* json_str = "{\"access_token\":\"xyz\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    int is_valid = parse_json(json_str);
    if (is_valid) {
        printf("JSON data is valid.\n");
    } else {
        printf("JSON data is invalid.\n");
    }

    return 0;
}
