const { exec } = require('child_process');
const { LRUCache } = require('./cacheManager');
const fs = require('fs');
const path = require('path');
const { APIService } = require('./apiService');
const { RateLimiter } = require('./rateLimiter');

const cache = new LRUCache();
const apiService = new APIService();
const rateLimiter = new RateLimiter(10, 60); // 10 requests per minute

class CommandManager {
  async executeCommand(command) {
    if (!rateLimiter.isAllowed(command)) {
      throw new Error('Rate limit exceeded');
    }
    const cachedResult = cache.get(command);
    if (cachedResult) {
      return cachedResult;
    }
    try {
      return new Promise((resolve, reject) => {
        exec(command, { maxBuffer: 1024 * 1024 * 5 }, (error, stdout, stderr) => {
          if (error) {
            reject(error);
          } else {
            const result = { command, output: stdout, error: stderr };
            apiService.fetchSupplementaryInfo(result).then((info) => {
              result.info = info;
              cache.set(command, result);
              resolve(result);
            });
          }
        });
      });
    } catch (error) {
      throw new Error('Failed to execute command');
    }
  }

  async getPage(page, pageSize) {
    const results = [];
    for (const [key, value] of cache.entries()) {
      if (results.length >= page * pageSize) break;
      results.push(value);
    }
    return { page, pageSize, total: results.length, results };
  }

  async filterResults(criteria) {
    const filteredResults = [];
    for (const [key, value] of cache.entries()) {
      if (value.output.includes(criteria)) {
        filteredResults.push(value);
      }
    }
    return { total: filteredResults.length, results: filteredResults };
  }
}

module.exports = { CommandManager };"
