const max = 1000; // Maximum number of items in the cache
const ttl = 60 * 60 * 1000; // Time to live for each item in milliseconds

class LRUCache {
  constructor() {
    this.cache = lruCache({
      max,
      ttl,
      dispose(key, n) {
        console.log(`Key ${key} has been evicted from the cache`);
      },
      allowStale: false,
    });
  }

  get(command) {
    return this.cache.get(command);
  }

  set(command, result) {
    this.cache.set(command, result);
  }
}

module.exports = { LRUCache };"
