      "content": "// Manages rate limiting for command executions
class RateLimiter {
  constructor(maxRequests, interval) {
    this.maxRequests = maxRequests;
    this.interval = interval;
    this.requests = new Map();
  }

  isAllowed(command) {
    const now = Date.now();
    if (!this.requests.has(command)) {
      this.requests.set(command, { lastRequestTime: now, requestCount: 1 });
      return true;
    } else {
      const requestInfo = this.requests.get(command);
      if (now - requestInfo.lastRequestTime < this.interval) {
        if (requestInfo.requestCount >= this.maxRequests) {
          return false;
        } else {
          requestInfo.requestCount++;
          return true;
        }
      } else {
        this.requests.set(command, { lastRequestTime: now, requestCount: 1 });
        return true;
      }
    }
  }
}

module.exports = { RateLimiter };"
