std::vector<std::string> readFileAsync(const std::string& filePath, boost::asio::io_context& ioContext) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file: " + filePath);
    }

    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(line);
    }
    return lines;
}

// Define a function to send POST requests using Boost.Asio
void sendPostRequest(const std::string& url, const std::string& data) {
    try {
        boost::asio::io_context ioContext;
        boost::asio::ip::tcp::resolver resolver(ioContext);
        boost::asio::ip::tcp::resolver::results_type endpoints = resolver.resolve(url, "http");
        boost::asio::ip::tcp::socket socket(ioContext);
        boost::asio::connect(socket, endpoints);

        // Create HTTP POST request
        std::string request = "POST /endpoint HTTP/1.1\r\n"
                             "Host: example.com\r\n"
                             "Content-Type: application/json\r\n"
                             "Content-Length: " + std::to_string(data.size()) + "\r\n"
                             "\r\n" + data;

        // Send request
        boost::asio::write(socket, boost::asio::buffer(request));

        // Read response (not implemented for brevity)
    } catch (const std::exception& e) {
        std::cerr << "Error sending POST request: " << e.what() << std::endl;
    }
}

// Define a function to process text files asynchronously
void processTextFilesAsync(const std::string& directory, const std::vector<std::string>& preProcessSteps) {
    boost::asio::io_context ioContext;

    // Get list of text files in the specified directory
    std::vector<std::future<std::vector<std::string>>> futures;
    for (const auto& file : getFilesInDirectory(directory)) {
        if (file.extension() == ".txt") {
            futures.push_back(std::async(std::launch::async, readFileAsync, file.path().string(), ioContext));
        }
    }

    // Process each text file asynchronously
    int successfulRequests = 0;
    int failedRequests = 0;
    for (auto& future : futures) {
        try {
            std::vector<std::string> lines = future.get();

            // Apply pre-processing steps to each line
            for (auto& line : lines) {
                for (const auto& step : preProcessSteps) {
                    line = applyPreprocessingStep(line, step);
                }

                // Send POST request asynchronously
                sendPostRequest("http://example.com/api", line);

                successfulRequests++;
            }
        } catch (const std::exception& e) {
            failedRequests++;
            std::cerr << "Error processing file: " << e.what() << std::endl;
        }
    }

    // Log performance metrics
    std::cout << "Successful requests: " << successfulRequests << std::endl;
    std::cout << "Failed requests: " << failedRequests << std::endl;
}

// Define a function to get list of files in a directory
std::vector<std::filesystem::path> getFilesInDirectory(const std::string& directory) {
    std::vector<std::filesystem::path> files;
    for (const auto& entry : std::filesystem::directory_iterator(directory)) {
        if (entry.is_regular_file()) {
            files.push_back(entry.path());
        }
    }
    return files;
}

