using System;
using System.Data;
using System.IO;
using System.Net.Sockets;
using System.Threading.Tasks;

public class NetworkDatabaseClient
{
    private TcpClient _client;
    private NetworkStream _stream;
    private BinaryWriter _writer;
    private BinaryReader _reader;

    public NetworkDatabaseClient(string server, int port)
    {
        _client = new TcpClient(server, port);
        _stream = _client.GetStream();
        _writer = new BinaryWriter(_stream);
        _reader = new BinaryReader(_stream);
    }

    public async Task<DataTable> ExecuteQueryAsync(byte[] queryData)
    {
        try
        {
            var compressedData = Compress(queryData);

            lock (_stream)
            {
                _writer.Write(compressedData.Length);
                _writer.Flush();
                await _stream.WriteAsync(compressedData, 0, compressedData.Length);
            }

            return ReadDataTableFromStream();
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private byte[] Compress(byte[] data)
    {
        using var memoryStream = new MemoryStream();
        using var gzipStream = new GZipStream(memoryStream, CompressionMode.Compress);
        gzipStream.Write(data, 0, data.Length);
        gzipStream.Close();
        return memoryStream.ToArray();
    }

    private DataTable ReadDataTableFromStream()
    {
        int rowsCount = _reader.ReadInt32();
        var dataTable = new DataTable();

        for (int i = 0; i < rowsCount; i++)
        {
            string columnName = _reader.ReadString();
            dataTable.Columns.Add(columnName);
        }

        for (int i = 0; i < rowsCount; i++)
        {
            var row = dataTable.NewRow();

            for (int j = 0; j < dataTable.Columns.Count; j++)
            {
                if (_reader.PeekChar() == -1)
                    break;

                object value = _reader.ReadObject();
                row[j] = value;
            }

            dataTable.Rows.Add(row);
        }

        return dataTable;
    }

    private void LogError(Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
        // Add logging to a file or external system here
    }
}
