import java.io.*;
import java.util.concurrent.*;

public class ShellCommandExecutor {
    private final ExecutorService executor;
    private final BlockingQueue<Future<String>> tasks;

    public ShellCommandExecutor(int poolSize) {
        this.executor = Executors.newFixedThreadPool(poolSize);
        this.tasks = new LinkedBlockingQueue<>();
    }

    public void executeCommand(String command, String directory) throws IOException, InterruptedException {
        ProcessBuilder processBuilder = new ProcessBuilder("sh", "-c", command)
                .directory(new File(directory))
                .redirectErrorStream(true);

        Process process = processBuilder.start();

        Future<String> future = executor.submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                StringBuilder output = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append("\n");
                }
                return output.toString();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        });

        tasks.add(future);

        // Wait for the process to complete
        int exitCode = process.waitFor();

        // Handle command completion and exception logging
        try {
            String result = future.get();
            System.out.println("Command executed successfully: " + result);
        } catch (ExecutionException e) {
            System.err.println("Error executing command: " + e.getCause().getMessage());
        }

        // Log the execution metadata
        logMetadata(command, exitCode);

        // Close resources
        process.destroy();
    }

    private void logMetadata(String command, int exitCode) {
        // Implement logging logic here
        System.out.println("Command: " + command);
        System.out.println("Exit Code: " + exitCode);
        // Add more metadata as needed
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    // Additional methods for retry strategy, timeout handling, and resource management can be added here
}
