class UserAccountManager {
    // Function to process user account requests
    public function handleUserAccountRequests() {
        // Get the request method
        $requestMethod = $_SERVER['REQUEST_METHOD'];

        // Handle different types of requests
        switch ($requestMethod) {
            case 'POST':
                return $this->processPostRequest();
            case 'GET':
                return $this->processGetRequest();
            case 'DELETE':
                return $this->processDeleteRequest();
            default:
                return json_encode(['error' => 'Invalid request method'], JSON_PRETTY_PRINT);
        }
    }

    // Process POST requests
    private function processPostRequest() {
        // Get the user data from POST request
        $userData = $_POST;

        // Validate the user data
        if (!$this->validateUserData($userData)) {
            return json_encode(['error' => 'Invalid user data'], JSON_PRETTY_PRINT);
        }

        // Process the account creation or update
        try {
            $this->externalAuthService->authenticateUser($userData);
            $token = $this->externalAuthService->generateToken($userData);

            if (isset($userData['id'])) {
                return json_encode(['message' => 'Account updated successfully', 'token' => $token], JSON_PRETTY_PRINT);
            } else {
                return json_encode(['message' => 'Account created successfully', 'token' => $token], JSON_PRETTY_PRINT);
            }
        } catch (Exception $e) {
            return json_encode(['error' => 'Failed to create or update account'], JSON_PRETTY_PRINT);
        }
