#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <boost/asio.hpp>

using boost::asio::ip::tcp;
using namespace std;

class SandeshClient {
public:
    string FindVmUuidFromMetadataIp(const string& ip) {
        // Simulated implementation
        return "vm-uuid-for-" + ip;
    }
};

class JobQueue {
private:
    queue<string> jobs;
    mutex mtx;
    condition_variable cv;
    bool running;

public:
    JobQueue() : running(true) {}

    void EnqueueJob(const string& job) {
        lock_guard<mutex> lock(mtx);
        jobs.push(job);
        cv.notify_one();
    }

    void StartProcessing(boost::asio::io_context& io_context, SandeshClient& client) {
        while (running) {
            unique_lock<mutex> lock(mtx);
            cv.wait(lock, [this] { return !jobs.empty() || !running; });

            if (!running && jobs.empty()) break;

            string job = jobs.front();
            jobs.pop();
            lock.unlock();

            processJob(io_context, client, job);
        }
    }

private:
    void processJob(boost::asio::io_context& io_context, SandeshClient& client, const string& job) {
        try {
            // Simulated job processing
            string vmUuid = client.FindVmUuidFromMetadataIp(job);
            cout << "Processed job: " << job << ", VM UUID: " << vmUuid << endl;
        } catch (const exception& e) {
            cerr << "Error processing job " << job << ": " << e.what() << endl;
        }
    }

public:
    void StopProcessing() {
        running = false;
        cv.notify_all();
    }
};

int main() {
    boost::asio::io_context io_context;
    SandeshClient client;
    JobQueue queue;

    thread worker([&io_context, &queue]() { queue.StartProcessing(io_context, client); });

    // Enqueue some jobs
    for (int i = 0; i < 10; ++i) {
        queue.EnqueueJob("metadata-ip-" + to_string(i));
    }

    // Simulate stopping the processing after a while
    this_thread::sleep_for(chrono::seconds(5));
    queue.StopProcessing();
    worker.join();

    return 0;
}
```

