using System;
using System.IO;
using System.Runtime.Serialization;
using System.Security.Cryptography;

[Serializable]
public class MyClass : IDeserializableObject
{
    public int MyProperty { get; set; }

    // Deserialization constructor
    protected MyClass(SerializationInfo info, StreamingContext context)
    {
        if (info == null)
            throw new ArgumentNullException("info");

        MyProperty = info.GetInt32("MyProperty");
    }

    void IDeserializableObject.GetObjectData(SerializationInfo info, StreamingContext context)
    {
        if (info == null)
            throw new ArgumentNullException("info");

        info.AddValue("MyProperty", MyProperty);
    }
}

public class SerializationHelper
{
    private static readonly byte[] Key = new byte[24];
    private static readonly byte[] IV = new byte[8];

    public static MyClass Deserialize(byte[] encryptedData)
    {
        try
        {
            TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider();
            ICryptoTransform decryptor = tripleDES.CreateDecryptor(Key, IV);
            using (MemoryStream ms = new MemoryStream(encryptedData))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    BinaryFormatter formatter = new BinaryFormatter();
                    try
                    {
                        return (MyClass)formatter.Deserialize(cs);
                    }
                    catch (SerializationException)
                    {
                        throw new RuntimeException("Failed to deserialize the object.");
                    }
                }
            }
        }
        catch (CryptographicException ex)
        {
            throw new RuntimeException("Decryption failed: " + ex.Message);
        }
        catch (IOException ex)
        {
            throw new RuntimeException("IO error during decryption: " + ex.Message);
        }
    }
}
