import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.*;

public class FileProcessor {

    public static void processFileChunksAsync(List<String> filePaths, int chunkSize, int parallelismLevel, 
                                            ChunkProcessor processFunction) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(parallelismLevel);
        CompletionService<Void> completionService = new ExecutorCompletionService<>(executor);

        for (String filePath : filePaths) {
            completionService.submit(() -> {
                try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        processFunction.process(line);
                    }
                } catch (IOException e) {
                    System.err.println("Failed to read file: " + filePath);
                }
                return null;
            });
        }

        for (int i = 0; i < filePaths.size(); i++) {
            try {
                completionService.take().get();
            } catch (InterruptedException | ExecutionException e) {
                System.err.println("Error processing chunk from a file");
                Thread.currentThread().interrupt();
            }
        }

        executor.shutdown();
    }

    @FunctionalInterface
    public interface ChunkProcessor {
        void process(String chunk);
    }

    // Example usage:
    public static void main(String[] args) throws InterruptedException {
        List<String> filePaths = List.of("file1.txt", "file2.txt");
        int chunkSize = 1024;
        int parallelismLevel = 4;

        FileProcessor.processFileChunksAsync(filePaths, chunkSize, parallelismLevel, 
            line -> System.out.println("Processing line: " + line));
    }
}
```

