public class ImageProcessor {

    public static void processImageBatchWithMetadata(List<String> imagePaths, String batchLabel, boolean enableParallelProcessing) {
        // Validate input files using regular expressions
        Pattern filenamePattern = Pattern.compile("^(?=.*[a-zA-Z0-9])[a-zA-Z0-9\\s]*$");
        for (String path : imagePaths) {
            File file = new File(path);
            if (!filenamePattern.matcher(file.getName()).matches()) {
                System.err.println("Invalid filename: " + file.getName());
                continue;
            }
            // Proceed with metadata extraction and API call
            try {
                extractMetadataAndCallAPI(file, batchLabel, enableParallelProcessing);
            } catch (Exception e) {
                handleException(e, file.getName());
            }
        }
    }

    private static void extractMetadataAndCallAPI(File imageFile, String batchLabel, boolean enableParallelProcessing) throws Exception {
        // Extract metadata logic here
        System.out.println("Extracting metadata for " + imageFile.getName());

        ExecutorService executor = enableParallelProcessing ? Executors.newFixedThreadPool(10) : null;
        if (enableParallelProcessing) {
            executor.submit(() -> callExternalAPI(imageFile, batchLabel));
        } else {
            callExternalAPI(imageFile, batchLabel);
        }

        if (executor != null) {
            executor.shutdown();
        }
    }

    private static void callExternalAPI(File imageFile, String batchLabel) throws Exception {
        // External API call logic here
        System.out.println("Calling external API for " + imageFile.getName());
        // Simulate network delay
        Thread.sleep(1000);
        System.out.println("API response received for " + imageFile.getName());
    }

    private static void handleException(Exception e, String fileName) {
        // Log error and handle exception logic here
        System.err.println("Error processing file: " + fileName);
        e.printStackTrace();
    }
}
