# weather_fetcher.py

import asyncio
import aiohttp
import json
from datetime import datetime
from tenacity import retry, stop_after_attempt, wait_exponential, before_log, after_log

# Load configuration from config.json
with open('config.json', 'r') as f:
    config = json.load(f)

API_LIST = config['apis']

async def fetch_weather(api_url, auth_token):
    headers = {
        'Authorization': f'Bearer {auth_token}',
        'User-Agent': 'WeatherApp'
    }
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(api_url, headers=headers) as response:
                if response.status == 200:
                    return await response.json()
                else:
                    raise Exception(f"Failed to fetch data: {response.status} - {await response.text()}")
    except asyncio.TimeoutError:
        raise Exception("Request timed out")
    except aiohttp.ClientConnectionError:
        raise Exception("Connection error")

@retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=2, min=1, max=30),
        before_log=None, after_log=None)
async def retry_fetch_weather(api_url, auth_token):
    try:
        return await fetch_weather(api_url, auth_token)
    except Exception as e:
        logging.error(f"Failed to fetch weather data from {api_url}: {e}")
        raise

async def main():
    tasks = []
    for api in API_LIST:
        task = asyncio.create_task(retry_fetch_weather(api['url'], api['token']))
        tasks.append(task)

    results = await asyncio.gather(*tasks, return_exceptions=True)
    weather_data = {}
    for i, result in enumerate(results):
        if isinstance(result, Exception):
            logging.error(f"Failed to fetch data from {API_LIST[i]['name']}: {result}")
        else:
            weather_data[API_LIST[i]['name']] = result
    print(json.dumps(weather_data, indent=4))

# Configure logging
import logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Run the script
if __name__ == '__main__':
    asyncio.run(main())
