# Python Flask Application for User Profiles

from flask import Flask, request, jsonify, abort
import re
import jwt
from functools import wraps
from rate_limiter import RateLimiter
from user_service_manager import UserServiceManager

app = Flask(__name__)
rate_limiter = RateLimiter(max_calls=100, period=60)
user_manager = UserServiceManager()

# JWT Authentication
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.args.get('token')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403
        try:
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=["HS256"])
        except:
            return jsonify({'message': 'Token is invalid!'}), 403
        return f(*args, **kwargs)
    return decorated

# Password Validation
def validate_password(password):
    if len(password) < 8:
        return False
    if not re.search("[a-z]", password):
        return False
    if not re.search("[A-Z]", password):
        return False
    if not re.search("[0-9]", password):
        return False
    if not re.search("[!@#$%^&*(),.?\":{}|<>]", password):
        return False
    return True

# Rate Limiting
@app.before_request
def before_request_func():
    if request.endpoint in ['update_user_profile']:
        if rate_limiter.is_allowed(request.remote_addr, 'rate_limit_key'):
            pass  # Continue with the request
        else:
            abort(429)  # Too Many Requests

# Update User Profile Endpoint
@app.route('/user/profile', methods=['PUT'])
@token_required
def update_user_profile():
    data = request.get_json()
    email = data['email']
    password = data['password']

    if not validate_email(email):
        return jsonify({'message': 'Invalid email format!'}), 400

    if not validate_password(password):
        return jsonify({'message': 'Password does not meet criteria!'}), 400

    user_manager.update_profile(email, password)
    return jsonify({'message': 'Profile updated successfully!'})

# Validate Email Function
def validate_email(email):
    regex = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    if re.fullmatch(regex, email):
        return True
    else:
        return False

if __name__ == '__main__':
    app.run(debug=True)
```

