# Python Flask Rate Limiter Module

class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.call_counts = {}

    def is_allowed(self, user_ip, key):
        if key not in self.call_counts:
            self.call_counts[key] = []

        current_time = time.time()
        call_times = [t for t in self.call_counts[key] if current_time - t < self.period]
        self.call_counts[key] = call_times

        if len(call_times) >= self.max_calls:
            return False
        else:
            self.call_counts[key].append(current_time)
            return True
