    private readonly Dictionary<string, byte[]> _keyCache = new Dictionary<string, byte[]>();
    private readonly Dictionary<string, byte[]> _ivCache = new Dictionary<string, byte[]>();

    public async Task<byte[]> DecryptWithAESCBC(string keyId, string ivId, byte[] ciphertext)
    {
        if (string.IsNullOrEmpty(keyId) || string.IsNullOrEmpty(ivId))
        {
            throw new ArgumentException("Key ID and IV ID cannot be null or empty.");
        }

        var key = await GetKeyAsync(keyId);
        var iv = await GetIVAsync(ivId);

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;
            aesAlg.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
            byte[] decryptedBytes = await Task.Run(() => decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length));

            return decryptedBytes;
        }
    }

    private async Task<byte[]> GetKeyAsync(string keyId)
    {
        if (!_keyCache.ContainsKey(keyId))
        {
            // Simulate fetching the key from a secure storage
            _keyCache[keyId] = await FetchKeyFromStorageAsync(keyId);
        }
        return _keyCache[keyId];
    }

    private async Task<byte[]> GetIVAsync(string ivId)
    {
        if (!_ivCache.ContainsKey(ivId))
        {
            // Simulate fetching the IV from a secure storage
            _ivCache[ivId] = await FetchIvFromStorageAsync(ivId);
        }
        return _ivCache[ivId];
    }

