            Service service = new Service();
            long startDelay = START_DELAY + randomInt(MIN_INTERVAL, MAX_INTERVAL);
            long stopDelay = STOP_DELAY + randomInt(MIN_INTERVAL, MAX_INTERVAL);
            executorService.scheduleAtFixedRate(service::start, startDelay, startDelay, TimeUnit.MILLISECONDS);
            executorService.scheduleAtFixedRate(service::stop, stopDelay, stopDelay, TimeUnit.MILLISECONDS);
        }

        // Simulate user experience scenarios
    }

    private static int randomInt(int min, int max) {
        return (int) (Math.random() * (max - min + 1)) + min;
    }
}

