def validate_jwt(token, secret_key):
    try:
        claims = jwt.decode(token, secret_key, algorithms=["HS256"], options={"require": ["exp", "nbf", "typ", "sub"]})

        # Validate 'typ' claim
        if claims["typ"] != 'JWT':
            logging.error("Invalid token type")
            return False

        # Validate 'exp' and 'nbf' claims
        current_time = datetime.utcnow()
        exp_time = datetime.utcfromtimestamp(claims["exp"])
        nbf_time = datetime.utcfromtimestamp(claims["nbf"])

        if current_time >= exp_time:
            logging.error("Token has expired")
            return False

        if current_time < nbf_time:
            logging.error("Token is not yet valid")
            return False

        # Additional validation logic can be added here

    except jwt.ExpiredSignatureError:
        logging.error("Token has expired")
    except jwt.InvalidTokenError:
        logging.error("Invalid token signature or format")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

    return True
