```cpp
#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <string>
#include <vector>
#include <unordered_map>
#include <optional>
#include <chrono>
#include <libcurl/curl.h>

// Define the structure for a HTTP GET request
struct HttpRequest {
    std::string url;
    std::vector<std::string> selectors;
};

// Define the type for a thread-safe map
using ThreadSafeMap = std::unordered_map<std::string, std::vector<std::string>>;

// Function to fetch HTML content from a URL using libcurl
std::optional<std::string> fetchHtml(const std::string& url) {
    CURL* curl;
    CURLcode res;
    std::string htmlContent;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* contents, size_t size, size_t nmemb, void* userp) -> size_t {
            ((std::string*)userp)->append((char*)contents, size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &htmlContent);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            std::cerr << "Failed to fetch HTML content: " << curl_easy_strerror(res) << std::endl;
            return {};
        }
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return htmlContent;
}

// Function to extract text based on CSS selectors
void extractText(const std::string& html, const std::vector<std::string>& selectors, ThreadSafeMap& resultMap) {
    // Implement the extraction logic here using a library like libxml2 or htmlcxx
    // For simplicity, let's assume the extraction is done and store in resultMap
}

// Function to process HTTP GET requests from a queue
void processRequestQueue(std::queue<HttpRequest>& requestQueue, ThreadSafeMap& resultMap, int maxRetries = 3, std::chrono::milliseconds throttleRate = std::chrono::seconds(1)) {
    std::mutex mapMutex;
    std::condition_variable cv;
    bool done = false;

    auto worker = [&requestQueue, &resultMap, &mapMutex, &cv, &done, maxRetries, throttleRate]() {
        while(true) {
            HttpRequest request;
            std::optional<std::string> htmlContent;

            { // Lock the queue
                std::unique_lock<std::mutex> lock(requestQueue.empty() ? cv : mapMutex);
                if(done && requestQueue.empty()) break;
                if(!requestQueue.empty()) {
                    request = requestQueue.front();
                    requestQueue.pop();
                } else {
                    cv.wait(lock, []{ return !requestQueue.empty() || done; });
                }
            }

            for(int attempt = 0; attempt <= maxRetries; ++attempt) {
                htmlContent = fetchHtml(request.url);
                if(htmlContent.has_value()) break;
                std::this_thread::sleep_for(throttleRate);
            }

            if(!htmlContent.has_value()) {
                std::cerr << "Failed to fetch HTML content after retries" << std::endl;
                continue;
            }

            { // Lock the map
                std::lock_guard<std::mutex> lock(mapMutex);
                extractText(*htmlContent, request.selectors, resultMap);
            }
        }
    };

    // Start multiple worker threads
    const int numThreads = 4; // Adjust based on available resources
    std::vector<std::thread> workers;
    for(int i = 0; i < numThreads; ++i) {
        workers.emplace_back(worker);
    }

    // Join the worker threads
    for(auto& thread : workers) {
        thread.join();
    }
}
```
This code provides a basic structure for processing HTTP GET requests using C++. It uses libcurl to fetch HTML content, and it assumes that an extraction function `extractText` is implemented elsewhere to handle CSS selectors. The `processRequestQueue` function manages a queue of requests, handles retries, throttles request rates, and ensures thread safety when updating the result map. Adjustments may be needed based on specific requirements and libraries used for HTML parsing and CSS selector matching.

