// Server.js - Main server file
const express = require('express');
const http = require('http');
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;

if (cluster.isMaster) {
  console.log(`Master ${process.pid} is running`);

  // Fork workers.
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`worker ${worker.process.pid} died`);
  });
} else {
  const app = express();
  const server = http.createServer(app);

  // IoT Device Communication
  const WebSocket = require('ws');
  const wss = new WebSocket.Server({ server });

  wss.on('connection', (ws, req) => {
    ws.on('message', async (message) => {
      try {
        const data = JSON.parse(message);
        await aggregateSensorData(data);
      } catch (error) {
        console.error('Error parsing or processing sensor data:', error);
      }
    });

    ws.on('close', () => {
      console.log('Client disconnected');
    });
  });

  // Sensor Data Aggregation
  const readings = [];
  function aggregateSensorData(reading) {
    return new Promise((resolve, reject) => {
      readings.push(reading);

      // Aggregate every 5 minutes
      setTimeout(() => {
        const aggregatedData = readings.reduce((acc, curr) => {
          if (!acc[curr.deviceId]) acc[curr.deviceId] = {};
          if (!acc[curr.deviceId][curr.timestamp]) acc[curr.deviceId][curr.timestamp] = [];

          acc[curr.deviceId][curr.timestamp].push(curr.value);
          return acc;
        }, {});

        saveToDatabase(aggregatedData).then(() => {
          readings = [];
          resolve();
        }).catch((error) => {
          reject(error);
        });
      }, 300000); // 5 minutes in milliseconds
    });
  }

  // Database Integration
  const MongoClient = require('mongodb').MongoClient;
  let db;

  async function saveToDatabase(data) {
    const uri = 'your_mongodb_connection_string';
    const client = new MongoClient(uri, { useNewUrlParser: true, useUnifiedTopology: true });

    try {
      await client.connect();
      db = client.db('sensorData');
      await db.collection('readings').insertMany(Object.values(data));
    } catch (error) {
      console.error('Error saving data to MongoDB:', error);
      throw error;
    } finally {
      await client.close();
    }
  }

  // Error Handling and Logging
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    process.exit(1);
  });

  server.listen(3000, () => {
    console.log('Server is running on port 3000');
  });
}
