        self.api_key = api_key
        self.cache_expiration = cache_expiration
        self.cache = {}

    @patch('requests.get')
    def GetWeatherData(self, mock_get, city):
        if city in self.cache and (time.time() - self.cache[city]['timestamp']) < self.cache_expiration:
            return self.cache[city]['data']

        url = f"http://api.weatherapi.com/v1/current.json?key={self.api_key}&q={city}"
        response = mock_get(url)
        if response.status_code == 200:
            data = response.json()
            self.cache[city] = {'timestamp': time.time(), 'data': data}
            return data
        else:
            raise Exception(f"Failed to fetch weather data for {city}: {response.status_code}")

# Example usage
