        threads[i].index = i;
        pthread_create(&threads[i].thread_id, NULL, processFile, &threads[i]);
    }

    for (int i = 0; i < NUM_THREADS && i < argc - 1; ++i) {
        pthread_join(threads[i].thread_id, NULL);
    }

    for (int i = 0; i < argc - 1; ++i) {
        fclose(inputFiles[i]);
    }

