    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> IntegrateEndpointAsync(string url, string[] headers, int timeout, bool useCache = false)
    {
        // Validate URL
        if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
        {
            _logger.LogError("Invalid URL: {Url}", url);
            throw new ArgumentException("Invalid URL", nameof(url));
        }

        // Check if API is available with retry mechanism
        int maxRetries = 5;
        TimeSpan delay = TimeSpan.FromSeconds(1);

        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                _httpClient.Timeout = TimeSpan.FromMilliseconds(timeout);
                var requestMessage = new HttpRequestMessage(HttpMethod.Get, uri)
                {
                    Headers =
                    {
                        { "Accept", "application/json" }
                    }
                };

                foreach (var header in headers)
                {
                    var parts = header.Split(':');
                    if (parts.Length == 2)
                    {
                        requestMessage.Headers.Add(parts[0].Trim(), parts[1].Trim());
                    }
                }

                var response = await _httpClient.SendAsync(requestMessage);
