                _logger.LogError(ex, "Request failed on attempt {Attempt}", attempt + 1);

                if (attempt == maxRetries - 1)
                {
                    throw;
                }

                await Task.Delay(delay);
                delay = TimeSpan.FromSeconds(Math.Pow(2, attempt));
            }
        }

        return null;
    }

