#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the configuration structure
typedef struct {
    char* config_path;
} Config;

// Function to load semaphore initial value from configuration
int load_semaphore_value(Config *config, int *initial_value) {
    // Implement logic to read and parse initial_value from config_path
    // For demonstration, we'll assume a hardcoded value
    *initial_value = 5; // Example initial value
    return 0;
}

// Semaphore structure
typedef struct {
    sem_t* sem;
    Config config;
} SemaphoreWrapper;

// Function to create semaphore and load initial value from configuration
SemaphoreWrapper* create_semaphore(Config *config) {
    SemaphoreWrapper *sem_wrapper = (SemaphoreWrapper*)malloc(sizeof(SemaphoreWrapper));
    if (!sem_wrapper) {
        perror("Failed to allocate memory for SemaphoreWrapper");
        return NULL;
    }

    sem_wrapper->config = *config;

    // Load initial value from configuration
    int initial_value;
    int ret = load_semaphore_value(&config, &initial_value);
    if (ret != 0) {
        fprintf(stderr, "Error loading semaphore initial value\n");
        free(sem_wrapper);
        return NULL;
    }

    // Initialize semaphore
    sem_wrapper->sem = sem_open("/my_semaphore", O_CREAT, 0644, initial_value);
    if (sem_wrapper->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(sem_wrapper);
        return NULL;
    }

    return sem_wrapper;
}

// Function to safely close and delete a semaphore
void close_and_delete_semaphore(SemaphoreWrapper *sem_wrapper) {
    if (!sem_wrapper) {
        fprintf(stderr, "Invalid SemaphoreWrapper\n");
        return;
    }

    // Close the semaphore
    if (sem_close(sem_wrapper->sem) == -1) {
        perror("Failed to close semaphore");
    }

    // Unlink the semaphore for deletion
    if (sem_unlink("/my_semaphore") == -1) {
        perror("Failed to unlink semaphore");
    }

    free(sem_wrapper);
}

// Function to demonstrate thread-safe access using the semaphore
void* thread_routine(void *arg) {
    SemaphoreWrapper *sem_wrapper = (SemaphoreWrapper*)arg;
    if (!sem_wrapper) {
        fprintf(stderr, "Invalid SemaphoreWrapper\n");
        return NULL;
    }

    // Wait for the semaphore
    if (sem_wait(sem_wrapper->sem) == -1) {
        perror("Failed to wait on semaphore");
        return NULL;
    }

    printf("Thread acquired semaphore\n");

    // Simulate some work
    sleep(2);

    // Release the semaphore
    if (sem_post(sem_wrapper->sem) == -1) {
        perror("Failed to post semaphore");
    }

    printf("Thread released semaphore\n");

    return NULL;
}

int main() {
    Config config = {"/path/to/config"};

    SemaphoreWrapper *sem_wrapper = create_semaphore(&config);
    if (!sem_wrapper) {
        fprintf(stderr, "Failed to create semaphore\n");
        return 1;
    }

    pthread_t thread_ids[5];
    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&thread_ids[i], NULL, thread_routine, sem_wrapper) != 0) {
            perror("Failed to create thread");
            close_and_delete_semaphore(sem_wrapper);
            return 1;
        }
    }

    for (int i = 0; i < 5; ++i) {
        if (pthread_join(thread_ids[i], NULL) != 0) {
            perror("Failed to join thread");
        }
    }

    close_and_delete_semaphore(sem_wrapper);

    return 0;
}
```

This code provides a basic structure for creating, managing, and cleaning up a semaphore in C. It includes a demonstration of thread-safe access using the semaphore with multiple threads. The `load_semaphore_value` function is a placeholder for actual configuration management logic, which you need to implement based on your specific requirements.

Please note that this example assumes a Unix-like environment and uses POSIX semaphores (`sem_t`). For Windows, you would need to use a different type of semaphore or synchronization mechanism.

