#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} SharedArray;

void init_shared_array(SharedArray *array) {
    array->data = malloc(sizeof(int));
    array->size = 0;
    array->capacity = 1;
    pthread_mutex_init(&array->mutex, NULL);
}

void free_shared_array(SharedArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
}

void grow_shared_array(SharedArray *array) {
    size_t new_capacity = array->capacity * 2;
    int *new_data = realloc(array->data, sizeof(int) * new_capacity);
    if (new_data == NULL) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void add_to_shared_array(SharedArray *array, int value) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        grow_shared_array(array);
    }
    array->data[array->size++] = value;
    pthread_mutex_unlock(&array->mutex);
}

void *read_from_socket(void *arg) {
    SharedArray *shared_array = (SharedArray *)arg;
    int socket_fd = *(int *)malloc(sizeof(int));
    // Initialize and connect to the socket
    // ...

    char buffer[MAX_BUFFER_SIZE];
    ssize_t bytes_read;
    while ((bytes_read = recv(socket_fd, buffer, MAX_BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_read] = '\0';
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            int value = atoi(token);
            add_to_shared_array(shared_array, value);
            token = strtok(NULL, " ");
        }
    }

    if (bytes_read == -1) {
        perror("recv");
        // Handle socket error
    }

    free((int *)arg);  // Free the allocated memory for socket_fd
    return NULL;
}

void find_and_print_largest(SharedArray *array) {
    pthread_mutex_lock(&array->mutex);
    int largest = array->data[0];
    for (size_t i = 1; i < array->size; ++i) {
        if (array->data[i] > largest) {
            largest = array->data[i];
        }
    }
    printf("Largest integer: %d\n", largest);
    pthread_mutex_unlock(&array->mutex);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <num_sockets> <socket1_address> <socket1_port> ... <socketN_address> <socketN_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_sockets = atoi(argv[1]);
    if (num_sockets <= 0) {
        fprintf(stderr, "Invalid number of sockets\n");
        return EXIT_FAILURE;
    }

    SharedArray shared_array;
    init_shared_array(&shared_array);

    pthread_t threads[num_sockets];
    for (int i = 0; i < num_sockets; ++i) {
        int socket_fd = create_socket_and_connect(argv[2 + i * 2], atoi(argv[3 + i * 2]));
        if (socket_fd == -1) {
            perror("create_socket_and_connect");
            // Handle socket creation and connection error
        }

        pthread_create(&threads[i], NULL, read_from_socket, &shared_array);
    }

    for (int i = 0; i < num_sockets; ++i) {
        pthread_join(threads[i], NULL);
    }

    find_and_print_largest(&shared_array);

    free_shared_array(&shared_array);
    return EXIT_SUCCESS;
}
