// Function to encrypt data using AES-256-GCM
int aes_encrypt(const unsigned char *key, const unsigned char *iv, const unsigned char *plaintext, size_t plaintext_len,
                unsigned char *ciphertext, unsigned char *tag) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    size_t tag_len = 0;
    if (1 != EVP_EncryptFinal_ex(ctx, NULL, &tag_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    memcpy(tag, ciphertext + plaintext_len, tag_len);

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Function to decrypt data using AES-256-GCM
int aes_decrypt(const unsigned char *key, const unsigned char *iv, const unsigned char *ciphertext, size_t ciphertext_len,
                const unsigned char *tag, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_GCM_AddAuthTag(ctx, tag, GCM_TAG_LEN)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    size_t plaintext_len = 0;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptFinal_ex(ctx, NULL, &plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Example usage
int main() {
    unsigned char key[32], iv[16], tag[GCM_TAG_LEN];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[sizeof(plaintext) + GCM_TAG_LEN];

    // Derive key using PBKDF2
    const char *password = "my_password";
    unsigned char salt[16];
    RAND_bytes(salt, sizeof(salt));
    derive_key_pbkdf2(password, salt, sizeof(salt), key, sizeof(key));

    // Generate random IV
    RAND_bytes(iv, sizeof(iv));

    // Encrypt plaintext
    aes_encrypt(key, iv, plaintext, strlen((char *)plaintext), ciphertext, tag);

    // Decrypt ciphertext
    unsigned char decrypted_text[sizeof(plaintext)];
    aes_decrypt(key, iv, ciphertext, sizeof(ciphertext) - GCM_TAG_LEN, tag, decrypted_text);

    printf("Decrypted: %s\n", decrypted_text);

    return 0;
}
