from collections import OrderedDict
from threading import Lock

class DistributedCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()
        self.lock = Lock()
        self.monitoring_system = RemoteMonitoringSystem()

    def put(self, key, value, expire_time):
        with self.lock:
            if key in self.cache:
                self.cache.move_to_end(key)
            else:
                while len(self.cache) >= self.capacity:
                    self.evict_lru_entry()
            self.cache[key] = (value, time.time() + expire_time)

    def get(self, key):
        with self.lock:
            if key not in self.cache or self.cache[key][1] < time.time():
                self.monitoring_system.report_cache_miss()
                return None
            else:
                value, _ = self.cache[key]
                self.cache.move_to_end(key)
                self.monitoring_system.report_cache_hit()
                return value

    def evict_lru_entry(self):
        with self.lock:
            if self.cache:
                key, _ = self.cache.popitem(last=False)
                self.monitoring_system.log_eviction(key)

    def update_monitoring_config(self, new_config):
        try:
            self.monitoring_system.update_config(new_config)
        except Exception as e:
            print(f"Failed to update monitoring config: {e}")

