#include <stdio.h>
#include <stdlib.h>

/**
 * @brief Dynamically allocates memory for an integer array, reads integers from standard input until -999 is encountered.
 *        Prints the largest integer found in the array. Handles potential overflow and invalid inputs.
 *
 * @return int Returns 0 on success, non-zero on failure.
 */
int findLargestInteger() {
    const int endMarker = -999;
    int currentInput;
    size_t count = 0;
    size_t capacity = 10; // Initial capacity
    int *numbers = (int *)malloc(capacity * sizeof(int));

    if (!numbers) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    printf("Enter integers, enter -999 to end: ");
    while (1) {
        if (scanf("%d", &currentInput) != 1 || currentInput == endMarker) break;

        if (count >= capacity) {
            capacity *= 2; // Double the capacity
            int *newNumbers = (int *)realloc(numbers, capacity * sizeof(int));
            if (!newNumbers) {
                fprintf(stderr, "Memory reallocation failed.\n");
                free(numbers);
                return 1;
            }
            numbers = newNumbers;
        }

        numbers[count++] = currentInput;
    }

    if (count == 0) {
        printf("No integers entered.\n");
        free(numbers);
        return 0;
    }

    int largest = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("The largest integer is: %d\n", largest);
    free(numbers);
    return 0;
}

int main() {
    findLargestInteger();
    return 0;
}
```

This code snippet defines a function `findLargestInteger` that reads integers from standard input until `-999` is encountered. It dynamically allocates and resizes an array to store the integers, handling potential overflow by doubling the array size when needed. The function includes basic error handling for memory allocation failures and invalid inputs (non-integer values). After reading all valid integers, it prints the largest one found.

