class UserDAO {
    public function updateUserPassword($userId, $password) {
        // Update logic here
    }
}

function updateUserPassword($userId, $password) {
    global $lastCallTime;

    if (!checkCooldown()) {
        echo "Error: Cooldown in progress. Please try again later.";
        return;
    }

    $userDAO = new UserDAO();

    // Validate password strength
    if (!validatePasswordStrength($password)) {
        error_log("Error: Password does not meet strength requirements.");
        return;
    }

    // Update user's password
    $userDAO->updateUserPassword($userId, $password);

    // Print password strength status
    echo "Password updated successfully with strength: " . get_password_strength_status($password);
}

function validatePasswordStrength($password) {
    $hasUppercase = preg_match('/[A-Z]/', $password) > 0;
    $hasLowercase = preg_match('/[a-z]/', $password) > 0;
    $hasNumber = preg_match('/\d/', $password) > 0;
    $hasSpecialChar = preg_match('/[^A-Za-z\d]/', $password) > 0;

    return strlen($password) >= 8 && $hasUppercase && $hasLowercase && $hasNumber && $hasSpecialChar;
}

function get_password_strength_status($password) {
    if (preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z\d]).{8,}$/', $password)) {
        return "Strong";
    } else {
        return "Weak";
    }
}

// Cooldown mechanism
$lastCallTime = null;
function checkCooldown() {
    global $lastCallTime;
    if ($lastCallTime === null || time() - $lastCallTime >= 9) {
        $lastCallTime = time();
        return true;
    }
    return false;
}

// Usage example
if (checkCooldown()) {
    updateUserPassword(1, "NewP@ssw0rd");
}
