import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class CommandExecutor {
    private static final int MAX_CONCURRENT_PROCESSES = 5;
    private static final long TIMEOUT_MS = 60000; // 1 minute

    public static void main(String[] args) throws IOException, InterruptedException {
        String logDir = System.getProperty("log.dir", "./logs");
        int maxConcurrentProcesses = MAX_CONCURRENT_PROCESSES;
        Map<String, String> env = new HashMap<>(System.getenv());
        Path targetFile = Paths.get("/path/to/target/file.txt");

        // Validate and prepare log directory
        Files.createDirectories(logDir);

        // Delete file if it exists
        if (Files.exists(targetFile)) {
            Files.deleteIfExists(targetFile);
        }

        List<String[]> commands = Arrays.asList(
            new String[]{"command1", "arg1"},
            new String[]{"command2", "arg2"},
            new String[]{"command3", "arg3"}
        );

        ExecutorService executor = Executors.newFixedThreadPool(maxConcurrentProcesses);

        for (String[] command : commands) {
            Path outputLog = logDir.resolve(command[0] + ".out");
            Path errorLog = logDir.resolve(command[0] + ".err");

            executor.submit(() -> {
                try {
                    executeCommand(command, env, targetFile.toAbsolutePath().toString(), outputLog.toString(), errorLog.toString());
                } catch (IOException | InterruptedException e) {
                    e.printStackTrace();
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    }

    private static void executeCommand(String[] command, Map<String, String> env, String workingDir, String outputLog, String errorLog) throws IOException, InterruptedException {
        ProcessBuilder processBuilder = new ProcessBuilder(command)
            .environment(env)
            .directory(new File(workingDir))
            .redirectOutput(ProcessBuilder.RedirectToFile.of(outputLog))
            .redirectError(ProcessBuilder.RedirectToFile.of(errorLog));

        Process process = processBuilder.start();
        if (!process.waitFor(TIMEOUT_MS, TimeUnit.MILLISECONDS)) {
            process.destroyForcibly();
            throw new TimeoutException("Command execution timed out");
        }

        int exitCode = process.exitValue();
        if (exitCode != 0) {
            throw new IOException("Command exited with non-zero code: " + exitCode);
        }
    }
}
