int validate_password_and_salt(const char* password, const char* salt)
{
    if (strlen(password) < 8 || strlen(salt) < 16)
    {
        return -1;
    }
    for (int i = 0; i < strlen(password); i++)
    {
        if ((unsigned char)password[i] > 127)
        {
            log_warning("Non-ASCII character found in password. Please use ASCII characters only.");
        }
    }
    for (int i = 0; i < strlen(salt); i++)
    {
        if ((unsigned char)salt[i] > 127)
        {
            log_warning("Non-ASCII character found in salt. Please use ASCII characters only.");
        }
    }
    return 0;
}

int derive_key_with_pbkdf2(const char* password, const char* salt, int iterations, unsigned char* key)
{
    if (validate_password_and_salt(password, salt) != 0)
    {
        log_error("Invalid password or salt length");
        return -1;
    }
    if (!PKCS5_PBKDF2_HMAC_SHA256(password, strlen(password), (unsigned char*)salt, strlen(salt), iterations, 32, key))
    {
        log_error("Failed to derive key with PBKDF2");
        return -1;
    }
    return 0;
}

int init_aes_cipher_with_pbkdf2(const char* password, const char* salt, int iterations, unsigned char* iv, unsigned char* key)
{
    if (derive_key_with_pbkdf2(password, salt, iterations, key) != 0)
    {
        log_error("Failed to derive key");
        return -1;
    }
    if (!RAND_bytes(iv, AES_BLOCK_SIZE))
    {
        log_error("Failed to generate IV");
        return -1;
    }
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL)
    {
        log_error("Failed to create EVP_CIPHER_CTX");
        return -1;
    }
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
    {
        log_error("Failed to initialize AES cipher");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    // Set up the cipher for encryption
    EVP_CIPHER_CTX_set_key_length(ctx, 32);
    EVP_CIPHER_CTX_set_iv_length(ctx, AES_BLOCK_SIZE);
    // Proceed with encryption using ctx
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
