using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Hangfire;
using Hangfire.MemoryStorage;

[ApiController]
[Route("api/[controller]")]
public class UserProfileController : ControllerBase
{
    private readonly IUserProfileService _userProfileService;
    private readonly IEmailSender _emailSender;
    private static readonly object LockObject = new object();

    public UserProfileController(IUserProfileService userProfileService, IEmailSender emailSender)
    {
        _userProfileService = userProfileService;
        _emailSender = emailSender;
    }

    [HttpPut("{userId}")]
    public async Task<IActionResult> UpdateUserProfile(string userId, [FromBody] UserProfileDTO updatedProfile)
    {
        if (string.IsNullOrEmpty(userId) || !Guid.TryParse(userId, out _))
        {
            return BadRequest("Invalid user ID.");
        }

        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        try
        {
            var existingProfile = await _userProfileService.GetProfileAsync(userId);

            if (existingProfile == null)
            {
                return NotFound();
            }

            var updatedUserProfile = await _userProfileService.UpdateProfileAsync(existingProfile, updatedProfile);
            BackgroundJob.Enqueue(() => SendConfirmationEmail(updatedUserProfile));
            return Ok(updatedUserProfile);
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Failed to update user profile.");
            return StatusCode(503, "Service unavailable.");
        }
    }

    [AutomaticRetry(OnAttemptsExceeded = AttemptsExceededAction.Delete)]
    public async Task SendConfirmationEmail(UserProfileDTO userProfile)
    {
        lock (LockObject)
        {
            // Check if the email has already been sent for this update
            var hasSentEmail = await _userProfileService.HasSentEmailAsync(userProfile.UserId);
            if (!hasSentEmail)
            {
                try
                {
                    await _emailSender.SendConfirmationEmailAsync(userProfile.Email, userProfile.Name);
                    await _userProfileService.MarkEmailAsSentAsync(userProfile.UserId);
                }
                catch (Exception ex)
                {
                    Log.Error(ex, "Failed to send confirmation email.");
                }
            }
        }
    }
}
