public class ConfigurationLoader
{
    private XmlDocument _xmlDoc;
    private Dictionary<string, string> _configSettings;

    public void LoadConfiguration(string filePath)
    {
        _xmlDoc = new XmlDocument();
        try
        {
            _xmlDoc.Load(filePath);
            _configSettings = ParseConfigurations(_xmlDoc);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to load configuration: {ex.Message}");
            // Fallback mechanism or default values
            _configSettings = new Dictionary<string, string>();
        }
    }

    public void ReloadConfiguration(string filePath)
    {
        LoadConfiguration(filePath);
    }

    private Dictionary<string, string> ParseConfigurations(XmlDocument xmlDoc)
    {
        var configSettings = new Dictionary<string, string>();
        foreach (XmlNode node in xmlDoc.DocumentElement.ChildNodes)
        {
            if (node.NodeType == XmlNodeType.Element)
            {
                configSettings[node.Name] = node.InnerText;
            }
        }
        return configSettings;
    }

