public class DataBufferManager
{
    private List<byte[]> _bufferChunks;
    private Dictionary<int, byte[]> _cache;

    public DataBufferManager()
    {
        _bufferChunks = new List<byte[]>();
        _cache = new Dictionary<int, byte[]>();
    }

    public void AddChunk(byte[] chunk)
    {
        _bufferChunks.Add(chunk);
    }

    public byte[] CopyRange(int startOffset, int length)
    {
        if (_cache.ContainsKey(startOffset))
        {
            return _cache[startOffset];
        }

        var newBuffer = new byte[length];
        int bytesRead = 0;

        for (int i = 0; i < _bufferChunks.Count && bytesRead < length; i++)
        {
            int chunkStart = startOffset - bytesRead;
            int chunkEnd = Math.Min(startOffset + length - bytesRead, _bufferChunks[i].Length);
            Array.Copy(_bufferChunks[i], chunkStart, newBuffer, bytesRead, chunkEnd - chunkStart);
            bytesRead += chunkEnd - chunkStart;
        }

        if (bytesRead == length)
        {
            _cache[startOffset] = newBuffer;
        }

        return newBuffer;
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        ConfigurationLoader configLoader = new ConfigurationLoader();
        configLoader.LoadConfiguration("config.xml");

        DataBufferManager dataBufferManager = new DataBufferManager();
        // Populate dataBufferManager with chunks from the streaming service

        int tileSize = configLoader.GetTileSize();
        int worldWidth = configLoader.GetWorldWidth();
        int worldHeight = configLoader.GetWorldHeight();
        float cameraSpeed = configLoader.GetCameraSpeed();

        Console.WriteLine($"Tile Size: {tileSize}, World Width: {worldWidth}, World Height: {worldHeight}, Camera Speed: {cameraSpeed}");

        // Example usage of CopyRange
        byte[] dataChunk = dataBufferManager.CopyRange(1024, 512);
        // Process the data chunk as needed
    }
}
