// Worker thread class
class Worker {
private:
    std::queue<RandomNumberGenerator*> taskQueue;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    bool stop;

public:
    Worker() : stop(false) {}

    void start(std::function<void()> task) {
        std::thread([this, task]() {
            while (true) {
                RandomNumberGenerator* generator = nullptr;
                {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    notEmpty.wait(lock, [this] { return stop || !taskQueue.empty(); });
                    if (stop && taskQueue.empty()) {
                        break;
                    }
                    generator = taskQueue.front();
                    taskQueue.pop();
                }
                task();
                delete generator; // Clean up after execution
            }
        }).detach();
    }

    void enqueue(RandomNumberGenerator* generator) {
        std::unique_lock<std::mutex> lock(queueMutex);
        taskQueue.push(generator);
        notEmpty.notify_one();
    }

    void stopAll() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        notEmpty.notify_all();
    }
};

// DistributedRandomNumberGenerator service
class DistributedRandomNumberGenerator {
private:
    std::vector<Worker> workers;
    std::mutex workerMutex;

public:
    DistributedRandomNumberGenerator(int numThreads) : workers(numThreads) {
        for (auto& worker : workers) {
            worker.start([this]() {
                RandomNumberGenerator* generator = nullptr;
                while (true) {
                    {
                        std::unique_lock<std::mutex> lock(workerMutex);
                        notEmpty.wait(lock, [this] { return !workers.empty(); });
                        if (workers.empty()) {
                            break;
                        }
                        generator = workers.front();
                        workers.pop_front();
                    }
                    // Execute task
                }
            });
        }
    }

    void generateNumbers(int count, int range) {
        std::unique_lock<std::mutex> lock(workerMutex);
        // Distribute tasks to available workers
    }

    ~DistributedRandomNumberGenerator() {
        for (auto& worker : workers) {
            worker.stopAll();
        }
    }
};
