// Function to calculate MD5 checksum of a file
void calculate_md5(const char *file_path, unsigned char digest[MD5_DIGEST_LENGTH]) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return;

    MD5_CTX md5;
    MD5_Init(&md5);

    const size_t bufferSize = 1024 * 1024; // 1MB buffer
    unsigned char buffer[bufferSize];
    while (size_t bytesRead = fread(buffer, 1, bufferSize, file)) {
        MD5_Update(&md5, buffer, bytesRead);
    }
    fclose(file);

    MD5_Final(digest, &md5);
}

