        file_paths[i] = NULL;
    }

    // Read file paths from standard input
    int filePathCount = 0;
    while (filePathCount < maxFilePaths && scanf("%99s", file_paths[filePathCount]) == 1) {
        ++filePathCount;
    }

    // Process each file path
    for (int i = 0; i < filePathCount; ++i) {
        struct stat fileStat;
        if (stat(file_paths[i], &fileStat) != 0) {
            fprintf(stderr, "Error reading file path: %s\n", file_paths[i]);
            continue;
        }

        printf("File Path: %s\n", file_paths[i]);
        printf("File Size: %ld bytes\n", fileStat.st_size);
        printf("Last Modified: %s", ctime(&fileStat.st_mtime));

        unsigned char md5Digest[MD5_DIGEST_LENGTH];
        calculate_md5(file_paths[i], md5Digest);
        printf("MD5 Checksum: ");
        for (int j = 0; j < MD5_DIGEST_LENGTH; ++j) {
            printf("%02x", md5Digest[j]);
        }
        printf("\n");
    }

    // Free dynamically allocated memory
    for (size_t i = 0; i < filePathCount; ++i) {
        free(file_paths[i]);
    }

    // Parse JSON object for user profile
    const char *json = "{\"username\":\"john_doe\",\"email\":\"john@example.com\", \"age\":30}";
    if (!validate_user_profile(json)) {
        fprintf(stderr, "Invalid user profile\n");
        return 1;
    }

