#include <iostream>
#include <map>
#include <mutex>
#include <string>
#include <thread>

class NetworkSessionManager {
public:
    struct SessionData {
        std::string ip;
        int port;
        // Add more session data as needed
    };

private:
    std::map<std::string, SessionData> sessions;
    std::mutex sessionsMutex;

public:
    NetworkSessionManager() {}

    ~NetworkSessionManager() {
        for (const auto& session : sessions) {
            terminateSession(session.first);
        }
    }

    std::string establishSession(const std::string& ip, int port) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        static unsigned long id = 0;
        std::stringstream ss;
        ss << "ID" << ++id;
        sessions[ss.str()] = {ip, port};
        return ss.str();
    }

    bool updateSession(const std::string& sessionId, const SessionData& newData) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        if (sessions.find(sessionId) != sessions.end()) {
            sessions[sessionId] = newData;
            return true;
        }
        return false;
    }

    bool getSessionStatus(const std::string& sessionId, SessionData& outData) const {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        auto it = sessions.find(sessionId);
        if (it != sessions.end()) {
            outData = it->second;
            return true;
        }
        return false;
    }

    bool terminateSession(const std::string& sessionId) {
        std::lock_guard<std::mutex> lock(sessionsMutex);
        if (sessions.find(sessionId) != sessions.end()) {
            sessions.erase(sessionId);
            return true;
        }
        return false;
    }
};

int main() {
    NetworkSessionManager manager;

    // Establish a session
    std::string sessionId = manager.establishSession("192.168.1.1", 12345);

    // Update session data
    NetworkSessionManager::SessionData newData = {"192.168.1.1", 12346};
    if (manager.updateSession(sessionId, newData)) {
        std::cout << "Session updated successfully." << std::endl;
    } else {
        std::cout << "Failed to update session." << std::endl;
    }

    // Get session status
    NetworkSessionManager::SessionData sessionData;
    if (manager.getSessionStatus(sessionId, sessionData)) {
        std::cout << "Session IP: " << sessionData.ip << ", Port: " << sessionData.port << std::endl;
    } else {
        std::cout << "Failed to get session status." << std::endl;
    }

    // Terminate a session
    if (manager.terminateSession(sessionId)) {
        std::cout << "Session terminated successfully." << std::endl;
    } else {
        std::cout << "Failed to terminate session." << std::endl;
    }

    return 0;
}
