using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Microsoft.AspNet.Identity;

public class AccountValidator
{
    // Regex patterns for validation
    private static readonly string[] OldTestamentBooks = { "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy" };
    private static readonly string[] SecurityKeywords = { "password", "login", "data security", "encryption" };
    private static readonly string EmailPattern = @"^[^@\s]+@[^@\s]+\.[^@\s]+$";
    private static readonly string CommonWeakPasswords = @"^(123456|qwerty|password|admin|letmein)$";
    private static readonly string MaliciousEmailDomains = @"(example.com|test.net|fake.org)";

    // Validate book names
    public bool IsValidBookName(string text)
    {
        var words = Regex.Split(text.ToLower(), @"\W+");
        foreach (var word in words)
        {
            if (OldTestamentBooks.Contains(word))
                return true;
        }
        return false;
    }

    // Validate security keywords
    public bool IsValidSecurityKeyword(string text)
    {
        var words = Regex.Split(text.ToLower(), @"\W+");
        foreach (var word in words)
        {
            if (SecurityKeywords.Contains(word))
                return true;
        }
        return false;
    }

    // Validate email formats
    public bool IsValidEmail(string text)
    {
        var match = Regex.Match(text, EmailPattern);
        if (!match.Success)
            return false;

        var domain = match.Groups[2].Value.ToLower();
        return !Regex.IsMatch(domain, MaliciousEmailDomains);
    }

    // Validate password policies
    public IdentityResult ValidatePassword(string password)
    {
        var errors = new List<string>();

        if (password.Length < 8)
            errors.Add("The Password must be at least 8 characters long.");

        if (!password.Any(char.IsUpper))
            errors.Add("The Password must contain at least one uppercase letter.");

        if (!password.Any(char.IsLower))
            errors.Add("The Password must contain at least one lowercase letter.");

        if (!password.Any(char.IsDigit))
            errors.Add("The Password must contain at least one digit.");

        if (Regex.IsMatch(password, CommonWeakPasswords))
            errors.Add("The Password is too common and weak.");

        return new IdentityResult(errors);
    }

    // User lockout with external logging
    public async Task LockUserAsync(UserManager<IdentityUser> userManager, string userId)
    {
        try
        {
            await userManager.LockoutUserAsync(userId, TimeSpan.FromMinutes(15));
            await LogLockoutEventAsync(userManager, userId);
        }
        catch (Exception ex)
        {
            // Handle error logging and rethrow if necessary
            throw;
        }
    }

    private async Task LogLockoutEventAsync(UserManager<IdentityUser> userManager, string userId)
    {
        try
        {
            await ExternalLoggingSystem.LogAsync("Lockout", $"User {userId} has been locked out.");
        }
        catch (Exception ex)
        {
            // Handle error logging and rethrow if necessary
            throw;
        }
    }

    // Caching mechanism for validation checks
    public static class ValidationCache
    {
        private static readonly ConcurrentDictionary<string, bool> Cache = new ConcurrentDictionary<string, bool>();

        public static bool TryGetValue(string key, out bool result)
        {
            return Cache.TryGetValue(key, out result);
        }

        public static void AddOrUpdate(string key, bool value)
        {
            Cache.AddOrUpdate(key, value, (k, v) => value);
        }
    }
}
