            string cacheKey = $"items_{userId}_{updatedCount}";
            var cachedItemDetails = await FetchAndCacheItemDetails(updatedCount, cacheKey);

            return Ok(new { UpdatedCount = updatedCount, CachedItemDetails = cachedItemDetails });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing item update request.");
            return StatusCode(500, "Internal server error");
        }
    }

    private async Task<object> FetchAndCacheItemDetails(int itemCount, string cacheKey)
    {
        if (!_cachingService.IsCached(cacheKey))
        {
            var apiClient = new HttpClient();
            // Replace with actual API endpoint and parameters
            var response = await apiClient.GetAsync($"https://api.example.com/items?count={itemCount}");
            var itemDetails = await response.Content.ReadAsAsync<object>();
            _cachingService.Cache(cacheKey, itemDetails);
