use std::env;
use std::fs::{self, DirBuilder};
use std::io::{self, Write};
use std::path::PathBuf;

fn initialize_logging(log_directory: &str, log_file_name: &str) -> io::Result<()> {
    // Check if LOG_DIR environment variable is already set
    if env::var("LOG_DIR").is_err() {
        // Create a new directory at the user-specified location
        let mut dir_builder = DirBuilder::new();
        dir_builder.recursive(true);
        dir_builder.create(log_directory)?;

        // Set the LOG_DIR environment variable to the path of the created directory
        env::set_var("LOG_DIR", log_directory);

        // Ensure that the log directory has write permissions for the current process
        fs::set_permissions(&PathBuf::from(log_directory), fs::Permissions::from_mode(0o755))?;
    }

    // Create a log file within the log directory named according to the provided log file name
    let log_file_path = PathBuf::from(log_directory).join(log_file_name);
    let mut log_file = fs::OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true) // Overwrite existing file if it exists
        .open(&log_file_path)?;

    // Configure a logging system to use this log file, supporting both debug and release modes
    println!("Logging configured for file: {}", log_file_path.display());

    Ok(())
}

fn cleanup_logging() -> io::Result<()> {
    // Clean up resources when the logging configuration is no longer needed
    println!("Cleaning up logging resources...");
    Ok(())
}

fn main() {
    let log_directory = "/path/to/log/directory";
    let log_file_name = "app.log";

    match initialize_logging(log_directory, log_file_name) {
        Ok(_) => println!("Logging initialized successfully."),
        Err(e) => eprintln!("Failed to initialize logging: {}", e),
    }

    // Perform other operations...

    if let Err(e) = cleanup_logging() {
        eprintln!("Failed to clean up logging resources: {}", e);
    }
}
