using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class CSVProcessor
{
    private string inputDirectory;
    private string outputFilePath;
    private char delimiter;
    private int skipRowsThreshold;

    public CSVProcessor(string inputDirectory, string outputFilePath, char delimiter, int skipRowsThreshold)
    {
        this.inputDirectory = inputDirectory;
        this.outputFilePath = outputFilePath;
        this.delimiter = delimiter;
        this.skipRowsThreshold = skipRowsThreshold;
    }

    public void ProcessFiles()
    {
        try
        {
            var files = Directory.GetFiles(inputDirectory, "*.csv");
            using (var writer = new StreamWriter(outputFilePath))
            {
                foreach (var file in files)
                {
                    ProcessFile(file, writer);
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing files: {ex.Message}");
        }
    }

    private void ProcessFile(string filePath, StreamWriter writer)
    {
        try
        {
            using (var reader = new StreamReader(filePath))
            {
                var lines = reader.ReadToEnd().Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries);
                for (int i = 0; i < lines.Length; i++)
                {
                    if (i >= skipRowsThreshold)
                    {
                        var fields = lines[i].Split(delimiter, StringSplitOptions.RemoveEmptyEntries);
                        if (fields.Length >= 2 && double.TryParse(fields[^1], out _) && double.TryParse(fields[^2], out _))
                        {
                            var average = (double.Parse(fields[^1]) + double.Parse(fields[^2])) / 2;
                            writer.WriteLine($"{string.Join(delimiter, fields)}{delimiter}{average}");
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
        }
    }

    public static string GetMD5Hash(string input)
    {
        using (var md5 = MD5.Create())
        {
            var inputBytes = Encoding.ASCII.GetBytes(input);
            var hashBytes = md5.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }
}
