const fs = require('fs');
const path = require('path');
const readline = require('readline');

class ModuleLoader {
  constructor(modulesPath) {
    this.modulesPath = modulesPath;
    this.moduleFiles = [];
    this.moduleFunctions = {};
  }

  async loadModules() {
    try {
      const files = await fs.promises.readdir(this.modulesPath);
      this.moduleFiles = files.filter(file => path.extname(file) === '.js');
      for (const file of this.moduleFiles) {
        const filePath = path.join(this.modulesPath, file);
        const module = require(filePath);
        if (typeof module.init !== 'function') {
          console.error(`Module ${file} does not export an init function.`);
          continue;
        }
        this.moduleFunctions[file] = module;
      }
    } catch (error) {
      console.error('Error loading modules:', error.message);
    }
  }

  async executeModules() {
    for (const file of this.moduleFiles) {
      try {
        await this.moduleFunctions[file].init();
      } catch (error) {
        console.error(`Failed to initialize module ${file}:`, error.message);
      }
    }
  }

  async updateConfiguration() {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    console.log('Enter new configuration for the modules (or type "exit" to cancel):');
    let config = {};
    while (true) {
      const key = await rl.question('Enter a configuration key or type "done" to finish:\n');
      if (key === 'done') break;
      const value = await rl.question(`Enter value for ${key}:\n`);
      config[key] = value;
    }
    rl.close();

    // Update the modules with new configurations
    for (const file of this.moduleFiles) {
      try {
        Object.assign(this.moduleFunctions[file], config);
        await this.moduleFunctions[file].updateConfig();
        console.log(`Updated configuration for module ${file}`);
      } catch (error) {
        console.error(`Failed to update configuration for module ${file}:`, error.message);
      }
    }
  }

  async run() {
    await this.loadModules();
    if (this.moduleFiles.length > 0) {
      console.log('Executing modules...');
      await this.executeModules();
      console.log('All modules executed successfully.');
    } else {
      console.log('No valid modules found in the specified directory.');
    }
    await this.updateConfiguration();
  }
}

const loader = new ModuleLoader('./modules');
loader.run();
```

