public class BufferManager
{
    public static byte[] CopyBufferRange(List<byte[]> dataChunks, int start, int end)
    {
        if (start < 0 || end >= dataChunks.Sum(chunk => chunk.Length))
            throw new IndexOutOfRangeException("Start or end position exceeds available data length.");

        using (MemoryStream ms = new MemoryStream())
        {
            foreach (byte[] chunk in dataChunks)
            {
                if (end <= chunk.Length)
                {
                    ms.Write(chunk, 0, end);
                    break;
                }
                else
                {
                    ms.Write(chunk, 0, chunk.Length);
                    start -= chunk.Length;
                    end -= chunk.Length;
                }
            }

            return ms.ToArray();
        }
    }
}
