from bs4 import BeautifulSoup

def find_elements_with_attribute(soup, attr_name, attr_value, depth_limit=5):
    if not isinstance(soup, (BeautifulSoup, Tag)):
        raise TypeError("First argument must be a BeautifulSoup or Tag object")

    if not isinstance(attr_name, str) or not isinstance(attr_value, str):
        raise ValueError("Attribute name and value must be strings")

    if not isinstance(depth_limit, int) or depth_limit < 0:
        raise ValueError("Depth limit must be a non-negative integer")

    result = []

    def recursive_search(element, current_depth):
        if current_depth > depth_limit:
            return
        if attr_name in element.attrs and element[attr_name] == attr_value:
            result.append(element)
        for child in element.children:
            recursive_search(child, current_depth + 1)

    recursive_search(soup, 0)
    return result
