import os
import ssl
import time
from threading import Lock

class OAuthCertificateManager:
    def __init__(self):
        self.cache = {}
        self.lock = Lock()

    def fetch_certificate(self, oauth_request):
        with self.lock:
            if 'cert_id' in oauth_request and oauth_request['cert_id'] in self.cache:
                return self.cache[oauth_request['cert_id']]

            private_key_path = os.path.join('path/to/private_keys', f"{oauth_request['cert_id']}.key")
            certificate_path = os.path.join('path/to/certificates', f"{oauth_request['cert_id']}.pem")

            try:
                with open(private_key_path, 'r') as key_file, open(certificate_path, 'r') as cert_file:
                    private_key = key_file.read()
                    certificate = cert_file.read()

                combined_certificate = ssl.PEM_cert_to_DER_cert(certificate) + ssl.PEM_key_to_DER_private_key(private_key)
                self.cache[oauth_request['cert_id']] = (certificate, time.time() + 3600)  # Cache for an hour
                return certificate
            except FileNotFoundError:
                print(f"Certificate not found for cert_id: {oauth_request['cert_id']}")
            except Exception as e:
                print(f"Error fetching certificate: {e}")

    def get_tls_ssl_certificate(self, oauth_request):
        while True:
            certificate = self.fetch_certificate(oauth_request)
            if certificate is None:
                time.sleep(1)  # Wait before retrying
                continue

            try:
                ssl_context = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
                ssl_context.load_cert_chain(certificate, privatekey=certificate)
                return ssl_context
            except Exception as e:
                print(f"Error creating SSL context: {e}")
                time.sleep(1)  # Wait before retrying

# Example usage
manager = OAuthCertificateManager()
oauth_request = {'cert_id': 'example_cert'}
ssl_context = manager.get_tls_ssl_certificate(oauth_request)
