        // Validate password strength
        if (!$this->validatePasswordStrength($newPassword)) {
            return json_encode(['error' => 'Password does not meet the security criteria']);
        }

        // Check if password is on the common list
        if ($this->isCommonPassword($newPassword)) {
            return json_encode(['error' => 'Password cannot be a commonly used password']);
        }

        // Check for simple patterns
        if ($this->hasSimplePattern($newPassword)) {
            return json_encode(['error' => 'Password contains a simple pattern']);
        }

        // Update the password in the database
        if ($this->dao->updatePassword($userId, $newPassword)) {
            return json_encode(['success' => true]);
        } else {
            return json_encode(['error' => 'Failed to update password']);
        }
    }

    private function validatePasswordStrength($password) {
        $length = strlen($password);
        if ($length < 8 || $length > 64) {
            return false;
        }

        return preg_match('/[A-Z]/', $password) && preg_match('/[a-z]/', $password) &&
               preg_match('/\d/', $password) && preg_match('/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/', $password);
