struct BookCounts {
    books: HashMap<String, usize>,
}

impl BookCounts {
    // Constructor to initialize the HashMap
    fn new() -> Self {
        BookCounts { 
            books: HashMap::new(), 
        }
    }

    // Method to update the count of a book
    fn update(&mut self, book_name: &str) {
        *self.books.entry(book_name.to_string()).or_insert(0) += 1;
    }
}

