public class DynamicNetworkSimulator
{
    private ConcurrentDictionary<int, Node> _nodes = new ConcurrentDictionary<int, Node>();
    private ConcurrentBag<Connection> _connections = new ConcurrentBag<Connection>();

    public void AddNode(int nodeId, double x, double y)
    {
        if (!_nodes.TryAdd(nodeId, new Node { Id = nodeId, X = x, Y = y }))
            throw new InvalidOperationException($"Node with ID {nodeId} already exists.");
    }

    public bool RemoveNode(int nodeId)
    {
        Node node;
        return _nodes.TryRemove(nodeId, out node) && _connections.RemoveAll(c => c.From == nodeId || c.To == nodeId);
    }

    public void AddConnection(int fromNodeId, int toNodeId, double weight)
    {
        if (_nodes.ContainsKey(fromNodeId) && _nodes.ContainsKey(toNodeId))
            _connections.Add(new Connection { From = fromNodeId, To = toNodeId, Weight = weight });
        else
            throw new InvalidOperationException($"One or both nodes for connection between {fromNodeId} and {toNodeId} do not exist.");
    }

    public bool RemoveConnection(int fromNodeId, int toNodeId)
    {
        return _connections.TryRemove(_connections.FirstOrDefault(c => c.From == fromNodeId && c.To == toNodeId), out _);
    }

    public double CalculateAveragePathLength()
    {
        // Placeholder for algorithm
        return 0.0;
    }

    public double CalculateClusteringCoefficient()
    {
        // Placeholder for algorithm
        return 0.0;
    }

    public Dictionary<int, int> CalculateDegreeDistribution()
    {
        var distribution = new Dictionary<int, int>();
        foreach (var node in _nodes.Values)
        {
            if (!distribution.ContainsKey(_connections.Count(c => c.From == node.Id || c.To == node.Id)))
                distribution[_connections.Count(c => c.From == node.Id || c.To == node.Id)] = 0;
            distribution[_connections.Count(c => c.From == node.Id || c.To == node.Id)]++;
        }
        return distribution;
    }

    public override string ToString()
    {
        return $"Nodes: {_nodes.Count}, Connections: {_connections.Count}";
    }
}

public class Node
{
    public int Id { get; set; }
    public double X { get; set; }
    public double Y { get; set; }
}

public class Connection
{
    public int From { get; set; }
    public int To { get; set; }
    public double Weight { get; set; }
