```cpp
#include <iostream>
#include <mutex>
#include <list>
#include <string>
#include <thread>
#include <condition_variable>
#include <queue>
#include <stdexcept>

class StringManager {
private:
    std::list<std::string> forwardList;
    std::mutex listMutex;
    std::condition_variable dataReady;
    bool mergeInProgress;

public:
    StringManager() : mergeInProgress(false) {}

    void insertAfterTarget(const std::string& target, const std::string& newString) {
        std::lock_guard<std::mutex> lock(listMutex);
        for (auto it = forwardList.begin(); it != forwardList.end(); ++it) {
            if (*it == target) {
                forwardList.insert(it, newString);
                return;
            }
        }
        forwardList.push_back(newString);
    }

    void mergeDataSource(const std::queue<std::string>& dataSource) {
        if (mergeInProgress) {
            throw std::runtime_error("Merge already in progress.");
        }
        mergeInProgress = true;

        std::lock_guard<std::mutex> lock(listMutex);
        for (const auto& str : dataSource) {
            forwardList.push_back(str);
        }

        mergeInProgress = false;
        dataReady.notify_all();
    }

    void waitForData() {
        std::unique_lock<std::mutex> lock(listMutex);
        while (!mergeInProgress && forwardList.empty()) {
            dataReady.wait(lock);
        }
    }
};

int main() {
    StringManager manager;

    // Example usage
    manager.insertAfterTarget("world", "C++");
    manager.mergeDataSource({"Hello", "world"});

    return 0;
}
