public class FileMetadataProcessor {
    private static final Logger logger = LoggerFactory.getLogger(FileMetadataProcessor.class);
    private ConcurrentHashMap<String, FileMetadata> metadataCache = new ConcurrentHashMap<>();

    public List<FileMetadata> ProcessFileMetadata(String filePath) {
        List<FileMetadata> fileMetadatas = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                FileMetadata metadata = parseJsonLine(line);
                if (metadata != null) {
                    fileMetadatas.add(metadata);
                }
            }
        } catch (IOException e) {
            logger.error("Error processing file: {}", filePath, e);
        }
        return fileMetadatas;
    }

    private FileMetadata parseJsonLine(String line) {
        // Implement JSON parsing logic here
        return new FileMetadata();
    }

    public void InitializeMetadataCache(List<String> filePaths) {
        for (String filePath : filePaths) {
            try {
                List<FileMetadata> metadatas = ProcessFileMetadata(filePath);
                mergeIntoCache(metadatas);
            } catch (Exception e) {
                logger.error("Error initializing metadata cache", e);
            }
        }
    }

    private void mergeIntoCache(List<FileMetadata> metadatas) {
        for (FileMetadata metadata : metadatas) {
            String key = metadata.getFilename();
            FileMetadata existingMetadata = metadataCache.putIfAbsent(key, metadata);
            if (existingMetadata != null) {
                // Handle conflict resolution logic here
            }
        }
    }

    // Other methods and utilities
}
