import java.io.*;
import java.util.*;
import com.fasterxml.jackson.databind.ObjectMapper;

public class UserQueueProcessor {

    private ConcurrentLinkedQueue<User> userQueue = new ConcurrentLinkedQueue<>();
    private final ObjectMapper objectMapper = new ObjectMapper();

    public void processUser(User newUser, String interest) {
        for (User existingUser : userQueue) {
            if (existingUser.getInterests().contains(interest)) {
                existingUser.getInterests().addAll(newUser.getInterests());
                return;
            }
        }
        newUser.setInterests(Collections.singletonList(interest));
        userQueue.add(newUser);
    }

    public void serializeUsers(String filePath) throws IOException {
        objectMapper.writeValue(new File(filePath), userQueue);
    }

    @SuppressWarnings("unchecked")
    public void deserializeUsers(String filePath) {
        try {
            List<User> users = (List<User>) objectMapper.readValue(new File(filePath), List.class);
            for (User user : users) {
                userQueue.add(user);
            }
        } catch (IOException e) {
            System.err.println("Failed to deserialize users from file: " + e.getMessage());
        }
    }

    public void updateUserInterests(String interest, String newInterest) {
        Iterator<User> iterator = userQueue.iterator();
        while (iterator.hasNext()) {
            User user = iterator.next();
            if (user.getInterests().contains(interest)) {
                user.getInterests().add(newInterest);
                if (user.getInterests().size() > 10) { // Example condition for cleanup
                    user.setInterests(Collections.singletonList(newInterest));
                }
                break;
            }
        }
    }

    public static class User {
        private String name;
        private int age;
        private List<String> interests;

        // Getters and setters

        public List<String> getInterests() {
            return interests;
        }

        public void setInterests(List<String> interests) {
            this.interests = interests;
        }
    }
}
