using boost::asio::ip::tcp;
using boost::property_tree::ptree;

void handle_get_request(const std::string& url, boost::asio::io_context& io_context) {
    tcp::resolver resolver(io_context);
    auto endpoints = resolver.resolve(url);

    tcp::socket socket(io_context);
    boost::asio::connect(socket, endpoints);

    // Perform GET request
    std::string request = "GET " + url + " HTTP/1.1\r\nHost: " + url + "\r\n\r\n";
    boost::asio::write(socket, boost::asio::buffer(request));

    // Read response
    boost::asio::streambuf buffer;
    boost::asio::read_until(socket, buffer, "\r\n");

    std::istream response_stream(&buffer);
    std::string status_line;
    std::getline(response_stream, status_line);

    // Parse the status line to check if request was successful
    int status_code = 0;
    std::istringstream iss(status_line);
    iss >> std::ws >> status_code;

    if (status_code == 200) {
        std::cout << "GET request successful." << std::endl;
    } else {
        std::cout << "GET request failed with status code: " << status_code << std::endl;
    }
}

