#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000
#define BACKOFF_BASE 200
#define BACKOFF_FACTOR 2

typedef struct {
    int transaction_id;
    double weighted_sum;
    time_t timestamp;
} Transaction;

Transaction transactions[MAX_TRANSACTIONS];
int transaction_count = 0;
time_t current_time;

void process_transaction(Transaction* new_transaction) {
    if (new_transaction->timestamp > current_time) {
        return; // Ignore future transactions
    }

    int index = -1;
    for (int i = 0; i < transaction_count; i++) {
        if (transactions[i].transaction_id == new_transaction->transaction_id) {
            index = i;
            break;
        }
    }

    if (index != -1) {
        transactions[index] = *new_transaction;
    } else {
        if (transaction_count >= MAX_TRANSACTIONS) {
            return; // Drop oldest transaction
        }
        transactions[transaction_count++] = *new_transaction;
    }

    // Perform real-time analysis and updates of transaction metrics
}

void filter_and_process_transactions() {
    current_time = time(NULL);
    for (int i = 0; i < transaction_count; i++) {
        if (current_time - transactions[i].timestamp > 60) {
            // Remove expired transactions
            memmove(&transactions[i], &transactions[i + 1], sizeof(Transaction) * (transaction_count - i - 1));
            transaction_count--;
            i--;
        }
    }

    int recent_transaction_count = 0;
    for (int i = 0; i < transaction_count; i++) {
        if (current_time - transactions[i].timestamp <= 3) {
            recent_transaction_count++;
        }
    }

    double total_weighted_sum = 0;
    for (int i = 0; i < transaction_count; i++) {
        total_weighted_sum += transactions[i].weighted_sum;
    }

    if (recent_transaction_count > 500 || total_weighted_sum <= 1000) {
        return; // Filter out based on criteria
    }

    // Update counters and statistics in real-time

    int max_index = -1;
    double max_weighted_sum = -1;
    for (int i = 0; i < transaction_count; i++) {
        if (transactions[i].weighted_sum > max_weighted_sum) {
            max_index = i;
            max_weighted_sum = transactions[i].weighted_sum;
        }
    }

    if (max_index != -1) {
        printf("Transaction ID with highest weighted sum: %d\n", transactions[max_index].transaction_id);
        printf("Weighted Sum: %.2f\n", transactions[max_index].weighted_sum);
        printf("Timestamp: %s", ctime(&transactions[max_index].timestamp));
    } else {
        printf("No valid transaction found.\n");
    }
}

int main() {
    // Simulate processing of high-frequency financial transactions
    for (int i = 0; i < 1000; i++) {
        Transaction new_transaction;
        new_transaction.transaction_id = rand();
        new_transaction.weighted_sum = (double)rand() / RAND_MAX * 2000;
        new_transaction.timestamp = time(NULL) - (rand() % 60);
        process_transaction(&new_transaction);
    }

    filter_and_process_transactions();

    return 0;
}
