public class DynamicGraphPopulator
{
    private readonly IGraphDatabaseApi _graphDatabaseApi;
    private readonly IRandomValueGenerator _randomValueGenerator;

    public DynamicGraphPopulator(IGraphDatabaseApi graphDatabaseApi, IRandomValueGenerator randomValueGenerator)
    {
        _graphDatabaseApi = graphDatabaseApi ?? throw new ArgumentNullException(nameof(graphDatabaseApi));
        _randomValueGenerator = randomValueGenerator ?? throw new ArgumentNullException(nameof(randomValueGenerator));
    }

    public async Task AddVerticesAndEdgesAsync(int minVertices, int maxVertices, int minEdges, int maxEdges)
    {
        if (minVertices > maxVertices || minEdges > maxEdges)
            throw new ArgumentException("Invalid range settings.");

        var vertexCount = _randomValueGenerator.GenerateRandomNumber(minVertices, maxVertices);
        var edgeCount = _randomValueGenerator.GenerateRandomNumber(minEdges, maxEdges);

        for (int i = 0; i < vertexCount; i++)
        {
            var vertexProperties = GenerateRandomVertexProperties();
            await _graphDatabaseApi.AddVertexAsync(vertexProperties);
        }

        for (int i = 0; i < edgeCount; i++)
        {
            var sourceVertexId = _randomValueGenerator.GenerateRandomNumber(1, vertexCount);
            var destinationVertexId = _randomValueGenerator.GenerateRandomNumber(1, vertexCount);
            var edgeProperties = GenerateRandomEdgeProperties();
            await _graphDatabaseApi.AddEdgeAsync(sourceVertexId, destinationVertexId, edgeProperties);
        }
    }

    private Dictionary<string, object> GenerateRandomVertexProperties()
    {
        return new Dictionary<string, object>
        {
            { "id", _randomValueGenerator.GenerateRandomNumber(1, int.MaxValue) },
            { "name", $"Vertex{_randomValueGenerator.GenerateRandomString(5)}" },
            { "value", _randomValueGenerator.GenerateRandomDouble(0.0, 1.0) }
        };
    }

    private Dictionary<string, object> GenerateRandomEdgeProperties()
    {
        return new Dictionary<string, object>
        {
            { "id", _randomValueGenerator.GenerateRandomNumber(1, int.MaxValue) },
            { "weight", _randomValueGenerator.GenerateRandomDouble(0.0, 1.0) }
        };
    }
}

public interface IGraphDatabaseApi
{
    Task AddVertexAsync(Dictionary<string, object> vertexProperties);
    Task AddEdgeAsync(int sourceVertexId, int destinationVertexId, Dictionary<string, object> edgeProperties);
}

public interface IRandomValueGenerator
{
    int GenerateRandomNumber(int min, int max);
    double GenerateRandomDouble(double min, double max);
    string GenerateRandomString(int length);
}
