// Define the NetworkClient interface
class NetworkClient {
public:
    virtual bool FindVmUuidFromMetadataIp(const std::string& ip, int port) = 0;
};

// Mock implementation of NetworkClient for testing
class MockNetworkClient : public NetworkClient {
private:
    std::mutex lock_;
    std::condition_variable cv_;
    bool isMockResponseAvailable_ = false;
    bool mockResponseValue_;

public:
    void SetMockResponse(bool value) {
        std::unique_lock<std::mutex> lock(lock_);
        mockResponseValue_ = value;
        isMockResponseAvailable_ = true;
        cv_.notify_one();
    }

    bool FindVmUuidFromMetadataIp(const std::string& ip, int port) override {
        std::unique_lock<std::mutex> lock(lock_);
        cv_.wait(lock, [this]{ return isMockResponseAvailable_; });
        isMockResponseAvailable_ = false;
        return mockResponseValue_;
    }
};

// Function to process a file and send GET requests
void ProcessFile(const std::string& filename, NetworkClient* client) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return;
    }

    std::mutex outputMutex;
    int successfulRequests = 0;
    int proxySessions = 0;
    int internalErrors = 0;
    int externalErrors = 0;

    for (std::string line; std::getline(file, line);) {
        // Parse the line and compute average of last three fields
        std::istringstream iss(line);
        std::vector<int> values;
        for (int value; iss >> value;) {
            values.push_back(value);
        }
        if (values.size() < 3) {
            continue;
        }
        double average = (values[values.size() - 1] + values[values.size() - 2] + values[values.size() - 3]) / 3.0;

        // Send GET request using the client
        try {
            boost::asio::io_context io_context;
            boost::asio::ip::tcp::resolver resolver(io_context);
            boost::asio::ip::tcp::socket socket(io_context);
            boost::asio::connect(socket, resolver.resolve("example.com", "80"));

            // Send GET request
            std::string request = "GET /?average=" + std::to_string(average) + " HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n";
            boost::asio::write(socket, boost::asio::buffer(request));

            // Handle response (simplified for demonstration)
            char reply[512];
            size_t bytes_received = boost::asio::read_until(socket, boost::asio::dynamic_buffer(reply), "\r\n");
            if (bytes_received > 0) {
                std::cout << "Response: " << std::string(reply, bytes_received) << std::endl;
                successfulRequests++;
            }
        } catch (const std::exception& e) {
            if (e.what() == "network timeout" || e.what() == "connection failure") {
                externalErrors++;
            } else {
                internalErrors++;
            }
        }

        // Simulate proxy session creation
        proxySessions++;
    }

    // Output results
    std::lock_guard<std::mutex> lock(outputMutex);
    std::cout << "Successful requests: " << successfulRequests << std::endl;
    std::cout << "Proxy sessions: " << proxySessions << std::endl;
    std::cout << "Internal errors: " << internalErrors << std::endl;
    std::cout << "External errors: " << externalErrors << std::endl;
}

int main() {
    MockNetworkClient mockClient;
    mockClient.SetMockResponse(true);

    std::vector<std::thread> threads;
    for (const auto& file : {"file1.txt", "file2.txt"}) { // Specify the directory and files
        threads.emplace_back(ProcessFile, file, &mockClient);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
