use reqwest::{
    ClientBuilder,
    Response,
    Error,
    RequestBuilder,
};
use std::time::{Duration, Instant};

async fn create_request_builder(url: &str, disable_ssl_verification: bool) -> Result<RequestBuilder, Error> {
    let client = if disable_ssl_verification {
        ClientBuilder::new()
            .danger_accept_invalid_certs(true)
            .build()?
    } else {
        ClientBuilder::new().build()?
    };

    Ok(client.get(url))
}

async fn make_request_with_retries(
    url: &str,
    disable_ssl_verification: bool,
) -> Result<Response, Error> {
    const MAX_RETRIES: u32 = 3;
    const BACKOFF_BASE: Duration = Duration::from_secs(1);

    for attempt in 0..=MAX_RETRIES {
        let start_time = Instant::now();
        match make_request(url, disable_ssl_verification).await {
            Ok(response) => {
                log_request_response(attempt, url, start_time.elapsed(), &response);
                return Ok(response);
            }
            Err(err) => log_error(attempt, url, err),
        }

        if attempt < MAX_RETRIES {
            tokio::time::sleep(BACKOFF_BASE * (2u32.pow(attempt))).await;
        }
    }

    Err(Error::new(
        reqwest::ErrorKind::InvalidData,
        "Failed to make request after multiple attempts",
    ))
}

async fn make_request(url: &str, disable_ssl_verification: bool) -> Result<Response, Error> {
    let start_time = Instant::now();
    match create_request_builder(url, disable_ssl_verification).await?.timeout(Duration::from_secs(30)).send().await {
        Ok(response) => {
            log_request_response(0, url, start_time.elapsed(), &response);
            Ok(response)
        }
        Err(err) => Err(log_error(0, url, err)),
    }
}

fn log_request_response(attempt: u32, url: &str, duration: Duration, response: &Response) {
    println!("Request {}: {} took {}ms", attempt, url, duration.as_millis());
    // Log response details
}

fn log_error(attempt: u32, url: &str, err: Error) -> Error {
    println!("Request {}: {} failed after {} attempts with error: {}", attempt, url, attempt + 1, err);
    err
}
