    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** create_and_populate_list(int n, int* size) {
    // Error handling for large values of N
    if (n > MAX_N) {
        fprintf(stderr, "Error: N is too large. Maximum allowed value is %d\n", MAX_N);
        return NULL;
    }

    *size = n;

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            perror("Memory allocation failed");
            // Free already allocated memory before returning
            for (int j = 0; j < i; j++) {
                free(list[j]);
            }
            free(list);
            return NULL;
        }

        // Populate RX_UE_INFORMATION_TAG and RNTI with validation logic
        list[i]->RX_UE_INFORMATION_TAG = generate_valid_rx_ue_information_tag();
        list[i]->RNTI = get_rnti_from_database(/* criteria */);

        // Generate random CRCFLAG for CRC_INDICATION_REL8_TAG
        list[i]->CRC_INDICATION_REL8_TAG = rand() % 2;  // Binary flag: 0 or 1
    }

    return list;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    for (int i = 0; i < size; i++) {
        free(list[i]);
    }
    free(list);
}
