```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_SIZE 1024
#define NUM_THREADS 10

typedef struct {
    int device_id;
    double packet_size;
    time_t timestamp;
} LogEntry;

typedef struct {
    pthread_mutex_t lock;
    FILE *output_files[NUM_THREADS];
    int last_device_id;
} OutputManager;

OutputManager output_manager;

void initialize_output_manager() {
    pthread_mutex_init(&output_manager.lock, NULL);
    for (int i = 0; i < NUM_THREADS; i++) {
        char filename[50];
        snprintf(filename, sizeof(filename), "output_%d.txt", i);
        output_manager.output_files[i] = fopen(filename, "w");
    }
}

void write_log_entry(LogEntry *entry) {
    pthread_mutex_lock(&output_manager.lock);
    int device_id = entry->device_id;
    while (device_id >= NUM_THREADS) {
        device_id -= NUM_THREADS;
    }
    fprintf(output_manager.output_files[device_id], "%d,%f,%ld\n", entry->device_id, entry->packet_size, entry->timestamp);
    fflush(output_manager.output_files[device_id]);
    output_manager.last_device_id = (output_manager.last_device_id + 1) % NUM_THREADS;
    pthread_mutex_unlock(&output_manager.lock);
}

void *process_log_line(void *arg) {
    char log_line[MAX_LOG_SIZE];
    while (fgets(log_line, sizeof(log_line), stdin)) {
        LogEntry entry;
        sscanf(log_line, "%d,%lf,%ld", &entry.device_id, &entry.packet_size, &entry.timestamp);
        write_log_entry(&entry);
    }
    pthread_exit(NULL);
}

int main() {
    initialize_output_manager();
    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_log_line, NULL);
    }
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
    for (int i = 0; i < NUM_THREADS; i++) {
        fclose(output_manager.output_files[i]);
    }
    pthread_mutex_destroy(&output_manager.lock);
    return 0;
}
