        encrypted_data = {}
        for key, value in data.items():
            if key in ['api_key', 'user_credentials']:
                salt = os.urandom(16)
                hashed_value = hashlib.new(self.hashing_algorithm, (value + salt).encode()).hexdigest()
                encrypted_data[key] = {'hash': hashed_value, 'salt': salt}
                logging.info(f"Encrypted {key} with algorithm: {self.hashing_algorithm}, salt: {salt.hex()}")
            else:
                encrypted_data[key] = value
        return encrypted_data

    def generate_graph_schema(self, num_nodes, num_edges, node_properties, edge_properties):
