#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <openssl/evp.h> // OpenSSL library

// Define a task structure for worker threads
struct Task {
    int numRandoms;
    int rangeStart;
    int rangeEnd;
};

// Worker thread function to handle random number generation tasks
void worker(std::queue<Task>& taskQueue, std::mutex& queueMutex, std::condition_variable& condition, bool& stop) {
    while (true) {
        std::unique_lock<std::mutex> lock(queueMutex);
        condition.wait(lock, [&]{ return !taskQueue.empty() || stop; });

        if (stop && taskQueue.empty()) {
            break;
        }

        Task task = taskQueue.front();
        taskQueue.pop();

        lock.unlock();

        // Perform random number generation using OpenSSL
        EVP_RAND *randctx = EVP_RAND_new();
        unsigned char *buffer = new unsigned char[task.numRandoms];
        if (EVP_RAND_generate(randctx, buffer, task.numRandoms) > 0) {
            std::cout << "Generated random numbers: ";
            for (int i = 0; i < task.numRandoms; ++i) {
                std::cout << static_cast<int>(buffer[i]) % (task.rangeEnd - task.rangeStart + 1) + task.rangeStart << " ";
            }
            std::cout << std::endl;
        } else {
            std::cerr << "Failed to generate random numbers" << std::endl;
        }

        EVP_RAND_free(randctx);
        delete[] buffer;
    }
}

int main() {
    const int numWorkerThreads = 4;
    std::queue<Task> taskQueue;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop = false;

    // Create worker threads
    std::vector<std::thread> workers(numWorkerThreads);
    for (int i = 0; i < numWorkerThreads; ++i) {
        workers[i] = std::thread(worker, std::ref(taskQueue), std::ref(queueMutex), std::ref(condition), std::ref(stop));
    }

    // Example task
    Task exampleTask = {10, 1, 100};
    {
        std::lock_guard<std::mutex> lock(queueMutex);
        taskQueue.push(exampleTask);
    }
    condition.notify_all();

    // Wait for all worker threads to finish
    for (auto& thread : workers) {
        thread.join();
    }

    stop = true;
    condition.notify_all();

    return 0;
}
