# Python code for generating a certificate in PEM format

import requests
import json
from urllib.parse import urlparse
import time
import os
import hashlib
from functools import lru_cache

CA_PROVIDERS = {
    'provider1': {
        'url': 'https://api.provider1.com/certificate',
        'key': os.getenv('PROVIDER1_KEY')
    },
    # Add more CA providers as needed
}

@lru_cache(maxsize=128)
def get_certificate(oauth_params):
    provider = oauth_params['provider']
    if provider not in CA_PROVIDERS:
        raise ValueError(f"Unsupported CA provider: {provider}")

    url = CA_PROVIDERS[provider]['url']
    headers = {'Authorization': f'Bearer {CA_PROVIDERS[provider]["key"]}'}
    response = requests.post(url, json=oauth_params, headers=headers)

    if response.status_code != 200:
        raise Exception(f"Failed to fetch certificate from {provider}: {response.text}")

    return response.json()

def generate_pem(oauth_params):
    try:
        cert_data = get_certificate(oauth_params)
        pem_file_path = f"{oauth_params['filename']}.pem"

        with open(pem_file_path, 'w') as file:
            file.write(cert_data['certificate'])
            file.write('\n')
            file.write(f"-----END CERTIFICATE-----\n")
            file.write(cert_data['private_key'])

        return pem_file_path
    except Exception as e:
        print(f"Error generating PEM: {e}")
        raise

# Unit tests for the generate_pem function

def test_generate_pem():
    oauth_params = {
        'provider': 'provider1',
        'filename': 'test_certificate',
        'param1': 'value1',
        # Add more parameters as needed
    }

    try:
        pem_path = generate_pem(oauth_params)
        assert os.path.exists(pem_path)
        with open(pem_path, 'r') as file:
            content = file.read()
            assert "-----BEGIN CERTIFICATE-----" in content
            assert "-----END CERTIFICATE-----" in content
            assert "-----BEGIN PRIVATE KEY-----" in content
        os.remove(pem_path)
    except Exception as e:
        print(f"Test failed: {e}")
        raise

test_generate_pem()
