// Define cryptographic primitives structure
typedef struct {
    char name[32];
    void (*init)();
    void (*cleanup)();
} CryptoPrimitive;

// Global list of added cryptographic primitives
CryptoPrimitive *crypto_primitives = NULL;
int num_primitives = 0;

// Mutex for thread-safe access to the primitive list
pthread_mutex_t crypto_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a cryptographic primitive
void add_crypto_primitive(const char *name, void (*init)(), void (*cleanup)()) {
    pthread_mutex_lock(&crypto_lock);
    // Check if primitive is already added
    for (int i = 0; i < num_primitives; i++) {
        if (strcmp(crypto_primitives[i].name, name) == 0) {
            fprintf(stderr, "Primitive %s already added\n", name);
            pthread_mutex_unlock(&crypto_lock);
            return;
        }
    }
    // Add primitive to the list
    crypto_primitives = realloc(crypto_primitives, (num_primitives + 1) * sizeof(CryptoPrimitive));
    if (!crypto_primitives) {
        perror("Failed to allocate memory for primitives");
        pthread_mutex_unlock(&crypto_lock);
        return;
    }
    strcpy(crypto_primitives[num_primitives].name, name);
    crypto_primitives[num_primitives].init = init;
    crypto_primitives[num_primitives].cleanup = cleanup;
    num_primitives++;
    pthread_mutex_unlock(&crypto_lock);
}

