```java
import java.util.*;
import java.util.concurrent.*;

// Define the Service interface with basic operations
interface Service {
    void start();
    void stop();
    void restart();
}

// Implement a concrete service class that implements the Service interface
class BackgroundService implements Service {
    private String serviceName;
    private ExecutorService executor;

    public BackgroundService(String serviceName) {
        this.serviceName = serviceName;
        this.executor = Executors.newSingleThreadExecutor();
    }

    @Override
    public void start() {
        executor.execute(() -> {
            System.out.println("Starting " + serviceName);
            // Service logic goes here
        });
    }

    @Override
    public void stop() {
        executor.shutdownNow();
        System.out.println("Stopping " + serviceName);
    }

    @Override
    public void restart() {
        stop();
        start();
    }
}

// Define the MessagingSystem interface for various messaging systems
interface MessagingSystem {
    void sendMessage(String message);
    String receiveMessage();
}

// Implement a concrete messaging system class using Kafka
class KafkaMessaging implements MessagingSystem {
    private String topic;
    private Producer<String, String> producer;
    private Consumer<String, String> consumer;

    public KafkaMessaging(String topic) {
        this.topic = topic;
        // Initialize Kafka producer and consumer
    }

    @Override
    public void sendMessage(String message) {
        producer.send(new ProducerRecord<>(topic, message));
    }

    @Override
    public String receiveMessage() {
        ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
        for (ConsumerRecord<String, String> record : records) {
            return record.value();
        }
        return null;
    }
}

// Define the ServiceOrchestrationFramework class to manage services and messaging
class ServiceOrchestrationFramework {
    private List<Service> services = new ArrayList<>();
    private Map<MessagingSystem, List<String>> messageQueues = new HashMap<>();

    public void addService(Service service) {
        services.add(service);
    }

    public void removeService(Service service) {
        services.remove(service);
        service.stop();
    }

    public void startAllServices() {
        for (Service service : services) {
            service.start();
        }
    }

    public void stopAllServices() {
        for (Service service : services) {
            service.stop();
        }
    }

    public void addMessagingSystem(MessagingSystem ms, String queueName) {
        messageQueues.put(ms, new ArrayList<>());
        // Initialize the messaging system and subscribe to the queue
    }

    public void sendMessageToAll(String message) {
        for (List<String> queue : messageQueues.values()) {
            for (String queueName : queue) {
                MessagingSystem ms = getMessageSystemByName(queueName);
                if (ms != null) {
                    ms.sendMessage(message);
                }
            }
        }
    }

    private MessagingSystem getMessageSystemByName(String name) {
        for (Map.Entry<MessagingSystem, List<String>> entry : messageQueues.entrySet()) {
            if (entry.getValue().contains(name)) {
                return entry.getKey();
            }
        }
        return null;
    }
}

// Example usage
public class Main {
    public static void main(String[] args) {
        ServiceOrchestrationFramework framework = new ServiceOrchestrationFramework();

        // Add services
        framework.addService(new BackgroundService("Service1"));
        framework.addService(new BackgroundService("Service2"));

        // Start all services
        framework.startAllServices();

        // Send a message to all message queues
        framework.sendMessageToAll("Hello, Services!");

        // Stop all services
        framework.stopAllServices();
    }
}
