const dbName = 'sensorDataDB';
const numWorkers = os.cpus().length;

// Database connection
let db;

async function connectToDatabase() {
  const client = await MongoDB.connect(dbUrl, { useNewUrlParser: true, useUnifiedTopology: true });
  db = client.db(dbName);
}

// WebSocket server for IoT device communication
const wss = new WebSocket.Server({ port: 8080 });

