  console.log('Device connected');

  ws.on('message', async (message) => {
    const reading = JSON.parse(message);
    await storeSensorReading(reading);
  });
});

// MQTT client for IoT device communication
const mqttClient = mqtt.connect('mqtt://broker.hivemq.com');

mqttClient.on('connect', () => {
  console.log('MQTT connected');
  mqttClient.subscribe('sensor/data');
});

mqttClient.on('message', async (topic, message) => {
  const reading = JSON.parse(message.toString());
  await storeSensorReading(reading);
});

// Function to store sensor readings in the database
async function storeSensorReading(reading) {
  try {
    const collection = db.collection('readings');
    await collection.insertOne(reading);
  } catch (error) {
    console.error('Error storing reading:', error);
  }
}

