const newTestamentBooks = ['Matthew', 'Mark', 'Luke', 'John', 'Acts', 'Romans', '1 Corinthians', '2 Corinthians', 'Galatians', 'Ephesians'];

function extractBookNames(text) {
  const bookRegex = new RegExp(`(${oldTestamentBooks.join('|')}|${newTestamentBooks.join('|')})`, 'gi');
  let matches = text.match(bookRegex);

  if (!matches) return {};

  const bookCounts = {};
  matches.forEach(match => {
    match = match.toLowerCase();
    if (bookCounts[match]) {
      bookCounts[match]++;
    } else {
      bookCounts[match] = 1;
    }
  });

  return bookCounts;
}

// Example usage
