#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    char* str;
} Record;

// Define the dynamic array structure
typedef struct {
    Record** records;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} DynamicArray;

// Function to initialize the dynamic array
void init_dynamic_array(DynamicArray* arr) {
    arr->records = (Record**)malloc(sizeof(Record*) * 10);
    arr->size = 0;
    arr->capacity = 10;
    pthread_mutex_init(&arr->mutex, NULL);
}

// Function to add a record to the dynamic array
void add_record(DynamicArray* arr, char* str) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        arr->capacity *= 2;
        arr->records = (Record**)realloc(arr->records, sizeof(Record*) * arr->capacity);
    }
    arr->records[arr->size] = (Record*)malloc(sizeof(Record));
    arr->records[arr->size]->str = strdup(str);
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

// Function to free the dynamic array
void free_dynamic_array(DynamicArray* arr) {
    for (int i = 0; i < arr->size; i++) {
        free(arr->records[i]->str);
        free(arr->records[i]);
    }
    free(arr->records);
    pthread_mutex_destroy(&arr->mutex);
}

// Function to simulate deserialization from a binary file
void* deserialize_from_binary(void* arg) {
    DynamicArray* arr = (DynamicArray*)arg;
    // Simulate reading from a binary file and adding records
    for (int i = 0; i < 100; i++) {
        char buffer[256];
        sprintf(buffer, "Record-%d", i);
        add_record(arr, buffer);
    }
    return NULL;
}

int main() {
    DynamicArray arr;
    init_dynamic_array(&arr);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, deserialize_from_binary, &arr);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free_dynamic_array(&arr);

    return 0;
}
