# Queue-based system for managing PDF files
class PDFQueue:
    def __init__(self):
        self.queue = queue.Queue()

    def add_task(self, pdf_path):
        self.queue.put(pdf_path)

    def get_next_task(self):
        return self.queue.get()

    def has_tasks_remaining(self):
        return not self.queue.empty()

# Function to process PDF files using multiple threads
def process_pdf_queue(queue):
    while queue.has_tasks_remaining():
        pdf_path = queue.get_next_task()
        output_dir = os.path.join(os.getcwd(), 'output', os.path.basename(pdf_path).replace('.pdf', ''))
        try:
            pdf_to_images(pdf_path, output_dir)
        except Exception as e:
            logging.error(f"Failed to process {pdf_path}: {e}")
        queue.task_done()

# Main function to start processing
def main(pdf_paths):
    queue = PDFQueue()
    for pdf_path in pdf_paths:
        queue.add_task(pdf_path)

    threads = []
    num_threads = 5  # Adjust based on system capabilities and resource constraints
    for _ in range(num_threads):
        thread = threading.Thread(target=process_pdf_queue, args=(queue,))
        thread.start()
        threads.append(thread)

    queue.join()
    for thread in threads:
        thread.join()

# Example usage
if __name__ == "__main__":
    pdf_paths = ['document1.pdf', 'document2.pdf']  # List of PDF files to process
    main(pdf_paths)
```

