// Define a service in AngularJS to handle dialog field refresh logic
angular.module('dialogService', []).service('DialogRefreshService', ['$http', '$q', '$timeout', 'cacheFactory', function($http, $q, $timeout, cacheFactory) {
    // Create a cache for resource ID and their last fetch time
    var cache = cacheFactory('resourceCache', { capacity: 100 });
    var MINUTE_IN_MS = 5 * 60 * 1000; // 5 minutes in milliseconds

    this.refreshFields = function(resourceId, fieldsToRefresh, url) {
        // Check if the resource ID is cached and not expired
        if (cache.get(resourceId) && Date.now() - cache.get(resourceId).timestamp < MINUTE_IN_MS) {
            console.log('Using cached data for resourceId:', resourceId);
            return this.processCachedData(fieldsToRefresh, cache.get(resourceId).data);
        }

        // Make an AJAX request to fetch the data
        var deferred = $q.defer();
        $http.get(url)
            .then(function(response) {
                if (response.status === 200) {
                    // Cache the fetched data with current timestamp
                    cache.put(resourceId, { timestamp: Date.now(), data: response.data });
                    console.log('Data fetched and cached for resourceId:', resourceId);
                    deferred.resolve(this.processCachedData(fieldsToRefresh, response.data));
                } else {
                    deferred.reject(new Error('Failed to fetch data'));
                }
            })
            .catch(function(error) {
                deferred.reject(new Error('Network error or server timeout'));
            });

        return deferred.promise;
    };

    this.processCachedData = function(fieldsToRefresh, data) {
        var promises = [];
        angular.forEach(document.getElementsByName('*'), function(field) {
            if (fieldsToRefresh.includes(field.name)) {
                promises.push($q.when(this.sendMessageToParent(field.name, data[field.name])));
            }
        }, this);

        return $q.all(promises);
    };

    this.sendMessageToParent = function(fieldName, fieldValue) {
        var deferred = $q.defer();
        window.parent.postMessage({ fieldName: fieldName, value: fieldValue }, '*');
        console.log('Message sent to parent:', { fieldName: fieldName, value: fieldValue });
        return deferred.promise;
    };
}]);

// Controller that uses the DialogRefreshService
angular.module('app', ['dialogService']).controller('MainController', ['$scope', 'DialogRefreshService', function($scope, DialogRefreshService) {
    $scope.refreshFields = function() {
        var resourceId = '123';
        var fieldsToRefresh = ['name', 'age', 'email'];
        var url = 'https://api.example.com/data';

        DialogRefreshService.refreshFields(resourceId, fieldsToRefresh, url)
            .then(function() {
                console.log('Fields refreshed successfully');
            })
            .catch(function(error) {
                console.error('Error refreshing fields:', error);
            });
    };
}]);
