using System;
using System.Data;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using log4net;

public class DynamicSecureDataHandler
{
    private static readonly ILog _log = LogManager.GetLogger(typeof(DynamicSecureDataHandler));
    private readonly string _connectionString;

    public DynamicSecureDataHandler(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<string> DecryptMessageAsync(string base64EncryptedMessage, byte[] key, byte[] iv)
    {
        try
        {
            using (var des = new TripleDESCryptoServiceProvider { Mode = CipherMode.CBC })
            {
                des.Key = key;
                des.IV = iv;

                var encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);
                using (var msDecrypt = new MemoryStream(encryptedBytes))
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, des.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (var srDecrypt = new StreamReader(csDecrypt))
                        {
                            return await srDecrypt.ReadToEndAsync();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _log.Error("Error decrypting message", ex);
            throw;
        }
    }

    public async Task<DataTableReader> ExecuteQueryAsync(byte[] queryData)
    {
        try
        {
            using (var connection = new System.Data.SqlClient.SqlConnection(_connectionString))
            {
                connection.Open();
                var command = new System.Data.SqlClient.SqlCommand { CommandText = System.Text.Encoding.UTF8.GetString(queryData), Connection = connection };
                return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
            }
        }
        catch (Exception ex)
        {
            _log.Error("Error executing query", ex);
            throw;
        }
    }
}
