// Define a class for handling religious text extraction
class ReligiousTextExtractor {
  constructor(configUrl) {
    this.configUrl = configUrl;
    this.bookNames = {};
    this.loadConfiguration();
  }

  // Load book name variations from external JSON configuration file
  async loadConfiguration() {
    try {
      const response = await axios.get(this.configUrl);
      this.bookNames = response.data;
    } catch (error) {
      console.error('Error loading configuration:', error);
    }
  }

  // Extract mentions of religious texts from input text
  extractMentions(inputText) {
    let matches = [];
    for (const bookName in this.bookNames) {
      const regex = new RegExp(`\\b(${this.bookNames[bookName].join('|')})\\b`, 'gi');
      matches.push(...inputText.match(regex) || []);
    }
    return matches;
  }

  // Asynchronously process multiple texts concurrently
  async processMultiple(texts) {
    const results = [];
    for (const text of texts) {
      results.push(this.extractMentions(text));
    }
    return Promise.all(results);
  }
}

// Export the ReligiousTextExtractor class
module.exports = ReligiousTextExtractor;
