class RandomNumberGenerator {
public:
    RandomNumberGenerator() : seed(std::random_device{}()) {}

    int generateRandomNumber(int min, int max) {
        std::uniform_int_distribution<int> dist(min, max);
        return dist(generator);
    }

private:
    std::mt19937 generator;
    std::seed_seq seed;
};

class SecureRandomService {
public:
    SecureRandomService(size_t poolSize = 4) : poolSize(poolSize), stop(false) {
        for (size_t i = 0; i < poolSize; ++i) {
            workers.emplace_back(&SecureRandomService::workerThread, this);
        }
    }

    ~SecureRandomService() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    int generateRandomNumber(int min, int max) {
        std::lock_guard<std::mutex> lock(mutex);
        if (queue.empty()) throw std::runtime_error("No available generators in the pool");
        auto generator = queue.front(); queue.pop();
        int randomNumber = generator->generateRandomNumber(min, max);
        freeQueue.push(generator);
        return randomNumber;
    }

private:
    void workerThread() {
        while (true) {
            RandomNumberGenerator* generator = nullptr;
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !queue.empty() || stop; });
            if (stop && queue.empty()) break;
            generator = queue.front(); queue.pop();
        }
    }

    size_t poolSize;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable condition;
    std::queue<RandomNumberGenerator*> queue;
    std::queue<RandomNumberGenerator*> freeQueue;

    bool stop;
};
