import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class FileProcessor {
    private static final int MAX_CONCURRENT_OPERATIONS = 5;
    private static final String LOG_FILE_PATH = "log.txt";
    private static final Path TEMP_DIR = Paths.get("temp");
    private static final Path BACKUP_DIR = Paths.get("backup");

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_OPERATIONS);
        try (BufferedWriter logWriter = Files.newBufferedWriter(Paths.get(LOG_FILE_PATH))) {
            List<Path> textFiles = findTextFiles();
            for (Path file : textFiles) {
                executor.submit(() -> processFile(file, logWriter));
            }
        } catch (IOException e) {
            logError("Error initializing the log writer: " + e.getMessage());
        } finally {
            executor.shutdown();
        }
    }

    private static List<Path> findTextFiles() throws IOException {
        return Files.walk(TEMP_DIR)
                    .filter(Files::isRegularFile)
                    .filter(path -> path.toString().endsWith(".txt"))
                    .collect(Collectors.toList());
    }

    private static void processFile(Path file, BufferedWriter logWriter) {
        try {
            if (fileExistsInBackup(file)) {
                moveFileToBackup(file);
                return;
            }
            List<String> lines = sortLines(file);
            int sequenceNumber = extractSequenceNumber(lines.get(lines.size() - 1));
            runCommand(sequenceNumber, file, logWriter);
        } catch (IOException e) {
            logError("Error processing file " + file: " + e.getMessage());
        }
    }

    private static boolean fileExistsInBackup(Path file) throws IOException {
        Path backupFile = BACKUP_DIR.resolve(file.getFileName());
        return Files.exists(backupFile);
    }

    private static void moveFileToBackup(Path file) throws IOException {
        Path backupDir = createBackupDirectory();
        Path backupFile = backupDir.resolve(file.getFileName());
        Files.move(file, backupFile, StandardCopyOption.REPLACE_EXISTING);
        logStatus("Moved " + file + " to " + backupFile);
    }

    private static Path createBackupDirectory() throws IOException {
        if (!Files.exists(BACKUP_DIR)) {
            Files.createDirectories(BACKUP_DIR);
        }
        return BACKUP_DIR;
    }

    private static List<String> sortLines(Path file) throws IOException {
        List<String> lines = Files.readAllLines(file);
        Collections.sort(lines);
        return lines;
    }

    private static int extractSequenceNumber(String line) {
        // Implement logic to extract sequence number from the last line
        return Integer.parseInt(line.split(" ")[1]);
    }

    private static void runCommand(int sequenceNumber, Path file, BufferedWriter logWriter) throws IOException {
        String[] command = {"command", String.valueOf(sequenceNumber)};
        try {
            ProcessBuilder pb = new ProcessBuilder(command);
            pb.directory(file.getParent());
            Process process = pb.start();
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                logError("Command failed for file " + file + ": Exit code " + exitCode);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logError("Command interrupted for file " + file: " + e.getMessage());
        }
    }

    private static void logStatus(String message) throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(LOG_FILE_PATH), StandardOpenOption.APPEND)) {
            writer.write(message);
            writer.newLine();
        }
    }

    private static void logError(String message) throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(LOG_FILE_PATH), StandardOpenOption.APPEND)) {
            writer.write("ERROR: " + message);
            writer.newLine();
        }
    }
}
```

This Java program reads multiple large text files concurrently, sorts their lines, extracts a sequence number from the last line of each file, and runs a command based on this sequence number. It handles exceptions gracefully, ensures thread safety, logs errors or status updates to a log file, limits the maximum number of concurrent operations, and separates concerns into distinct classes and methods for maintainability and organization.

