import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ServiceManager {

    private ExecutorService executorService;
    private ExternalMessagingSystem externalMessagingSystem;

    public ServiceManager(int numberOfServices, ExternalMessagingSystem messagingSystem) {
        this.executorService = Executors.newFixedThreadPool(numberOfServices);
        this.externalMessagingSystem = messagingSystem;
    }

    public void startService(Service service) {
        executorService.submit(() -> {
            try {
                // Simulate random delay
                Thread.sleep((long)(Math.random() * 1000));

                // Execute service logic
                service.execute();

                // Send status update on completion
                externalMessagingSystem.sendStatusUpdate(service.getId(), "Stopped");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                externalMessagingSystem.sendStatusUpdate(service.getId(), "Failed - Interrupted");
            } catch (Exception e) {
                externalMessagingSystem.sendStatusUpdate(service.getId(), "Failed - Exception: " + e.getMessage());
            }
        });
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);
    }
}

interface ExternalMessagingSystem {
    void sendStatusUpdate(String serviceId, String status);
}

class Service {
    private int id;

    public Service(int id) {
        this.id = id;
    }

    public int getId() {
        return id;
    }

    public void execute() throws Exception {
        // Simulate service execution
        System.out.println("Service " + id + " is running");

        // Introduce a random failure point
        if (Math.random() < 0.1) {
            throw new Exception("Random Failure for Service " + id);
        }
    }
}

class KafkaMessagingSystem implements ExternalMessagingSystem {
    public void sendStatusUpdate(String serviceId, String status) {
        System.out.println("Kafka: Sending status update for service " + serviceId + ": " + status);
    }
}

class RabbitMQMessagingSystem implements ExternalMessagingSystem {
    public void sendStatusUpdate(String serviceId, String status) {
        System.out.println("RabbitMQ: Sending status update for service " + serviceId + ": " + status);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        int numberOfServices = 10;

        // Choose messaging system based on configuration
        ExternalMessagingSystem messagingSystem = new KafkaMessagingSystem(); // or RabbitMQMessagingSystem

        ServiceManager serviceManager = new ServiceManager(numberOfServices, messagingSystem);

        for (int i = 0; i < numberOfServices; i++) {
            Service service = new Service(i);
            serviceManager.startService(service);
        }

        serviceManager.shutdown();
    }
}
