import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

public class NioClient {

    private final String[] serverAddresses;
    private final int port;
    private final Selector selector;
    private final ConcurrentHashMap<String, SocketChannel> clientChannels = new ConcurrentHashMap<>();
    private final RateLimiter rateLimiter;
    private final Config config;

    public NioClient(String[] serverAddresses, int port, Config config) throws IOException {
        this.serverAddresses = serverAddresses;
        this.port = port;
        this.selector = Selector.open();
        this.rateLimiter = new RateLimiter(config.getMaxRequestsPerSecond());
        this.config = config;
        initClients();
    }

    private void initClients() throws IOException {
        for (String address : serverAddresses) {
            SocketChannel channel = SocketChannel.open();
            channel.configureBlocking(false);
            if (channel.connect(new InetSocketAddress(address, port))) {
                channel.register(selector, SelectionKey.OP_READ);
                clientChannels.put(address, channel);
            } else {
                channel.register(selector, SelectionKey.OP_CONNECT);
                clientChannels.put(address, channel);
            }
        }
    }

    public void run() throws IOException {
        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();
                keyIterator.remove();

                if (!key.isValid()) continue;

                if (key.isConnectable()) {
                    connect(key);
                } else if (key.isReadable()) {
                    read(key);
                }
            }

            try {
                Thread.sleep(10); // Adjust as needed
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void connect(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        if (channel.isConnectionPending()) {
            channel.finishConnect();
        }
        channel.register(selector, SelectionKey.OP_READ);
    }

    private void read(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(config.getBufferSize());
        int bytesRead = channel.read(buffer);

        if (bytesRead == -1) {
            channel.close();
            clientChannels.remove(channel.socket().getInetAddress().toString());
        } else if (bytesRead > 0) {
            buffer.flip();
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            processMessage(new String(data));
        }
    }

    private void processMessage(String message) {
        // Integrate with distributed message queue system
        // Implement load balancing strategy
        // Log processing event with timestamp
    }

    public void sendRequest(String message, String serverAddress) throws IOException {
        if (!rateLimiter.tryAcquire()) return;

        SocketChannel channel = clientChannels.get(serverAddress);
        ByteBuffer buffer = ByteBuffer.wrap(message.getBytes());
        int bytesWritten = channel.write(buffer);

        if (bytesWritten == -1) {
            channel.close();
            clientChannels.remove(channel.socket().getInetAddress().toString());
            // Retry logic here
        }
    }

    public static class Config {
        private final int maxRequestsPerSecond;
        private final int bufferSize;

        public Config(int maxRequestsPerSecond, int bufferSize) {
            this.maxRequestsPerSecond = maxRequestsPerSecond;
            this.bufferSize = bufferSize;
        }

        public int getMaxRequestsPerSecond() {
            return maxRequestsPerSecond;
        }

        public int getBufferSize() {
            return bufferSize;
        }
    }

    private static class RateLimiter {
        private final long interval;
        private long lastRequestTime;

        public RateLimiter(int requestsPerSecond) {
            this.interval = 1000 / requestsPerSecond;
            this.lastRequestTime = System.currentTimeMillis();
        }

        public boolean tryAcquire() {
            long currentTime = System.currentTimeMillis();
            if (currentTime - lastRequestTime >= interval) {
                lastRequestTime = currentTime;
                return true;
            }
            return false;
        }
    }

    public static void main(String[] args) throws IOException {
        String[] serverAddresses = {"192.168.1.1", "192.168.1.2"};
        int port = 8080;
        Config config = new Config(5, 4096);
        NioClient client = new NioClient(serverAddresses, port, config);
        client.run();
    }
}
