using System;
using System.Collections.Generic;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;
using UnityEngine;

public class AsyncValueGenerator
{
    private Dictionary<string, TcpClient> _clients = new Dictionary<string, TcpClient>();
    private Random _random = new Random();
    private DateTime _lastHeartbeat;

    public void SeedRandom(int seed)
    {
        _random = new Random(seed);
    }

    public int GenerateRandomValueInRange(int min, int max, bool exclusive)
    {
        if (exclusive)
        {
            return _random.Next(min, max + 1);
        }
        else
        {
            return _random.Next(min, max);
        }
    }

    public async Task ConnectAsync(List<string> addresses, Dictionary<string, Tuple<int, string, string>> credentials)
    {
        foreach (var address in addresses)
        {
            var parts = address.Split(':');
            var host = parts[0];
            int port;
            if (!int.TryParse(parts[1], out port))
            {
                throw new ArgumentException("Invalid port format.");
            }

            try
            {
                var client = new TcpClient(host, port);
                _clients[address] = client;

                await SendCredentialsAsync(client, credentials[address].Item2, credentials[address].Item3);

                _lastHeartbeat = DateTime.Now;
            }
            catch (Exception ex)
            {
                Debug.LogError($"Failed to connect to {address}: {ex.Message}");
            }
        }
    }

    private async Task SendCredentialsAsync(TcpClient client, string username, string password)
    {
        var networkStream = client.GetStream();
        byte[] data = Encoding.ASCII.GetBytes($"{username}:{password}");
        await networkStream.WriteAsync(data, 0, data.Length);
    }

    public async Task<int> GenerateUniqueValue(string address, int min, int max, bool exclusive)
    {
        if (!_clients.ContainsKey(address))
        {
            throw new ArgumentException("Client not connected.");
        }

        while (true)
        {
            int value = GenerateRandomValueInRange(min, max, exclusive);
            await SendDataAsync(_clients[address], value.ToString());
            var response = await ReceiveResponseAsync(_clients[address]);
            if (response == "OK")
            {
                return value;
            }
        }
    }

    private async Task SendDataAsync(TcpClient client, string data)
    {
        var networkStream = client.GetStream();
        byte[] info = Encoding.ASCII.GetBytes(data);
        await networkStream.WriteAsync(info, 0, info.Length);
    }

    private async Task<string> ReceiveResponseAsync(TcpClient client)
    {
        var buffer = new byte[256];
        int bytesReceived;
        using (var reader = new System.IO.StreamReader(client.GetStream()))
        {
            bytesReceived = await reader.BaseStream.ReadAsync(buffer, 0, buffer.Length);
        }
        return Encoding.ASCII.GetString(buffer, 0, bytesReceived);
    }

    public void CheckSubset(string address, List<int> subset)
    {
        if (!_clients.ContainsKey(address))
        {
            throw new ArgumentException("Client not connected.");
        }

        int value = GenerateRandomValueInRange(subset.Min(), subset.Max(), true);
        Debug.Log($"Generated value: {value}, Subset: [{string.Join(", ", subset)}]");

        bool isInSubset = subset.Contains(value);
        if (isInSubset)
        {
            Debug.Log("The generated value is within the specified subset.");
        }
        else
        {
            Debug.LogWarning("The generated value is not within the specified subset.");
        }
    }

    public void Heartbeat()
    {
        foreach (var client in _clients.Values)
        {
            if ((DateTime.Now - _lastHeartbeat).TotalSeconds > 60) // Example timeout: 60 seconds
            {
                Debug.LogWarning("Client connection timed out. Attempting to reconnect.");
                await ReconnectAsync(client);
            }
        }
    }

    private async Task ReconnectAsync(TcpClient client)
    {
        try
        {
            client.Close();
            string address = GetAddressFromClient(client);
            var parts = address.Split(':');
            var host = parts[0];
            int port;
            if (!int.TryParse(parts[1], out port))
            {
                throw new ArgumentException("Invalid port format.");
            }

            var newClient = new TcpClient(host, port);
            _clients[address] = newClient;

            await SendCredentialsAsync(newClient, GetUsernameFromClient(client), GetPasswordFromClient(client));

            _lastHeartbeat = DateTime.Now;
        }
        catch (Exception ex)
        {
            Debug.LogError($"Failed to reconnect to {client.Client.RemoteEndPoint}: {ex.Message}");
        }
    }

    private string GetAddressFromClient(TcpClient client)
    {
        // Implement logic to extract address from the client
        return "127.0.0.1:8080"; // Placeholder
    }

    private string GetUsernameFromClient(TcpClient client)
    {
        // Implement logic to extract username from the client
        return "user"; // Placeholder
    }

    private string GetPasswordFromClient(TcpClient client)
    {
        // Implement logic to extract password from the client
        return "password"; // Placeholder
    }
}
