import pytest
import threading
import time

def run_module_tests(module_tests, label=None, parallel=True):
    def execute_test(test_func, module_name):
        try:
            print(f"Starting test {test_func.__name__} for module {module_name}")
            result = pytest.main(['-v', '-k', test_func.__name__])
            if result == 0:
                print(f"Test {test_func.__name__} passed for module {module_name}")
            else:
                print(f"Test {test_func.__name__} failed for module {module_name}")
        except Exception as e:
            print(f"Error executing test {test_func.__name__}: {e}")

    threads = []
    if parallel:
        for module, tests in module_tests.items():
            for test in tests:
                thread = threading.Thread(target=execute_test, args=(test, module))
                threads.append(thread)
                thread.start()
        for thread in threads:
            thread.join()
    else:
        for module, tests in module_tests.items():
            for test in tests:
                execute_test(test, module)

if __name__ == "__main__":
    module_tests = {
        'module1': ['test_function1', 'test_function2'],
        'module2': ['test_function3']
    }
