import os
import importlib.util
from threading import Lock

class ModelManager:
    def __init__(self):
        self.models = {}
        self.lock = Lock()

    def load_model(self, model_path, version=None):
        with self.lock:
            if model_path not in self.models or self.models[model_path]['version'] != version:
                try:
                    module_name = os.path.basename(model_path).replace('.py', '')
                    spec = importlib.util.spec_from_file_location(module_name, model_path)
                    model_module = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(model_module)

                    if version is not None:
                        self.models[model_path] = {'module': model_module, 'version': version}
                    else:
                        self.models[model_path] = {'module': model_module, 'version': 1}

                except Exception as e:
                    print(f"Failed to load model from {model_path}: {e}")
                    raise

    def get_model(self, model_path):
        if model_path in self.models:
            return self.models[model_path]['module']
        else:
            raise ValueError(f"Model not found at path: {model_path}")

# Example usage
manager = ModelManager()
manager.load_model('path/to/model.py', version=1)
model = manager.get_model('path/to/model.py')
