// Import necessary modules
const express = require('express');
const WebSocket = require('ws');
const AWS = require('aws-sdk');
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;
const axios = require('axios');
const logger = require('./logger'); // Assume a custom logger module

// Initialize AWS S3 client
AWS.config.update({
  region: 'your-region',
  accessKeyId: 'your-access-key-id',
  secretAccessKey: 'your-secret-access-key'
});
const s3 = new AWS.S3();

// Create an Express app
const app = express();
app.use(express.json());

// Create a WebSocket server
const wss = new WebSocket.Server({ port: 8080 });

// Handle WebSocket connections
wss.on('connection', (ws) => {
  ws.on('message', async (message) => {
    try {
      const data = JSON.parse(message);
      // Store sensor reading in S3
      await storeReading(data);
      // Broadcast the new reading to connected clients
      wss.clients.forEach((client) => {
        if (client.readyState === WebSocket.OPEN) {
          client.send(JSON.stringify(data));
        }
      });
    } catch (error) {
      logger.error('Error processing sensor data:', error);
    }
  });
});

// Function to store sensor reading in S3
async function storeReading(reading) {
  const params = {
    Bucket: 'your-bucket-name',
    Key: `${reading.deviceId}/${reading.timestamp}.json`,
    Body: JSON.stringify(reading),
    ContentType: 'application/json'
  };
  try {
    await s3.upload(params).promise();
  } catch (error) {
    logger.error('Error storing reading in S3:', error);
  }
}

// Function to aggregate sensor readings
function aggregateReadings(readings, callback) {
  return readings.reduce((acc, reading) => {
    if (!acc[reading.deviceId]) {
      acc[reading.deviceId] = [];
    }
    const index = acc[reading.deviceId].findIndex(
      (r) =>
        r.timestamp >= reading.timestamp - 300 && // 5 minutes window
        r.timestamp <= reading.timestamp + 300
    );
    if (index !== -1) {
      acc[reading.deviceId][index].value += reading.value;
    } else {
      acc[reading.deviceId].push({ timestamp: reading.timestamp, value: reading.value });
    }
    return acc;
  }, {});
}

// Define routes
app.post('/readings', async (req, res) => {
  const readings = req.body;
  try {
    // Aggregate readings using the reduce function
    const aggregatedReadings = aggregateReadings(readings);
    // Call the callback function with the result
    await callback(aggregatedReadings);
    res.status(200).send('Readings processed successfully');
  } catch (error) {
    logger.error('Error processing readings:', error);
    res.status(500).send('Internal Server Error');
  }
});

// Start the server
if (cluster.isMaster) {
  console.log(`Master ${process.pid} is running`);

  // Fork workers.
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`worker ${worker.process.pid} died`);
  });
} else {
  app.listen(3000, () => {
    console.log(`Worker ${process.pid} started`);
  });
}
