// Forward declaration of the Octree class
class Octree;

// Function to initialize an octree system
std::pair<bool, std::string> initializeOctreeSystem(const std::string& command, int maxRetries = 3) {
    // Mutex for thread-safe operations
    static std::mutex mtx;
    static std::condition_variable cv;
    static bool initialized = false;
    static std::string initializationError;

    // Lock the mutex to ensure exclusive access
    std::unique_lock<std::mutex> lock(mtx);

    // Wait until the octree is fully initialized or an error occurs
    while (!initialized && initializationError.empty()) {
        cv.wait(lock);
    }

    if (initialized) {
        return {true, "Octree initialized successfully"};
    } else {
        return {false, initializationError};
    }
}

// Function to execute a command and handle retries with exponential backoff
bool runCommand(const std::string& command, int maxRetries = 3) {
    for (int i = 0; i <= maxRetries; ++i) {
        try {
            // Simulate running the command using system call
            int status = system(command.c_str());
            if (status == 0) {
                return true;
            } else {
                throw std::runtime_error("Command failed with status: " + std::to_string(status));
            }
        } catch (const std::exception& e) {
            if (i < maxRetries) {
                std::this_thread::sleep_for(std::chrono::seconds(1 << i)); // Exponential backoff
            } else {
                return false;
            }
        }
    }
    return false;
}

