const { exec } = require('child_process');
const lruCache = require('lru-cache');
const axios = require('axios');

const cache = new lruCache({ max: 100, maxAge: 1000 * 60 });

async function executeShellCommand(command) {
  if (cache.has(command)) {
    console.log('Cache hit:', command);
    return cache.get(command);
  }

  try {
    const { stdout } = await exec(command);
    cache.set(command, stdout);
    console.log('Cache miss:', command);
    return stdout;
  } catch (error) {
    console.error('Error executing shell command:', error.message);
    throw error;
  }
}

async function fetchSupplementaryInfo(commandOutput) {
  try {
    const response = await axios.post('https://api.example.com/supplementary', { output: commandOutput });
    return response.data;
  } catch (error) {
    console.error('Error fetching supplementary info:', error.message);
    throw error;
  }
}

async function handleCommandExecution(command, mode) {
  if (!['sync', 'async'].includes(mode)) {
    throw new Error('Invalid execution mode. Please use "sync" or "async".');
  }

  let result = null;

  if (mode === 'sync') {
    result = await executeShellCommand(command);
  } else {
    const promise = executeShellCommand(command);
    promise.then((output) => {
      result = output;
      fetchSupplementaryInfo(output).then((info) => {
        console.log('Supplementary info:', info);
      }).catch((error) => {
        console.error('Error fetching supplementary info:', error.message);
      });
    }).catch((error) => {
      console.error('Error executing shell command:', error.message);
    });
  }

  return result;
}

// Example usage:
handleCommandExecution('ls -la', 'sync').then((output) => {
  console.log('Command output:', output);
}).catch((error) => {
  console.error('Error handling command execution:', error.message);
});
