using System;
using System.Collections.Generic;

public class DynamicValueGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;
    private HashSet<int> _usedIntegers;

    public DynamicValueGenerator()
    {
        _random = new Random();
        _minValue = 0;
        _maxValue = 100;
        _usedIntegers = new HashSet<int>();
    }

    public void SeedRandom(int seed)
    {
        _random = new Random(seed);
    }

    public void SetRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value cannot be greater than max value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
        _usedIntegers.Clear();
    }

    public int GetUniqueRandomInteger(int count)
    {
        if (_maxValue - _minValue + 1 < count)
        {
            throw new ArgumentException("Range too small for the requested number of unique values.");
        }
        while (true)
        {
            int randomInt = _random.Next(_minValue, _maxValue + 1);
            if (!_usedIntegers.Contains(randomInt))
            {
                _usedIntegers.Add(randomInt);
                return randomInt;
            }
        }
    }

    public float GetRandomFloat(float minValue, float maxValue)
    {
        return (float)(_random.NextDouble() * (maxValue - minValue) + minValue);
    }

    public bool IsValueInSubset(int value, int subsetMin, int subsetMax)
    {
        return value >= subsetMin && value <= subsetMax;
    }

    public bool IsUnique(int value)
    {
        return !_usedIntegers.Contains(value);
    }
}
