#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define IV_LENGTH 16
#define KEY_LENGTH 32

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[IV_LENGTH];
} CipherContext;

int init_cipher(CipherContext **context, const char *password, size_t password_len,
                const unsigned char *salt, size_t salt_len) {
    if (context == NULL || password == NULL || password_len == 0 ||
        salt == NULL || salt_len != EVP_SALT_LENGTH) {
        return -1;
    }

    *context = malloc(sizeof(CipherContext));
    if (*context == NULL) {
        return -2;
    }

    memset(*context, 0, sizeof(CipherContext));

    unsigned char key[KEY_LENGTH];
    int key_len;

    EVP_sha1_derive(password, password_len, salt, salt_len, key, &key_len);
    if (key_len != KEY_LENGTH) {
        free(*context);
        return -3;
    }

    (*context)->ctx = EVP_CIPHER_CTX_new();
    if ((*context)->ctx == NULL) {
        free(*context);
        return -4;
    }

    if (EVP_EncryptInit_ex((*context)->ctx, EVP_aes_256_cbc(), NULL, key, (*context)->iv) != 1) {
        EVP_CIPHER_CTX_free((*context)->ctx);
        free(*context);
        return -5;
    }

    return 0;
}

void cleanup_cipher(CipherContext *context) {
    if (context == NULL || context->ctx == NULL) {
        return;
    }

    EVP_EncryptEnd_ex(context->ctx, NULL, NULL);
    EVP_CIPHER_CTX_free(context->ctx);
    free(context);
}
