    void handlePostRequest(const std::forward_list<std::string>& sections, const std::string& sectionId, const std::string& elementId, const std::string& encryptedData, int desType) {
        // Decrypt logic using DES algorithm
        std::string decryptedData = decrypt(encryptedData, desType);

        std::forward_list<std::string>::iterator insertIt = sections.begin();
        for (; insertIt != sections.end() && *insertIt != sectionId; ++insertIt);
