            }
        }
        return true;
    }

    void write_log(const std::string& operation, const std::string& item) {
        // Placeholder for log writing logic
        std::ofstream log_file(config.log_file_path, std::ios_base::app);
        if (log_file.is_open()) {
            log_file << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now())
                     << " - " << operation << " - " << item << std::endl;
            log_file.close();
        }
    }

public:
    ForwardListManager(const Config& config) : config(config), cache_expiration(std::chrono::steady_clock::now()) {}

    bool insert_after_target(const std::string& target, const std::string& new_item) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = list.before_begin();
        for (auto i = list.begin(); i != list.end(); ++i, ++it) {
            if (*i == target) {
                list.insert_after(it, new_item);
                write_log("Insert", new_item);
                return true;
            }
        }
        list.push_front(new_item);
        write_log("Append", new_item);
        return true;
    }

    bool merge_external_data_source(const std::string& file_path) {
        std::ifstream file(file_path);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open external data source file.");
        }
        std::forward_list<std::string> cache_data;
        std::string line;
        while (std::getline(file, line)) {
            if (cache.count(line)) {
                continue; // Skip duplicates
            }
            cache.insert(line);
            cache_data.push_front(line);
        }
        file.close();
        return merge_with_cache(cache_data);
    }

    bool search_replace(const std::string& search_term, const std::string& replacement_term) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == search_term) {
                *it = replacement_term;
                write_log("Replace", search_term + " -> " + replacement_term);
            }
            ++it;
        }
        return true;
    }

    bool remove_item(const std::string& item) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == item) {
                list.erase(it);
                write_log("Delete", item);
                return true;
            }
            ++it;
        }
        return false;
    }

    void clear_cache() {
        cache.clear();
        cache_expiration = std::chrono::steady_clock::now();
    }
};
