// ConcurrentLinkedQueue Implementation

#include <mutex>
#include <queue>
#include <condition_variable>

template<typename T>
class ConcurrentLinkedQueue {
public:
    void push(T value) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(value);
        cond.notify_one();
    }

    bool pop(T& value) {
        std::unique_lock<std::mutex> lock(mutex);
        while (queue.empty()) {
            cond.wait(lock);
        }
        value = queue.front();
        queue.pop();
        return true;
    }

private:
    std::mutex mutex;
    std::queue<T> queue;
    std::condition_variable cond;
};

