// Streaming Data Collector Function
function streamingDataCollector(apiUrl, pauseCallback, resumeCallback) {
    let intervalId;
    let dataQueue = [];
    let isPaused = false;

    function fetchData() {
        if (isPaused) return;

        fetch(apiUrl)
            .then(response => response.json())
            .then(data => {
                dataQueue.push(...data);
                pauseCallback(() => {
                    clearInterval(intervalId);
                    resumeCallback(fetchData);
                });
            })
            .catch(error => {
                console.error('Error fetching data:', error);
                pauseCallback(() => {
                    clearInterval(intervalId);
                    resumeCallback(fetchData);
                });
            });
    }

    function startCollecting() {
        intervalId = setInterval(fetchData, 1000);
    }

    return {
        start: startCollecting,
        stop: () => isPaused = true,
        resume: () => {
            isPaused = false;
            fetchData();
        },
        getData: () => dataQueue
    };
}

