    unsigned char* key = (unsigned char*)malloc(key_length);
    if (!key) return 1;
    if (!RAND_bytes(key, key_length)) {
        free(key);
        return 1;
    }
    FILE* file = fopen(filename, "wb");
    if (!file) {
        free(key);
        return 1;
    }
    fwrite(key, 1, key_length, file);
    fclose(file);
    free(key);
    return 0;
