import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Properties;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DatabaseConnectionManager {
    private final String url;
    private final Properties properties;
    private int maxActiveConnections;
    private long idleTimeout;
    private String validationQuery;
    private ConcurrentHashMap<String, Connection> connectionPool = new ConcurrentHashMap<>();
    private ExecutorService executorService = Executors.newCachedThreadPool();
    private boolean isRunning = false;

    public DatabaseConnectionManager(String url, Properties properties, int maxActiveConnections, long idleTimeout, String validationQuery) {
        this.url = url;
        this.properties = properties;
        this.maxActiveConnections = maxActiveConnections;
        this.idleTimeout = idleTimeout;
        this.validationQuery = validationQuery;
    }

    public synchronized Connection getConnection() throws SQLException {
        if (isRunning && connectionPool.size() < maxActiveConnections) {
            String key = Thread.currentThread().getName();
            while (!connectionPool.containsKey(key)) {
                try {
                    Connection conn = DriverManager.getConnection(url, properties);
                    connectionPool.put(key, conn);
                } catch (SQLException e) {
                    throw new SQLException("Failed to get a database connection", e);
                }
            }
            return connectionPool.get(key);
        } else {
            throw new SQLException("Connection pool is full or not running");
        }
    }

    public void releaseConnection(Connection conn) {
        if (conn != null && connectionPool.containsValue(conn)) {
            connectionPool.values().remove(conn);
        }
    }

    // Other methods for managing and optimizing database connections...

    @Override
    public String toString() {
        return "DatabaseConnectionManager{" +
                "url='" + url + '\'' +
                ", maxActiveConnections=" + maxActiveConnections +
                ", idleTimeout=" + idleTimeout +
                ", validationQuery='" + validationQuery + '\'' +
                ", connectionPoolSize=" + connectionPool.size() +
                '}';
    }

    // Additional methods for configuration persistence, monitoring, and integration...
}
