const { exec } = require('child_process');

function executeShellCommand(command) {
  return new Promise((resolve, reject) => {
    exec(command, (error, stdout, stderr) => {
      if (error) {
        console.error(`Error executing command: ${command}`);
        console.error(`Error message: ${stderr}`);
        reject(error);
      } else {
        console.log(`Command output: ${stdout}`);
        resolve(stdout);
      }
    });
  });
}

module.exports = { executeShellCommand };
```

This JavaScript function `executeShellCommand` takes a shell command as input and returns a Promise that resolves with the output of the command if successful, or rejects with an error if the command fails. It uses Node.js's built-in `child_process` module to execute the command asynchronously. The function logs both the standard output and any errors encountered during execution, providing useful feedback for debugging and monitoring purposes.

