```javascript
function renderFooterScripts(scripts) {
    const footer = document.querySelector('footer');

    if (!footer) {
        console.error('Footer element not found.');
        return;
    }

    scripts.forEach(script => {
        const { key, src, innerHTML } = script;

        if (!key || (!src && !innerHTML)) {
            console.error(`Script missing required properties: ${key}`);
            return;
        }

        const existingScript = document.querySelector(`script[${key}]`);
        if (existingScript) {
            console.log(`Script already exists with key: ${key}`);
            return;
        }

        const scriptTag = document.createElement('script');
        scriptTag.setAttribute('data-key', key);

        if (src) {
            scriptTag.src = src;
            scriptTag.async = true;
            scriptTag.onload = () => console.log(`Script loaded successfully: ${src}`);
            scriptTag.onerror = () => console.error(`Failed to load script: ${src}`);
        } else if (innerHTML) {
            scriptTag.innerHTML = innerHTML;
            console.log('Custom script injected.');
        }

        footer.appendChild(scriptTag);
    });
}
