```javascript
// JavaScript Function for Asynchronous Reduction

async function asyncReduce(array, initialValue, operation, callback) {
    let accumulator = initialValue;

    if (array.length === 0) {
        return Promise.reject(new Error("Array is empty"));
    }

    try {
        for (let i = 0; i < array.length; i++) {
            const currentNumber = array[i];
            if (typeof currentNumber !== 'number') {
                throw new Error("Array contains non-numeric values");
            }
            accumulator = await callback(accumulator, currentNumber);
        }
        return Promise.resolve(accumulator);
    } catch (error) {
        return Promise.reject(error);
    }
}

// Example Usage
const numbers = [1, 2, 3, 4];
const initialValue = 0;
const operation = 'sum';

asyncReduce(numbers, initialValue, operation, (acc, num) => {
    return new Promise((resolve) => {
        setTimeout(() => resolve(acc + num), 100); // Simulate async operation
    });
}).then(result => {
    console.log("Result:", result);
}).catch(error => {
    console.error("Error:", error.message);
});
