import hashlib
import bcrypt

def modify_kickstart_config(file_path, placeholders):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            checksum = hashlib.md5(content.encode()).hexdigest()

            # Check file integrity
            if not verify_checksum(checksum):
                print("File has been tampered with. Exiting.")
                return

        # Modify the configuration file
        modified_content = content
        for placeholder, value in placeholders.items():
            if placeholder in modified_content:
                if placeholder == 'password':
                    salt = bcrypt.gensalt()
                    hashed_password = bcrypt.hashpw(value.encode(), salt)
                    modified_content = modified_content.replace(placeholder, hashed_password.decode())
                else:
                    modified_content = modified_content.replace(placeholder, value)

        # Write the modified content back to the file
        with open(file_path, 'w') as file:
            file.write(modified_content)

        print("Configuration file updated successfully.")

    except FileNotFoundError:
        print("File not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

