#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libssh/libssh.h>

#define MAX_BUFFER_SIZE 1024

void error_exit(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

ssh_session create_ssh_session(const char *host, const char *user, const char *keyfile) {
    ssh_session session = ssh_new();
    if (!session)
        error_exit("Could not allocate SSH session");

    int rc = ssh_connect(session, host);
    if (rc != SSH_OK)
        error_exit(ssh_get_error(session));

    rc = ssh_userauth_pubkey_file(session, user, keyfile, NULL, NULL);
    if (rc != SSH_AUTH_SUCCESS)
        error_exit("Authentication failed: " ssh_get_error(session));

    return session;
}

void download_binary_file(ssh_session session, const char *remote_path, const char *local_path, size_t max_buffer_size) {
    ssh_channel channel = ssh_channel_open_session(session);
    if (channel == SSH_NULL)
        error_exit("Could not open SSH channel");

    int rc = ssh_channel_request_exec(channel, "cat " remote_path);
    if (rc != SSH_OK)
        error_exit(ssh_get_error(session));

    FILE *local_file = fopen(local_path, "wb");
    if (!local_file)
        error_exit("Failed to open local file for writing");

    char *buffer = malloc(max_buffer_size);
    if (!buffer)
        error_exit("Memory allocation failed");

    while (1) {
        rc = ssh_channel_read(channel, buffer, max_buffer_size, 0);
        if (rc < 0) {
            error_exit(ssh_get_error(session));
        } else if (rc == 0) {
            break;
        }

        fwrite(buffer, sizeof(char), rc, local_file);
    }

    free(buffer);
    fclose(local_file);
    ssh_channel_close(channel);
}

void parse_and_transform(const char *input_path, const char *output_path, const char *rules) {
    // Implement parsing and transformation logic here
    // This is a placeholder for the actual implementation
    printf("Parsing and transforming: %s -> %s\n", input_path, output_path);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <remote_file> <local_output_file> <rules_json> <max_buffer_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *remote_file = argv[1];
    const char *local_output_file = argv[2];
    const char *rules_json = argv[3];
    size_t max_buffer_size = atoi(argv[4]);

    if (max_buffer_size > MAX_BUFFER_SIZE) {
        fprintf(stderr, "Max buffer size cannot exceed %zu bytes\n", MAX_BUFFER_SIZE);
        return EXIT_FAILURE;
    }

    ssh_session session = create_ssh_session("remote_server_host", "username", "path_to_private_key");
    download_binary_file(session, remote_file, local_output_file, max_buffer_size);

    parse_and_transform(local_output_file, local_output_file, rules_json);

    ssh_disconnect(session);
    ssh_free(session);

    return EXIT_SUCCESS;
}
