        self.iot_api_url = iot_api_url
        self.sensor_data_queue = Queue()

    def fetch_real_time_data(self):
        response = requests.get(self.iot_api_url)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Failed to fetch real-time data from IoT platform")

    def parse_sensor_logs(self, log_file):
        with open(log_file, 'r') as file:
            for line in file:
                try:
                    sensor_data = json.loads(line)
                    self.sensor_data_queue.put(sensor_data)
                except ValueError:
                    print(f"Error parsing log line: {line}")

    def aggregate_metrics(self):
        total_temp, total_humidity, motion_count = 0, 0, 0
        while not self.sensor_data_queue.empty():
            data = self.sensor_data_queue.get()
            total_temp += data['temperature']
            total_humidity += data['humidity']
            if data['motion']:
                motion_count += 1
        avg_temp = total_temp / self.sensor_data_folder.count()
        avg_humidity = total_humidity / self.sensor_data_folder.count()
        return {'avg_temperature': avg_temp, 'avg_humidity': avg_humidity, 'motion_frequency': motion_count}

    def detect_anomalies(self):
        # Implement anomaly detection logic here
        pass

    def run_analysis(self):
        threads = []
        for log_file in os.listdir(self.device_logs_folder):
            thread = Thread(target=self.parse_sensor_logs, args=(os.path.join(self.device_logs_folder, log_file),))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        metrics = self.aggregate_metrics()
