#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <sys/stat.h>

#define INPUT_DIR "/path/to/input/directory"
#define OUTPUT_DIR "/path/to/output/directory"
#define LOG_FILE "validation_errors.log"

typedef struct {
    char *filename;
    pthread_mutex_t lock;
} CSVFile;

CSVFile* read_csv_files(const char* dir) {
    DIR *dp;
    struct dirent *ep;
    CSVFile *csv_files = NULL;
    int count = 0;

    dp = opendir(dir);
    if (dp != NULL) {
        while ((ep = readdir(dp)) != NULL) {
            if (strstr(ep->d_name, ".csv") != NULL) {
                csv_files = realloc(csv_files, sizeof(CSVFile) * (count + 1));
                csv_files[count].filename = strdup(ep->d_name);
                pthread_mutex_init(&csv_files[count].lock, NULL);
                count++;
            }
        }
        closedir(dp);
    }

    return csv_files;
}

void process_csv_file(void* arg) {
    CSVFile *file = (CSVFile*)arg;
    FILE *fp;
    char line[1024];
    double sum = 0, average;

    fp = fopen(file->filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    while (fgets(line, sizeof(line), fp)) {
        // Parse CSV line and calculate average
        char *token;
        int count = 0;
        double num;

        token = strtok(line, ",");
        while (token != NULL) {
            if (sscanf(token, "%lf", &num) == 1 && num >= 0) {
                sum += num;
                count++;
            }
            token = strtok(NULL, ",");
        }

        average = count > 1 ? sum / 2 : 0;

        // Write processed data to output file
        FILE *out_fp;
        out_fp = fopen(OUTPUT_DIR "/processed_" file->filename, "a");
        if (out_fp == NULL) {
            perror("Error opening output file");
        } else {
            fprintf(out_fp, "%s,%f\n", line, average);
            fclose(out_fp);
        }
    }

    fclose(fp);
}

void *validate_transactions(void* arg) {
    CSVFile *file = (CSVFile*)arg;
    FILE *fp;
    char line[1024];

    fp = fopen(file->filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return NULL;
    }

    while (fgets(line, sizeof(line), fp)) {
        // Validate transaction against external service
        // Log errors to LOG_FILE
    }

    fclose(fp);
    return NULL;
}

int main(int argc, char *argv[]) {
    CSVFile *csv_files = read_csv_files(INPUT_DIR);

    pthread_t threads[10];
    int num_threads = 0;

    for (int i = 0; csv_files[i].filename != NULL; i++) {
        if (pthread_create(&threads[num_threads], NULL, process_csv_file, &csv_files[i]) == 0) {
            num_threads++;
        } else {
            perror("Error creating thread");
        }

        if (num_threads >= 10) {
            for (int j = 0; j < num_threads; j++) {
                pthread_join(threads[j], NULL);
            }
            num_threads = 0;
        }
    }

    for (int i = 0; csv_files[i].filename != NULL; i++) {
        pthread_join(threads[num_threads], NULL);
        num_threads++;
    }

    for (int i = 0; csv_files[i].filename != NULL; i++) {
        pthread_mutex_destroy(&csv_files[i].lock);
        free(csv_files[i].filename);
    }
    free(csv_files);

    return 0;
}
