    private static readonly Regex SecurityKeywordRegex = new Regex(@"\b(password|encryption|security)\b", RegexOptions.IgnoreCase);
    private static readonly Regex EmailFormatRegex = new Regex(@"^[^@\s]+@[^@\s]+\.[^@\s]+$");
    private static readonly List<string> MaliciousEmailDomains = new List<string> { "malicious.com", "spam.org" };

    public bool ValidateBookName(string bookName)
    {
        return OldTestamentBookRegex.IsMatch(bookName);
    }

    public bool ValidateSecurityKeyword(string keyword)
    {
        return SecurityKeywordRegex.IsMatch(keyword);
    }

    public bool ValidateEmail(string email)
    {
        if (!EmailFormatRegex.IsMatch(email))
            return false;

        var domain = email.Split('@')[1];
        return !MaliciousEmailDomains.Contains(domain);
    }
}

public class PasswordPolicyService
{
    private static readonly Regex ComplexPasswordRegex = new Regex(@"^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$");

    public bool IsPasswordComplex(string password)
    {
        return ComplexPasswordRegex.IsMatch(password);
    }

    public bool IsCommonWeakPassword(string password)
    {
        // List of common weak passwords
        var commonPasswords = new List<string> { "password", "123456", "qwerty" };
        return commonPasswords.Contains(password);
    }
}

public class UserAccountService : IDisposable
{
    private readonly ValidationService _validationService;
    private readonly PasswordPolicyService _passwordPolicyService;
    private bool _isLockedOut = false;
    private static readonly object LockoutMutex = new object();
