```javascript
const crypto = require('crypto');
const https = require('https');
const WebSocket = require('ws');
const Redis = require('ioredis');

class DataCollector {
  constructor(options) {
    this.options = options;
    this.redis = new Redis(options.redisUrl);
    this.rateLimiters = {};
  }

  async collectData(source) {
    if (this.isRateLimited(source)) return;

    try {
      const data = await this.fetchDataFromSource(source);
      if (!data) throw new Error('No data received from source');

      const hash = await this.computeSHA256(data);
      await this.storeHashInCache(source, hash);

      console.log(`Data collected and stored for ${source}`);
    } catch (error) {
      this.logError('ERROR', error.message);
      throw error;
    }
  }

  async fetchDataFromSource(source) {
    try {
      if (source.startsWith('ws')) {
        return await this.fetchDataFromWebSocket(source);
      } else {
        return await this.fetchDataFromHTTP(source);
      }
    } catch (error) {
      this.logError('NETWORK', `Failed to fetch data from ${source}: ${error.message}`);
      throw error;
    }
  }

  async fetchDataFromWebSocket(url) {
    return new Promise((resolve, reject) => {
      const ws = new WebSocket(url);

      ws.on('message', (data) => {
        resolve(data);
        ws.close();
      });

      ws.on('error', (error) => {
        reject(error);
      });
    });
  }

  async fetchDataFromHTTP(url) {
    return new Promise((resolve, reject) => {
      const request = https.get(url, (response) => {
        let data = '';
        response.setEncoding('utf8');

        response.on('data', (chunk) => {
          data += chunk;
        });

        response.on('end', () => {
          resolve(data);
        });
      }).on('error', (error) => {
        reject(error);
      });
    });
  }

  async computeSHA256(data) {
    return new Promise((resolve, reject) => {
      const hash = crypto.createHash('sha256');
      hash.update(data);

      hash.on('finish', () => {
        resolve(hash.digest('hex'));
      });

      hash.on('error', (error) => {
        reject(error);
      });
    });
  }

  async storeHashInCache(source, hash) {
    try {
      await this.redis.setex(`${this.options.cachePrefix}:${source}`, this.options.cacheTTL, hash);
    } catch (error) {
      this.logError('CACHE', `Failed to store hash in cache for ${source}: ${error.message}`);
      throw error;
    }
  }

  isRateLimited(source) {
    if (!this.rateLimiters[source]) {
      this.rateLimiters[source] = { count: 0, lastRequest: Date.now() };
    }

    const now = Date.now();
    if (now - this.rateLimiters[source].lastRequest < this.options.rateLimitInterval) {
      this.rateLimiters[source].count++;
      if (this.rateLimiters[source].count >= this.options.rateLimitMaxRequests) {
        console.log(`Rate limit exceeded for ${source}`);
        return true;
      }
    } else {
      this.rateLimiters[source] = { count: 1, lastRequest: now };
    }

    return false;
  }

  logError(level, message) {
    const timestamp = new Date().toISOString();
    console.log(`[${timestamp}][${level}] ${message}`);
  }
}

module.exports = DataCollector;
