using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public interface ILogger
{
    void LogInfo(string message);
    void LogError(string message);
}

public class AesCbcDecryptor
{
    private readonly ILogger _logger;

    public AesCbcDecryptor(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, bool returnString = false)
    {
        try
        {
            if (key.Length != 16 && key.Length != 24 && key.Length != 32)
                throw new ArgumentException("Invalid key size. It must be 16, 24, or 32 bytes.");

            if (iv.Length != 16)
                throw new ArgumentException("Invalid IV length. It must be 16 bytes.");

            using (Aes aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;

                ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

                using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (MemoryStream msOutput = new MemoryStream())
                        {
                            csDecrypt.CopyTo(msOutput);
                            byte[] decryptedBytes = msOutput.ToArray();

                            if (returnString)
                            {
                                return Encoding.UTF8.GetBytes(Convert.ToBase64String(decryptedBytes));
                            }

                            return decryptedBytes;
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"Decryption failed: {ex.Message}");
            throw;
        }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        ILogger logger = new ConsoleLogger();
        AesCbcDecryptor decryptor = new AesCbcDecryptor(logger);

        // Example usage from command line arguments
        if (args.Length >= 4)
        {
            byte[] ciphertext = Convert.FromBase64String(args[0]);
            byte[] key = Convert.FromBase64String(args[1]);
            byte[] iv = Convert.FromBase64String(args[2]);
            bool returnString = args[3].Equals("string", StringComparison.OrdinalIgnoreCase);

            try
            {
                byte[] decryptedData = decryptor.Decrypt(ciphertext, key, iv, returnString);
                if (returnString)
                {
                    Console.WriteLine(Encoding.UTF8.GetString(decryptedData));
                }
                else
                {
                    Console.WriteLine(Convert.ToBase64String(decryptedData));
                }
            }
            catch (Exception ex)
            {
                logger.LogError($"Error: {ex.Message}");
            }
        }
        else
        {
            Console.WriteLine("Usage: AesCbcDecryptor <ciphertext> <key> <iv> [string|bytearray]");
        }
    }
}

public class ConsoleLogger : ILogger
{
    public void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    public void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
}
