from flask import Flask, request, jsonify, abort, g, make_response
from functools import wraps
from sqlalchemy.exc import SQLAlchemyError
import redis

app = Flask(__name__)
# Configure database connection
db = SQLAlchemy(app)
# Configure Redis for caching and rate limiting
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

def authenticate(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header or 'Bearer' not in auth_header:
            abort(401)
        # Implement authentication logic here
        g.user = get_user_from_token(auth_header.split()[1])
        return f(*args, **kwargs)
    return decorated_function

def optimistic_concurrency(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        resource_id = kwargs['id']
        etag = request.headers.get('If-Match')
        if etag != get_resource_etag(resource_id):
            abort(412)
        return f(*args, **kwargs)
    return decorated_function

def rate_limit(limit, period):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            key = 'rate-limit:' + request.remote_addr
            if redis_client.get(key) is not None:
                count = int(redis_client.get(key))
                if count >= limit:
                    abort(429)
                else:
                    redis_client.incr(key)
                    redis_client.expire(key, period)
            else:
                redis_client.set(key, 1)
                redis_client.expire(key, period)
            return f(*args, **kwargs)
        return decorated_function
    return decorator

@app.route('/resources/<int:id>', methods=['PUT'])
@authenticate
@optimistic_concurrency
def update_resource(id):
    try:
        resource = Resource.query.get_or_404(id)
        data = request.json
        if 'version' in data and data['version'] != resource.version:
            abort(409)
        resource.update(data)
        db.session.commit()
        return jsonify(resource.to_dict()), 200
    except SQLAlchemyError as e:
        db.session.rollback()
        abort(500)

