import random

class Graph:
    def __init__(self, min_vertices=2, max_vertices=10, edge_probability=0.5):
        self.min_vertices = min_vertices
        self.max_vertices = max_vertices
        self.edge_probability = edge_probability
        self.vertices = {}
        self.edges = {}

    def add_vertex(self, vertex_id, properties=None):
        if vertex_id in self.vertices:
            raise ValueError("Vertex ID already exists")
        self.vertices[vertex_id] = properties or {}

    def remove_vertex(self, vertex_id):
        if vertex_id not in self.vertices:
            raise ValueError("Vertex ID does not exist")
        for edge_id in list(self.edges.keys()):
            if vertex_id in self.edges[edge_id]:
                del self.edges[edge_id]
        del self.vertices[vertex_id]

    def add_edge(self, from_vertex, to_vertex, properties=None):
        if from_vertex not in self.vertices or to_vertex not in self.vertices:
            raise ValueError("Invalid vertex ID(s)")
        edge_id = f"{from_vertex}-{to_vertex}"
        if edge_id in self.edges:
            raise ValueError("Edge ID already exists")
        self.edges[edge_id] = properties or {}

    def remove_edge(self, from_vertex, to_vertex):
        edge_id = f"{from_vertex}-{to_vertex}"
        if edge_id not in self.edges:
            raise ValueError("Edge ID does not exist")
        del self.edges[edge_id]

    def get_vertex_count(self):
        return len(self.vertices)

    def get_edge_count(self):
        return len(self.edges)

    def get_neighbors(self, vertex_id):
        neighbors = []
        for edge_id in self.edges.keys():
            if vertex_id in edge_id:
                if vertex_id == edge_id.split('-')[0]:
                    neighbors.append(edge_id.split('-')[1])
                else:
                    neighbors.append(edge_id.split('-')[0])
