#include <iostream>
#include <string>
#include <fstream>
#include <ctime>
#include <openssl/md5.h> // For MD5 hashing

struct PathConfig {
    std::string dirPath;
    std::string fileType;
    bool useCustomHash;
};

int generateUniqueFilePath(const std::string &baseFilename, const struct PathConfig &config, std::string &uniqueFilePath) {
    if (baseFilename.empty()) {
        uniqueFilePath = "Error: Base filename is empty.";
        return -1;
    }

    std::string fullPath = config.dirPath + "/" + baseFilename + "." + config.fileType;
    if (!std::filesystem::exists(config.dirPath)) {
        uniqueFilePath = "Error: Directory path does not exist.";
        return -2;
    }

    char buffer[4097];
    time_t now = time(nullptr);
    std::string timestamp = std::to_string(now);

    unsigned char hash[MD5_DIGEST_LENGTH];
    if (config.useCustomHash) {
        // Implement custom hash function here
        // For demonstration, using MD5 as a placeholder for a custom hash function
        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, baseFilename.c_str(), baseFilename.length());
        MD5_Final(hash, &md5);
    } else {
        // Standard hash function (MD5)
        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, baseFilename.c_str(), baseFilename.length());
        MD5_Final(hash, &md5);
    }

    char *hashStr = (char *)malloc(33); // MD5 hash is 16 bytes, which gives 32 hex characters + null terminator
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&(hashStr[i*2]), "%02x", hash[i]);
    }

    std::string newFilename = baseFilename + "_" + timestamp + "_" + hashStr;
    delete[] hashStr;

    if (newFilename.length() > 4096) {
        uniqueFilePath = "Error: New filepath exceeds maximum length.";
        return -3;
    }

    uniqueFilePath = config.dirPath + "/" + newFilename;
    return 0;
}

int main() {
    PathConfig config = {"/path/to/directory", "txt", false};
    std::string baseFilename = "example";
    std::string uniqueFilePath;

    int result = generateUniqueFilePath(baseFilename, config, uniqueFilePath);
    if (result == 0) {
        std::cout << "Unique file path: " << uniqueFilePath << std::endl;
    } else {
        std::cerr << uniqueFilePath << std::endl;
    }

    return 0;
}
