```php
<?php

use League\OAuth2\Client\Provider\Facebook;
use League\OAuth2\Client\Provider\Google;
use League\OAuth2\Client\Provider\LinkedIn;
use Predis\Client as RedisClient;

class AuthController extends Controller
{
    private $providers = [
        'facebook' => Facebook::class,
        'google'   => Google::class,
        'linkedin' => LinkedIn::class,
    ];

    private $redis;

    public function __construct(RedisClient $redis)
    {
        $this->redis = $redis;
    }

    public function authenticate(Request $request)
    {
        $provider = $request->input('provider');
        if (!array_key_exists($provider, $this->providers)) {
            return response()->json(['error' => 'Invalid provider'], 400);
        }

        $client = new $this->providers[$provider]([
            'clientId'     => config("oauth.providers.$provider.client_id"),
            'clientSecret' => config("oauth.providers.$provider.client_secret"),
            'redirectUri'  => route('auth.callback', ['provider' => $provider]),
        ]);

        if (!empty($request->input('code'))) {
            try {
                $token = $client->getAccessToken('authorization_code', [
                    'code' => $request->input('code'),
                ]);

                $user = $client->getResourceOwner($token);
                $userId = $user->getId();

                session(['access_token' => $token->getToken()]);
                $this->redis->set("user:$userId:info", json_encode($user));
                $this->logAuthAttempt(true, $provider, $userId);

                return response()->json(['message' => 'Authentication successful']);
            } catch (\Exception $e) {
                $this->logAuthAttempt(false, $provider, null, $e->getMessage());
                return response()->json(['error' => 'Authentication failed'], 401);
            }
        }

        $authorizationUrl = $client->getAuthorizationUrl();
        session(['oauth2state' => $client->getState()]);
        return redirect($authorizationUrl);
    }

    public function callback(Request $request)
    {
        if (empty(session('oauth2state')) || $request->input('state') !== session('oauth2state')) {
            return response()->json(['error' => 'Invalid state'], 400);
        }

        return redirect()->route('auth.authenticate', ['provider' => $request->input('provider')]);
    }

    private function logAuthAttempt($success, $provider, $userId = null, $errorMessage = null)
    {
        $logEntry = [
            'timestamp'   => now()->toIso8601String(),
            'provider'    => $provider,
            'user_id'     => $userId,
            'success'     => $success,
            'error_message' => $errorMessage,
        ];

        Log::channel('auth')->info(json_encode($logEntry));
    }
}
