```csharp
using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class GameConfiguration
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public float CameraSpeed { get; set; }
}

public class ConfigurationLoader : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;
    private GameConfiguration _cachedConfig;
    private DateTime _lastFetchTime;

    public ConfigurationLoader(string apiUrl)
    {
        _httpClient = new HttpClient();
        _apiUrl = apiUrl;
        _lastFetchTime = DateTime.MinValue;
    }

    public async Task<GameConfiguration> LoadConfigurationAsync()
    {
        if (_lastFetchTime.AddSeconds(10) < DateTime.Now) // Cache for 10 seconds
        {
            try
            {
                var response = await _httpClient.GetAsync(_apiUrl);
                response.EnsureSuccessStatusCode();
                var json = await response.Content.ReadAsStringAsync();
                _cachedConfig = JsonConvert.DeserializeObject<GameConfiguration>(json);
                _lastFetchTime = DateTime.Now;
            }
            catch (HttpRequestException)
            {
                // Handle network error, return cached config if available
                if (_cachedConfig != null)
                {
                    return _cachedConfig;
                }
                else
                {
                    throw; // No cached config and no network response
                }
            }
        }

        return _cachedConfig;
    }

    public void Dispose()
    {
        _httpClient.Dispose();
    }
}

public class GameWorld
{
    private readonly ConfigurationLoader _configLoader;

    public GameWorld(ConfigurationLoader configLoader)
    {
        _configLoader = configLoader;
    }

    public async Task InitializeAsync()
    {
        var config = await _configLoader.LoadConfigurationAsync();
        // Use config to initialize game world dimensions and camera speed
    }
}

[TestClass]
public class ConfigurationLoaderTests
{
    [TestMethod]
    public async Task LoadConfigurationAsync_ShouldReturnValidConfigOnSuccess()
    {
        var mockClient = new Mock<HttpClient>();
        mockClient.Setup(client => client.GetAsync(It.IsAny<string>()))
            .ReturnsAsync(new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("{\"TileSize\":32,\"WorldWidth\":1024,\"WorldHeight\":768,\"CameraSpeed\":5.0}")
            });

        var configLoader = new ConfigurationLoader("http://example.com/api/config", mockClient.Object);
        var config = await configLoader.LoadConfigurationAsync();

        Assert.AreEqual(32, config.TileSize);
        Assert.AreEqual(1024, config.WorldWidth);
        Assert.AreEqual(768, config.WorldHeight);
        Assert.AreEqual(5.0f, config.CameraSpeed);
    }

    [TestMethod]
    public async Task LoadConfigurationAsync_ShouldUseCachedConfigOnNetworkFailure()
    {
        var mockClient = new Mock<HttpClient>();
        mockClient.Setup(client => client.GetAsync(It.IsAny<string>()))
            .ThrowsAsync(new HttpRequestException());

        var configLoader = new ConfigurationLoader("http://example.com/api/config", mockClient.Object);
        _ = await configLoader.LoadConfigurationAsync(); // Fetch initial config
        mockClient.Reset();

        mockClient.Setup(client => client.GetAsync(It.IsAny<string>()))
            .ThrowsAsync(new HttpRequestException());

        var cachedConfig = await configLoader.LoadConfigurationAsync();

        Assert.IsNotNull(cachedConfig);
    }

    [TestMethod]
    public async Task LoadConfigurationAsync_ShouldHandleInvalidJson()
    {
        var mockClient = new Mock<HttpClient>();
        mockClient.Setup(client => client.GetAsync(It.IsAny<string>()))
            .ReturnsAsync(new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("invalid json")
            });

        var configLoader = new ConfigurationLoader("http://example.com/api/config", mockClient.Object);
        await Assert.ThrowsExceptionAsync<JsonReaderException>(() => configLoader.LoadConfigurationAsync());
    }

    [TestMethod]
    public async Task LoadConfigurationAsync_ShouldReturnZeroConfigIfEmpty()
    {
        var mockClient = new Mock<HttpClient>();
        mockClient.Setup(client => client.GetAsync(It.IsAny<string>()))
            .ReturnsAsync(new HttpResponseMessage(HttpStatusCode.OK)
            {
