```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.net.URL;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class FileIntegrityVerifier {

    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB
    private static final Map<String, String> cache = new HashMap<>();

    public static void main(String[] args) {
        if (args.length != 2) {
            System.out.println("Usage: java FileIntegrityVerifier <file_path> <expected_hash>");
            return;
        }

        String filePath = args[0];
        String expectedHash = args[1];

        try {
            String actualHash = getMD5Hash(new File(filePath));
            if (actualHash.equals(expectedHash)) {
                System.out.println("File integrity verified.");
            } else {
                System.out.println("File integrity check failed. Expected: " + expectedHash + ", but got: " + actualHash);
            }
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

    public static String getMD5Hash(File file) throws IOException, NoSuchAlgorithmException {
        if (cache.containsKey(file.getAbsolutePath())) {
            return cache.get(file.getAbsolutePath());
        }

        MessageDigest md = MessageDigest.getInstance("MD5");
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }

        String hash = bytesToHex(md.digest());
        cache.put(file.getAbsolutePath(), hash);

        return hash;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```

This Java code snippet provides a basic implementation of the File Integrity Verification tool. It calculates the MD5 hash of a file and checks its integrity against an expected hash value provided as command-line arguments. The code includes error handling for file operations, MD5 calculation, and hashing service API availability. The caching mechanism is implemented using a `HashMap` to store recently computed hashes, which can be used to optimize performance when verifying multiple files.

Note that this solution assumes the existence of a network and a hashing service API. You may need to modify it according to your specific requirements and environment.

