```java
import java.util.concurrent.*;
import java.util.logging.Logger;

public class ServiceManager {
    private static final Logger LOGGER = Logger.getLogger(ServiceManager.class.getName());
    private ExecutorService executor;
    private int maxConcurrentServices;
    private long delay;
    private Random random;

    public ServiceManager(int maxConcurrentServices, long baseDelay) {
        this.maxConcurrentServices = maxConcurrentServices;
        this.delay = baseDelay;
        this.random = new Random();
        this.executor = Executors.newCachedThreadPool(r -> {
            Thread t = new Thread(r);
            t.setUncaughtExceptionHandler((t1, e) -> LOGGER.severe(e.getMessage()));
            return t;
        });
    }

    public void startService(Runnable serviceTask) {
        Future<?> future = executor.submit(() -> {
            try {
                long executionTime = delay + random.nextInt(2 * (int) delay);
                Thread.sleep(executionTime);
                serviceTask.run();
            } catch (InterruptedException e) {
                LOGGER.warning("Service interrupted: " + e.getMessage());
            }
        });

        if (executor.getActiveCount() >= maxConcurrentServices) {
            try {
                future.cancel(true);
                LOGGER.severe("Too many services running. Service not started.");
            } catch (Exception e) {
                LOGGER.severe("Error canceling service: " + e.getMessage());
            }
        }
    }

    public void stopAllServices() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}
