import java.util.concurrent.*;
import java.util.logging.Logger;

public class DatabaseManager {
    private static final Logger LOGGER = Logger.getLogger(DatabaseManager.class.getName());
    private ExecutorService dbExecutor;
    private BlockingQueue<Runnable> dbTaskQueue;
    private int maxConcurrentDBOperations;

    public DatabaseManager(int maxConcurrentDBOperations) {
        this.maxConcurrentDBOperations = maxConcurrentDBOperations;
        this.dbExecutor = Executors.newFixedThreadPool(maxConcurrentDBOperations, r -> {
            Thread t = new Thread(r);
            t.setUncaughtExceptionHandler((t1, e) -> LOGGER.severe(e.getMessage()));
            return t;
        });
        this.dbTaskQueue = new LinkedBlockingQueue<>();
    }

    public void executeDbOperation(Runnable dbTask) {
        try {
            dbExecutor.execute(dbTask);
        } catch (Exception e) {
            LOGGER.severe("Error executing DB operation: " + e.getMessage());
        }
    }

    public void shutdown() {
        dbExecutor.shutdown();
        try {
            if (!dbExecutor.awaitTermination(60, TimeUnit.SECONDS)) {
                dbExecutor.shutdownNow();
            }
        } catch (InterruptedException e) {
            dbExecutor.shutdownNow();
        }
    }
}
