int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: client <hostname> <port>" << std::endl;
        return 1;
    }

    boost::asio::io_context io_context;

    // Create a TCP socket and SSL context
    boost::asio::ip::tcp::socket socket(io_context);
    boost::asio::ssl::context ssl_context(boost::asio::ssl::context::sslv23);

    try {
        // Connect to the server
        boost::asio::ip::tcp::resolver resolver(io_context);
        auto endpoints = resolver.resolve(argv[1], argv[2]);
        boost::asio::connect(socket, endpoints);

        // Wrap the socket with SSL
        ssl_context.set_default_verify_paths();
        boost::asio::ssl::stream<boost::asio::ip::tcp::socket> ssl_socket(io_context, ssl_context);
        ssl_socket.lowest_layer().assign(socket.native_handle());
        ssl_socket.async_handshake(boost::asio::ssl::stream_base::client,
                                   [&](const boost::system::error_code& error) {
                                       if (!error) {
                                           // Send and receive messages here
                                       } else {
                                           std::cerr << "SSL handshake failed: " << error.message() << std::endl;
                                       }
                                   });

        io_context.run();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
