        table[key] = value;
        return true;
    }

    // Remove method implementation
    bool DHT::remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        if (table.find(key) != table.end()) {
            table.erase(key);
            return true;
        }
        return false;
    }

    // Lookup method implementation
    std::optional<std::string> DHT::lookup(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        if (table.find(key) != table.end()) {
            return table[key];
        }
        return std::nullopt;
