```cpp
#include <random>
#include <vector>
#include <mutex>
#include <atomic>
#include <iostream>

namespace RandomGenerator {
    class MT19937_RNG {
    public:
        static std::atomic<int> activeInstances;

        MT19937_RNG(unsigned long long seed = std::random_device{}()) : gen(seed), dist(0, 1000) {
            ++activeInstances;
            log("RNG initialized with seed: " + std::to_string(seed));
        }

        MT19937_RNG(const MT19937_RNG& other) : gen(other.gen), dist(other.dist) {
            ++activeInstances;
            log("RNG copied");
        }

        MT19937_RNG(MT19937_RNG&& other) noexcept : gen(std::move(other.gen)), dist(std::move(other.dist)) {
            ++activeInstances;
            log("RNG moved");
        }

        ~MT19937_RNG() noexcept {
            --activeInstances;
            log("RNG destroyed");
        }

        MT19937_RNG& operator=(const MT19937_RNG& other) {
            if (this != &other) {
                gen = other.gen;
                dist = other.dist;
                ++activeInstances;
                log("RNG assigned by copy");
            }
            return *this;
        }

        MT19937_RNG& operator=(MT19937_RNG&& other) noexcept {
            if (this != &other) {
                gen = std::move(other.gen);
                dist = std::move(other.dist);
                ++activeInstances;
                log("RNG assigned by move");
            }
            return *this;
        }

        std::vector<int> generate(int n) {
            std::vector<int> result(n);
            for (int& num : result) {
                num = dist(gen);
            }
            log("Generated random numbers: " + formatVector(result));
            return result;
        }

        unsigned long long getSeed() const {
            return gen.seed();
        }

        void setSeed(unsigned long long seed) {
            gen.seed(seed);
            log("RNG seed updated to: " + std::to_string(seed));
        }

    private:
        std::mt19937 gen;
        std::uniform_int_distribution<> dist;
        static std::mutex logMutex;

        void log(const std::string& message) {
            std::lock_guard<std::mutex> lock(logMutex);
            std::cout << "Log: " << message << std::endl;
        }

        static std::string formatVector(const std::vector<int>& vec) {
            std::string result = "{";
            for (size_t i = 0; i < vec.size(); ++i) {
                if (i > 0) result += ", ";
                result += std::to_string(vec[i]);
            }
            result += "}";
            return result;
        }
    };

    std::atomic<int> MT19937_RNG::activeInstances = 0;
    std::mutex MT19937_RNG::logMutex;
}
