using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

public class AdvancedSqlQueryExecutor
{
    private readonly Dictionary<string, string> queryCache = new Dictionary<string, string>();
    private readonly object cacheLock = new object();
    private readonly string metadataApiUrl = "https://metadataapi.example.com";

    public async Task<DataTable> ExecuteDynamicQueryAsync(List<KeyValuePair<string, string>> filters, string connectionString, string baseQueryTemplate)
    {
        var queryKey = GenerateQueryKey(filters);
        string sqlQuery;

        lock (cacheLock)
        {
            if (!queryCache.TryGetValue(queryKey, out sqlQuery))
            {
                sqlQuery = await FetchAndCacheQueryAsync(filters, baseQueryTemplate);
            }
        }

        using (var connection = new SqlConnection(connectionString))
        {
            using (var command = new SqlCommand(sqlQuery, connection))
            {
                try
                {
                    await connection.OpenAsync();
                    using (var adapter = new SqlDataAdapter(command))
                    {
                        var dataTable = new DataTable();
                        await adapter.FillAsync(dataTable);
                        return dataTable;
                    }
                }
                catch (Exception ex)
                {
                    LogError(ex);
                    throw;
                }
            }
        }
    }

    private async Task<string> FetchAndCacheQueryAsync(List<KeyValuePair<string, string>> filters, string baseQueryTemplate)
    {
        var metadata = await FetchMetadataFromApiAsync(filters);
        var sqlBuilder = new System.Text.StringBuilder(baseQueryTemplate);

        foreach (var filter in filters)
        {
            if (metadata.ContainsKey(filter.Key))
            {
                sqlBuilder.Replace("{" + filter.Key + "}", $"@{filter.Key}");
            }
        }

        lock (cacheLock)
        {
            queryCache[queryKey] = sqlBuilder.ToString();
        }

        return sqlBuilder.ToString();
    }

    private async Task<Dictionary<string, string>> FetchMetadataFromApiAsync(List<KeyValuePair<string, string>> filters)
    {
        var metadataUrl = $"{metadataApiUrl}?columns={string.Join(",", filters.Select(f => f.Key))}";
        using (var client = new HttpClient())
        {
            try
            {
                var response = await client.GetAsync(metadataUrl);
                response.EnsureSuccessStatusCode();
                var content = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<Dictionary<string, string>>(content);
            }
            catch (Exception ex)
            {
                LogError(ex, "Failed to fetch metadata from API.");
                return new Dictionary<string, string>();
            }
        }
    }

    private string GenerateQueryKey(List<KeyValuePair<string, string>> filters)
    {
        return string.Join(",", filters.Select(f => $"{f.Key}={f.Value}"));
    }

    private void LogError(Exception ex, string message = null)
    {
        // Implement error logging logic here
        Console.WriteLine($"{DateTime.Now}: {message ?? "An error occurred."}");
    }
}
