        fclose(log_file);

        // Rotate logs if they exceed 1MB
        struct stat file_stat;
        if (stat("app.log", &file_stat) == 0 && file_stat.st_size > MAX_LOG_SIZE) {
            rename("app.log", "app.log.old");
        }
    }
}

void* process_string(void* args) {
