        log_message("Configuration file not found or unreadable.", "error");
        pthread_exit(NULL);
    }

    Config config;
    fscanf(config_file, "%d", &config.limit);

    fclose(config_file);

    int current_len = strlen(input_str);
    char* result = malloc(current_len + 2); // Extra space for slash and null terminator

    if (current_len < size_limit) {
        strcpy(result, input_str);
        strcat(result, "/");
