        return NULL;
    }

    // Allocate memory for the array of records
    Record* records = malloc(count * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize each record with dynamic memory and default values
    for (size_t i = 0; i < count; ++i) {
        records[i].data = malloc(sizeof(int));
        if (!records[i].data) {
            perror("Memory allocation failed for record data");
            // Free previously allocated records
            for (size_t j = 0; j < i; ++j) {
                free(records[j].data);
