use std::env;
use std::fs::{create_dir, create_dir_all};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread::sleep;
use std::time::{Duration, Instant};

static RETRY_COUNT: AtomicUsize = AtomicUsize::new(3);

fn create_or_update_dir(
    dir_name: &str,
    parent_path: Option<&Path>,
    max_depth: usize,
) -> Result<PathBuf, String> {
    validate_dir_name(dir_name)?;
    let mut path = if let Some(parent) = parent_path {
        ensure_max_depth(&parent, max_depth)?;
        parent.join(dir_name)
    } else {
        Path::new(dir_name).to_path_buf()
    };

    for attempt in 0..RETRY_COUNT.load(Ordering::SeqCst) {
        match create_dir_all(&path) {
            Ok(_) => {
                set_env_variable("MY_DIR", &path);
                log_action("Created directory", &path);
                return Ok(path);
            }
            Err(e) if e.kind() == std::io::ErrorKind::PermissionDenied => {
                let backoff = Duration::from_secs(2u64.pow(attempt as u32));
                sleep(backoff);
            }
            Err(_) => break,
        }
    }

    // Fallback mechanism
    let mut attempt = 0;
    loop {
        let unique_name = generate_unique_name(dir_name, &mut attempt);
        path = if let Some(parent) = parent_path {
            ensure_max_depth(&parent, max_depth)?;
            parent.join(unique_name)
        } else {
            Path::new(&unique_name).to_path_buf()
        };

        match create_dir_all(&path) {
            Ok(_) => {
                set_env_variable("MY_DIR", &path);
                log_action("Created directory (fallback)", &path);
                return Ok(path);
            }
            Err(e) if e.kind() == std::io::ErrorKind::PermissionDenied => {
                let backoff = Duration::from_secs(2u64.pow(attempt as u32));
                sleep(backoff);
                attempt += 1;
            }
            Err(_) => break,
        }
    }

    log_action("Failed to create directory", &path);
    Err(format!("Failed to create or update directory: {}", path.display()))
}

fn validate_dir_name(dir_name: &str) -> Result<(), String> {
    if dir_name.chars().all(|c| c.is_alphanumeric() || c == '_') {
        Ok(())
    } else {
        Err("Invalid directory name".to_string())
    }
}

fn ensure_max_depth(parent_path: &Path, max_depth: usize) -> Result<(), String> {
    let depth = parent_path.components().count();
    if depth >= max_depth {
        Err(format!("Exceeded maximum path depth of {}", max_depth))
    } else {
        Ok(())
    }
}

fn generate_unique_name(base_name: &str, attempt: &mut usize) -> String {
    format!("{}_{}", base_name, attempt)
}

fn set_env_variable(name: &str, value: &Path) {
    env::set_var(name, value.to_str().unwrap());
}

fn log_action(action: &str, path: &Path) {
    println!("{}: {}", action, path.display());
}
