// src/lib.rs

mod elasticsearch;
mod splunk;

use std::collections::HashMap;
use std::env;
use std::sync::{Arc, Mutex};
use tokio::sync::mpsc;
use tokio::task;

pub struct Logger {
    config: Config,
    sender: mpsc::Sender<LogEvent>,
}

struct Config {
    elasticsearch_url: String,
    splunk_url: String,
    log_format: LogFormat,
    retry_count: usize,
}

enum LogFormat {
    JSON,
    Syslog,
    PlainText,
}

struct LogEvent {
    timestamp: chrono::Local,
    level: LogLevel,
    message: String,
    fields: HashMap<String, String>,
}

#[derive(Debug)]
enum LogLevel {
    Error,
    Warn,
    Info,
    Debug,
}

impl Logger {
    pub fn new() -> Self {
        let config = Config {
            elasticsearch_url: env::var("ELASTICSEARCH_URL").unwrap_or_else(|_| "http://localhost:9200".to_string()),
            splunk_url: env::var("SPLUNK_URL").unwrap_or_else(|_| "http://localhost:8080/services/collector".to_string()),
            log_format: LogFormat::JSON,
            retry_count: 3,
        };

        let (sender, receiver) = mpsc::channel(100);
        task::spawn(Logger::send_logs(receiver, config.retry_count));

        Logger { config, sender }
    }

    pub async fn log(&self, level: LogLevel, message: String, fields: HashMap<String, String>) {
        let event = LogEvent {
            timestamp: chrono::Local::now(),
            level,
            message,
            fields,
        };
        if self.sender.send(event).is_err() {
            eprintln!("Failed to send log event");
        }
    }

    async fn send_logs(receiver: mpsc::Receiver<LogEvent>, retry_count: usize) {
        let client = reqwest::Client::new();
        while let Some(mut event) = receiver.recv().await {
            for _ in 0..retry_count {
                match event.format(&event.log_format) {
                    Ok(log_data) => {
                        if event.send_to_elasticsearch(&client).is_err() {
                            continue;
                        }
                        break;
                    }
                    Err(e) => {
                        eprintln!("Failed to format log event: {}", e);
                        return;
                    }
                }
            }
        }
    }

    fn format(&self, event: &LogEvent) -> Result<String, String> {
        match self.config.log_format {
            LogFormat::JSON => serde_json::to_string(event).map_err(|e| e.to_string()),
            LogFormat::Syslog => {
                let mut log_line = format!("{} {} ", chrono::Local::now().format("%Y-%m-%dT%H:%M:%S%z"), event.level);
                if let Some(msg) = event.message.strip_prefix("rust:") {
                    log_line.push_str(msg);
                } else {
                    log_line.push_str(&event.message);
                }
                Ok(log_line)
            }
            LogFormat::PlainText => Ok(format!("{} {} {}\n", chrono::Local::now(), event.level, event.message)),
        }
    }

    fn send_to_elasticsearch(&self, client: &reqwest::Client) -> Result<(), String> {
        // Implementation to send log event to Elasticsearch
        unimplemented!()
    }

    fn send_to_splunk(&self, client: &reqwest::Client) -> Result<(), String> {
        // Implementation to send log event to Splunk
        unimplemented!()
    }
}

// src/elasticsearch.rs

mod elasticsearch {
    use super::*;
    impl Logger {
        fn send_to_elasticsearch(&self, client: &reqwest::Client) -> Result<(), String> {
            let url = format!("{}/logs", self.config.elasticsearch_url);
            let response = client.post(&url).json(&event).send().await;
            if response.is_err() {
                return Err(format!("Failed to send log event to Elasticsearch: {:?}", response.err()));
            }
            Ok(())
        }
    }
}

// src/splunk.rs

mod splunk {
    use super::*;
    impl Logger {
        fn send_to_splunk(&self, client: &reqwest::Client) -> Result<(), String> {
            let url = format!("{}/services/collector", self.config.splunk_url);
            let response = client.post(&url).json(&event).send().await;
            if response.is_err() {
                return Err(format!("Failed to send log event to Splunk: {:?}", response.err()));
            }
