// Define constants for maximum line length, field lengths, and number of fields
#define MAX_LINE_LENGTH 1024
#define FIELD_LENGTH 50
#define NUM_FIELDS 7

// Function prototypes
void read_csv(const char *file_path);
void parse_line(char *line, double *grades);
double calculate_average(double grade1, double grade2);
int update_database(int student_id, int course_id, double average_grade);

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <input_csv> <database_type> <grade_type>\n", argv[0]);
        return 1;
    }

    const char *file_path = argv[1];
    int grade_type = strcmp(argv[3], "assignment_exam") == 0 ? 0 : 1;

    // Initialize database connection
    if (!initialize_database(argv[2])) {
        fprintf(stderr, "Failed to initialize database connection.\n");
        return 1;
    }

    read_csv(file_path);

    // Close database connection
    close_database();

    return 0;
}

void read_csv(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        double grades[NUM_FIELDS];
        parse_line(line, grades);

        int student_id = (int)grades[0];
        int course_id = (int)grades[1];
        double average_grade = calculate_average(grades[grade_type * 2], grades[(grade_type + 1) * 2]);

        if (!update_database(student_id, course_id, average_grade)) {
            fprintf(stderr, "Failed to update database for student ID %d and course ID %d.\n", student_id, course_id);
        }
    }

    fclose(file);
}

void parse_line(char *line, double *grades) {
    char *token = strtok(line, ",");
    int field_index = 0;

    while (token != NULL && field_index < NUM_FIELDS) {
        if (field_index == 2 || field_index >= grade_type * 2 + 1) { // Skip non-grade fields and additional notes
            grades[field_index] = atof(token);
        }
        token = strtok(NULL, ",");
        field_index++;
    }

    if (field_index < NUM_FIELDS) {
        fprintf(stderr, "Line is missing fields: %s\n", line);
    }
}

double calculate_average(double grade1, double grade2) {
    return (grade1 + grade2) / 2;
}

