        response = requests.put(f"https://api.example.com/products/{product.name}/inventory", json=data)
        if response.status_code != 200:
            print("Error: Failed to update inventory for product.")
            return False
        return True

    products = []
    for i in range(num_products):
        product_id = f"Product{i+1}"
        product_details = fetch_product_details(product_id)
        if not product_details:
            continue

        name = product_details.get('name')
        price = product_details.get('price', 0.0)
        inventory = product_details.get('inventory', 0)

        if inventory <= 0:
            print(f"Warning: Product {product_id} is out of stock and will not be added to the list.")
            continue

        product = Product(name, price, inventory)
        products.append(product)

        if not update_inventory(product):
            products.pop()  # Remove the product from the list if inventory update fails

    return 0, products
