    ImageInfo image_info;
} Result;

enum Error {
    OK,
    ERROR_UNSUPPORTED_BIT_DEPTH,
    ERROR_OAUTH_FAILURE,
    ERROR_KEY_RETRIEVAL,
    ERROR_CERTIFICATE_COMBINATION
};

Result parse_tiff_and_authenticate(const char *tiff_file_path, const char *oauth_endpoint) {
    Result result = {NULL, {0, 0}};
    enum Error error = OK;

    // Parse TIFF file and extract information
    // (Assuming a function `parse_tiff` exists to do this)
    ImageInfo image_info = parse_tiff(tiff_file_path);
    if (image_info.bits_per_sample != 1 && image_info.bits_per_sample != 2 &&
        image_info.bits_per_sample != 4 && image_info.bits_per_sample != 8 &&
        image_info.bits_per_sample != 16) {
        error = ERROR_UNSUPPORTED_BIT_DEPTH;
        goto cleanup;
    }

    // Initialize libcurl
    CURL *curl;
    CURLcode res;
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        // Make OAuth request
        // (Assuming a function `make_oauth_request` exists to do this)
        char *oauth_response = make_oauth_request(oauth_endpoint, headers);
        if (!oauth_response) {
            error = ERROR_OAUTH_FAILURE;
            goto cleanup;
        }

        // Extract private key and certificate from OAuth response
        // (Assuming a function `extract_key_cert` exists to do this)
        char *private_key = NULL;
        char *certificate = NULL;
        if (!extract_key_cert(oauth_response, &private_key, &certificate)) {
            error = ERROR_KEY_RETRIEVAL;
            goto cleanup;
        }

        // Combine private key and certificate into PEM file
        // (Assuming a function `combine_pem` exists to do this)
        char *pem_file_path = "/tmp/image.pem";
        if (!combine_pem(private_key, certificate, pem_file_path)) {
            error = ERROR_CERTIFICATE_COMBINATION;
            goto cleanup;
        }

        result.certificate_pem = load_certificate_pem(pem_file_path);
        result.image_info = image_info;

cleanup:
        // Free resources
        free(oauth_response);
        free(private_key);
        free(certificate);
        curl_slist_free_all(headers);
        if(curl) {
            curl_easy_cleanup(curl);
        }
    }

    return result;
}

// Example usage
int main() {
    Result result = parse_tiff_and_authenticate("path/to/image.tiff", "https://oauth.example.com/token");
    if (result.certificate_pem) {
        printf("Certificate:\n%s\n", result.certificate_pem);
        free(result.certificate_pem);
    } else {
        printf("Error: %d\n", result.error);
    }
    return 0;
}
