namespace DHT {

    class DistributedHashTable {
    public:
        static std::hash<std::string> custom_hash;

        DistributedHashTable(size_t capacity, size_t node_id) : capacity_(capacity), node_id_(node_id) {}

        ~DistributedHashTable() = default;

        void insert(const std::string& key, const std::string& value) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (data_.size() < capacity_) {
                data_[key] = value;
                cv_.notify_all();
            }
        }

        bool erase(const std::string& key) {
            std::lock_guard<std::mutex> lock(mutex_);
            auto it = data_.find(key);
            if (it != data_.end()) {
                data_.erase(it);
                return true;
            }
            return false;
        }

        std::optional<std::string> lookup(const std::string& key) {
            std::lock_guard<std::mutex> lock(mutex_);
            auto it = data_.find(key);
            if (it != data_.end()) {
                return it->second;
            }
            return std::nullopt;
        }

        void flush_to_redis() {
            // Implement flushing to Redis here
        }

    private:
        std::unordered_map<std::string, std::string> data_;
        size_t capacity_;
        size_t node_id_;
        mutable std::mutex mutex_;
        std::condition_variable cv_;
        std::atomic<bool> running_{true};
    };

    std::hash<std::string> DistributedHashTable::custom_hash;

}

