import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class ChatServer {

    private Selector selector;
    private SocketChannel serverSocketChannel;

    public ChatServer(int port) throws IOException {
        selector = Selector.open();
        serverSocketChannel = SocketChannel.open(new InetSocketAddress(port));
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);
    }

    public void start() throws IOException {
        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> iterator = selectedKeys.iterator();

            while (iterator.hasNext()) {
                SelectionKey key = iterator.next();

                if (key.isAcceptable()) {
                    accept(key);
                } else if (key.isReadable()) {
                    read(key);
                }

                iterator.remove();
            }
        }
    }

    private void accept(SelectionKey key) throws IOException {
        SocketChannel clientSocketChannel = ((ServerSocketChannel) key.channel()).accept();
        clientSocketChannel.configureBlocking(false);
        clientSocketChannel.register(selector, SelectionKey.OP_READ);
    }

    private void read(SelectionKey key) throws IOException {
        SocketChannel clientSocketChannel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        int bytesRead = clientSocketChannel.read(buffer);

        if (bytesRead == -1) {
            clientSocketChannel.close();
        } else if (bytesRead > 0) {
            processMessage(clientSocketChannel, buffer);
        }
    }

    private void processMessage(SocketChannel clientSocketChannel, ByteBuffer buffer) throws IOException {
        // Process the message and send a response
        String message = new String(buffer.array(), 0, buffer.position());
        System.out.println("Received message: " + message);

        // Send a response back to the client
        String response = "Message received!";
        ByteBuffer responseBuffer = ByteBuffer.wrap(response.getBytes());
        clientSocketChannel.write(responseBuffer);
    }

    public static void main(String[] args) {
        try {
            ChatServer chatServer = new ChatServer(8080);
            chatServer.start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
