import re
from datetime import datetime
import requests

def validate_timestamp(timestamp):
    return bool(re.match(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}', timestamp))

def is_valid_reading(reading, min_value=-50, max_value=50):
    return min_value <= reading <= max_value

def get_historical_weather(timestamp, location):
    api_key = 'your_api_key_here'
    url = f"http://api.weatherapi.com/v1/history.json?key={api_key}&q={location}&dt={timestamp}"
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.json().get('forecast', {}).get('forecastday', [{}])[0].get('hour', [])
    except (requests.RequestException, KeyError):
        return []

def analyze_sensor_data(file_path=None):
    sensor_readings = []

    if file_path:
        with open(file_path, 'r') as file:
            for line in file:
                parts = line.strip().split()
                if len(parts) == 2:
                    timestamp, reading_str = parts
                    try:
                        reading = float(reading_str)
                        if validate_timestamp(timestamp) and is_valid_reading(reading):
                            sensor_readings.append((timestamp, reading))
                        else:
                            print(f"Invalid entry: {line}")
                    except ValueError:
                        print(f"Malformed data in line: {line}")
    else:
        for line in iter(input, ""):
            parts = line.strip().split()
            if len(parts) == 2:
                timestamp, reading_str = parts
                try:
                    reading = float(reading_str)
                    if validate_timestamp(timestamp) and is_valid_reading(reading):
                        sensor_readings.append((timestamp, reading))
                    else:
                        print(f"Invalid entry: {line}")
                except ValueError:
                    print(f"Malformed data in line: {line}")

    if not sensor_readings:
        print("No valid readings found.")
        return

    max_reading = max(sensor_readings, key=lambda x: x[1])
    print(f"Maximum Sensor Reading: {max_reading[1]} at {max_reading[0]}")

    location = 'your_location_here'  # Replace with actual location
    historical_weather = get_historical_weather(max_reading[0], location)

    for entry in historical_weather:
        diff_temp = abs(entry['temp_c'] - max_reading[1])
        if diff_temp > 5:
            print(f"Significantly different from historical data: {max_reading[1]} at {max_reading[0]}, "
                  f"Historical temp: {entry['temp_c']}, Timestamp: {entry['time']}")

# Example usage
analyze_sensor_data('sensor_data.txt')
