use async_trait::async_trait;
use std::sync::{Arc, Mutex};
use tokio::sync::mpsc;

#[async_trait]
trait ExternalAPIClient {
    async fn fetch_grammar(&self, grammar_id: &str) -> Result<String, String>;
    async fn validate_file(&self, file_path: &str) -> Result<(), String>;
}

struct MockAPI {
    grammars: Arc<Mutex<Vec<(String, String)>>>,
}

#[async_trait]
impl ExternalAPIClient for MockAPI {
    async fn fetch_grammar(&self, grammar_id: &str) -> Result<String, String> {
        if let Some(grammars) = self.grammars.lock().unwrap().iter().find(|(_, id)| id == grammar_id) {
            Ok(grammars.0.clone())
        } else {
            Err(format!("Grammar not found for ID {}", grammar_id))
        }
    }

    async fn validate_file(&self, file_path: &str) -> Result<(), String> {
        // Simulate file validation
        if file_path.ends_with(".rs") {
            Ok(())
        } else {
            Err(format!("Invalid file type: {}", file_path))
        }
    }
}

struct DynamicCodeCompiler {
    api_client: Box<dyn ExternalAPIClient>,
    cache: Arc<Mutex<Vec<(String, String)>>>,
    sender: mpsc::Sender<String>,
}

impl DynamicCodeCompiler {
    fn new(api_client: Box<dyn ExternalAPIClient>, sender: mpsc::Sender<String>) -> Self {
        DynamicCodeCompiler {
            api_client,
            cache: Arc::new(Mutex::new(Vec::new())),
            sender,
        }
    }

    async fn compile_file(&self, file_path: &str) -> Result<(), String> {
        if let Err(e) = self.api_client.validate_file(file_path).await {
            return Err(e);
        }

        // Fetch or use cached grammar
        let grammar_id = "rust_grammar".to_string();
        let mut cache = self.cache.lock().unwrap();
        if let Some(gram) = cache.iter().find(|(_, id)| *id == grammar_id) {
            println!("Using cached grammar");
        } else {
            println!("Fetching new grammar");
            let gram = self.api_client.fetch_grammar(&grammar_id).await?;
            cache.push((gram, grammar_id.clone()));
        }

        // Simulate compilation process
        println!("Compiling file: {}", file_path);
        self.sender.send(format!("Compilation of {} successful", file_path)).await?;

        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let (sender, mut receiver) = mpsc::channel(100);
    let api_client = Box::new(MockAPI {
        grammars: Arc::new(Mutex::new(vec![("rust_grammar".to_string(), "Rust grammar".to_string())])),
    });
    let compiler = DynamicCodeCompiler::new(api_client, sender);

    // Simulate file compilation
    compiler.compile_file("example.rs").await.unwrap();

    while let Some(msg) = receiver.recv().await {
        println!("{}", msg);
    }
}
