#include <iostream>
#include <vector>
#include <string>
#include <fstream>
#include <memory>
#include <unordered_map>
#include <mutex>

struct Employee {
    int id;
    char* name;
    char* department;
};

class BinaryEmployeeSerializer {
public:
    void Serialize(const std::vector<Employee>& employees, const std::string& filename) {
        std::ofstream ofs(filename, std::ios::binary);
        if (!ofs.is_open()) {
            std::cerr << "Failed to open file for writing." << std::endl;
            return;
        }

        int size = employees.size();
        ofs.write(reinterpret_cast<char*>(&size), sizeof(size));

        for (const auto& emp : employees) {
            ofs.write(reinterpret_cast<char*>(&emp.id), sizeof(emp.id));
            size_t nameLen = strlen(emp.name);
            ofs.write(reinterpret_cast<char*>(&nameLen), sizeof(nameLen));
            ofs.write(emp.name, nameLen);

            size_t deptLen = strlen(emp.department);
            ofs.write(reinterpret_cast<char*>(&deptLen), sizeof(deptLen));
            ofs.write(emp.department, deptLen);
        }

        ofs.close();
    }

    std::vector<Employee> Deserialize(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::binary);
        if (!ifs.is_open()) {
            std::cerr << "Failed to open file for reading." << std::endl;
            return {};
        }

        int size;
        ifs.read(reinterpret_cast<char*>(&size), sizeof(size));

        std::vector<Employee> employees(size);
        for (auto& emp : employees) {
            ifs.read(reinterpret_cast<char*>(&emp.id), sizeof(emp.id));
            size_t nameLen;
            ifs.read(reinterpret_cast<char*>(&nameLen), sizeof(nameLen));
            emp.name = new char[nameLen + 1];
            ifs.read(emp.name, nameLen);
            emp.name[nameLen] = '\0';

            size_t deptLen;
            ifs.read(reinterpret_cast<char*>(&deptLen), sizeof(deptLen));
            emp.department = new char[deptLen + 1];
            ifs.read(emp.department, deptLen);
            emp.department[deptLen] = '\0';
        }

        ifs.close();
        return employees;
    }

    void CacheEmployee(const Employee& emp) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[emp.id] = emp;
        if (cache_.size() > cacheSize_) {
            EvictLRURecord();
        }
    }

private:
    std::unordered_map<int, Employee> cache_;
    size_t cacheSize_ = 100; // Example cache size
    std::mutex mutex_;

    void EvictLRURecord() {
        // Implement LRU eviction logic here
    }
};
