import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.CompletableFuture;

public class StateLoader {

    public MoSTState loadStateFromFile(String filePath) throws CustomException {
        try {
            // Asynchronously load the state object from the file
            CompletableFuture<MoSTState> future = CompletableFuture.supplyAsync(() -> {
                try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
                    Object obj = ois.readObject();
                    if (obj instanceof MoSTState) {
                        return (MoSTState) obj;
                    } else {
                        return null;
                    }
                } catch (IOException | ClassNotFoundException e) {
                    throw new CustomException("Failed to load state from file: " + filePath, e);
                }
            });

            // Wait for the future to complete and handle exceptions
            MoSTState state = future.get();
            if (state == null) {
                throw new CustomException("Loaded object is not an instance of MoSTState");
            }
            return state;

        } catch (InterruptedException | ExecutionException e) {
            throw new CustomException("Error while loading state asynchronously", e);
        }
    }

    private static class CustomException extends Exception {
        public CustomException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
