package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

type StockUpdate struct {
	Symbol string `json:"symbol"`
	Price  float64 `json:"price"`
	Timestamp int64 `json:"timestamp"`
}

var stockUpdates = make(chan StockUpdate)
var mu sync.Mutex

func main() {
	go handleWebSocketConnection()
	http.HandleFunc("/api/stock_prices", getStockPrices)
	http.ListenAndServe(":8080", nil)
}

func handleWebSocketConnection() {
	server := http.Server{Addr: ":8081"}
	log.Println("Starting WebSocket server on :8081")
	err := server.ListenAndServeTLS("", "")
	if err != nil {
		log.Fatal(err)
	}
}

func getStockPrices(w http.ResponseWriter, r *http.Request) {
	symbol := r.URL.Query().Get("symbol")
	page := r.URL.Query().GetInt("page")
	limit := r.URL.Query().GetInt("limit")

	db := connectToDatabase()
	query := "SELECT symbol, price, timestamp FROM stock_prices WHERE symbol = $1 ORDER BY timestamp DESC LIMIT $2 OFFSET $3"
	rows, err := db.Query(query, symbol, limit, (page-1)*limit)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []StockUpdate
	for rows.Next() {
		var update StockUpdate
		err := rows.Scan(&update.Symbol, &update.Price, &update.Timestamp)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		results = append(results, update)
	}

	json.NewEncoder(w).Encode(results)
}
