from functools import wraps
import time

app = Flask(__name__)

# Configuration variables
NER_API_URL = "https://api.example.com/ner"
LOCAL_MODEL_PATH = "/path/to/local/model"
FEEDBACK_QUEUE = []

# Rate limiting configuration
REQUEST_LIMIT = 100
TIME_WINDOW = 60

def rate_limit(limit=REQUEST_LIMIT, window=TIME_WINDOW):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            current_time = time.time()
            request_times = [t for t in FEEDBACK_QUEUE if current_time - t < window]

            if len(request_times) >= limit:
                return jsonify({"error": "Rate limit exceeded"}), 429

            FEEDBACK_QUEUE.append(current_time)
            return func(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/ner', methods=['POST'])
@rate_limit()
def ner_service():
    try:
        text = request.json.get('text')
        if not text:
            return jsonify({"error": "Text is required"}), 400

        response = requests.post(NER_API_URL, json={'text': text})

        if response.status_code == 200:
            return jsonify(response.json())
        else:
