# Import necessary libraries
import json
import requests
from concurrent.futures import ThreadPoolExecutor
import re

# Define a function to validate book names against the external API
def validate_book_name(book_name):
    api_url = "https://api.example.com/bible/books"
    response = requests.get(f"{api_url}/{book_name}")
    if response.status_code == 200:
        return True
    return False

# Define a function to process book mentions in text
def process_text(text):
    books_counted = {}
    book_pattern = re.compile(r'\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiahus|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk/Zephaniah/Haggai/Solomon/Ezra/Haggai/Zechariah/Malachi)\b')
    books = book_pattern.findall(text)

    for book in books:
        if validate_book_name(book):
            books_counted[book] = books_counted.get(book, 0) + 1

    return books_counted

# Define a function to handle multiple text files concurrently
def process_files(file_paths):
    results = {}
    with ThreadPoolExecutor(max_workers=5) as executor:
        future_to_file = {executor.submit(process_text, open(path, 'r').read()): path for path in file_paths}
        for future in concurrent.futures.as_completed(future_to_file):
            path = future_to_file[future]
            try:
                results[path] = future.result()
            except Exception as e:
                print(f"An error occurred while processing {path}: {e}")
    return results

# Example usage
file_paths = ['text1.txt', 'text2.txt', 'text3.txt']
results = process_files(file_paths)
print(json.dumps(results, indent=4))
