public class DynamicNetworkSimulator
{
    private Dictionary<string, Node> nodes;
    private Dictionary<(string, string), Connection> connections;
    private Dictionary<string, Tenant> tenants;

    public DynamicNetworkSimulator()
    {
        nodes = new Dictionary<string, Node>();
        connections = new Dictionary<(string, string), Connection>();
        tenants = new Dictionary<string, Tenant>();
    }

    // Real-Time Network Topology Updates
    public void AddNode(string nodeId, double x, double y)
    {
        if (!nodes.ContainsKey(nodeId))
        {
            nodes[nodeId] = new Node { Id = nodeId, X = x, Y = y };
        }
    }

    public void RemoveNode(string nodeId)
    {
        if (nodes.ContainsKey(nodeId))
        {
            nodes.Remove(nodeId);
            foreach (var connection in connections.Keys.ToList())
            {
                if (connection.Item1 == nodeId || connection.Item2 == nodeId)
                {
                    RemoveConnection(connection.Item1, connection.Item2);
                }
            }
        }
    }

    public void AddConnection(string sourceNodeId, string targetNodeId, double weight)
    {
        if (nodes.ContainsKey(sourceNodeId) && nodes.ContainsKey(targetNodeId))
        {
            connections[(sourceNodeId, targetNodeId)] = new Connection { SourceId = sourceNodeId, TargetId = targetNodeId, Weight = weight };
        }
    }

    public void RemoveConnection(string sourceNodeId, string targetNodeId)
    {
        if (connections.ContainsKey((sourceNodeId, targetNodeId)))
