// Function to run a command in the background
int runCommandInBackground(const std::string& command) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command.c_str(), nullptr);
        exit(1); // Exit if execl fails
    } else if (pid > 0) {
        // Parent process
        wait(nullptr);
        return 1;
    }
    return 0;
}

// Function to initialize an octree with cryptographic primitives
void initializeOctreeWithCryptoPrimitives(int featureSize, int numLeafNodes, int maxDepth) {
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<std::thread> threads;

    // Locking mechanism for thread safety
    std::unique_lock<std::mutex> lock(mutex);

    // Simulate octree node creation and deletion
    for (int i = 0; i < numLeafNodes; ++i) {
        threads.emplace_back([&mutex, &cv]() {
            // Simulate key generation from KMS
            unsigned char aesKey[32];
            if (!RAND_bytes(aesKey, sizeof(aesKey))) {
                std::cerr << "Error generating AES key" << std::endl;
                return;
            }

            // Log key generation
            std::cout << "AES Key generated: ";
            for (int j = 0; j < sizeof(aesKey); ++j) {
                std::cout << std::hex << static_cast<int>(aesKey[j]);
            }
            std::cout << std::endl;

            // Simulate hash verification
            unsigned char expectedHash[32];
            unsigned char generatedHash[32];
            // Generate actual hashes here using EVP functions

            if (memcmp(expectedHash, generatedHash, sizeof(generatedHash)) != 0) {
                std::cerr << "Error in hash verification" << std::endl;
                return;
            }

            // Log hash verification
            std::cout << "Hash verified successfully" << std::endl;

            // Signal that the thread has completed its task
            cv.notify_one();
        });
    }

    // Wait for all threads to complete
    for (auto& t : threads) {
        t.join();
    }

    // Clean up resources
    EVP_cleanup();

    // Log graceful shutdown
    std::cout << "Octree and cryptographic services shut down gracefully" << std::endl;
}

int main() {
    // Example usage of the function
    if (runCommandInBackground("ls -l") == 1) {
        std::cout << "Command executed successfully in background" << std::endl;
    } else {
        std::cerr << "Failed to execute command in background" << std::endl;
    }

    initializeOctreeWithCryptoPrimitives(32, 100, 5);

    return 0;
}
