// app.js
const express = require('express');
const axios = require('axios');
const LRU = require('lru-cache');

const app = express();
const cache = new LRU({ max: 500 });
const fetchInterval = 60 * 1000; // Fetch data every minute

// Middleware to handle API rate limiting
const rateLimit = (req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
  if (!rateLimit[ip]) rateLimit[ip] = { count: 1, lastCall: Date.now() };
  else {
    rateLimit[ip].count++;
    if (Date.now() - rateLimit[ip].lastCall < 1000) return res.status(429).send('Too many requests');
    rateLimit[ip].count = 1;
    rateLimit[ip].lastCall = Date.now();
  }
  next();
};

app.use(rateLimit);

// Route to fetch data from external API and cache it
const fetchData = async () => {
  try {
    const response = await axios.get('https://api.example.com/data');
    const data = processData(response.data);
    data.forEach(item => cache.set(item.id, item));
  } catch (error) {
    console.error('Error fetching data:', error);
  }
};

const processData = (data) => {
  // Implement your data processing logic here
  return data;
};

// Periodically fetch and cache data
setInterval(fetchData, fetchInterval);

// Route to expose cached data via API
app.get('/api/data', (req, res) => {
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;
  const start = (page - 1) * limit;
  const end = start + limit;

  const items = Array.from(cache.values())
    .slice(start, end)
    .map(item => ({ id: item.id, name: item.name })); // Adjust based on your data structure

  res.json({ page, totalItems: cache.size, items });
});

// Robust logging mechanism
app.use((req, res, next) => {
  console.log(`${req.method} ${req.url} ${res.statusCode}`);
  next();
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server is running on port ${PORT}`));
