// Import necessary libraries
const axios = require('axios');
const crypto = require('crypto');

// Define the StreamingDataCollector class
class StreamingDataCollector {
  constructor() {
    this.collectors = {};
    this.errorLog = [];
  }

  // Method to add a new collector for a source
  async addCollector(sourceId, apiEndpoint) {
    if (this.collectors[sourceId]) {
      throw new Error(`Collector already exists for ${sourceId}`);
    }
    try {
      const response = await axios.get(apiEndpoint);
      this.collectors[sourceId] = { data: response.data, paused: false };
      return response.data;
    } catch (error) {
      this.logError(sourceId, error.message);
      throw new Error(`Failed to add collector for ${sourceId}: ${error.message}`);
    }
  }

  // Method to pause data collection for a source
  async pauseCollector(sourceId) {
    if (!this.collectors[sourceId]) {
      throw new Error(`No collector found for ${sourceId}`);
    }
    this.collectors[sourceId].paused = true;
  }

  // Method to resume data collection for a source
  async resumeCollector(sourceId) {
    if (!this.collectors[sourceId]) {
      throw new Error(`No collector found for ${sourceId}`);
    }
    this.collectors[sourceId].paused = false;
    await this.collectData(sourceId);
  }

  // Method to collect data from a source
  async collectData(sourceId) {
    if (!this.collectors[sourceId] || this.collectors[sourceId].paused) return;

    try {
      const response = await axios.get(this.collectors[sourceId].apiEndpoint);
      this.collectors[sourceId].data = response.data;
      this.logCollectorStatus(sourceId, 'Data collected successfully');
    } catch (error) {
      this.logError(sourceId, error.message);
      this.logCollectorStatus(sourceId, 'Failed to collect data');
    }
  }

  // Method to compute SHA-256 hash of a webpage's content
  async computeHash(content) {
    const hash = crypto.createHash('sha256');
    hash.update(content);
    return hash.digest('hex');
  }

  // Method to log errors
  logError(sourceId, errorMessage) {
    this.errorLog.push({ sourceId, errorMessage, timestamp: new Date() });
  }

  // Method to log collector status
  logCollectorStatus(sourceId, statusMessage) {
    console.log(`${sourceId}: ${statusMessage}`);
  }
}

// Export the StreamingDataCollector class for use in other modules
module.exports = StreamingDataCollector;
```

