import java.util.concurrent.*;
import java.util.List;
import java.util.ArrayList;

public class ServiceManager {
    private List<BackgroundService> services = new ArrayList<>();
    private ExecutorService executor = Executors.newFixedThreadPool(10);
    private int activeServices = 0;
    private int maxActiveServices = 5;

    public void addService(BackgroundService service) {
        services.add(service);
    }

    public void startServices() {
        for (BackgroundService service : services) {
            executor.submit(() -> manageService(service));
        }
    }

    private void manageService(BackgroundService service) {
        try {
            while (!Thread.currentThread().isInterrupted()) {
                long delay = getRandomDelay();
                Thread.sleep(delay);

                if (activeServices < maxActiveServices) {
                    activeServices++;
                    System.out.println("Starting service: " + service.getName());
                    service.start();
                }
            }
        } catch (InterruptedException e) {
            System.out.println("Service interrupted: " + service.getName());
        } finally {
            activeServices--;
            System.out.println("Stopping service: " + service.getName());
            service.stop();
        }
    }

    private long getRandomDelay() {
        // Generate a random delay between 100 and 500 milliseconds
        return ThreadLocalRandom.current().nextInt(100, 501);
    }

    public void updateMaxActiveServices(int max) {
        this.maxActiveServices = max;
    }
}

class BackgroundService {
    private String name;
    private boolean running;

    public BackgroundService(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public synchronized void start() {
        if (!running) {
            running = true;
            System.out.println("Service started: " + name);
            // Simulate service operation
            try {
                Thread.sleep(2000); // Simulate service operation time
            } catch (InterruptedException e) {
                System.out.println("Service interrupted during start: " + name);
            }
        }
    }

    public synchronized void stop() {
        if (running) {
            running = false;
            System.out.println("Service stopped: " + name);
        }
    }

    public boolean isRunning() {
        return running;
    }
}

class Main {
    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        manager.addService(new BackgroundService("Service1"));
        manager.addService(new BackgroundService("Service2"));

        // Start managing services
        manager.startServices();

        // Simulate updating max active services
        manager.updateMaxActiveServices(3);
    }
}
```

