// File processing function
void processFile(const std::filesystem::path& filePath, SandeshClient& client, std::mutex& logMutex, std::condition_variable& cv, bool& stopFlag) {
    // Implement file reading and API integration logic here
}

int main() {
    std::vector<std::thread> threads;
    std::queue<std::string> filePathQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool stopFlag = false;

    SandeshClient client;
    std::mutex logMutex;
    int successfulRequests = 0, failedRequests = 0;

    // Function to scan and enqueue files
    auto scanDirectory = [&](const std::filesystem::path& dir) {
        for (const auto& entry : std::filesystem::recursive_directory_iterator(dir)) {
            if (entry.is_regular_file() && entry.path().extension() == ".txt") {
                std::lock_guard<std::mutex> lock(queueMutex);
                filePathQueue.push(entry.path().string());
            }
        }
    };

    // Thread to process files
    auto worker = [&client, &logMutex, &cv, &stopFlag, &successfulRequests, &failedRequests]() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [&stopFlag] { return !stopFlag || !filePathQueue.empty(); });

            if (stopFlag && filePathQueue.empty()) break;

            std::string filePath = filePathQueue.front();
            filePathQueue.pop();

            lock.unlock();

            processFile(filePath, client, logMutex, cv, stopFlag);
        }
    };

    // Scan directory and start threads
    scanDirectory("/path/to/directory");
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        threads.emplace_back(worker);
    }

    // Wait for all threads to finish
    for (auto& thread : threads) {
        thread.join();
    }

    std::cout << "Successful requests: " << successfulRequests << ", Failed requests: " << failedRequests << std::endl;

    return 0;
}
