using System;
using System.Collections.Generic;
using System.Linq;

public class DynamicValueGenerator
{
    private Random random;
    private int min;
    private int max;
    private HashSet<int> generatedValues;

    public void SeedRandom(int seed)
    {
        random = new Random(seed);
    }

    public void SetRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value.");

        min = minValue;
        max = maxValue;
        generatedValues = new HashSet<int>();
    }

    public int GenerateUniqueRandom()
    {
        while (true)
        {
            int value = random.Next(min, max + 1);
            if (!generatedValues.Contains(value))
            {
                generatedValues.Add(value);
                return value;
            }
        }
    }

    public bool IsInSubset(int value, int subsetMin, int subsetMax)
    {
        return value >= subsetMin && value <= subsetMax;
    }

    public bool IsValueGenerated(int value)
    {
        return generatedValues.Contains(value);
    }
}
