async def fetch_stock_price(provider, symbol):
    if provider == "AlphaVantage":
        # Simulate API call to Alpha Vantage
        return {"symbol": symbol, "price": "150.75"}
    elif provider == "YahooFinance":
        # Simulate API call to Yahoo Finance
        return {"symbol": symbol, "price": "152.50"}

@sleep_and_retry
@limits(calls=5, period=60)  # Rate limit per minute
async def fetch_crypto_market_cap(provider, coin):
    if provider == "CoinGecko":
        # Simulate API call to CoinGecko
        return {"coin": coin, "market_cap": "20000000000"}
    elif provider == "AlphaVantage":
        # Simulate API call to Alpha Vantage for crypto data
        return {"coin": coin, "market_cap": "21000000000"}

@app.get("/data")
async def get_data(request):
    data_type = request.args.get("type", default="stock_price").lower()
    provider = request.args.get("provider", default="AlphaVantage")
    symbol_or_coin = request.args.get("symbol_or_coin")

    if data_type == "stock_price":
        result = await fetch_stock_price(provider, symbol_or_coin)
    elif data_type == "crypto_market_cap":
        result = await fetch_crypto_market_cap(provider, symbol_or_coin)
    else:
        return json({"error": "Invalid data type"}, status=400)

    return json(result)

@app.post("/data")
