    data = request.json
    data_type = data.get("type", "").lower()
    provider = data.get("provider", "")
    symbol_or_coin = data.get("symbol_or_coin")

    if not (data_type and provider and symbol_or_coin):
        return json({"error": "Missing required fields"}, status=400)

    result = await get_data(request)
    return response.raw(result.body, content_type=result.headers["Content-Type"])

