// Define a custom exception for data processing errors
class DataProcessingException : public std::exception {
public:
    DataProcessingException(const std::string& message) : m_message(message) {}
    const char* what() const noexcept override { return m_message.c_str(); }
private:
    std::string m_message;
};

// Function to insert transformation rules into a forward_list
bool insertTransformationRule(std::forward_list<std::string>& rules, const std::string& specificRule, const std::string& newRule) {
    auto it = rules.before_begin();
    while (it != rules.end() && *it != specificRule) {
        ++it;
    }
    if (it == rules.end()) {
        return false; // Specific rule not found
    }
    ++it; // Move past the specific rule
    rules.insert_after(it, newRule);
    return true;
}

// Function to log operations to a file
void logOperation(const std::string& operation) {
    static std::ofstream logFile("data_processing.log", std::ios::app);
    if (logFile.is_open()) {
        logFile << "[" << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) << "] " << operation << std::endl;
    }
}

int main() {
    try {
        // Example usage of the function
        std::forward_list<std::string> transformationRules = {"rule1", "rule2", "rule3"};
        bool inserted = insertTransformationRule(transformationRules, "rule2", "new_rule");
        if (inserted) {
            logOperation("Transformation rule inserted successfully.");
        } else {
            logOperation("Failed to insert transformation rule.");
            throw DataProcessingException("Failed to find specific rule for insertion.");
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
