#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define API_URL "https://api.example.com/directory-separator"
#define LOG_FILE "app.log"

typedef enum {
    INFO,
    WARNING,
    ERROR
} LogLevel;

typedef struct {
    char* path;
    pthread_mutex_t mutex;
} PathConfig;

typedef struct {
    LogLevel level;
    FILE* logFile;
    pthread_mutex_t logMutex;
} LogSystem;

PathConfig* path_configs = NULL;
int num_paths = 0;
LogSystem log_system;
pthread_mutex_t cache_mutex;
time_t last_api_call_time;
char cached_separator;

void init_path_config(int num_paths) {
    path_configs = malloc(num_paths * sizeof(PathConfig));
    for (int i = 0; i < num_paths; i++) {
        path_configs[i].path = NULL;
        pthread_mutex_init(&path_configs[i].mutex, NULL);
    }
}

void init_log_system(LogLevel level) {
    log_system.level = level;
    log_system.logFile = fopen(LOG_FILE, "a");
    if (!log_system.logFile) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&log_system.logMutex, NULL);
}

void log_message(LogLevel level, const char* message) {
    if (level < log_system.level) return;

    time_t now = time(NULL);
    struct tm* t_info = localtime(&now);

    pthread_mutex_lock(&log_system.logMutex);
    fprintf(log_system.logFile, "%s [%d/%02d/%02d %02d:%02d:%02d] - %s\n",
            level == INFO ? "INFO" : (level == WARNING ? "WARNING" : "ERROR"),
            t_info->tm_year + 1900, t_info->tm_mon + 1, t_info->tm_mday,
            t_info->tm_hour, t_info->tm_min, t_info->tm_sec,
            message);
    fflush(log_system.logFile);
    pthread_mutex_unlock(&log_system.logMutex);

    if (level == ERROR) {
        fprintf(stderr, "%s\n", message);
    }
}

int fetch_directory_separator_from_api() {
    // Simulate API call
    sleep(1); // Simulate delay
    return '/'; // Example separator
}

char* get_directory_separator(const char* path) {
    pthread_mutex_lock(&cache_mutex);
    time_t now = time(NULL);
    if (difftime(now, last_api_call_time) > 3600 || cached_separator == '\0') { // Cache for 1 hour
        cached_separator = fetch_directory_separator_from_api();
        last_api_call_time = now;
    }
    pthread_mutex_unlock(&cache_mutex);

    return &cached_separator;
}

void* append_directory_separator(void* arg) {
    int index = *(int*)arg;
    PathConfig* config = &path_configs[index];
    char separator = get_directory_separator(config->path);
    pthread_mutex_lock(&config->mutex);

    if (strrchr(config->path, separator) != NULL) {
        // Directory already ends with the separator
        pthread_mutex_unlock(&config->mutex);
        return NULL;
    }

    int new_length = strlen(config->path) + 2;
    char* new_path = realloc(config->path, new_length);
    if (!new_path) {
        log_message(ERROR, "Failed to reallocate memory for path");
        pthread_mutex_unlock(&config->mutex);
        return NULL;
    }
    config->path = new_path;

    config->path[new_length - 3] = separator;
    config->path[new_length - 2] = '\0';

    pthread_mutex_unlock(&config->mutex);
    return NULL;
}

void free_path_configs() {
    for (int i = 0; i < num_paths; i++) {
        pthread_mutex_destroy(&path_configs[i].mutex);
        free(path_configs[i].path);
    }
    free(path_configs);
}

void close_log_system() {
    fclose(log_system.logFile);
    pthread_mutex_destroy(&log_system.logMutex);
}
```

