namespace SecureRandom {
    class RandomNumberGenerator {
    private:
        std::mt19937_64 generator;

        // Helper function to read a secure seed from /dev/urandom
        uint64_t readSecureSeed() {
            std::ifstream urandom("/dev/urandom", std::ios::binary);
            if (!urandom) {
                throw std::runtime_error("Failed to open /dev/urandom");
            }
            uint64_t seed;
            urandom.read(reinterpret_cast<char*>(&seed), sizeof(seed));
            return seed;
        }

    public:
        RandomNumberGenerator() : generator(readSecureSeed()) {}

        ~RandomNumberGenerator() = default; // Default destructor

        // Method to generate a random unsigned integer
        uint64_t nextUint64() {
            return generator();
        }

        // Method to generate a random floating-point number between 0 and 1
        double nextDouble() {
            std::uniform_real_distribution<double> distribution(0.0, 1.0);
            return distribution(generator);
        }
    };
}

int main() {
    SecureRandom::RandomNumberGenerator rng;

    // Example usage
    uint64_t randomUint = rng.nextUint64();
    double randomDouble = rng.nextDouble();

    std::cout << "Random Uint64: " << randomUint << std::endl;
    std::cout << "Random Double: " << randomDouble << std::endl;

    return 0;
}
