def extract_metadata(api_url, image_path):
    # Send request to external API for metadata extraction
    for attempt in range(RETRY_ATTEMPTS):
        try:
            response = requests.post(api_url, files={'file': open(image_path, 'rb')})
            if response.status_code == 200:
                return response.json()
            else:
                sleep(BACKOFF_FACTOR ** attempt)
        except requests.exceptions.RequestException as e:
            print(f"Error: {e}")
    return None

def store_metadata(file_path, metadata):
    # Store metadata in database
    cursor.execute('INSERT INTO metadata (file_path, metadata) VALUES (?, ?)', (file_path, str(metadata)))
