```python
import threading
import serial
from queue import Queue, Empty
from datetime import datetime

class SensorDataReceiver:
    def __init__(self, port, baud_rate=9600, timeout=1, buffer_size=1024):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.buffer_size = buffer_size
        self.serial_port = None

    def connect(self):
        try:
            self.serial_port = serial.Serial(
                self.port,
                self.baud_rate,
                timeout=self.timeout,
                read_timeout=self.timeout,
                write_timeout=self.timeout,
                inter_byte_timeout=self.timeout,
                dsrdtr=False,
                rtscts=False
            )
            print(f"Connected to {self.port}")
        except serial.SerialException as e:
            print(f"Failed to connect to {self.port}: {e}")

    def disconnect(self):
        if self.serial_port and self.serial_port.is_open:
            self.serial_port.close()
            print(f"Disconnected from {self.port}")

class SensorDataProcessor(threading.Thread):
    def __init__(self, queue, anomaly_threshold=2.5, window_size=10):
        threading.Thread.__init__(self)
        self.queue = queue
        self.anomaly_threshold = anomaly_threshold
        self.window_size = window_size
        self.readings = []

    def run(self):
        while True:
            try:
                data = self.queue.get(timeout=1)
                self.process_data(data)
            except Empty:
                continue

    def process_data(self, data):
        try:
            reading = float(data.strip())
            if not reading.is_integer():
                raise ValueError("Invalid data point")
            self.readings.append(reading)
            if len(self.readings) > self.window_size:
                mean = sum(self.readings[-self.window_size:]) / self.window_size
                variance = sum((x - mean) ** 2 for x in self.readings[-self.window_size:]) / self.window_size
                std_dev = variance ** 0.5
                if abs(reading - mean) > self.anomaly_threshold * std_dev:
                    print(f"Anomaly detected: {reading}")
        except ValueError as e:
            print(f"Skipping invalid data point: {data}, error: {e}")

class ConfigManager:
    def __init__(self):
        self.sensor_params = {}
        self.anomaly_config = {}

    def set_sensor_params(self, port, baud_rate, timeout, buffer_size):
        self.sensor_params[port] = (baud_rate, timeout, buffer_size)

    def get_sensor_params(self, port):
        return self.sensor_params.get(port, None)

    def set_anomaly_config(self, threshold, window_size):
        self.anomaly_config['threshold'] = threshold
        self.anomaly_config['window_size'] = window_size

    def get_anomaly_config(self):
        return self.anomaly_config

# Usage example
if __name__ == "__main__":
    config_manager = ConfigManager()
    config_manager.set_sensor_params('/dev/ttyUSB0', 9600, 1, 1024)
    config_manager.set_anomaly_config(2.5, 10)

    queue = Queue()
    receiver = SensorDataReceiver('/dev/ttyUSB0')
    processor = SensorDataProcessor(queue, **config_manager.get_anomaly_config())

    receiver.connect()
    processor.start()

    # Simulate sensor data stream
    for i in range(100):
        if i % 2 == 0:
            queue.put(str(i * 1.1))  # Simulated normal reading with slight variation
        else:
            queue.put(str("invalid_data"))  # Simulated invalid data

    receiver.disconnect()
    processor.join()
