import requests
from PyPDF2 import PdfReader
from rust_http_client import AsyncClient, RateLimiter
import re

# Predefined fields that need text extraction
PREDEFINED_FIELDS = ['field1', 'field2', 'field3']

# OCR API endpoint and rate limit configuration
OCR_API_ENDPOINT = "https://api.ocr.com/extract"
RATE_LIMITER = RateLimiter(max_requests=100, interval=60)

def extract_text_from_pdf(pdf_path):
    with open(pdf_path, 'rb') as file:
        reader = PdfReader(file)
        pages = [page.extract_text() for page in reader.pages]
    return pages

async def fetch_text_from_ocr_api(text, field_name):
    headers = {"Content-Type": "application/json"}
    data = {
        "text": text,
        "field": field_name
    }
    async with AsyncClient() as client:
        response = await client.post(OCR_API_ENDPOINT, json=data, headers=headers)
        return response.json()

def validate_text(text):
    # Example validation: simple email format check
    if re.match(r"[^@]+@[^@]+\.[^@]+", text):
        return True
    return False

def process_form(form_instance, pdf_path):
    pages = extract_text_from_pdf(pdf_path)

    for field_name in form_instance.fields:
        if field_name in PREDEFINED_FIELDS:
            index = PREDEFINED_FIELDS.index(field_name)
            if index < len(pages):
                page_text = pages[index]
                result = fetch_text_from_ocr_api(page_text, field_name)

                if result['success']:
                    extracted_text = result['text']
                    if validate_text(extracted_text):
                        form_instance.data[field_name] = extracted_text
                    else:
                        raise ValueError(f"Invalid text for field {field_name}: {extracted_text}")
                else:
                    raise Exception("OCR API processing failed")

# Example usage
# form_instance = SomeForm()
# process_form(form_instance, 'path/to/document.pdf')
