```csharp
public interface IAccountService
{
    Task CreateUserAsync(string username, string password, string confirmPassword);
    Task UpdateUserAsync(int userId, string newUsername, string newPassword);
    Task DeleteUserAsync(int userId);
}

public class AccountService : IAccountService
{
    private readonly ApplicationDbContext _context;
    private readonly IAuthenticationService _authenticationService;

    public AccountService(ApplicationDbContext context, IAuthenticationService authenticationService)
    {
        _context = context;
        _authenticationService = authenticationService;
    }

    public async Task CreateUserAsync(string username, string password, string confirmPassword)
    {
        if (password != confirmPassword) throw new InvalidOperationException("Passwords do not match.");
        if (!await _authenticationService.ValidateUsernameAsync(username)) throw new InvalidOperationException("Username already exists.");

        var user = new User
        {
            Username = username,
            PasswordHash = HashPassword(password),
            CreatedAt = DateTime.UtcNow
        };

        await _context.Users.AddAsync(user);
        await _context.SaveChangesAsync();
    }

    public async Task UpdateUserAsync(int userId, string newUsername, string newPassword)
    {
        var user = await _context.Users.FindAsync(userId);
        if (user == null) throw new InvalidOperationException("User not found.");

        if (!string.IsNullOrEmpty(newUsername) && !await _authenticationService.ValidateUsernameAsync(newUsername)) throw new InvalidOperationException("Username already exists.");
        if (!string.IsNullOrEmpty(newPassword))
        {
            if (newPassword != confirmPassword) throw new InvalidOperationException("Passwords do not match.");
            user.PasswordHash = HashPassword(newPassword);
        }

        if (!string.IsNullOrEmpty(newUsername)) user.Username = newUsername;
        user.UpdatedAt = DateTime.UtcNow;

        _context.Users.Update(user);
        await _context.SaveChangesAsync();
    }

    public async Task DeleteUserAsync(int userId)
    {
        var user = await _context.Users.FindAsync(userId);
        if (user == null) throw new InvalidOperationException("User not found.");

        _context.Users.Remove(user);
