// JavaScript WebSocket Data Collector Application

const dataStore = [];
let isPaused = false;

function connectWebSocket() {
  const socket = new WebSocket('wss://example.com/data');

  socket.onopen = () => {
    console.log('Connected to WebSocket server');
  };

  socket.onmessage = (event) => {
    if (!isPaused) {
      try {
        dataStore.push(JSON.parse(event.data));
        console.log('Data saved:', dataStore[dataStore.length - 1]);
      } catch (error) {
        console.error('Error parsing message:', error);
      }
    }
  };

  socket.onerror = (error) => {
    console.error('WebSocket error:', error);
  };

  socket.onclose = () => {
    console.log('Disconnected from WebSocket server');
    setTimeout(connectWebSocket, 5000); // Retry connection after 5 seconds
  };
}

function pauseDataCollection() {
  isPaused = true;
  console.log('Data collection paused');
}

function resumeDataCollection() {
  isPaused = false;
  console.log('Data collection resumed');
}

connectWebSocket();

// Simulate user interaction
setInterval(() => {
  if (!isPaused) {
    console.log('Collecting data...');
  } else {
    console.log('Pausing data collection...');
  }
}, 1000);

