// Define the random number generator interface
class RandomNumberGenerator {
public:
    virtual ~RandomNumberGenerator() = default;
    virtual double generate(double min, double max) = 0;
};

// Implement a thread-safe random number generator using OpenSSL
class OpenSSLRandomNumberGenerator : public RandomNumberGenerator {
private:
    std::mutex mutex;

public:
    double generate(double min, double max) override {
        std::lock_guard<std::mutex> lock(mutex);
        unsigned char buffer[sizeof(double)];
        RAND_bytes(buffer, sizeof(double));
        double randomValue = *reinterpret_cast<double*>(buffer);
        return min + (randomValue / UINT64_MAX) * (max - min);
    }
};

