```python
import paho.mqtt.client as mqtt
from flask import Flask, jsonify
import json
import time

app = Flask(__name__)

# Configuration
MQTT_BROKERS = ["mqtt1.example.com", "mqtt2.example.com"]
SUBSCRIPTIONS = {
    "sensor/#": {"qos": 1},
    "log/#": {"qos": 0}
}
ALERT_THRESHOLDS = {
    "message_count": 1000,
    "delivery_delay": 500
}

# MQTT Client Setup
mqtt_clients = {}
stats = {}

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    for topic, qos in SUBSCRIPTIONS.items():
        client.subscribe(topic, qos)

def on_message(client, userdata, msg):
    topic = msg.topic
    if topic not in stats:
        stats[topic] = {"count": 0, "size": 0, "last_time": None}

    # Parsing and validating incoming MQTT messages
    try:
        payload = json.loads(msg.payload)
    except json.JSONDecodeError:
        print("Invalid JSON message")
        return

    # Applying configurable message filters
    if not topic.startswith("sensor"):
        return

    stats[topic]["count"] += 1
    stats[topic]["size"] += len(json.dumps(payload))

    current_time = time.time()
    if "last_time" in stats[topic]:
        delay = current_time - stats[topic]["last_time"]
        print(f"Message delivery delay for {topic}: {delay} seconds")

    stats[topic]["last_time"] = current_time

def on_disconnect(client, userdata, rc):
    print("Disconnected from MQTT broker")

for broker in MQTT_BROKERS:
    client = mqtt.Client()
    client.on_connect = on_connect
    client.on_message = on_message
    client.on_disconnect = on_disconnect
    client.connect(broker)
    mqtt_clients[broker] = client
    client.loop_start()

# Flask Web Interface
@app.route('/stats', methods=['GET'])
def get_stats():
    return jsonify(stats)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

This code sets up a basic MQTT client that connects to multiple brokers and subscribes to various topics, processing incoming messages in real-time. It includes logging, basic statistics tracking, and a simple Flask web interface for viewing stats. The application can be expanded with additional features like alerting, configuration management, and more sophisticated resource management as needed.

