    PersistRecords(records, data->offsets[0], outputDbConnectionString);

    // Free allocated memory
    FreeCustomData(data);
    free(records);

    printf("Operation completed successfully\n");

    return 0;
}

// Function to free the custom data structure
void FreeCustomData(CustomData* data) {
    if (data) {
        if (data->offsets) {
            free(data->offsets);
        }
        if (data->keys) {
            free(data->keys);
        }
        free(data);
    }
}
