using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class UserCredentialManager
{
    private readonly ConcurrentDictionary<string, DateTime> rateLimits = new ConcurrentDictionary<string, DateTime>();
    private readonly HttpClient httpClient;
    private readonly PaymentGatewayClient paymentGateway;

    public UserCredentialManager(HttpClient httpClient, PaymentGatewayClient paymentGateway)
    {
        this.httpClient = httpClient;
        this.paymentGateway = paymentGateway;
    }

    public async Task<string> HashPasswordAsync(string password)
    {
        using (SHA256 sha256Hash = SHA256.Create())
        {
            byte[] bytes = sha256Hash.ComputeHash(Encoding.UTF8.GetBytes(password));
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
            {
                builder.Append(bytes[i].ToString("x2"));
            }
            return builder.ToString();
        }
    }

    public bool ValidateEmail(string email)
    {
        string pattern = @"^[\w-\.]+@([\w-]+\.)+[a-zA-Z]{2,4}$";
        return System.Text.RegularExpressions.Regex.IsMatch(email, pattern);
    }

    public async Task UpdateUserProfileAsync(string userId, string newEmail, string newPassword)
    {
        if (await IsRateLimited(userId))
        {
            throw new InvalidOperationException("Rate limit exceeded.");
        }

        await ValidateUserInputs(newEmail, newPassword);

        string hashedPassword = await HashPasswordAsync(newPassword);
        var userProfileUpdateRequest = new
        {
            UserId = userId,
            Email = newEmail,
            PasswordHash = hashedPassword
        };

        var response = await httpClient.PutAsJsonAsync("https://api.example.com/users/update", userProfileUpdateRequest);

        if (!response.IsSuccessStatusCode)
        {
            throw new InvalidOperationException($"Failed to update user profile: {response.ReasonPhrase}");
        }

        await paymentGateway.ProcessTransactionAsync(userId, "Profile Update");

        rateLimits.TryAddOrUpdate(userId, DateTime.UtcNow.AddSeconds(5), (key, oldValue) => oldValue.AddSeconds(5));
    }

    private async Task ValidateUserInputs(string email, string password)
    {
        if (!ValidateEmail(email))
        {
            throw new ArgumentException("Invalid email format.");
        }

        if (string.IsNullOrEmpty(password) || password.Length < 8)
        {
            throw new ArgumentException("Password must be at least 8 characters long.");
        }
    }

    private async Task<bool> IsRateLimited(string userId)
    {
        DateTime lastAccessTime;
        if (!rateLimits.TryGetValue(userId, out lastAccessTime))
        {
            return false;
        }

        if (DateTime.UtcNow < lastAccessTime.AddSeconds(5))
        {
            return true;
        }

        rateLimits.TryRemove(userId, out _);
        return false;
    }
}

public class PaymentGatewayClient
{
    private readonly HttpClient httpClient;

    public PaymentGatewayClient(HttpClient httpClient)
    {
        this.httpClient = httpClient;
    }

    public async Task ProcessTransactionAsync(string userId, string transactionDescription)
    {
        var paymentRequest = new
        {
            UserId = userId,
            Description = transactionDescription
        };

        var response = await httpClient.PostAsJsonAsync("https://paymentgateway.example.com/transactions", paymentRequest);

        if (!response.IsSuccessStatusCode)
        {
            throw new InvalidOperationException($"Failed to process payment: {response.ReasonPhrase}");
        }
    }
}
