        headers = curl_slist_append(headers, "Accept: application/json");

        // Set the URL and other parameters for a GET request
        curl_easy_setopt(curl, CURLOPT_URL, metadataUrl);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](char *ptr, size_t size, size_t nmemb, void *userdata) -> size_t {
            ((std::string*)userdata)->append(ptr, size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        // Execute the request
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            std::cerr << "Error in updateFileName: " << curl_easy_strerror(res) << std::endl;
            return NULL;
        }

        // Parse response and modify filename based on rules (pseudo-code)
        std::string newFilename = originalFilename;  // Modify as needed

        // Clean up
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        curl_global_cleanup();

        return strdup(newFilename.c_str());
    } else {
        std::cerr << "Error in updateFileName: Failed to initialize libcurl" << std::endl;
        return NULL;
    }
}
