```python
import json
import os
from collections import defaultdict
from datetime import datetime
import re
from typing import Dict, List
import sqlite3

class ServerLogAnalyzer:
    def __init__(self, database: str):
        self.database = database
        self.keyword_categories = {}
        self.load_keyword_categories()

    def load_keyword_categories(self):
        with open('keyword_categories.json', 'r') as f:
            self.keyword_categories = json.load(f)

    def analyze_logs(self, input_dir: str, output_dir: str, server_instance: str = None, time_period: str = None) -> Dict:
        logs = []
        for root, _, files in os.walk(input_dir):
            for file in files:
                if file.endswith('.json'):
                    with open(os.path.join(root, file), 'r') as f:
                        logs.extend(json.load(f))

        filtered_logs = self.filter_logs(logs, server_instance, time_period)

        summary = {
            'response_times': [],
            'error_rates': [],
            'throughput': []
        }

        for log in filtered_logs:
            summary['response_times'].append(log['response_time'])
            if log['error']:
                summary['error_rates'].append(1)
            else:
                summary['error_rates'].append(0)
            summary['throughput'].append(log['throughput'])

        nlp_keywords = self.extract_nlp_keywords(filtered_logs)

        # Store historical data in the database
        self.store_data(summary, nlp_keywords)

        return summary

    def filter_logs(self, logs: List[Dict], server_instance: str, time_period: str) -> List[Dict]:
        if server_instance:
            logs = [log for log in logs if log['server_instance'] == server_instance]
        if time_period:
            start_time, end_time = time_period.split('-')
            logs = [log for log in logs if datetime.strptime(log['timestamp'], '%Y-%m-%d %H:%M:%S') >= datetime.strptime(start_time, '%Y-%m-%d %H:%M:%S') and datetime.strptime(log['timestamp'], '%Y-%m-%d %H:%M:%S') <= datetime.strptime(end_time, '%Y-%m-%d %H:%M:%S')]
        return logs

    def extract_nlp_keywords(self, logs: List[Dict]) -> Dict:
        nlp_keywords = defaultdict(int)
        for log in logs:
            for keyword_category, keywords in self.keyword_categories.items():
                for keyword in keywords:
                    if re.search(keyword, log['message']):
                        nlp_keywords[keyword_category] += 1
        return dict(nlp_keywords)

    def store_data(self, summary: Dict, nlp_keywords: Dict):
        conn = sqlite3.connect(self.database)
        c = conn.cursor()
        c.execute('''CREATE TABLE IF NOT EXISTS server_logs (response_times TEXT, error_rates TEXT, throughput TEXT)''')
        c.execute('''CREATE TABLE IF NOT EXISTS nlp_keywords (category TEXT, keyword TEXT, frequency INTEGER)''')

        c.execute('INSERT INTO server_logs VALUES (?, ?, ?)', (json.dumps(summary['response_times']), json.dumps(summary['error_rates']), json.dumps(summary['throughput'])))
        for category, freq in nlp_keywords.items():
            c.execute('INSERT INTO nlp_keywords VALUES (?, ?, ?)', (category, keyword, freq))

        conn.commit()
        conn.close()

if __name__ == '__main__':
    analyzer = ServerLogAnalyzer('server_logs.db')
    summary = analyzer.analyze_logs('/path/to/logs', '/path/to/output')
    print(summary)
```

