import java.io.File;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ImageResizerAndUploader {

    private ExecutorService executorService;

    public ImageResizerAndUploader(int maxThreads) {
        this.executorService = Executors.newFixedThreadPool(maxThreads);
    }

    public void processImage(String inputPath, int maxWidth, int maxHeight, String outputFormat) {
        File inputFile = new File(inputPath);
        if (!inputFile.exists() || !isValidImageFormat(inputFile.getName())) {
            throw new IllegalArgumentException("Invalid image file path or format");
        }

        executorService.submit(() -> {
            try {
                // Resize and upload logic here
                System.out.println("Processing " + inputPath);
                Thread.sleep(1000); // Simulate processing time
                System.out.println("Uploaded to cloud storage: " + inputPath);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                System.err.println("Processing interrupted");
            }
        });
    }

    private boolean isValidImageFormat(String fileName) {
        String[] validExtensions = {"jpg", "jpeg", "png", "bmp", "gif"};
        for (String ext : validExtensions) {
            if (fileName.toLowerCase().endsWith("." + ext)) {
                return true;
            }
        }
        return false;
    }

    public void shutdown() {
        executorService.shutdown();
    }
}
