// Singleton class to manage configuration settings
class ConfigurationManager {
private:
    static ConfigurationManager* instance;
    std::mutex mutex_;
    std::forward_list<std::string> configList_;

    ConfigurationManager() {}

public:
    static ConfigurationManager& getInstance() {
        if (instance == nullptr) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (instance == nullptr) {
                instance = new ConfigurationManager();
            }
        }
        return *instance;
    }

    void insertAfter(const std::string& target, const std::string& newString) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = configList_.begin();
        while (it != configList_.end()) {
            if (*it == target) {
                configList_.insert_after(it, newString);
                break;
            }
            ++it;
        }
    }

    void mergeFromDataSource(DataSourceParser* parser, const std::string& dataSource) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto data = parser->parse(dataSource);
        for (const auto& item : data) {
            configList_.push_front(item);
        }
    }

    void cleanUp() {
        std::lock_guard<std::mutex> lock(mutex_);
        // Implement memory cleanup logic
    }

    void printConfiguration() const {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& item : configList_) {
            std::cout << item << std::endl;
        }
    }
};

// Example usage
int main() {
    ConfigurationManager& configManager = ConfigurationManager::getInstance();
    CSVParser csvParser;
    JSONParser jsonParser;

    // Merge configurations from external sources
    configManager.mergeFromDataSource(&csvParser, "data.csv");
    configManager.mergeFromDataSource(&jsonParser, "{\"config\":\"settings\"}");

    // Insert new configuration after a target string
    configManager.insertAfter("old_config", "new_config");

    // Clean up unused elements
    configManager.cleanUp();

    // Print current configuration
    configManager.printConfiguration();

    return 0;
}
