```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <atomic>
#include <stdexcept>
#include <openssl/evp.h>
#include <botan/auto_rng.h>
#include <crypto++/osrng.h>

class SecureRandomNumberGenerator {
public:
    enum class Library { OpenSSL, Botan, CryptoPP };

    struct Config {
        int numThreads;
        std::vector<Library> preferredLibraries;
        int cacheSize;
    };

    SecureRandomNumberGenerator(const Config& config)
        : config_(config), stop_(false) {
        for (int i = 0; i < config_.numThreads; ++i) {
            workers_.emplace_back(&SecureRandomNumberGenerator::worker, this);
        }
    }

    ~SecureRandomNumberGenerator() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

    void requestNumbers(int count, int range, const std::vector<int>& thresholds) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            requests_.emplace(count, range, thresholds);
        }
        cv_.notify_one();
    }

    std::vector<int> getResults() {
        std::vector<int> results;
        {
            std::unique_lock<std::mutex> lock(mutex_);
            results = std::move(results_);
            results_.clear();
        }
        return results;
    }

private:
    Config config_;
    std::atomic<bool> stop_;
    std::vector<std::thread> workers_;
    std::queue<std::tuple<int, int, std::vector<int>>> requests_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::vector<int> results_;

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !requests_.empty() || stop_; });
            if (stop_ && requests_.empty()) {
                break;
            }
            auto [count, range, thresholds] = requests_.front();
            requests_.pop();
            lock.unlock();

            std::vector<int> numbers;
            try {
                for (int i = 0; i < count; ++i) {
                    int number = generateRandomNumber(range, thresholds);
                    numbers.push_back(number);
                }
            } catch (...) {
                // Handle error
            }

            {
                std::unique_lock<std::mutex> lock(mutex_);
                results_.insert(results_.end(), numbers.begin(), numbers.end());
            }
        }
    }

    int generateRandomNumber(int range, const std::vector<int>& thresholds) {
        auto rng = selectCryptoLibrary();
        return rng->generateNumber(range);
    }

    std::unique_ptr<crypto_library> selectCryptoLibrary() {
        for (const auto& lib : config_.preferredLibraries) {
            try {
                switch (lib) {
                    case Library::OpenSSL: return std::make_unique<openssl_rng>();
                    case Library::Botan: return std::make_unique<botan_rng>();
                    case Library::CryptoPP: return std::make_unique<cryptopp_rng>();
                }
            } catch (...) {
                // Fallback to next preferred library
            }
        }
        throw std::runtime_error("No suitable cryptographic library found");
    }

    class crypto_library {
    public:
        virtual int generateNumber(int range) = 0;
        virtual ~crypto_library() = default;
    };

    class openssl_rng : public crypto_library {
    public:
        int generateNumber(int range) override {
            unsigned char buffer[4];
            EVP_RAND_CTX* rand_ctx = EVP_RAND_new();
            if (!rand_ctx || !EVP_RAND_instantiate(rand_ctx, nullptr, 0, nullptr, 0)) {
                throw std::runtime_error("Failed to instantiate OpenSSL RNG");
            }
            EVP_RAND_generate(rand_ctx, buffer, sizeof(buffer), 0, nullptr);
            EVP_RAND_free(rand_ctx);
            return (int)(buffer[0] * range / 256);
        }
    };

    class botan_rng : public crypto_library {
    public:
        int generateNumber(int range) override {
            Botan::AutoSeeded_RNG rng;
            return static_cast<int>(rng.randomize_with_ts(4)) % (range + 1);
        }
    };

    class cryptopp_rng : public crypto_library {
    public:
        int generateNumber(int range) override {
            CryptoPP::OS_Generator osrng;
            byte buffer[4];
            osrng.GenerateBlock(buffer, sizeof(buffer));
            return static_cast<int>(buffer[0] * range / 256);
        }
    };
};
