using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DecryptionService
{
    private readonly HttpClient _httpClient;
    private readonly string _keyFilePath;
    private readonly string _logFilePath;

    public DecryptionService(string keyFilePath, string logFilePath)
    {
        _httpClient = new HttpClient();
        _keyFilePath = keyFilePath;
        _logFilePath = logFilePath;
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage)
    {
        for (int attempt = 0; attempt < 4; attempt++)
        {
            try
            {
                var key = ReadKeyFromConfig();
                var iv = ReadIVFromConfig();

                if (await ValidateDecryptionWithExternalService(base64EncodedMessage, key, iv))
                {
                    return DecryptMessageWithTripleDES(base64EncodedMessage, key, iv);
                }
            }
            catch (Exception ex)
            {
                LogError(ex.Message);
            }

            if (attempt < 3)
            {
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt)));
            }
        }

        return "Decryption failed after multiple attempts";
    }

    private string ReadKeyFromConfig()
    {
        // Read key from secure configuration file
        using (var reader = new StreamReader(_keyFilePath))
        {
            return reader.ReadLine();
        }
    }

    private string ReadIVFromConfig()
    {
        // Read IV from secure configuration file
        using (var reader = new StreamReader(_logFilePath))
        {
            return reader.ReadLine();
        }
    }

    private async Task<bool> ValidateDecryptionWithExternalService(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        var response = await _httpClient.GetAsync($"https://external-encryption-service.com/decrypt?message={base64EncodedMessage}&key={Convert.ToBase64String(key)}&iv={Convert.ToBase64String(iv)}");
        return response.IsSuccessStatusCode;
    }

    private string DecryptMessageWithTripleDES(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        using (var tripleDES = new TripleDESCryptoServiceProvider { Key = key, IV = iv })
        {
            using (var memoryStream = new MemoryStream(Convert.FromBase64String(base64EncodedMessage)))
            {
                using (var cryptoStream = new CryptoStream(memoryStream, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    using (var streamReader = new StreamReader(cryptoStream))
                    {
                        return streamReader.ReadToEnd();
                    }
                }
            }
        }
    }

    private void LogError(string error)
    {
        File.AppendAllText(_logFilePath, $"{DateTime.Now}: {error}{Environment.NewLine}");
    }
}

// Usage example
public class Program
{
    public static async Task Main()
    {
        var decryptionService = new DecryptionService("key.config", "logs.txt");
        var decryptedMessage = await decryptionService.DecryptMessageAsync("base64encodedmessage");
        Console.WriteLine(decryptedMessage);
    }
}
