import java.util.*;
import java.sql.*;

public class DisjointPairsChecker {
    private static final String DB_URL = "jdbc:mysql://localhost:3306/disjoint_pairs";
    private static final String USER = "username";
    private static final String PASS = "password";

    private Map<String, Integer> cache;
    private Connection conn;

    public DisjointPairsChecker() throws SQLException {
        this.cache = new HashMap<>();
        this.conn = DriverManager.getConnection(DB_URL, USER, PASS);
    }

    public int countDisjointPairs(int[] arr) throws Exception {
        long startTime = System.nanoTime();
        UF uf = new UF(arr.length);

        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                String key = arr[i] + "-" + arr[j];
                if (!cache.containsKey(key)) {
                    cache.put(key, uf.union(i, j));
                }
                if (cache.get(key) == -1) {
                    return 0;
                }
            }
        }

        long endTime = System.nanoTime();
        long averageTime = endTime - startTime;
        System.out.println("Average time taken per check: " + averageTime / (arr.length * (arr.length - 1) / 2));
        return arr.length - uf.getDisjointSets();
    }

    private static class UF {
        int[] id;
        int count;

        public UF(int n) {
            id = new int[n];
            count = n;
            for (int i = 0; i < n; i++) {
                id[i] = i;
            }
        }

        public int find(int p) {
            while (p != id[p]) {
                id[p] = id[id[p]];
                p = id[p];
            }
            return p;
        }

        public boolean union(int p, int q) throws SQLException {
            if (find(p) == find(q)) {
                conn.createStatement().executeUpdate("INSERT INTO disjoint_pairs (pair, result) VALUES ('" + p + "-" + q + "', -1)");
                return false;
            }
            id[find(p)] = find(q);
            count--;
            conn.createStatement().executeUpdate("INSERT INTO disjoint_pairs (pair, result) VALUES ('" + p + "-" + q + "', 0)");
            return true;
        }

        public int getDisjointSets() {
            return count;
        }
    }

    public static void main(String[] args) throws Exception {
        DisjointPairsChecker checker = new DisjointPairsChecker();
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter array elements separated by space: ");
        String[] input = scanner.nextLine().split("\\s+");
        int[] arr = Arrays.stream(input).mapToInt(Integer::parseInt).toArray();

        int result = checker.countDisjointPairs(arr);
        System.out.println("Number of disjoint pairs: " + result);

        // Add code to handle deletion of cached results based on criteria
    }
}
