public class DistributedInMemoryCache {
    private final Map<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final ConfigManager configManager;
    private final ConsistentHashingRing ring;

    public DistributedInMemoryCache(ConfigManager configManager) {
        this.configManager = configManager;
        this.ring = new ConsistentHashingRing();
        // Initialize cache policies and configure node membership
        configManager.addConfigListener(this::updateCachePolicies);
    }

    private void updateCachePolicies(Map<String, Object> newConfig) {
        // Update cache policies based on the new configuration
    }

    public void put(String key, byte[] value, long ttl) {
        CacheEntry entry = new CacheEntry(value, System.currentTimeMillis() + ttl);
        cache.put(key, entry);
        ring.addKey(key);
        executorService.submit(() -> scheduleExpiration(entry));
    }

    private void scheduleExpiration(CacheEntry entry) {
        try {
            Thread.sleep(entry.getExpiryTime() - System.currentTimeMillis());
            cache.remove(entry.getKey());
        } catch (InterruptedException e) {
            // Handle the exception appropriately
        }
    }

    public byte[] get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && entry.isExpired()) {
            cache.remove(key);
            return null;
        }
        return entry != null ? entry.getValue() : null;
    }

    public void remove(String key) {
        cache.remove(key);
        ring.removeKey(key);
    }

    public byte[] queryRange(String start, String end) {
        // Implement range query logic
        return new byte[0];
    }

    public void cacheFrequentlyAccessedData(Map<String, byte[]> data) {
        for (Map.Entry<String, byte[]> entry : data.entrySet()) {
            put(entry.getKey(), entry.getValue(), configManager.getDefaultTTL());
        }
    }

    private static class CacheEntry {
        private final byte[] value;
        private final long expiryTime;

        public CacheEntry(byte[] value, long expiryTime) {
            this.value = value;
            this.expiryTime = expiryTime;
        }

        public String getKey() {
            return null; // Implement key retrieval logic
        }

        public byte[] getValue() {
            return value;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expiryTime;
        }

        public long getExpiryTime() {
            return expiryTime;
        }
    }
}

interface ConfigManager {
    void addConfigListener(Runnable listener);
    Map<String, Object> getDefaultTTL();
}
