    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        Trade trade = { /* Populate trade data */ };
        pthread_create(&threads[i], NULL, process_trade, &trade);
    }

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
