            validateConfig(latestConfig);

            updateCacheAndKVStore(latestConfig, configId, locale);
            logOperation("UPDATE_SUCCESS", configId, locale, System.currentTimeMillis());

            return new ResponseEntity<>("Configuration updated successfully", HttpStatus.OK);
        } catch (ConstraintViolationException e) {
            logOperation("VALIDATION_ERROR", configId, locale, System.currentTimeMillis());
            return new ResponseEntity<>("Validation failed: " + e.getMessage(), HttpStatus.BAD_REQUEST);
        } catch (Exception e) {
            logOperation("ERROR", configId, locale, System.currentTimeMillis());
            return new ResponseEntity<>("Failed to update configuration: " + e.getMessage(), HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }

