```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_BUFFER_SIZE 1024
#define END_OF_DATA_MARKER '0x0A'

void process_network_stream(int socket_fd) {
    char buffer[MAX_BUFFER_SIZE];
    int *integers = NULL;
    size_t array_size = 0, used_size = 0;
    ssize_t bytes_read;

    while ((bytes_read = read(socket_fd, buffer, MAX_BUFFER_SIZE)) > 0) {
        for (ssize_t i = 0; i < bytes_read; ++i) {
            if (buffer[i] == END_OF_DATA_MARKER) {
                int value = atoi(buffer);
                if (value != 0) {
                    // Dynamically resize the array
                    if (used_size >= array_size) {
                        array_size = (array_size == 0) ? 1 : array_size * 2;
                        integers = realloc(integers, array_size * sizeof(int));
                        if (integers == NULL) {
                            perror("Memory reallocation failed");
                            exit(EXIT_FAILURE);
                        }
                    }
                    integers[used_size++] = value;
                } else {
                    break; // End of data marker reached
                }
            }
        }
    }

    if (bytes_read == -1) {
        perror("Error reading from socket");
        exit(EXIT_FAILURE);
    }

    // Find and print the largest integer
    int max_value = integers[0];
    for (size_t i = 1; i < used_size; ++i) {
        if (integers[i] > max_value) {
            max_value = integers[i];
        }
    }
    printf("Largest integer received: %d\n", max_value);

    // Free dynamically allocated memory
    free(integers);
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to an IP and port
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(12345);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    // Accept a new connection
    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    process_network_stream(new_socket);

    return 0;
}
```

This C program sets up a server to listen for incoming connections on port 12345. It reads data from the network socket, processes it to find and print the largest integer received, and handles memory allocation dynamically to avoid overflow. The program includes error handling for socket operations and invalid inputs.

