class SSLClient {
public:
    SSLClient(asio::io_context& io_context, const std::string& host, const std::string& port)
        : context(SSL_CTX_new(SSLv23_client_method())), socket(io_context, context) {
        // Load SSL certificates and private key
        SSL_CTX_use_certificate_file(context.native_handle(), "path/to/certificate.pem", SSL_FILETYPE_PEM);
        SSL_CTX_use_PrivateKey_file(context.native_handle(), "path/to/private_key.pem", SSL_FILETYPE_PEM);

        asio::ip::tcp::resolver resolver(io_context);
        auto endpoints = resolver.resolve(host, port);
        asio::connect(socket.lowest_layer(), endpoints.begin(), endpoints.end());
        socket.set_verify_mode(SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT);
        socket.async_handshake(ssl_stream::client, [this](std::error_code ec) {
            if (!ec) {
                // Connection established and SSL handshake successful
            }
        });
    }

    void send(const std::string& message) {
        asio::write(socket, asio::buffer(message));
    }

private:
    ssl_stream socket;
    boost::asio::ssl::context context;
};

