#include <iostream>
#include <queue>
#include <map>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <curl/curl.h>
#include "ExternalDatabase.h"
#include "RateLimiter.h"
#include "Logger.h"

struct Request {
    std::string url;
    std::vector<std::string> selectors;
    int scrapingInterval;
    RetryPolicy retryPolicy;
};

class WebScraper {
public:
    WebScraper(int numThreads, const RateLimitConfig& rateLimitConfig) 
        : numThreads(numThreads), rateLimiter(rateLimitConfig) {}

    void enqueueRequest(const Request& request) {
        std::unique_lock<std::mutex> lock(mutex);
        requests.push(request);
        condition.notify_one();
    }

private:
    int numThreads;
    RateLimiter rateLimiter;
    std::queue<Request> requests;
    std::map<std::string, std::vector<std::string>> dataMap;
    mutable std::mutex mutex;
    std::condition_variable condition;

    void worker() {
        while (true) {
            Request request;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this]{ return !requests.empty(); });
                request = requests.front();
                requests.pop();
            }

            rateLimiter.throttle();

            try {
                processRequest(request);
            } catch (const std::exception& e) {
                Logger::logError("WebScraper: " + std::string(e.what()));
            }
        }
    }

    void processRequest(const Request& request) {
        CURL* curl = curl_easy_init();
        if (!curl) throw std::runtime_error("Failed to initialize libcurl");

        CURLcode res;
        int retriesLeft = request.retryPolicy.maxRetries;

        while (retriesLeft > 0) {
            res = curl_easy_setopt(curl, CURLOPT_URL, request.url.c_str());
            if (res != CURLE_OK) throw std::runtime_error("Failed to set URL");

            // Perform the HTTP GET request
            std::string htmlContent;
            res = performRequest(curl, htmlContent);
            if (res == CURLE_OK) {
                break;
            } else if (res == CURLE_COULDNT_CONNECT) {
                Logger::logWarning("WebScraper: Failed to connect to " + request.url + ". Retrying...");
                retriesLeft--;
                std::this_thread::sleep_for(std::chrono::seconds(request.retryPolicy.delay));
            } else {
                throw std::runtime_error("Failed to perform HTTP GET request");
            }
        }

        curl_easy_cleanup(curl);

        if (res == CURLE_OK) {
            for (const auto& selector : request.selectors) {
                try {
                    std::vector<std::string> extractedTexts = extractData(htmlContent, selector);
                    dataMap[selector].insert(dataMap[selector].end(), extractedTexts.begin(), extractedTexts.end());
                } catch (const std::exception& e) {
                    Logger::logWarning("WebScraper: Failed to extract data for selector " + selector + ". Skipping...");
                }
            }

            ExternalDatabase::storeData(request.url, dataMap);
        }
    }

    CURLcode performRequest(CURL* curl, std::string& output) {
        // Set up the callback function to store HTML content
        struct MemoryStruct chunk;
        chunk.memory = (char*)malloc(1L);  /* will be grown as needed by the realloc above */
        chunk.size = 0;    /* no data at this point */

        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void*)&chunk);

        CURLcode res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            Logger::logError("WebScraper: Failed to perform HTTP GET request. Error: " + std::string(curl_easy_strerror(res)));
        } else {
            output.assign(chunk.memory, chunk.size);
        }

        free(chunk.memory);  /* don't forget to free the memory again */

        return res;
    }

    static size_t WriteMemoryCallback(void* contents, size_t size, size_t nmemb, void* userp) {
        size_t realsize = size * nmemb;
        struct MemoryStruct* mem = (struct MemoryStruct*)userp;

        char* ptr = (char*)realloc(mem->memory, mem->size + realsize + 1);
        if(ptr == NULL) {
            Logger::logError("WebScraper: Not enough memory to resize buffer");
            return 0;
        }

        mem->memory = ptr;
        memcpy(&(mem->memory[mem->size]), contents, realsize);
        mem->size += realsize;
        mem->memory[mem->size] = 0;

        return realsize;
    }

    std::vector<std::string> extractData(const std::string& htmlContent, const std::string& selector) {
        // Implement CSS selector extraction logic here
        // Return vector of extracted texts
        return {};
    }
};

int main() {
    int numThreads = 4;
    RateLimitConfig rateLimitConfig = {100, 10};
    WebScraper scraper(numThreads, rateLimitConfig);

    // Enqueue requests
    scraper.enqueueRequest(Request{"http://example.com", {"#title"}, 60, RetryPolicy{3, 5}});
    scraper.enqueueRequest(Request{"http://example.org", {"#description"}, 300, RetryPolicy{2, 10}});

    // Start worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < numThreads; ++i) {
        workers.emplace_back(&WebScraper::worker, &scraper);
    }

    // Join worker threads
    for (auto& thread : workers) {
        thread.join();
    }

    return 0;
}
