    private static final String USER = "username";
    private static final String PASS = "password";

    private ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public void processVideoStream(VideoCapture videoCapture) {
        Mat frame;
        while ((frame = videoCapture.read()) != null) {
            executorService.submit(() -> {
                try {
                    detectFaces(frame);
                } catch (Exception e) {
                    handleException(e);
                }
            });
        }
    }

    private void detectFaces(Mat frame) throws Exception {
        // Load face detection model and perform detection
        Mat grayFrame = new Mat();
        Imgproc.cvtColor(frame, grayFrame, Imgproc.COLOR_BGR2GRAY);
        CascadeClassifier faceDetector = new CascadeClassifier("path_to_face_cascade.xml");
        Rect[] faces = faceDetector.detectMultiScale(grayFrame, 1.3, 5);

        for (Rect face : faces) {
            double confidence = calculateConfidence(face); // Implement your own method
            String orientation = determineOrientation(face, frame); // Implement your own method

            saveFaceData(frame, face, confidence, orientation);
        }
    }

    private void saveFaceData(Mat frame, Rect face, double confidence, String orientation) throws Exception {
        Connection conn = DriverManager.getConnection(DB_URL, USER, PASS);
        PreparedStatement stmt = conn.prepareStatement("INSERT INTO FaceDetection (timestamp, coordinates, confidence, orientation) VALUES (?, ?, ?, ?)");
        stmt.setTimestamp(1, new Timestamp(System.currentTimeMillis()));
        stmt.setString(2, face.x + "," + face.y + "," + (face.x + face.width) + "," + (face.y + face.height));
        stmt.setDouble(3, confidence);
        stmt.setString(4, orientation);

        stmt.executeUpdate();
        conn.close();
