using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using System.Text.RegularExpressions;

public class Startup
{
    public IConfiguration Configuration { get; }

    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public void ConfigureServices(IServiceCollection services)
    {
        // Configure database context
        services.AddDbContext<UserContext>(options =>
            options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));

        // Configure validation system
        services.AddScoped<IValidationService, ValidationService>();

        // Configure rate limiting
        services.AddRateLimiting(options =>
        {
            options.GlobalLimiter = PartitionedRateLimiter.Create(context => RateLimiterPartition.GetFixedWindowLimiter(context.Connection.RemoteIpAddress?.ToString()));
        });

        // Configure logging systems
        services.AddLogging(builder =>
        {
            builder.ClearProviders();
            builder.AddFile("logs.txt");
            builder.AddDatabase(Configuration.GetConnectionString("LoggingDb"));
            builder.AddCloudService(Configuration["CloudLoggingConfig"]);
        });

        // Configure email and SMS notification system
        services.AddScoped<INotificationService, NotificationService>();

        // Configure account management
        services.AddScoped<IUserAccountService, UserAccountService>();

        // Add controllers and other services as needed
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }
        else
        {
            app.UseExceptionHandler("/Home/Error");
            app.UseHsts();
        }

        app.UseHttpsRedirection();
        app.UseStaticFiles();

        app.UseRouting();

        app.UseAuthentication();
        app.UseAuthorization();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllerRoute(
                name: "default",
                pattern: "{controller=Home}/{action=Index}/{id?}");
        });
    }
}

