```java
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import com.fasterxml.jackson.databind.ObjectMapper;

public class ProductManager {
    private ConcurrentHashMap<String, Product> products;
    private ObjectMapper objectMapper;

    public ProductManager() {
        products = new ConcurrentHashMap<>();
        objectMapper = new ObjectMapper();
    }

    public void addProducts(List<Integer> productIds, List<String> productNames, List<Double> prices, List<Integer> quantities) throws Exception {
        if (productIds.size() != productNames.size() || productIds.size() != prices.size() || productIds.size() != quantities.size()) {
            throw new IllegalArgumentException("All input lists must have matching sizes.");
        }

        for (int i = 0; i < productIds.size(); i++) {
            int productId = productIds.get(i);
            String productName = productNames.get(i);
            double price = prices.get(i);
            int quantity = quantities.get(i);

            if (productId <= 0 || price < 0 || quantity < 0) {
                throw new IllegalArgumentException("Invalid product details.");
            }

            Product newProduct = new Product(productId, productName.toCharArray(), price, quantity);
            products.put(String.valueOf(productId), newProduct);
        }
    }

    public void updateProducts(List<Integer> productIds, List<String> productNames, List<Double> prices, List<Integer> quantities) throws Exception {
        addProducts(productIds, productNames, prices, quantities);
    }

    public void removeProducts(List<Integer> productIds) {
        for (int productId : productIds) {
            products.remove(String.valueOf(productId));
        }
    }

    public String getJsonInventory() throws Exception {
        return objectMapper.writeValueAsString(products.values());
    }

    private static class Product {
        private int productId;
        private char[] productName;
        private double price;
        private int quantity;

        public Product(int productId, char[] productName, double price, int quantity) {
            this.productId = productId;
            this.productName = productName;
            this.price = price;
            this.quantity = quantity;
        }

        @Override
        public String toString() {
            return "Product{" +
                   "productId=" + productId +
                   ", productName='" + new String(productName) + '\'' +
