const WebSocket = require('ws');
const Redis = require('redis');
const uuidv4 = require('uuid/v4');

// Create a Redis client to store sensor data
const redisClient = Redis.createClient({ url: 'redis://localhost:6379' });

// Initialize WebSocket server and clients
const wss = new WebSocket.Server({ port: 8080 });
const clients = [];

wss.on('connection', (ws) => {
    console.log('New client connected');
    clients.push(ws);

    ws.on('message', async (message) => {
        try {
            const data = JSON.parse(message);
            await processSensorData(data);
        } catch (error) {
            handleError(error);
        }
    });

    ws.on('close', () => {
        console.log('Client disconnected');
        clients.splice(clients.indexOf(ws), 1);
    });
});

// Process incoming sensor data
async function processSensorData(data) {
    try {
        const key = `sensor:${data.sensorId}:${uuidv4()}`;
        await redisClient.hSet(key, 'timestamp', new Date().toISOString());
        await redisClient.hMSet(key, data);

        console.log(`Processed data for sensor ${data.sensorId}`);
    } catch (error) {
        handleError(error);
    }
}

// Handle errors and recover from network interruptions
function handleError(error) {
    console.error('Error processing data:', error);
    // Implement recovery mechanisms here, e.g., re-establishing connections
}

// Monitor module health and performance in real-time
setInterval(() => {
    const clientCount = clients.length;
    const memoryUsage = process.memoryUsage();
    console.log(`Client count: ${clientCount}, Memory usage:`, memoryUsage);
}, 10000);

module.exports = { wss, redisClient };
