// Define a simple State class for the FSA
class State {
public:
    int id;
    State(int id) : id(id) {}
};

// Function to dynamically allocate memory for storing states in an FSA
std::unique_ptr<State[]> createFsaStates(size_t numStates) {
    if (numStates == 0) {
        throw std::invalid_argument("Number of states must be greater than zero.");
    }
    return std::make_unique<State[]>(numStates);
}

int main() {
    try {
        // Example usage
        size_t numStates = 5;
        auto fsaStates = createFsaStates(numStates);

        // Initialize FSA states
        for (size_t i = 0; i < numStates; ++i) {
            fsaStates[i] = State(i);
            std::cout << "State ID: " << fsaStates[i].id << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
