```go
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"sync"

	"github.com/gorilla/mux"
	"github.com/dgrijalva/jwt-go"
)

type UserProfile struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

var userProfiles = make(map[string]UserProfile)
var profileMutex sync.Mutex

func main() {
	r := mux.NewRouter()

	r.HandleFunc("/user/{id}", updateUserProfile).Methods("PUT")
	r.HandleFunc("/user/{id}", deleteUserProfile).Methods("DELETE")

	http.ListenAndServe(":8080", r)
}

func updateUserProfile(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id := vars["id"]
	var userProfile UserProfile

	err := json.NewDecoder(r.Body).Decode(&userProfile)
	if err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	profileMutex.Lock()
	defer profileMutex.Unlock()

	if _, exists := userProfiles[id]; !exists {
		http.Error(w, "User not found", http.StatusNotFound)
		return
	}

	userProfiles[id] = userProfile
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Profile updated successfully")
}

func deleteUserProfile(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id := vars["id"]

	profileMutex.Lock()
	defer profileMutex.Unlock()

	if _, exists := userProfiles[id]; !exists {
		http.Error(w, "User not found", http.StatusNotFound)
		return
	}

	delete(userProfiles, id)
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Profile deleted successfully")
}
