using System.Threading.Tasks;

public class SecureDataProcessor
{
    private readonly IKeyManagementService _keyManagementService;
    private readonly ILogger _logger;
    private readonly ConcurrentBag<EncryptedFile> _filesToDecrypt = new();
    private CancellationTokenSource _cancellationTokenSource;

    public SecureDataProcessor(IKeyManagementService keyManagementService, ILogger logger)
    {
        _keyManagementService = keyManagementService ?? throw new ArgumentNullException(nameof(keyManagementService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public void AddFile(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path cannot be null or empty", nameof(filePath));

        _filesToDecrypt.Add(new EncryptedFile { FilePath = filePath });
    }

    public async Task StartDecryptionAsync()
    {
        _cancellationTokenSource = new CancellationTokenSource();
        var tasks = _filesToDecrypt.Select(async file =>
        {
            try
            {
                await DecryptFileAsync(file, _cancellationTokenSource.Token);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to decrypt file: {file.FilePath}");
            }
        }).ToList();

        await Task.WhenAll(tasks);
    }

    public async ValueTask<Stream> GetDecryptedDataAsync(string filePath)
    {
        // Implement logic to retrieve decrypted data for a specific file
        throw new NotImplementedException();
    }

    private async Task DecryptFileAsync(EncryptedFile file, CancellationToken cancellationToken)
    {
        using var keyAndIv = await _keyManagementService.GetEncryptionKeyAndIVAsync(file.FilePath);
        if (keyAndIv == null)
            throw new InvalidOperationException("Failed to retrieve encryption key and IV for the file.");

        using var aes = Aes.Create();
        aes.Key = keyAndIv.Key;
        aes.IV = keyAndIv.IV;

        try
        {
            var decryptedData = await DecryptFileContentAsync(aes, file.FilePath, cancellationToken);
            // Process or store the decrypted data as needed
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error decrypting file: {file.FilePath}");
        }
    }

    private async Task<byte[]> DecryptFileContentAsync(Aes aes, string filePath, CancellationToken cancellationToken)
    {
        using var inputStream = new FileStream(filePath, FileMode.Open, FileAccess.Read);
        using var cryptoStream = new CryptoStream(inputStream, aes.CreateDecryptor(), CryptoStreamMode.Read);
        using var memoryStream = new MemoryStream();

        await cryptoStream.CopyToAsync(memoryStream, 1024 * 1024, cancellationToken); // Buffer size: 1MB
        return memoryStream.ToArray();
    }

    public void CancelDecryption()
    {
        _cancellationTokenSource?.Cancel(false);
    }
}

public class EncryptedFile
{
    public string FilePath { get; set; }
}

public interface IKeyManagementService
{
    Task<(byte[] Key, byte[] IV)> GetEncryptionKeyAndIVAsync(string filePath);
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}
