#include <condition_variable>
#include <future>
#include <chrono>
#include <boost/asio.hpp>

namespace fs = std::filesystem;
using namespace boost::asio;

class SandeshClient {
public:
    void sendRequest(const std::string& url, const std::string& data) {
        // Implementation using Boost.Asio to send POST requests
    }
};

class FileProcessor {
private:
    SandeshClient& sandeshClient;
    std::thread workerThread;
    std::queue<fs::path> fileQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;
    bool stopProcessing;

public:
    FileProcessor(SandeshClient& client) : sandeshClient(client), stopProcessing(false) {
        workerThread = std::thread(&FileProcessor::processFiles, this);
    }

    ~FileProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stopProcessing = true;
        }
        queueCondition.notify_all();
        workerThread.join();
    }

    void enqueueFile(const fs::path& filePath) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            fileQueue.push(filePath);
        }
        queueCondition.notify_one();
    }

private:
    void processFiles() {
        while (true) {
            fs::path filePath;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                queueCondition.wait(lock, [this] { return !fileQueue.empty() || stopProcessing; });
                if (stopProcessing && fileQueue.empty()) break;
                filePath = fileQueue.front();
                fileQueue.pop();
            }

            // Read and process the file
            std::ifstream file(filePath);
            if (!file) {
                std::cerr << "Failed to open file: " << filePath << std::endl;
                continue;
            }

            std::string line;
            while (std::getline(file, line)) {
                // Process each line
                sandeshClient.sendRequest("http://example.com/api", line);
            }
        }
    }
};

int main() {
    SandeshClient sandeshClient;
    FileProcessor processor(sandeshClient);

    fs::path directoryPath = "path/to/text/files";
    for (const auto& entry : fs::directory_iterator(directoryPath)) {
        if (entry.is_regular_file() && entry.path().extension() == ".txt") {
            processor.enqueueFile(entry.path());
        }
    }

    // Simulate work to keep the application running
    std::this_thread::sleep_for(std::chrono::seconds(3600));

    return 0;
}
