#[tokio::main]
async fn main() {
    let matches = App::new("Image Processing System")
        .version("1.0")
        .author("Your Name")
        .about("Process large image files asynchronously and integrate with an external RESTful API for metadata extraction.")
        .arg(
            Arg::with_name("directory")
                .short('d')
                .long("directory")
                .value_name("DIR")
                .help("Sets the directory to scan for image files")
                .takes_value(true)
                .required(true),
        )
        .subcommand(App::new("run").about("Starts the image processing system"))
        .get_matches();

    let directory = matches.value_of("directory").unwrap();

    if let Some(subcommand) = matches.subcommand_matches("run") {
        run_image_processing_system(directory).await;
    } else {
        println!("Invalid subcommand");
    }
}

async fn run_image_processing_system(directory: &str) {
    // Initialize components
    let image_processor = image_processor::ImageProcessor::new();
    let api_client = api_client::APIClient::new();
    let db_manager = db_manager::DBManager::new();
    let cache_manager = cache_manager::CacheManager::new();
    let config_loader = config_loader::ConfigLoader::new();
    let logger = logger::Logger::new();

    // Load configuration
    let config = config_loader.load_config("config.yaml").await;

    // Initialize rate limiter and retry mechanism

    // Initialize redis for caching

    // Start processing directory in parallel
    let (tx, mut rx) = mpsc::channel(100);
    tokio::spawn(async move {
        scan_directory(directory, tx).await;
    });

    while let Some(image_path) = rx.recv().await {
        image_processor.preprocess_image(&image_path).await;
        api_client.extract_metadata(&image_path).await;
        db_manager.store_metadata(&image_path).await;
    }

    // Graceful shutdown
}

async fn scan_directory(path: &str, tx: mpsc::Sender<String>) {
    for entry in fs::read_dir(path).expect("Failed to read directory") {
        let entry = entry.expect("Failed to read dir entry");
        if entry.file_type().expect("Failed to get file type").is_file() {
            if let Some(extension) = entry.path().extension() {
                match extension.to_str() {
                    Some("jpg" | "jpeg" | "png") => {
                        tx.send(entry.path().display().to_string()).await.unwrap();
                    }
                    _ => {}
                }
            }
        } else if entry.file_type().expect("Failed to get file type").is_dir() {
            scan_directory(&entry.path(), tx).await;
        }
    }
}
