```rust
use reqwest::{Client, Error, header};
use tokio::time::{self, Duration};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

#[derive(Clone)]
struct RateLimiter {
    limiter: Arc<Mutex<HashMap<String, (u32, time::Instant)>>>,
}

impl RateLimiter {
    fn new() -> Self {
        RateLimiter {
            limiter: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    async fn check_and_wait(&self, endpoint: &str) -> Result<(), Error> {
        let mut limiter = self.limiter.lock().unwrap();
        if let Some((requests, last_reset)) = limiter.get_mut(endpoint) {
            if *requests >= 500 {
                if time::Instant::now() < *last_reset + Duration::from_secs(300) {
                    let wait_time = *last_reset + Duration::from_secs(300) - time::Instant::now();
                    time::sleep(wait_time).await;
                }
                *requests = 1;
                *last_reset = time::Instant::now();
            } else {
                *requests += 1;
            }
        } else {
            limiter.insert(endpoint.to_string(), (1, time::Instant::now()));
        }
        Ok(())
    }
}

struct AuthClient {
    client: Client,
    rate_limiter: RateLimiter,
    auth_token: Option<String>,
}

impl AuthClient {
    async fn new() -> Self {
        AuthClient {
            client: Client::new(),
            rate_limiter: RateLimiter::new(),
            auth_token: None,
        }
    }

    async fn fetch_auth_token(&mut self) -> Result<(), Error> {
        // Simulate fetching token from secure API
        let response = reqwest::get("https://api.example.com/auth").await?;
        let token: String = response.json().await?;
        self.auth_token = Some(token);
        Ok(())
    }

    async fn request<T>(&mut self, method: &str, url: &str, headers: Option<HashMap<String, String>>) -> Result<T, Error>
    where
        for<'de> T: serde::Deserialize<'de>,
    {
        if let None = self.auth_token {
            self.fetch_auth_token().await?;
        }

        let mut request = match method {
            "GET" => self.client.get(url),
            "POST" => self.client.post(url),
            "PUT" => self.client.put(url),
            "DELETE" => self.client.delete(url),
            _ => return Err(Error::new(reqwest::StatusCode::NotFound, "Unsupported HTTP method")),
        };

        request = match headers {
            Some(headers) => headers.into_iter().fold(request, |req, (key, value)| req.header(key, value)),
            None => request,
        };

        self.rate_limiter.check_and_wait(url).await?;
        let response = request.send().await?;

        if !response.status().is_success() {
            return Err(Error::new(response.status(), "Request failed"));
        }

        response.json::<T>().await
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let mut client = AuthClient::new().await?;
    let url = "https://api.example.com/data";
    let headers = Some([
        ("Authorization", client.auth_token.as_ref().unwrap()),
        ("Content-Type", "application/json"),
    ].iter()
    .cloned()
    .map(|(k, v)| (String::from(k), String::from(v)))
    .collect());

    match client.request::<serde_json::Value>("GET", url, headers).await {
        Ok(data) => println!("Data: {:?}", data),
        Err(e) => eprintln!("Error: {}", e),
    }

    Ok(())
}
```

