```cpp
#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <unordered_map>
#include <fstream>

class Employee {
public:
    int id;
    std::unique_ptr<char[]> name;
    std::unique_ptr<char[]> department;

    Employee(int id, const std::string& name, const std::string& department)
        : id(id), name(new char[name.size() + 1]), department(new char[department.size() + 1]) {
        std::copy(name.begin(), name.end(), this->name.get());
        this->name.get()[name.size()] = '\0';
        std::copy(department.begin(), department.end(), this->department.get());
        this->department.get()[department.size()] = '\0';
    }

    ~Employee() = default;
};

class BinaryEmployeeSerializer {
public:
    void save(const std::vector<Employee>& employees, const std::string& filename) {
        std::ofstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file for writing.");
        }
        size_t size = employees.size();
        file.write(reinterpret_cast<char*>(&size), sizeof(size));
        for (const auto& employee : employees) {
            file.write(reinterpret_cast<const char*>(&employee.id), sizeof(employee.id));
            size_t nameSize = strlen(employee.name.get());
            file.write(reinterpret_cast<const char*>(&nameSize), sizeof(nameSize));
            file.write(employee.name.get(), nameSize);
            size_t departmentSize = strlen(employee.department.get());
            file.write(reinterpret_cast<const char*>(&departmentSize), sizeof(departmentSize));
            file.write(employee.department.get(), departmentSize);
        }
    }

    std::vector<Employee> load(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file for reading.");
        }
        size_t size;
        file.read(reinterpret_cast<char*>(&size), sizeof(size));
        std::vector<Employee> employees;
        employees.reserve(size);
        for (size_t i = 0; i < size; ++i) {
            Employee employee;
            file.read(reinterpret_cast<char*>(&employee.id), sizeof(employee.id));
            size_t nameSize;
            file.read(reinterpret_cast<char*>(&nameSize), sizeof(nameSize));
            employee.name.reset(new char[nameSize + 1]);
            file.read(employee.name.get(), nameSize);
            employee.name.get()[nameSize] = '\0';
            size_t departmentSize;
            file.read(reinterpret_cast<char*>(&departmentSize), sizeof(departmentSize));
            employee.department.reset(new char[departmentSize + 1]);
            file.read(employee.department.get(), departmentSize);
            employee.department.get()[departmentSize] = '\0';
            employees.push_back(std::move(employee));
        }
        return employees;
    }
};

class EmployeeManager {
public:
    void addEmployee(const std::string& id, const std::string& name, const std::string& department) {
        employees[id] = Employee(std::stoi(id), name, department);
    }

    Employee getEmployee(const std::string& id) {
        auto it = employees.find(id);
        if (it != employees.end()) {
            return it->second;
        }
        throw std::runtime_error("Employee not found.");
    }

private:
    std::unordered_map<std::string, Employee> employees;
};

int main() {
    BinaryEmployeeSerializer serializer;
    std::vector<Employee> employees = {
        {1, "Alice", "HR"},
        {2, "Bob", "IT"},
        {3, "Charlie", "Finance"}
    };
    serializer.save(employees, "employees.bin");

    EmployeeManager manager;
    for (const auto& employee : employees) {
        manager.addEmployee(std::to_string(employee.id), employee.name.get(), employee.department.get());
    }

    Employee retrievedEmployee = manager.getEmployee("2");
    std::cout << "Retrieved Employee: ID=" << retrievedEmployee.id << ", Name=" << retrievedEmployee.name.get() << ", Department=" << retrievedEmployee.department.get() << std::endl;

    return 0;
}
