### C++ Random Number Generator Service

```cpp
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <vector>
#include <random>
#include <crypto++/cryptlib.h>

class SecureRandomNumberGenerator {
public:
    SecureRandomNumberGenerator() {
        // Initialize cryptographic library (e.g., Crypto++)
    }

    ~SecureRandomNumberGenerator() {
        // Cleanup resources
    }

    int32_t GenerateNumber(int seed) {
        std::mt19937 gen(seed);
        return gen();
    }
};

class RandomNumberService {
public:
    RandomNumberService(size_t poolSize) : generatorPool(poolSize), stop(false) {
        for (size_t i = 0; i < poolSize; ++i) {
            workers.emplace_back(&RandomNumberService::workerThread, this);
        }
    }

    ~RandomNumberService() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    int32_t Generate(int seed) {
        std::unique_lock<std::mutex> lock(mutex);
        requests.push(seed);
        condition.notify_one();
        return results.front();
    }

private:
    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !requests.empty() || stop; });
            if (stop && requests.empty()) {
                break;
            }
            int seed = requests.front();
            requests.pop();
            lock.unlock();

            SecureRandomNumberGenerator rng;
            int32_t number = rng.GenerateNumber(seed);
            results.push(number);
        }
    }

private:
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::queue<int> requests;
    std::queue<int32_t> results;
    bool stop;
    SecureRandomNumberGenerator generatorPool;
};
