import os
import queue
import logging
import concurrent.futures
from PyPDF2 import PdfFileReader, PdfFileWriter
from pdf2image import convert_from_path
from PIL import Image
import requests

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DocumentProcessor:
    def __init__(self, output_dir='output', max_workers=4):
        self.output_dir = output_dir
        self.max_workers = max_workers
        self.pdf_queue = queue.Queue()

    def add_pdf_to_queue(self, pdf_path):
        if os.path.exists(pdf_path) and pdf_path.endswith('.pdf'):
            self.pdf_queue.put(pdf_path)
        else:
            logger.error(f"Invalid PDF file: {pdf_path}")

    def process_documents(self):
        with concurrent.futures.ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            futures = {executor.submit(self.process_pdf, pdf): pdf for pdf in iter(self.pdf_queue.get, None)}
            for future in concurrent.futures.as_completed(futures):
                pdf_path = futures[future]
                try:
                    result = future.result()
                    logger.info(f"Processed PDF: {pdf_path}")
                except Exception as e:
                    logger.error(f"Error processing PDF: {pdf_path}, Error: {e}")

    def process_pdf(self, pdf_path):
        output_dir = os.path.join(self.output_dir, os.path.splitext(os.path.basename(pdf_path))[0])
        if not os.path.exists(output_dir):
            os.makedirs(output_dir)

        with open(pdf_path, 'rb') as file:
            reader = PdfFileReader(file)
            for page_num in range(reader.numPages):
                pdf_writer = PdfFileWriter()
                pdf_writer.addPage(reader.getPage(page_num))
                output_pdf_path = os.path.join(output_dir, f"page_{page_num + 1}.pdf")
                with open(output_pdf_path, 'wb') as output_file:
                    pdf_writer.write(output_file)

        images = convert_from_path(pdf_path)
        for i, image in enumerate(images):
            output_image_path = os.path.join(output_dir, f"page_{i + 1}.jpg")
            image.save(output_image_path, "JPEG")

    def send_data_to_service(self, data, service_url, api_key):
        headers = {
            'Authorization': f'Bearer {api_key}',
            'Content-Type': 'application/json'
        }
        response = requests.post(service_url, json=data, headers=headers)
        if response.status_code == 200:
            logger.info("Data sent successfully to service")
        else:
            logger.error(f"Failed to send data to service, Error: {response.text}")

# Example usage
if __name__ == "__main__":
    processor = DocumentProcessor(output_dir='processed_pdfs')
    processor.add_pdf_to_queue('large_archive.pdf')
    processor.process_documents()
```

