import json
from concurrent.futures import ThreadPoolExecutor, as_completed
from sentiment_analysis_module import analyze_sentiment

def process_review(review):
    try:
        review_data = json.loads(review)
        product_features = review_data.get('product_features', {})
        sentiments = {}

        for feature, text in product_features.items():
            sentiment = analyze_sentiment(text)
            sentiments[feature] = sentiment

        return sentiments
    except json.JSONDecodeError:
        print("Invalid JSON format")
        return None

def process_reviews_file(file_path):
    with open(file_path, 'r') as file:
        reviews = file.readlines()

    results = []
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(process_review, review): review for review in reviews}

        for future in as_completed(futures):
            review = futures[future]
            try:
                result = future.result()
                if result is not None:
                    results.append(result)
            except Exception as e:
                print(f"Error processing review: {e}")

    return results

def main():
    file_paths = ['reviews1.json', 'reviews2.json', 'reviews3.json']  # Example file paths

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = {executor.submit(process_reviews_file, path): path for path in file_paths}

        for future in as_completed(futures):
            path = futures[future]
            try:
                results = future.result()
                print(f"Processed results from {path}: {results}")
            except Exception as e:
                print(f"Error processing file: {e}")

if __name__ == "__main__":
    main()
```

