// Function to perform batch crossover operations on multiple prompts stored in binary files
void PerformBatchCrossover(const std::vector<std::string>& filenames, const DatabaseConnection& dbConn) {
    for (const auto& filename : filenames) {
        try {
            // Load prompt from binary file
            std::ifstream file(filename, std::ios::binary);
            if (!file.is_open()) {
                throw std::runtime_error("Failed to open file: " + filename);
            }

            std::string fileContent((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
            file.close();

            // Deserialize prompt data
            std::string promptData = BinaryFormatter::Deserialize(fileContent);

            // Validate prompt data with the database
            if (!dbConn.IsValidData(promptData)) {
                throw std::runtime_error("Invalid data detected in file: " + filename);
            }

            // Modify filenames by appending a unique identifier
            std::string newFilename = filename.substr(0, filename.find_last_of('.')) + "_processed.bin";

            // Save the modified prompt to a new file
            std::ofstream outFile(newFilename, std::ios::binary);
            if (!outFile.is_open()) {
                throw std::runtime_error("Failed to create new file: " + newFilename);
            }

            outFile.write(promptData.c_str(), promptData.size());
            outFile.close();

            std::cout << "Processed file: " << filename << " -> " << newFilename << std::endl;
        } catch (const std::exception& e) {
            std::cerr << "Error processing file: " << filename << " - " << e.what() << std::endl;
        }
    }
}

// Main function to handle command-line arguments and execute batch crossover operations
