    try {
        namespace po = boost::program_options;

        po::options_description desc("Allowed options");
        desc.add_options()
            ("help", "produce help message")
            ("directory", po::value<std::string>(), "directory containing the binary files")
            ("db-type", po::value<std::string>()->default_value("SQL"), "database connection type (SQL, NoSQL)")
            ("connection-string", po::value<std::string>(), "database connection string");

        po::variables_map vm;
        po::store(po::parse_command_line(argc, argv, desc), vm);
        po::notify(vm);

        if (vm.count("help")) {
            std::cout << desc << "\n";
            return 1;
        }

        std::string directory = vm["directory"].as<std::string>();
        std::string dbType = vm["db-type"].as<std::string>();
        std::string connectionString = vm["connection-string"].as<std::string>();

        // Validate command-line arguments
        if (vm.count("directory") == 0) {
            throw std::runtime_error("Directory not specified");
        }

        if (vm.count("connection-string") == 0) {
            throw std::runtime_error("Database connection string not specified");
        }

        // Create database connection
        DatabaseConnection::ConnectionType connType = dbType == "SQL" ? DatabaseConnection::ConnectionType::SQL : DatabaseConnection::ConnectionType::NoSQL;
        DatabaseConnection dbConn(connType, connectionString);

