import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Random;

public class DistributedServiceManager {
    private final int minStartDelay;
    private final int maxStartDelay;
    private final int minStopDelay;
    private final int maxStopDelay;
    private final int healthCheckInterval;
    private final double resourceUtilizationThreshold;
    private final BlockingQueue<Runnable> serviceQueue = new LinkedBlockingQueue<>();
    private final ExecutorService executorService = Executors.newCachedThreadPool();
    private AtomicInteger activeServices = new AtomicInteger(0);
    private Random random = new Random();

    public DistributedServiceManager(int minStartDelay, int maxStartDelay, int minStopDelay, int maxStopDelay,
                                    int healthCheckInterval, double resourceUtilizationThreshold) {
        this.minStartDelay = minStartDelay;
        this.maxStartDelay = maxStartDelay;
        this.minStopDelay = minStopDelay;
        this.maxStopDelay = maxStopDelay;
        this.healthCheckInterval = healthCheckInterval;
        this.resourceUtilizationThreshold = resourceUtilizationThreshold;

        // Start monitoring thread
        executorService.submit(() -> {
            while (true) {
                try {
                    Thread.sleep(healthCheckInterval);
                    checkServiceHealth();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });
    }

    public void startService() {
        if (activeServices.get() < getMaxActiveServices()) {
            int delay = random.nextInt(maxStartDelay - minStartDelay + 1) + minStartDelay;
            executorService.schedule(this::runService, delay, TimeUnit.MILLISECONDS);
        } else {
            System.out.println("Max active services reached. Cannot start new service.");
        }
    }

    private void runService() {
        try {
            // Simulate service running logic
            System.out.println("Service started");

            // Periodic health check within the service
            while (true) {
                Thread.sleep(healthCheckInterval);
                if (!checkServiceHealth()) {
                    break;
                }
            }

            System.out.println("Service stopped due to health issue");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            startService(); // Restart service
        }
    }

    private boolean checkServiceHealth() {
        double currentUtilization = getRandomResourceUtilization();

        if (currentUtilization > resourceUtilizationThreshold) {
            System.out.println("Service exceeded resource utilization threshold. Initiating graceful shutdown.");
            return false;
        }

        System.out.println("Service health check passed with current utilization: " + currentUtilization);
        return true;
    }

    private double getRandomResourceUtilization() {
        // Simulate random resource utilization
        return random.nextDouble() * 100; // Resource usage between 0% and 100%
    }

    private int getMaxActiveServices() {
        // Simulate maximum active services calculation based on current system resources
        return 5; // Example value, replace with actual logic
    }

    public void stopService() {
        int delay = random.nextInt(maxStopDelay - minStopDelay + 1) + minStopDelay;
        executorService.schedule(this::shutdownService, delay, TimeUnit.MILLISECONDS);
    }

    private void shutdownService() {
        System.out.println("Service initiating graceful shutdown");
        // Simulate service shutdown logic
    }

    public void close() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        DistributedServiceManager manager = new DistributedServiceManager(5000, 10000, 3000, 8000, 5000, 90.0);

        for (int i = 0; i < 20; i++) {
            manager.startService();
        }

        // Simulate running the manager for a while
        try {
            TimeUnit.MINUTES.sleep(1);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        manager.close();
    }
}
