```java
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class URLMetadataFetcher {
    private static final int THREAD_POOL_SIZE = 10;
    private static final long CHECK_INTERVAL = 60 * 1000; // every minute
    private ExecutorService executorService;

    public URLMetadataFetcher() {
        this.executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
    }

    public void startFetchingMetadata(String[] urls) {
        for (String url : urls) {
            executorService.submit(() -> fetchMetadata(url));
        }
    }

    private void fetchMetadata(String url) {
        try {
            URL obj = new URL(url);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();
            int responseCode = con.getResponseCode();
            System.out.println("URL: " + url + ", Response Code: " + responseCode);

            // Simulate metadata fetching
            Thread.sleep(1000); // Simulating 1 second for metadata fetch

        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public void stopFetchingMetadata() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException ex) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        URLMetadataFetcher fetcher = new URLMetadataFetcher();
        String[] urls = {"http://example.com", "http://example.org"};
        fetcher.startFetchingMetadata(urls);

        // Simulate running for a while
        try {
            Thread.sleep(3 * CHECK_INTERVAL);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        fetcher.stopFetchingMetadata();
    }
}
```

