using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;

public class WebsiteManager
{
    private readonly HttpClient _httpClient;

    public WebsiteManager(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<WebsiteStatus> AddAndStartWebsiteAsync(string directoryPath, string siteName, string configServiceUrl)
    {
        try
        {
            // Validate input
            if (string.IsNullOrEmpty(directoryPath) || string.IsNullOrEmpty(siteName))
                return new WebsiteStatus(false, "Directory path and site name are required.");

            if (!Directory.Exists(directoryPath))
                return new WebsiteStatus(false, $"Directory {directoryPath} does not exist.");

            // Fetch configuration from external service
            var config = await FetchConfigAsync(configServiceUrl);
            if (config == null)
                return new WebsiteStatus(false, "Failed to fetch configuration from the external service.");

            // Create web.config file if missing
            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                File.WriteAllText(webConfigPath, config.WebConfigContent);
            }

            // Simulate website addition and start process
            await Task.Delay(100); // Simulate async operation

            return new WebsiteStatus(true, $"Website {siteName} added and started successfully.");
        }
        catch (Exception ex)
        {
            return new WebsiteStatus(false, $"An error occurred: {ex.Message}");
        }
    }

    private async Task<ConfigResponse> FetchConfigAsync(string url)
    {
        try
        {
            var response = await _httpClient.GetAsync(url);
            if (!response.IsSuccessStatusCode)
                throw new Exception($"Failed to fetch configuration from the external service.");

            var content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<ConfigResponse>(content);
        }
        catch (Exception ex)
        {
            // Log error and handle gracefully
            Console.WriteLine($"Error fetching config: {ex.Message}");
            return null;
        }
    }
}

public class ConfigResponse
{
    public string WebConfigContent { get; set; }
}

public class WebsiteStatus
{
    public bool Success { get; }
    public string Message { get; }

    public WebsiteStatus(bool success, string message)
    {
        Success = success;
        Message = message;
    }
}
