// JavaScript function to extract book names from a given text
function extractBookNames(text) {
  if (typeof text !== 'string' || !text.trim()) {
    throw new Error('Input must be a non-empty string');
  }

  const bookNames = {};
  const regex = /\b(?:Old|New)\sTestament\s+\w+\b/gi;
  let match;

  while ((match = regex.exec(text)) !== null) {
    const bookName = match[0].trim();
    if (bookNames[bookName]) {
      bookNames[bookName]++;
    } else {
      bookNames[bookName] = 1;
    }
  }

  return bookNames;
}

