public class EncryptionService {
    private static readonly HttpClient _httpClient = new HttpClient();
    private static readonly string _configFilePath = "path_to_config_file";
    private static readonly int _maxRetries = 3;

    public static void DecryptMessage(string base64EncodedEncryptedMessage, byte[] key, byte[] iv) {
        byte[] decryptedMessage = null;
        for (int attempt = 0; attempt <= _maxRetries; attempt++) {
            try {
                using (TripleDES td = TripleDES.Create()) {
                    td.Key = key;
                    td.IV = iv;
                    ICryptoTransform decryptor = td.CreateDecryptor(td.Key, td.IV);
                    byte[] encryptedBytes = Convert.FromBase64String(base64EncodedEncryptedMessage);
                    decryptedMessage = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
                }

                // Integrate with external encryption service API here...

                Console.WriteLine($"Decryption attempt {attempt + 1} successful");
                break;
            } catch (Exception ex) {
                if (attempt == _maxRetries) {
                    Console.WriteLine("Decryption failed after multiple attempts");
                } else {
                    Console.WriteLine($"Decryption attempt {attempt + 1} failed: {ex.Message}");
                    Thread.Sleep((int)Math.Pow(2, attempt) * 1000); // Exponential backoff
                }
