extern crate reqwest;
extern crate tokio;
extern crate serde_json;

use reqwest::{Client, Error};
use tokio::sync::ThreadPool;
use std::collections::HashMap;
use bcrypt::{hash, verify};

#[derive(Debug)]
enum AuthenticationError {
    InvalidCredentials,
    NetworkError(reqwest::StatusCode, String),
}

struct RequestBuilder {
    url: String,
    client: Client,
    headers: HashMap<String, String>,
    body: Option<String>,
    timeout: u64,
    validate_certs: bool,
}

impl RequestBuilder {
    fn new(url: &str) -> Self {
        RequestBuilder {
            url: url.to_string(),
            client: Client::new(),
            headers: HashMap::new(),
            body: None,
            timeout: 5000, // default timeout in milliseconds
            validate_certs: true,
        }
    }

    fn header(mut self, key: &str, value: &str) -> Self {
        self.headers.insert(key.to_string(), value.to_string());
        self
    }

    fn body<T>(mut self, body: T) -> Self
    where
        T: serde::Serialize,
    {
        self.body = Some(serde_json::to_string(&body).unwrap());
        self
    }

    fn timeout(mut self, timeout: u64) -> Self {
        self.timeout = timeout;
        self
    }

    fn validate_certs(mut self, validate_certs: bool) -> Self {
        self.validate_certs = validate_certs;
        self
    }

    async fn send(&self) -> Result<reqwest::Response, Error> {
        let mut request = reqwest::Request::new(reqwest::Method::GET, &self.url);
        for (key, value) in &self.headers {
            request = request.header(key, value);
        }
        if let Some(body) = &self.body {
            request = request.body(body.clone());
        }
        request.timeout(std::time::Duration::from_millis(self.timeout));
        if !self.validate_certs {
            request = request.dangerously_set_ssl_verify(false);
        }

        self.client.request(request).await
    }
}

