```typescript
import { createHash } from 'crypto';

interface FileChunk {
  index: number;
  data: Uint8Array;
  checksum: string;
}

async function mergeFileChunks(chunks: AsyncIterable<FileChunk>): Promise<Uint8Array> {
  const chunkMap = new Map<number, Uint8Array>();
  let totalLength = 0;

  for await (const chunk of chunks) {
    const calculatedChecksum = createHash('sha256').update(chunk.data).digest('hex');
    if (calculatedChecksum !== chunk.checksum) {
      throw new Error(`Chunk ${chunk.index} has an invalid checksum.`);
    }

    chunkMap.set(chunk.index, chunk.data);
    totalLength += chunk.data.length;
  }

  const mergedFile = new Uint8Array(totalLength);
  let offset = 0;

  for (const index of Array.from(chunkMap.keys()).sort((a, b) => a - b)) {
    mergedFile.set(chunkMap.get(index)!, offset);
    offset += chunkMap.get(index)!.length;
  }

  return mergedFile;
}
