#include <iostream>
#include <thread>
#include <vector>
#include <random>
#include <openssl/sha.h> // Include OpenSSL for hashing

namespace SecureRandomGenerator {
    class MT19937ThreadSafe {
    public:
        MT19937ThreadSafe(uint64_t seed, const std::string& hashAlgorithm);
        ~MT19937ThreadSafe();
        uint64_t generateNumber();
        void setRange(int min, int max);

    private:
        std::mt19937_64 generator;
        std::uniform_int_distribution<int> distribution;
        static constexpr size_t seedLength = 64;

        static std::mutex mtx;
    };

    extern MT19937ThreadSafe* instance;
}

// Definitions for the class and its member variables
SecureRandomGenerator::MT19937ThreadSafe* SecureRandomGenerator::instance = nullptr;
std::mutex SecureRandomGenerator::MT19937ThreadSafe::mtx;

// Constructor implementation
SecureRandomGenerator::MT19937ThreadSafe::MT19937ThreadSafe(uint64_t seed, const std::string& hashAlgorithm) {
    // Hash the seed using OpenSSL
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, &seed, sizeof(seed));
    SHA256_Final(hash, &sha256);

    // Convert hash to a 64-bit seed
    uint64_t secureSeed = (static_cast<uint64_t>(hash[0]) << 56) |
                           (static_cast<uint64_t>(hash[1]) << 48) |
                           (static_cast<uint64_t>(hash[2]) << 40) |
                           (static_cast<uint64_t>(hash[3]) << 32) |
                           (static_cast<uint64_t>(hash[4]) << 24) |
                           (static_cast<uint64_t>(hash[5]) << 16) |
                           (static_cast<uint64_t>(hash[6]) << 8) |
                           static_cast<uint64_t>(hash[7]);

    // Initialize the generator with the secure seed
    generator.seed(secureSeed);
}

// Destructor implementation
SecureRandomGenerator::MT19937ThreadSafe::~MT19937ThreadSafe() {
    // Clean up resources if necessary
}

// Generate a random number within the specified range
uint64_t SecureRandomGenerator::MT19937ThreadSafe::generateNumber() {
    std::lock_guard<std::mutex> lock(mtx);
    return distribution(generator);
}

// Set the range for the random numbers
void SecureRandomGenerator::MT19937ThreadSafe::setRange(int min, int max) {
    std::lock_guard<std::mutex> lock(mtx);
    distribution = std::uniform_int_distribution<int>(min, max);
}
```

