#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

#define LOG_MAX_LEN 1024

typedef enum {
    INFO,
    WARNING,
    ERROR,
    CRITICAL,
    DEBUG
} LogLevel;

typedef enum {
    FILE_LOGGER,
    SYSLOG_LOGGER
} LoggerType;

void logCondition(LoggerType loggerType, const char *filePath, int severity, const char *format, ...) {
    static pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
    va_list args;
    char buffer[LOG_MAX_LEN];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    pthread_mutex_lock(&logMutex);

    if (severity > INFO) {
        // Filter out less severe messages
        pthread_mutex_unlock(&logMutex);
        return;
    }

    snprintf(buffer, sizeof(buffer), "%s [%d] ", asctime(tm_info), severity);
    va_start(args, format);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), format, args);
    va_end(args);

    switch (loggerType) {
        case FILE_LOGGER:
            if (filePath == NULL || filePath[0] == '\0') {
                fprintf(stderr, "Error: Null or empty file path\n");
                break;
            }
            FILE *logFile = fopen(filePath, "a");
            if (logFile == NULL) {
                perror("Failed to open log file");
                break;
            }
            fprintf(logFile, "%s\n", buffer);
            fclose(logFile);
            break;
        case SYSLOG_LOGGER:
            // Implement syslog logging here
            printf("%s\n", buffer); // Placeholder for syslog implementation
            break;
    }

    pthread_mutex_unlock(&logMutex);
}
