#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <random>
#include <vector>
#include <queue>
#include <mutex>

namespace SecureCrypto {

class SecureRandomQuadtree {
private:
    static std::mt19937 rng;
    EVP_CIPHER_CTX* cipherCtx;

public:
    SecureRandomQuadtree(const std::string& password, const std::string& salt) {
        if (password.length() < 8 || salt.length() < 8) {
            throw std::invalid_argument("Password and salt must be at least 8 characters long.");
        }
        unsigned char key[32], iv[16];
        deriveKeyAndIV(password, salt, key, iv);
        cipherCtx = EVP_CIPHER_CTX_new();
        if (!cipherCtx) {
            throw std::runtime_error("Failed to create AES-256-CBC context.");
        }
        if (1 != EVP_EncryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, key, iv)) {
            throw std::runtime_error("Failed to initialize AES-256-CBC cipher.");
        }
    }

    ~SecureRandomQuadtree() {
        EVP_CIPHER_CTX_free(cipherCtx);
    }

private:
    static void deriveKeyAndIV(const std::string& password, const std::string& salt, unsigned char key[32], unsigned char iv[16]) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256((unsigned char*)password.c_str(), password.length(), hash);
        memcpy(key, hash, 32);

        std::mt19937 rng;
        rng.seed(hash[0] + hash[1]);
        for (size_t i = 0; i < 16; ++i) {
            iv[i] = rng();
        }
    }
};

} // namespace SecureCrypto
