#define MAX_FIELDS 10
#define BUFFER_SIZE 256

typedef struct {
    int id;
    double average;
} DataPoint;

DataPoint dataArray[1000];
int dataArrayIndex = 0;

sem_t semaphore;

void* networkStreamHandler(void* arg) {
    FILE* stream = (FILE*)arg;
    char buffer[BUFFER_SIZE];

    while (!feof(stream)) {
        if (sem_wait(&semaphore) != 0) {
            perror("Failed to wait on semaphore");
            continue;
        }

        if (fgets(buffer, BUFFER_SIZE, stream) == NULL) {
            if (feof(stream)) {
                printf("End of file reached.\n");
            } else {
                perror("Error reading from network stream");
            }
            sem_post(&semaphore);
            break;
        }

        // Process data here
        // Example: Calculate average and save to dataArray

        sem_post(&semaphore);
    }

    return NULL;
}

void* realTimeDatabaseHandler(void* arg) {
    FILE* output = (FILE*)arg;

    while (dataArrayIndex > 0) {
        if (sem_wait(&semaphore) != 0) {
            perror("Failed to wait on semaphore");
            continue;
        }

        DataPoint point = dataArray[--dataArrayIndex];
        fprintf(output, "%d,%f\n", point.id, point.average);

        sem_post(&semaphore);
    }

    return NULL;
}

void* semaphoreManager(void* arg) {
    // Implement semaphore creation and deletion here
    // Example:
    if (sem_init(&semaphore, 0, 1) != 0) {
        perror("Failed to initialize semaphore");
        exit(EXIT_FAILURE);
    }

    return NULL;
}

void testNetworkStreamHandler() {
