}

int main() {
    FILE* networkStream = fopen("network_stream.txt", "r");
    if (networkStream == NULL) {
        perror("Failed to open network stream file");
        return EXIT_FAILURE;
    }

    pthread_t networkThread, dbThread, semaphoreThread;

    if (pthread_create(&networkThread, NULL, networkStreamHandler, networkStream) != 0) {
        perror("Failed to create network thread");
        fclose(networkStream);
        return EXIT_FAILURE;
    }

    FILE* output = fopen("output.txt", "w");
    if (output == NULL) {
        perror("Failed to open output file");
        pthread_join(networkThread, NULL);
        fclose(networkStream);
        return EXIT_FAILURE;
    }

    if (pthread_create(&dbThread, NULL, realTimeDatabaseHandler, output) != 0) {
        perror("Failed to create database thread");
        pthread_join(networkThread, NULL);
        fclose(networkStream);
        fclose(output);
        return EXIT_FAILURE;
    }

    if (pthread_create(&semaphoreThread, NULL, semaphoreManager, NULL) != 0) {
        perror("Failed to create semaphore manager thread");
        pthread_join(networkThread, NULL);
        pthread_join(dbThread, NULL);
        fclose(networkStream);
        fclose(output);
        return EXIT_FAILURE;
    }

    pthread_join(networkThread, NULL);
    pthread_join(dbThread, NULL);
    pthread_join(semaphoreThread, NULL);

    sem_destroy(&semaphore);

    fclose(networkStream);
    fclose(output);

    testNetworkStreamHandler();

    return 0;
}
