import requests
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session
import json

class CloudStorageAPIClient:
    def __init__(self, client_id, client_secret, token_url):
        self.client = BackendApplicationClient(client_id=client_id)
        self.session = OAuth2Session(client=self.client)
        self.token_url = token_url
        self.refresh_token = None

    def get_access_token(self):
        if not self.access_token_valid():
            self.fetch_new_token()
        return self.session.token['access_token']

    def fetch_new_token(self):
        token = self.session.fetch_token(token_url=self.token_url, client_id=self.client_id, client_secret=self.client_secret)
        self.refresh_token = token.get('refresh_token', None)

    def access_token_valid(self):
        if not self.session.token:
            return False
        expires_at = self.session.token['expires_at']
        return expires_at > time.time()

    def get_user_metadata(self, user_id):
        url = f"https://api.cloudstorage.com/users/{user_id}"
        headers = {
            'Authorization': f'Bearer {self.get_access_token()}'
        }
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return json.loads(response.text)
        else:
            raise Exception(f"Error retrieving user metadata: {response.status_code} - {response.text}")

    def get_file_metadata(self, file_id):
        url = f"https://api.cloudstorage.com/files/{file_id}"
        headers = {
            'Authorization': f'Bearer {self.get_access_token()}'
        }
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return json.loads(response.text)
        else:
            raise Exception(f"Error retrieving file metadata: {response.status_code} - {response.text}")

# Usage
client_id = 'your_client_id'
client_secret = 'your_client_secret'
token_url = 'https://api.cloudstorage.com/oauth/token'
api_client = CloudStorageAPIClient(client_id, client_secret, token_url)
user_metadata = api_client.get_user_metadata('user123')
file_metadata = api_client.get_file_metadata('file456')
