```rust
use std::collections::HashMap;
use std::error::Error;
use tokio::sync::mpsc;
use reqwest::Client;
use futures_util::StreamExt;

struct GrammarDefinitionService {
    url: String,
    client: Client,
}

impl GrammarDefinitionService {
    async fn fetch_grammar_definition(&self, file_extension: &str) -> Result<String, Box<dyn Error>> {
        let response = self.client.get(&format!("{}/{}", self.url, file_extension)).send().await?;
        if response.status().is_success() {
            Ok(response.text().await?)
        } else {
            Err(format!("Error fetching grammar definition: {}", response.status()).into())
        }
    }
}

struct GrammarCompilerTool {
    service_map: HashMap<String, GrammarDefinitionService>,
    client: Client,
}

impl GrammarCompilerTool {
    fn new(service_urls: Vec<(&str, &str)>) -> Self {
        let mut service_map = HashMap::new();
        for (file_extension, url) in service_urls {
            service_map.insert(file_extension.to_string(), GrammarDefinitionService { url: url.to_string(), client: Client::new() });
        }
        GrammarCompilerTool { service_map, client: Client::new() }
    }

    async fn compile_file(&self, file_path: &str) -> Result<String, Box<dyn Error>> {
        let extension = file_path.split('.').last().unwrap();
        if let Some(service) = self.service_map.get(extension) {
            let definition = service.fetch_grammar_definition(extension).await?;
            // TODO: Implement grammar parsing and optimization logic for different programming languages
            Ok(format!("Compiled code using grammar: {}", definition))
        } else {
            Err(format!("Unsupported file extension: {}", extension).into())
        }
    }
}

// Usage
#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let service_urls = vec![("py", "https://api.python.org/grammar"), ("java", "https://api.java.com/grammar")];
    let compiler_tool = GrammarCompilerTool::new(service_urls);
    let compiled_code = compiler_tool.compile_file("example.py").await?;
    println!("Compiled code: {}", compiled_code);
    Ok(())
}
