using System;
using System.Data;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class DynamicSecureDataHandler
{
    private readonly string _connectionString;

    public DynamicSecureDataHandler(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<string> DecryptMessageAsync(string base64EncryptedMessage, byte[] key, byte[] iv)
    {
        try
        {
            using (var decryptor = TripleDES.Create())
            {
                decryptor.Key = key;
                decryptor.IV = iv;
                decryptor.Mode = CipherMode.CBC;

                using (var msDecrypt = new MemoryStream(Convert.FromBase64String(base64EncryptedMessage)))
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor.CreateDecryptor(), CryptoStreamMode.Read))
                using (var srDecrypt = new StreamReader(csDecrypt))
                {
                    return await srDecrypt.ReadToEndAsync();
                }
            }
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Decryption failed: {ex.Message}");
            throw;
        }
    }

    public async Task<DataTableReader> ExecuteQueryAsync(byte[] queryData)
    {
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                connection.Open();
                var command = new SqlCommand(queryData, connection);
                return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
            }
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Query execution failed: {ex.Message}");
            throw;
        }
    }

    public async Task LoadAndUpdateModelAsync(string modelPath, string newModelPath, List<(string parameterName, object newValue)> hyperparameters)
    {
        try
        {
            Process.Start("preprocess_data.bat");

            var model = DeserializeModel(modelPath);

            if (model != null)
            {
                UpdateModelHyperparameters(model, hyperparameters);
                SerializeModel(model, newModelPath);
            }
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Model handling failed: {ex.Message}");
        }
    }

    private object DeserializeModel(string path)
    {
        try
        {
            using (var fs = new FileStream(path, FileMode.Open))
            {
                return pickle.loads(fs);
            }
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Deserialization failed: {ex.Message}");
            return null;
        }
    }

    private void UpdateModelHyperparameters(object model, List<(string parameterName, object newValue)> hyperparameters)
    {
        foreach (var param in hyperparameters)
        {
            var property = model.GetType().GetProperty(param.parameterName);
            if (property != null)
            {
                property.SetValue(model, param.newValue);
            }
        }
    }

    private void SerializeModel(object model, string path)
    {
        try
        {
            using (var fs = new FileStream(path, FileMode.Create))
            {
                pickle.dumps(model, fs);
            }
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Serialization failed: {ex.Message}");
        }
    }
}
