#### `backend/src/models/User.js`
```javascript
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');

const userSchema = new mongoose.Schema({
  username: String,
  email: String,
  passwordHash: String,
  chatRooms: [{ type: mongoose.Schema.Types.ObjectId, ref: 'ChatRoom' }],
});

userSchema.pre('save', async function (next) {
  if (!this.isModified('passwordHash')) return next();
  this.passwordHash = await bcrypt.hash(this.passwordHash, 10);
  next();
});

module.exports = mongoose.model('User', userSchema);
```

#### `backend/src/controllers/chatRoomController.js`
```javascript
const ChatRoom = require('../models/ChatRoom');
const User = require('../models/User');

exports.createRoom = async (req, res) => {
  const { name, accessLevel, encryption } = req.body;
  const room = new ChatRoom({ name, accessLevel, encryption });
  await room.save();
  res.status(201).json(room);
};

exports.joinRoom = async (req, res) => {
  const { userId, roomId } = req.body;
  const user = await User.findById(userId);
  const room = await ChatRoom.findById(roomId);
  if (!user.chatRooms.includes(roomId)) {
    user.chatRooms.push(roomId);
    await user.save();
    room.users.push(userId);
    await room.save();
  }
  res.status(200).json({ message: 'User joined the chat room' });
};
```

