from flask import Flask, request, jsonify
from flask_socketio import SocketIO, emit
from functools import wraps
import redis
import pymongo
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session

app = Flask(__name__)
socketio = SocketIO(app)
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)
mongo_client = pymongo.MongoClient("mongodb://localhost:27017/")
client = BackendApplicationClient(client_id='your-client-id')
oauth = OAuth2Session(client=client)

@app.route('/login', methods=['POST'])
def login():
    token = oauth.fetch_token('https://your-auth-server/oauth/token',
                              client_secret='your-client-secret',
                              username=request.json['username'],
                              password=request.json['password'])
    return jsonify(token), 200

def rate_limit(max_calls, period):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = f"rate-limit:{request.remote_addr}"
            current_time = time.time()
            calls = redis_client.zrangebyscore(key, '-inf', current_time - period)
            if len(calls) >= max_calls:
                return jsonify({"error": "Too many requests"}), 429
            redis_client.zremrangebyscore(key, '-inf', current_time - period)
            redis_client.zadd(key, {current_time: current_time})
            return func(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/document', methods=['POST'])
@rate_limit(max_calls=10, period=60)
def create_document():
    data = request.json
    document_id = str(uuid.uuid4())
    mongo_client.documents.insert_one({"_id": document_id, "content": data["content"], "created_at": datetime.now()})
    emit('document_created', {"document_id": document_id}, broadcast=True)
    return jsonify({"document_id": document_id}), 201

@app.route('/document/<document_id>', methods=['GET'])
def get_document(document_id):
    document = mongo_client.documents.find_one({"_id": document_id})
    if not document:
        return jsonify({"error": "Document not found"}), 404
    return jsonify(document), 200

@app.route('/document/<document_id>', methods=['PUT'])
@rate_limit(max_calls=5, period=30)
def update_document(document_id):
    data = request.json
    result = mongo_client.documents.update_one({"_id": document_id}, {"$set": {"content": data["content"]}})
    if not result.modified_count:
        return jsonify({"error": "Document not found"}), 404
    emit('document_updated', {"document_id": document_id, "content": data["content"]}, broadcast=True)
    return jsonify({"message": "Document updated successfully"}), 200

@app.route('/document/<document_id>', methods=['DELETE'])
def delete_document(document_id):
    result = mongo_client.documents.delete_one({"_id": document_id})
    if not result.deleted_count:
        return jsonify({"error": "Document not found"}), 404
    emit('document_deleted', {"document_id": document_id}, broadcast=True)
    return jsonify({"message": "Document deleted successfully"}), 200

@socketio.on('edit_document')
def handle_edit(data):
    document_id = data['document_id']
    content = data['content']
    mongo_client.documents.update_one({"_id": document_id}, {"$set": {"content": content}})
    emit('document_edited', {"document_id": document_id, "content": content}, broadcast=True)

if __name__ == '__main__':
