        pub fn retry_with_backoff<F, R>(func: F) -> Result<R, Box<dyn std::error::Error>>
        where
            F: Fn() -> Result<R, Box<dyn std::error::Error>>,
        {
            for attempt in 1..=3 {
                match func() {
                    Ok(result) => return Ok(result),
                    Err(err) => log::warn!("Attempt {} failed with error: {}", attempt, err),
                }
                std::thread::sleep(delay::exponential(Duration::from_secs(2), attempt));
            }
            func()
        }
    }
