    private readonly IApiClient _slackClient;
    private readonly IDeploymentService _deploymentService;
    private readonly ILogger<DeploymentController> _logger;

    public DeploymentController(IApiClient slackClient, IDeploymentService deploymentService, ILogger<DeploymentController> logger)
    {
        _slackClient = slackClient ?? throw new ArgumentNullException(nameof(slackClient));
        _deploymentService = deploymentService ?? throw new ArgumentNullException(nameof(deploymentService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    [HttpPost("deploy")]
    public async Task<IActionResult> DeployPackage([FromQuery] string packageId, [FromBody] DeploymentRequest request)
    {
        if (string.IsNullOrEmpty(packageId) || request == null)
        {
            return BadRequest("Invalid package ID or request body");
        }

        try
        {
            // Validate the request body
            if (!IsValidDeploymentRequest(request))
            {
                return BadRequest("Invalid deployment request");
            }

            // Deploy the package asynchronously
            BackgroundJob.Enqueue(() => DeployAsync(packageId, request));

            return Accepted();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error deploying package {PackageId}", packageId);
            return StatusCode(503, "Service unavailable");
        }
    }

    private async Task DeployAsync(string packageId, DeploymentRequest request)
    {
        try
        {
            // Perform the deployment logic here
            await _deploymentService.Deploy(packageId, request);

            // Notify the deployment team via Slack
            await NotifyDeploymentTeam(packageId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error during deployment of package {PackageId}", packageId);
            throw; // Re-throw the exception to trigger Hangfire retries
        }
    }

    private async Task NotifyDeploymentTeam(string packageId)
    {
        try
        {
            await _slackClient.PostMessageAsync("Deployment successful for package: " + packageId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error sending Slack notification for deployment of package {PackageId}", packageId);
            throw; // Re-throw the exception to trigger Hangfire retries
        }
    }

    private bool IsValidDeploymentRequest(DeploymentRequest request)
    {
