import org.apache.tinkerpop.gremlin.structure.Vertex;

public class GraphDatabaseManager {

    private final GraphTraversalSource g;
    private final SecondaryIndexDatabase secondaryIndexDb;

    public GraphDatabaseManager(GraphTraversalSource graphTraversalSource, SecondaryIndexDatabase secondaryIndexDb) {
        this.g = graphTraversalSource;
        this.secondaryIndexDb = secondaryIndexDb;
    }

    public void addVerticesAndEdges(int numVertices, int numEdges) {
        for (int i = 0; i < numVertices; i++) {
            Vertex vertex = g.addV("vertex").property("created", System.currentTimeMillis())
                    .property("authorId", generateRandomAuthorId()).property("version", 1L).next();
            secondaryIndexDb.indexVertex(vertex);
        }

        for (int i = 0; i < numEdges; i++) {
            Vertex sourceVertex = g.V().hasLabel("vertex").iterator().next();
            Vertex targetVertex = g.V().hasLabel("vertex").iterator().next();
            g.addE("edge").from(sourceVertex).to(targetVertex)
                    .property("created", System.currentTimeMillis())
                    .property("authorId", generateRandomAuthorId()).property("version", 1L).next();
        }
    }

    private String generateRandomAuthorId() {
