```csharp
public class SecureDataHandler
{
    private readonly ILogger<SecureDataHandler> _logger;
    private readonly IKeyManager _keyManager;

    public SecureDataHandler(ILogger<SecureDataHandler> logger, IKeyManager keyManager)
    {
        _logger = logger;
        _keyManager = keyManager;
    }

    public async Task<HttpResponseMessage> UpdateResourceAsync(string resourceId, string requestBody)
    {
        try
        {
            // Validate resource ID and user permissions
            if (!IsValidResourceId(resourceId) || !IsUserAuthorizedForUpdate(resourceId))
            {
                return new HttpResponseMessage(HttpStatusCode.Forbidden);
            }

            using (var connection = new SqlConnection(_keyManager.GetConnectionString()))
            {
                await connection.OpenAsync();
                var command = new SqlCommand("UPDATE Resources SET Data = @Data, Version = Version + 1 WHERE Id = @Id AND Version = @CurrentVersion", connection);
                command.Parameters.AddWithValue("@Data", requestBody);
                command.Parameters.AddWithValue("@Id", resourceId);
                command.Parameters.AddWithValue("@CurrentVersion", GetCurrentVersion(connection, resourceId));

                var rowsAffected = await command.ExecuteNonQueryAsync();
                if (rowsAffected == 0)
                {
                    return new HttpResponseMessage(HttpStatusCode.PreconditionFailed);
                }

                return new HttpResponseMessage(HttpStatusCode.OK);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating resource");
            return new HttpResponseMessage(HttpStatusCode.InternalServerError);
        }
    }

    public async Task<DataTableReader> DeleteResourceAsync(string resourceId)
    {
        try
        {
            // Validate resource ID and user permissions
            if (!IsValidResourceId(resourceId) || !IsUserAuthorizedForDelete(resourceId))
            {
                throw new UnauthorizedAccessException();
            }

            using (var connection = new SqlConnection(_keyManager.GetConnectionString()))
            {
                await connection.OpenAsync();
                var command = new SqlCommand("DELETE FROM Resources WHERE Id = @Id", connection);
                command.Parameters.AddWithValue("@Id", resourceId);

                var reader = await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
                return reader;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error deleting resource");
            throw new InternalServerErrorException();
        }
    }

    private bool IsValidResourceId(string resourceId)
    {
        // Add validation logic for resource ID
        return true;
    }

    private bool IsUserAuthorizedForUpdate(string resourceId)
    {
        // Add authorization logic for updating the resource
        return true;
    }

    private bool IsUserAuthorizedForDelete(string resourceId)
    {
        // Add authorization logic for deleting the resource
        return true;
    }

    private int GetCurrentVersion(SqlConnection connection, string resourceId)
    {
        var command = new SqlCommand("SELECT Version FROM Resources WHERE Id = @Id", connection);
        command.Parameters.AddWithValue("@Id", resourceId);

        var version = (int)command.ExecuteScalar();
        return version;
    }
}
