import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.Instant;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Stream;

public class FileDeleter {
    private static final String API_URL = "https://example.com/api/files";
    private static final long AGE_THRESHOLD = 30 * 24 * 60 * 60 * 1000; // 30 days in milliseconds
    private static final long SIZE_THRESHOLD = 1024 * 1024 * 1024; // 1GB

    public static void main(String[] args) {
        try {
            // Fetch files from API
            URL url = new URL(API_URL);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            InputStream inputStream = connection.getInputStream();
            BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
            String line;
            while ((line = reader.readLine()) != null) {
                String filePath = "remote/path/" + line;
                deleteFileIfCriteriaMet(filePath);
            }
            reader.close();

            // Execute shell commands in parallel
            ExecutorService executorService = Executors.newFixedThreadPool(10);
            List<String> commands = Arrays.asList("command1", "command2", "command3");
            for (String command : commands) {
                executorService.submit(() -> executeShellCommand(command));
            }
            executorService.shutdown();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void deleteFileIfCriteriaMet(String filePath) {
        try {
            Path path = Paths.get(filePath);
            if (!Files.exists(path)) return;

            long lastModified = Files.getLastModifiedTime(path).toMillis();
            if ((System.currentTimeMillis() - lastModified) > AGE_THRESHOLD && path.toFile().length() > SIZE_THRESHOLD) {
                Files.delete(path);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void executeShellCommand(String command) {
        try {
            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            processBuilder.redirectErrorStream(true);
            Process process = processBuilder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                System.err.println("Command exited with code " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

