int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_transactions, NULL);
    // Simulate adding transactions to the queue
    for (int i = 0; i < 1000; i++) {
        Transaction tx = {i, rand() / 100.0, time(NULL), "buy"};
        add_to_queue(&tx);
    }
    pthread_join(thread_id, NULL);
    return 0;
}

void* process_transactions(void*) {
    while (1) {
        Transaction tx;
        if (remove_from_queue(&tx)) {
            // Process transaction based on type
            if (strcmp(tx.type, "buy") == 0) {
                // Apply buy-specific validation and processing logic
            } else if (strcmp(tx.type, "sell") == 0) {
                // Apply sell-specific validation and processing logic
            }
            // Update sliding window
            pthread_mutex_lock(&window_lock);
            for (int i = 4; i > 0; i--) {
                windows[i] = windows[i - 1];
            }
            windows[0].id_count[tx.id]++;
            windows[0].weighted_sum += tx.weighted_sum;
            windows[0].timestamp = time(NULL);
            pthread_mutex_unlock(&window_lock);
        } else {
            // No transactions in queue, wait for a short period
            usleep(1000);
        }
    }
}

int add_to_queue(Transaction* tx) {
    pthread_mutex_lock(&queue_lock);
    if (count == QUEUE_SIZE) {
        pthread_mutex_unlock(&queue_lock);
        return 0; // Queue is full
    }
    transaction_queue[rear] = *tx;
    rear = (rear + 1) % QUEUE_SIZE;
    count++;
    pthread_mutex_unlock(&queue_lock);
    return 1;
}

int remove_from_queue(Transaction* tx) {
    pthread_mutex_lock(&queue_lock);
    if (count == 0) {
        pthread_mutex_unlock(&queue_lock);
        return 0; // Queue is empty
    }
    *tx = transaction_queue[front];
    front = (front + 1) % QUEUE_SIZE;
    count--;
    pthread_mutex_unlock(&queue_lock);
    return 1;
}
```

This code snippet provides a basic framework for processing a high-frequency stream of financial transactions in real-time. It includes the implementation of a thread-safe transaction queue, a sliding window data structure to keep track of transaction counts and weighted sums within the last 5 seconds, and a function to process transactions based on their type. The `main` function simulates adding transactions to the queue for processing. This code is intended as a starting point and can be extended and modified according to specific requirements and use cases.

