import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.client.RestTemplate;

@Service
public class UserProfileService {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private CacheManager cacheManager;

    @Transactional
    public void updateUserProfile(String userId, String name, String email, String address) {
        // Validate and sanitize input
        if (userId == null || name == null || email == null || address == null) {
            throw new IllegalArgumentException("Input data cannot be null");
        }
        // Implement rate limiting logic here

        // Check cache for user profile
        UserProfile cachedProfile = (UserProfile) cacheManager.getFromCache(userId);
        if (cachedProfile != null && !isProfileDirty(cachedProfile, name, email, address)) {
            return; // No update needed
        }

        // Create request headers and body
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        UserUpdateRequest userUpdateRequest = new UserUpdateRequest(userId, name, email, address);
        HttpEntity<UserUpdateRequest> requestEntity = new HttpEntity<>(userUpdateRequest, headers);

        try {
            // Make REST API call to update user profile
            UserProfile updatedProfile = restTemplate.postForObject("https://api.example.com/users/update", requestEntity, UserProfile.class);

            // Cache the updated profile
            cacheManager.addToCache(userId, updatedProfile);
        } catch (RestClientException e) {
            // Handle network timeouts and server errors
            handleApiError(e);
        }
    }

    private boolean isProfileDirty(UserProfile cachedProfile, String name, String email, String address) {
        // Compare current profile with cache to determine if update is necessary
        return !cachedProfile.getName().equals(name)
                || !cachedProfile.getEmail().equals(email)
                || !cachedProfile.getAddress().equals(address);
    }

    private void handleApiError(RestClientException e) {
        // Log and handle API errors (rate limits, timeouts, server errors)
        log.error("API error occurred: ", e);
        throw new RuntimeException("Failed to update user profile", e);
    }
}
