                       public void initChannel(SocketChannel ch) throws Exception {
                           ChannelPipeline pipeline = ch.pipeline();
                           pipeline.addLast(sslCtx.newHandler(ch.alloc()));
                           pipeline.addLast(new IdleStateHandler(readTimeoutSeconds,
