import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.concurrent.*;
import java.util.regex.Pattern;

public class FileProcessor {
    private static final ForkJoinPool pool = new ForkJoinPool();
    private static long totalSize = 0;
    private static int errorCount = 0;
    private static ExecutorService logExecutor = Executors.newSingleThreadExecutor();

    public static void main(String[] args) {
        Path startingDir = Paths.get("C:\\path\\to\\folder");
        long startTime = System.currentTimeMillis();
        pool.invoke(new FileRecursiveTask(startingDir));
        long endTime = System.currentTimeMillis();
        System.out.println("Total size: " + totalSize + " bytes");
        System.out.println("Error count: " + errorCount);
        System.out.println("Processing time: " + (endTime - startTime) + " ms");
        pool.shutdown();
        logExecutor.shutdown();
    }

    private static class FileRecursiveTask extends RecursiveTask<Void> {
        private final Path path;

        public FileRecursiveTask(Path path) {
            this.path = path;
        }

        @Override
        protected Void compute() {
            try {
                if (Files.isDirectory(path)) {
                    List<FileRecursiveTask> subTasks = Files.list(path)
                            .map(FileRecursiveTask::new)
                            .collect(Collectors.toList());
                    invokeAll(subTasks);
                } else if (path.toString().endsWith(".pdf")) {
                    totalSize += Files.size(path);
                    logExecutor.execute(() -> System.out.println("Processed: " + path));
                }
            } catch (IOException e) {
                errorCount++;
                logExecutor.execute(() -> System.err.println("Error processing file: " + path + ", Error: " + e.getMessage()));
            }
            return null;
        }
    }

    public static boolean validateBookName(String bookName) {
        // Regex for Old Testament book names
        Pattern pattern = Pattern.compile("^([A-Za-z]+\\s+)*[A-Za-z]+$");
        return pattern.matcher(bookName).matches();
    }

    public static boolean validateSecurityKeyword(String keyword) {
        // Regex for data security keywords
        Pattern pattern = Pattern.compile("^(?!.*password).*\\b(\\d|\\D)+$");
        return pattern.matcher(keyword).matches();
    }

    public static boolean validateEmail(String email) {
        // Regex for standard email format
        Pattern pattern = Pattern.compile("^([a-zA-Z0-9_\\.+-]+)@(([a-zA-Z0-9-]+)\\.)+[a-zA-Z]{2,6}$");
        return pattern.matcher(email).matches();
    }

    public static boolean isCommonWeakPassword(String password) {
        // List of common weak passwords
        List<String> weakPasswords = Arrays.asList("password", "123456", "qwerty", "admin");
        return weakPasswords.contains(password);
    }
}
