#include <iostream>
#include <cstdlib>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

void logError(const std::string& message) {
    std::cerr << "ERROR: " << message << std::endl;
}

int initializeOctree(size_t featureSize, size_t numLeafNodes, size_t dataCapacity) {
    if (featureSize == 0 || numLeafNodes == 0 || dataCapacity == 0) {
        logError("Invalid input parameters.");
        return 0;
    }

    pid_t pid = fork();
    if (pid == -1) {
        logError("Failed to fork process.");
        return 0;
    } else if (pid == 0) {
        // Child process
        int status = execl("/path/to/command", "command_name", nullptr);
        if (status != 0) {
            logError("Command execution failed.");
        }
        exit(0);
    } else {
        // Parent process
        pid_t wpid;
        int status;
        while ((wpid = wait(&status)) > 0) {
            if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
                logError("Child process failed.");
                return 0;
            }
        }
    }

    // Allocate memory for octree
    auto* octree = new Octree(featureSize, numLeafNodes);
    if (octree == nullptr) {
        logError("Memory allocation failed.");
        return 0;
    }

    // Initialize octree
    try {
        octree->initialize(dataCapacity);
    } catch (const std::exception& e) {
        logError("Octree initialization failed: " + std::string(e.what()));
        delete octree;
        return 0;
    }

    delete octree;
    return 1;
}
