### C-based Transaction Processing System

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_TRANSACTIONS 1000
#define SEMAPHORE_NAME "/my_semaphore"

typedef struct {
    int id;
    char description[256];
    time_t timestamp;
    double weight;
} Transaction;

typedef struct {
    sem_t *semaphore;
    pthread_mutex_t *mutex;
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
} TransactionQueue;

void initializeTransactionQueue(TransactionQueue *queue) {
    queue->count = 0;
    sem_unlink(SEMAPHORE_NAME);
    queue->semaphore = sem_open(SEMAPHORE_NAME, O_CREAT, 0644, 1);
    pthread_mutex_init(&queue->mutex, NULL);
}

void addTransaction(TransactionQueue *queue, Transaction transaction) {
    pthread_mutex_lock(queue->mutex);
    if (queue->count < MAX_TRANSACTIONS) {
        queue->transactions[queue->count++] = transaction;
        sem_post(queue->semaphore);
    } else {
        printf("Transaction queue is full!\n");
    }
    pthread_mutex_unlock(queue->mutex);
}

int getTransaction(TransactionQueue *queue, Transaction *transaction) {
    int result = sem_wait(queue->semaphore);
    if (result == 0) {
        pthread_mutex_lock(queue->mutex);
        *transaction = queue->transactions[--queue->count];
        pthread_mutex_unlock(queue->mutex);
        return 1;
    }
    return 0;
}

void destroyTransactionQueue(TransactionQueue *queue) {
    sem_close(queue->semaphore);
    sem_unlink(SEMAPHORE_NAME);
    pthread_mutex_destroy(&queue->mutex);
}
