public class CommandExecutor {

    private static final int DEFAULT_MAX_CONCURRENT_PROCESSES = 10;
    private static final long DEFAULT_TIMEOUT = 60_000; // 1 minute

    public static void main(String[] args) {
        // Parse command-line arguments
        String logDir = parseLogDir(args);
        int maxConcurrentProcesses = parseMaxConcurrentProcesses(args, DEFAULT_MAX_CONCURRENT_PROCESSES);
        long timeout = parseTimeout(args, DEFAULT_TIMEOUT);

        // Initialize logging directory
        File logDirectory = new File(logDir);
        if (!logDirectory.exists()) {
            logDirectory.mkdirs();
        }

        // Define commands with their environment variables and working directories
        List<Command> commands = Arrays.asList(
                new Command("command1", Map.of("VAR1", "value1"), "/path/to/dir1"),
                new Command("command2", Map.of("VAR2", "value2"), "/path/to/dir2")
        );

        // Execute commands concurrently with dynamic limits
        try (ExecutorService executor = Executors.newFixedThreadPool(maxConcurrentProcesses)) {
            List<Future<?>> futures = new ArrayList<>();
            for (Command command : commands) {
                Path outputFile = Paths.get(logDirectory.toString(), command.name + ".out");
                Path errorFile = Paths.get(logDirectory.toString(), command.name + ".err");

                Callable<Void> task = () -> executeCommand(command, outputFile, errorFile);
                futures.add(executor.submit(task));
            }

            for (Future<?> future : futures) {
                future.get(timeout, TimeUnit.MILLISECONDS);
            }
        } catch (Exception e) {
            System.err.println("Error executing commands: " + e.getMessage());
        }
    }

    private static String parseLogDir(String[] args) {
