function copyBufferedData(dataChunks, startByte, byteCount, logger) {
    try {
        let totalSize = 0;
        for (let chunk of dataChunks) {
            totalSize += chunk.length;
        }

        if (startByte + byteCount > totalSize) {
            throw new Error("Requested byte range exceeds total size");
        }

        let targetBuffer = Buffer.alloc(byteCount);
        let currentByte = startByte;

        for (let chunk of dataChunks) {
            if (currentByte >= startByte && currentByte < startByte + byteCount) {
                let bytesToCopy = Math.min(chunk.length, startByte + byteCount - currentByte);
                targetBuffer.copy(chunk, 0, currentByte - startByte, bytesToCopy);
            }
            currentByte += chunk.length;
        }

        logger.log(`Successfully copied ${byteCount} bytes from buffered data starting at byte ${startByte}`);
        return targetBuffer;

    } catch (error) {
        logger.error(`Error copying buffered data: ${error.message}`);
        throw error;
    }
}
