import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DisjointPairs {
    private UnionFind uf;
    private ConcurrentHashMap<Integer, Integer> cache;
    private ExecutorService executor;

    public DisjointPairs(int[] array) {
        if (array == null || array.length <= 1) {
            throw new IllegalArgumentException("Invalid input array");
        }

        uf = new UnionFind(array);
        cache = new ConcurrentHashMap<>();
        executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void insert(int element) {
        if (element < 0) {
            throw new IllegalArgumentException("Negative integers are not allowed");
        }
        if (!uf.contains(element)) {
            uf.add(element);
            cache.clear(); // Clear cache on insertion
        }
    }

    public void delete(int element) {
        if (uf.contains(element)) {
            uf.remove(element);
            cache.clear(); // Clear cache on deletion
        } else {
            throw new IllegalArgumentException("Element not found in the array");
        }
    }

    public int countDisjointPairs() {
        long startTime = System.currentTimeMillis();
        int count = 0;

        for (int i = 0; i < uf.size() - 1; i++) {
            for (int j = i + 1; j < uf.size(); j++) {
                if (!uf.isDisjoint(i, j)) {
                    continue;
                }

                int pairKey = getPairKey(uf.find(i), uf.find(j));
                if (!cache.containsKey(pairKey)) {
                    long computationTime = System.currentTimeMillis();
                    count++;
                    cache.put(pairKey, 1);
                    computationTime = System.currentTimeMillis() - computationTime;
                    System.out.println("Computed disjoint pair (" + i + ", " + j + ") in " + computationTime + "ms");
                }
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Total computation time: " + (endTime - startTime) + "ms");
        return count;
    }

    private int getPairKey(int root1, int root2) {
        return Math.min(root1, root2) * 10000 + Math.max(root1, root2);
    }

    public void close() {
        executor.shutdown();
    }

    // Union-Find data structure implementation goes here
}

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int[] array) {
        parent = new int[array.length];
        rank = new int[array.length];

        for (int i = 0; i < array.length; i++) {
            parent[i] = i;
        }
    }

    public boolean contains(int element) {
        return element >= 0 && element < parent.length;
    }

    public void add(int element) {
        parent[element] = element;
        rank[element] = 0;
    }

    public void remove(int element) {
        int root = find(element);
        for (int i = 0; i < parent.length; i++) {
            if (find(i) == root) {
                parent[i] = i;
                rank[i] = 0;
            }
        }
    }

    public boolean isDisjoint(int index1, int index2) {
        return find(index1) != find(index2);
    }

    private int find(int element) {
        if (parent[element] != element) {
            parent[element] = find(parent[element]);
        }
        return parent[element];
    }

    public int size() {
        return parent.length;
    }
}
