// Import necessary libraries
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

// Function to create a new buffer from chunks
function copyBufferFromChunks(chunks, byteOffset, maxConcurrentCopies = 4) {
  if (byteOffset < 0 || !Number.isInteger(byteOffset)) {
    throw new Error('Invalid byte offset');
  }

  let totalSize = 0;
  for (const chunk of chunks) {
    totalSize += chunk.length;
  }

  if (totalSize <= 1 * 1024 * 1024 * 1024) {
    return Buffer.concat(chunks).slice(byteOffset);
  } else {
    return new Promise((resolve, reject) => {
      const workerData = { chunks, byteOffset };
      let completedChunks = 0;
      const results = [];
      const activeWorkers = new Set();

      function spawnWorker() {
        if (completedChunks >= chunks.length || activeWorkers.size >= maxConcurrentCopies) return;

        const index = completedChunks++;
        const worker = new Worker(__filename, { workerData });
        worker.on('message', result => {
          results[index] = result;
          spawnWorker();
        });
        worker.on('error', error => reject(error));
        worker.on('exit', code => {
          if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
        });
        activeWorkers.add(worker);
      }

      for (let i = 0; i < maxConcurrentCopies; i++) {
        spawnWorker();
      }

      worker.on('message', result => {
        results[index] = result;
        if (++completedChunks === chunks.length) {
          const newBuffer = Buffer.concat(results);
          resolve(newBuffer.slice(byteOffset));
          for (const worker of activeWorkers) worker.terminate();
        }
      });

      worker.on('error', error => reject(error));

      worker.on('exit', code => {
        if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
      });
    });
  }
}

// Worker script for copying chunks
if (isMainThread) {
  const { parentPort, workerData } = require('worker_threads');
  const { chunks, byteOffset } = workerData;
  let resultBuffer = Buffer.alloc(chunks[0].length);

  function copyChunk(chunk) {
    if (chunk.length < resultBuffer.length) {
      resultBuffer.set(chunk, chunk.length - resultBuffer.length);
    }
  }

  for (const chunk of chunks) {
    copyChunk(chunk);
  }

  parentPort.postMessage(resultBuffer.slice(byteOffset));
} else {
  // Main thread logic
}
```

This code defines a function `copyBufferFromChunks` that takes in an array of data chunks, a byte offset, and an optional maximum number of concurrent copies. It uses the Worker API to create worker threads for copying each chunk concurrently, which can help improve performance when dealing with large data sizes. The main thread waits for all workers to complete before returning the final buffer.

To test this function, you can use Node.js's built-in testing framework, such as `assert` or `jest`. You'll need to create a series of unit tests that cover different scenarios, including edge cases where the total size of the data chunks exceeds 1GB and when there are multiple concurrent operations.

