const express = require('express');
const jwt = require('jsonwebtoken');
const axios = require('axios');
const redis = require('redis');
const rateLimit = require('express-rate-limit');

// Configuration through environment variables
const JWT_SECRET = process.env.JWT_SECRET;
const TOKEN_ISSUERS = process.env.TOKEN_ISSUERS.split(',');
const REDIS_URL = process.env.REDIS_URL || 'localhost:6379';

// Initialize Redis client
const redisClient = redis.createClient({ url: REDIS_URL });

// Token cache middleware
async function cacheToken(userId, token) {
  try {
    await redisClient.setex(userId, 3600, token);
    console.log('Token cached successfully');
  } catch (error) {
    console.error('Failed to cache token:', error);
  }
}

async function getTokenFromCache(userId) {
  try {
    const token = await redisClient.get(userId);
    if (token) {
      console.log('Token retrieved from cache');
      return token;
    }
  } catch (error) {
    console.error('Failed to retrieve token from cache:', error);
  }
}

// Token issuer API client
async function fetchTokenFromIssuer(issuer, userId, mfaCode = null) {
  try {
    const response = await axios.post(`${issuer}/token`, { userId, mfaCode }, {
      headers: {
        'Content-Type': 'application/json'
      }
    });
    return response.data.token;
  } catch (error) {
    console.error(`Failed to fetch token from ${issuer}:`, error);
    throw error;
  }
}

// Middleware for validating JWT tokens
function validateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  const token = authHeader.substring(7);
  jwt.verify(token, JWT_SECRET, (err, decoded) => {
    if (err) {
      return res.status(403).json({ message: 'Invalid token' });
    }
    req.user = decoded;
    next();
  });
}

// Health check endpoint
app.get('/health', async (req, res) => {
  try {
    for (const issuer of TOKEN_ISSUERS) {
      await axios.get(`${issuer}/status`);
    }
    res.status(200).json({ message: 'All token issuers are healthy' });
  } catch (error) {
    res.status(503).json({ message: 'One or more token issuers are unhealthy' });
  }
});

// Rate limiting middleware
const apiLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 1000 // limit each IP to 1000 requests per windowMs
});

const cacheAccessLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 1000 // limit each IP to 1000 requests per windowMs
});

// Token generation and caching route
app.post('/token', apiLimiter, async (req, res) => {
  const { userId, mfaCode } = req.body;
  let token;

  try {
    token = await getTokenFromCache(userId);
    if (!token) {
      token = await fetchTokenFromIssuer(TOKEN_ISSUERS[0], userId, mfaCode);
      await cacheToken(userId, token);
    }

    const jwtPayload = { userId };
    const finalToken = jwt.sign(jwtPayload, JWT_SECRET);

    res.status(200).json({ token: finalToken });
  } catch (error) {
    res.status(500).json({ message: 'Failed to generate token' });
  }
});

// Example usage in an Express.js app
const app = express();
app.use(express.json());
app.use('/api', validateToken, cacheAccessLimiter);
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
