@SpringBootApplication
public class WebSocketClientApplication {

    public static void main(String[] args) {
        SpringApplication.run(WebSocketClientApplication.class, args);
    }

    @Bean
    public CommandLineRunner run(String... args) {
        return args0 -> {
            // Configure command-line arguments for server endpoints, message format, authentication token, etc.
            String[] serverEndpoints = new String[]{"ws://server1.com", "ws://server2.com"};
            String messageFormat = "text"; // or "binary"
            String authToken = "your-auth-token";

            for (String endpoint : serverEndpoints) {
                WebSocketClient webSocketClient = WebClient.builder()
                        .clientConnector(new ReactorClientHttpConnector(HttpClient.create()))
                        .baseUrl(endpoint)
                        .defaultHeader("Authorization", authToken)
                        .build();

                Flux<ServerSentEvent<String>> messages = webSocketClient.get()
                        .uri("/ws")
                        .retrieve()
                        .bodyToFlux(ServerSentEvent.class);

                messages.subscribe(event -> {
                    if (event.getData().equals("heartbeat")) {
                        // Handle heartbeat message
                    } else if ("text".equals(messageFormat)) {
                        TextWebSocketFrame textFrame = new TextWebSocketFrame(event.getData());
                        webSocketClient.post()
                                .uri("/send")
                                .contentType(MediaType.TEXT_PLAIN)
                                .bodyValue(textFrame.text())
                                .retrieve()
                                .toBodilessEntity()
                                .subscribe();
                    } else if ("binary".equals(messageFormat)) {
                        BinaryWebSocketFrame binaryFrame = new BinaryWebSocketFrame(event.getData().getBytes());
                        webSocketClient.post()
                                .uri("/send")
                                .contentType(MediaType.APPLICATION_OCTET_STREAM)
                                .bodyValue(binaryFrame.content())
                                .retrieve()
                                .toBodilessEntity()
                                .subscribe();
                    }
                });

                // Implement retry logic with exponential backoff
                // Handle server disconnections and reconnections gracefully
            }
        };
    }

    @Service
    public class MessageForwarder {
        private final SimpMessagingTemplate template;
        private final DatabaseClient databaseClient;

        public MessageForwarder(SimpMessagingTemplate template, DatabaseClient databaseClient) {
            this.template = template;
            this.databaseClient = databaseClient;
        }

        public void forwardMessage(DataBuffer messageData, String contentType) {
            if ("text".equals(contentType)) {
                // Forward text message to a queue or topic
                template.convertAndSend("/queue/text", new String(messageData.asByteBuffer().array()));
            } else if ("binary".equals(contentType)) {
                // Forward binary message to a queue or topic
                databaseClient.sql("INSERT INTO binary_messages (data) VALUES ($1)")
                        .bind(0, messageData.asByteBuffer().array())
                        .fetch()
                        .rowsUpdated()
                        .subscribe();
            }
        }
    }
}
