import { createWriteStream } from 'fs';
import { pipeline } from 'stream/promises';
import * as crypto from 'crypto';

interface Chunk {
  id: number;
  data: Buffer;
  checksum: string;
}

class FileMerger {
  private chunks: Map<number, Chunk> = new Map();
  private totalChunks: number | null = null;
  private outputFilePath: string;

  constructor(outputFilePath: string) {
    this.outputFilePath = outputFilePath;
  }

  async addChunk(chunk: Chunk): Promise<void> {
    if (chunk.id === 0 && this.totalChunks === null) {
      this.totalChunks = chunk.data.readUInt32BE(0);
    }

    const expectedChecksum = crypto.createHash('sha256').update(chunk.data).digest('hex');
    if (chunk.checksum !== expectedChecksum) {
      throw new Error(`Chunk ${chunk.id} has an invalid checksum.`);
    }

    this.chunks.set(chunk.id, chunk);

    if (this.chunks.size === this.totalChunks!) {
      await this.mergeFile();
    }
  }

  private async mergeFile(): Promise<void> {
    const writeStream = createWriteStream(this.outputFilePath);
    for (let i = 0; i < this.totalChunks!; i++) {
      const chunk = this.chunks.get(i)!;
      await pipeline(chunk.data, writeStream);
    }
    writeStream.end();
    console.log('File merging completed successfully.');
  }

