import java.util.HashMap;
import java.util.Map;

public class ProductManager {
    private Map<Integer, Product> productCache = new HashMap<>();

    public void addProducts(int[] productId, char[][] productName, float[] price, int[] stockQuantity) throws Exception {
        if (productId.length != productName.length || productId.length != price.length || productId.length != stockQuantity.length) {
            throw new IllegalArgumentException("Input sizes must match.");
        }

        for (int i = 0; i < productId.length; i++) {
            Product product = new Product(productId[i], productName[i], price[i], stockQuantity[i]);
            productCache.put(productId[i], product);
            // Perform database insertion here
        }
    }

    public void updateProduct(int productId, char[] productName, float price, int stockQuantity) throws Exception {
        if (!productCache.containsKey(productId)) {
            throw new IllegalArgumentException("Product not found in cache.");
        }

        Product product = productCache.get(productId);
        product.update(productName, price, stockQuantity);
        // Perform database update here
    }

    public void removeProduct(int productId) throws Exception {
        if (!productCache.containsKey(productId)) {
            throw new IllegalArgumentException("Product not found in cache.");
        }

        productCache.remove(productId);
        // Perform database deletion here
    }

    public Product getProduct(int productId) {
        return productCache.get(productId);
    }

    public void freeMemory() {
        productCache.clear();
    }
}

