```javascript
function extractBibleReferences(text) {
    if (typeof text !== 'string') {
        throw new Error('Invalid input: Expected a string');
    }

    const bookNames = [
        'Genesis', 'Gen.', 'Gen 1:1', 
        'Exodus', 'Exod.', 'Exo 2:3', 
        // ... add all other book names
        'Revelation', 'Rev.', 'Rev. 20:21'
    ];

    const bookRegex = new RegExp(`(${bookNames.join('|')})`, 'gi');

    let matches = text.match(bookRegex);
    if (!matches) return {};

    let bookCounts = {};
    for (let match of matches) {
        let cleanMatch = match.trim().replace(/[.,]/g, '');
        if (!bookCounts[cleanMatch]) {
            bookCounts[cleanMatch] = 1;
        }
    }

    return bookCounts;
}
