import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.ResponseEntity;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Async;
import com.fasterxml.jackson.databind.ObjectMapper;

public class FileUploadService {

    @Autowired
    private MetadataService metadataService;

    @Autowired
    private CacheService cacheService;

    @Async
    public ResponseEntity<String> uploadFile(MultipartFile file) {
        try {
            if (!file.isEmpty()) {
                String tenantId = file.getOriginalFilename().split("_")[0];
                String fileName = file.getOriginalFilename();
                String fileType = file.getContentType();
                byte[] fileData = file.getBytes();

                if (tenantId == null || tenantId.isEmpty()) {
                    return ResponseEntity.badRequest().body(new ObjectMapper().writeValueAsString(new Message("error", "missing tenant_id")));
                }

                // Validate and limit file type and size
                if (!isValidFileType(fileType) || !isValidFileSize(fileData.length)) {
                    return ResponseEntity.badRequest().body(new ObjectMapper().writeValueAsString(new Message("error", "invalid file type or size")));
                }

                // Check for existing file name within the tenant
                if (metadataService.fileExists(tenantId, fileName)) {
                    return ResponseEntity.badRequest().body(new ObjectMapper().writeValueAsString(new Message("error", "file already exists")));
                }

                // Cache file data to avoid redundant uploads
                cacheService.cacheFileData(tenantId + "_" + fileName, fileData);

                // Asynchronously process file upload and storage
                storeFileAsync(tenantId, fileName, fileType, fileData);

                return ResponseEntity.ok(new ObjectMapper().writeValueAsString(new Message("success", "file uploaded successfully")));
            } else {
                return ResponseEntity.badRequest().body(new ObjectMapper().writeValueAsString(new Message("error", "empty file")));
            }
        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.status(500).body(new ObjectMapper().writeValueAsString(new Message("error", "internal server error")));
        }
    }

    @Async
    private void storeFileAsync(String tenantId, String fileName, String fileType, byte[] fileData) {
        try {
            // Perform background processing for file upload and storage
            metadataService.storeFileMetadata(tenantId, fileName, fileType);
            metadataService.uploadFile(tenantId, fileName, fileData);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private boolean isValidFileType(String fileType) {
        // Implement file type validation logic here
        return true;
    }

    private boolean isValidFileSize(int fileSize) {
        // Implement file size limit logic here
        return true;
    }

    private static class Message {
        String message;
        String reason;

        public Message(String message, String reason) {
            this.message = message;
            this.reason = reason;
        }
    }
}
