#include <stdio.h>
#include <stdlib.h>

void findLargestIntegerWithStats() {
    int *numbers = NULL;
    int count = 0;
    int maxCount = -1; // Use -1 to indicate unlimited or a specific limit from user input
    long sum = 0;
    int largest = INT_MIN;
    int skipped = 0;

    printf("Enter integers, enter -999 to end:\n");

    while (1) {
        int num;
        if (scanf("%d", &num) != 1) {
            fprintf(stderr, "Invalid input. Please enter an integer.\n");
            while (getchar() != '\n'); // Clear the input buffer
            skipped++;
            continue;
        }
        if (num == -999) break;

        if (maxCount > 0 && count >= maxCount) {
            printf("Maximum number of integers reached. Stopping.\n");
            break;
        }

        numbers = realloc(numbers, (count + 1) * sizeof(int));
        if (!numbers) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(1);
        }

        numbers[count++] = num;

        if (num > largest) {
            largest = num;
        }
        sum += num;
    }

    double average = count > 0 ? (double)sum / count : 0;

    printf("Largest Integer: %d\n", largest);
    printf("Total Valid Integers: %d\n", count);
    printf("Skipped Invalid Inputs: %d\n", skipped);
    if (count > 0) {
        printf("Average Value of Valid Integers: %.2f\n", average);
    }

    free(numbers);
}

int main() {
    findLargestIntegerWithStats();
    return 0;
}
