import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;
import io.netty.handler.codec.string.StringDecoder;
import io.netty.handler.codec.string.StringEncoder;
import io.netty.handler.ssl.SslContext;
import io.netty.handler.ssl.SslContextBuilder;
import io.netty.handler.timeout.IdleStateHandler;

public class TcpConnectionPool {
    private final EventLoopGroup group = new NioEventLoopGroup();
    private final Bootstrap bootstrap;

    public TcpConnectionPool(String[] remoteHosts, int connectionLimitPerHost) throws Exception {
        SslContext sslCtx = SslContextBuilder.forClient()
                .trustManagerInsecureTrustManagerFactory() // Replace with actual trust manager
                .build();

        bootstrap = new Bootstrap();
        bootstrap.group(group)
                 .channel(NioSocketChannel.class)
                 .option(ChannelOption.SO_KEEPALIVE, true)
                 .handler(new ChannelInitializer<SocketChannel>() {
                     @Override
                     protected void initChannel(SocketChannel ch) throws Exception {
                         ChannelPipeline p = ch.pipeline();
                         if (sslCtx != null) {
                             p.addLast(sslCtx.newHandler(ch.alloc()));
                         }
                         p.addLast(new StringDecoder());
                         p.addLast(new StringEncoder());
                         p.addLast(new IdleStateHandler(5, 0, 60));
                         p.addLast(new ConnectionHandler(remoteHosts, connectionLimitPerHost));
                     }
                 });
    }

    public void connect() {
        for (String remoteHost : remoteHosts) {
            bootstrap.connect(remoteHost, port).addListener((ChannelFutureListener) future -> {
                if (!future.isSuccess()) {
                    System.err.println("Failed to connect to " + remoteHost);
                } else {
                    System.out.println("Connected to " + remoteHost);
                }
            });
        }
    }

    public void shutdownGracefully() {
        group.shutdownGracefully();
    }
}
