from flask import Flask, request, jsonify
from functools import wraps
import time
import logging
import random

app = Flask(__name__)

# Rate limiting dictionary to store user update counts per minute
rate_limit_counts = {}

# Locking mechanism using a simple dictionary for demonstration purposes
lock = {}

def validate_data(data):
    # Placeholder validation logic
    return data.get('name') is not None and isinstance(data['name'], str)

@app.route('/update_resource/<int:resource_id>', methods=['PUT'])
@limit_updates
def update_resource(resource_id):
    user_id = request.headers.get('User-Id')

    if resource_id not in lock:
        lock[resource_id] = True

    with app.app_context():
        data = request.json
        if validate_data(data):
            # Simulate updating the resource
            updated_resource = {
                'id': resource_id,
                'name': data['name'],
                'updated_at': time.time()
            }

            # Implement If-Match logic here

            return jsonify(updated_resource), 200
        else:
            return jsonify({'error': 'Invalid data'}), 400

def limit_updates(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        user_id = request.headers.get('User-Id')

        current_time = time.time()
        minute_start = int(current_time // 60) * 60

        if user_id not in rate_limit_counts:
            rate_limit_counts[user_id] = []

        # Remove old entries
        rate_limit_counts[user_id] = [time for time in rate_limit_counts[user_id] if time >= minute_start]

        if len(rate_limit_counts[user_id]) < 5:
            update_time = current_time
            rate_limit_counts[user_id].append(update_time)

            return func(*args, **kwargs)
        else:
            return jsonify({'error': 'Rate limit exceeded'}), 429

    return wrapper

if __name__ == '__main__':
    app.run(debug=True)
