logging.basicConfig(filename='graph_operations.log', level=logging.INFO)

def add_random_vertices_and_edges(neo4j_uri, user_name):
    driver = neo4j.GraphDatabase.driver(neo4j_uri)

    try:
        with driver.session() as session:
            for _ in range(random.randint(10, 50)):
                vertex_id = random.randint(1, 1000)  # Assuming unique IDs
                properties = {
                    'name': f'Node-{vertex_id}',
                    'created_at': time.time()
                }

                # Add vertex
                session.run('CREATE (n:Node {id: $id, ...$props})', id=vertex_id, props=properties)

                for _ in range(random.randint(1, 5)):
                    neighbor_vertex_id = random.randint(1, 1000)
                    edge_type = f'LINK-{random.randint(1, 3)}'

                    # Add edge
                    session.run('MATCH (a:Node {id: $source}), (b:Node {id: $target}) CREATE (a)-[:$type]->(b)',
                                source=vertex_id, target=neighbor_vertex_id, type=edge_type)

            logging.info(f"Added vertices and edges by {user_name}")
    except TransactionError as e:
        driver.session().rollback()
        logging.error(f"Transaction failed for {user_name}: {e}")
    finally:
        driver.close()

# Example usage
neo4j_uri = 'bolt://localhost:7687'
user_name = 'example_user'
