        num_files = atoi(line);
        file_array = (FileData *)malloc(num_files * sizeof(FileData));
        for (int i = 0; i < num_files; i++) {
            fgets(line, sizeof(line), stdin);
            file_array[i].file_path = strdup(line);
        }
    }

    worker_count = MIN(num_files, MAX_WORKERS);
    for (int i = 0; i < worker_count; i++) {
        pthread_create(&workers[i], NULL, process_file, &file_array[i]);
    }

    for (int i = 0; i < worker_count; i++) {
        pthread_join(workers[i], NULL);
    }

    free(file_array);

    const char *json_str = "{\"username\":\"john\", \"email\":\"john@example.com\", \"age\":30}";
    if (!validate_json(json_str)) {
        printf("JSON validation failed.\n");
    } else {
        printf("JSON validation successful.\n");
    }

    return 0;
}
