std::mutex mtx;
std::condition_variable cv;
bool done = false;

void processOctreeData(const std::string& encodedMessage, const std::string& key, const std::string& iv, int featureSize, int numLeafNodes, int dataCapacity) {
    try {
        std::string decryptedData = decrypt(encodedMessage, key, iv);

