#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <memory>
#include <openssl/evp.h>
#include <botan/auto_rng.h>

class RandomNumberService {
public:
    struct Config {
        size_t worker_threads = 4;
        // Add other configuration parameters here
    };

    class ClientRequest {
    public:
        explicit ClientRequest(size_t count, int range) : count(count), range(range) {}
        size_t getCount() const { return count; }
        int getRange() const { return range; }

    private:
        size_t count;
        int range;
    };

    using Result = std::vector<int>;

    RandomNumberService(const Config& config)
        : config(config), stop(false) {
        startWorkers();
    }

    ~RandomNumberService() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();

        for (auto& thread : workers) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void handleRequest(ClientRequest request, std::function<void(const Result&)> onComplete) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            requests.push(std::make_pair(request, onComplete));
        }
        cv.notify_one();
    }

private:
    Config config;
    bool stop;
    std::vector<std::thread> workers;
    std::queue<std::pair<ClientRequest, std::function<void(const Result&)>>> requests;
    mutable std::mutex mutex;
    std::condition_variable cv;

    void startWorkers() {
        for (size_t i = 0; i < config.worker_threads; ++i) {
            workers.emplace_back([this]() {
                while (true) {
                    ClientRequest request;
                    std::function<void(const Result&)> onComplete;
                    {
                        std::unique_lock<std::mutex> lock(mutex);
                        cv.wait(lock, [this] { return !requests.empty() || stop; });
                        if (stop && requests.empty()) {
                            return;
                        }
                        request = requests.front().first;
                        onComplete = requests.front().second;
                        requests.pop();
                    }

                    Result result = generateRandomNumbers(request.getCount(), request.getRange());
                    onComplete(result);
                }
            });
        }
    }

    Result generateRandomNumbers(size_t count, int range) {
        Result numbers;
        Botan::AutoSeeded_RNG rng;

        for (size_t i = 0; i < count; ++i) {
            numbers.push_back(rng.random_integer(1, range));
        }

        return numbers;
    }
};

int main() {
    RandomNumberService::Config config;
    config.worker_threads = 4;

    RandomNumberService service(config);

    // Example client request
    service.handleRequest(RandomNumberService::ClientRequest(10, 100), [](const RandomNumberService::Result& result) {
        for (int num : result) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    });

    // Keep the main thread alive to receive requests
    std::this_thread::sleep_for(std::chrono::seconds(60));

    return 0;
}
