import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.Date;

public class FileHasher {

    public static String computeFileHash(String filePath, int bufferSize, String algorithm)
            throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] buffer = new byte[bufferSize];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        } catch (IOException e) {
            System.err.println("Error reading file: " + filePath);
            throw e;
        }
        return bytesToHex(digest.digest());
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java FileHasher <file_path> <buffer_size> [algorithm]");
            return;
        }

        String filePath = args[0];
        int bufferSize = Integer.parseInt(args[1]);
        String algorithm = "SHA-256";
        if (args.length > 2) {
            algorithm = args[2];
        }

        try {
            String hash = computeFileHash(filePath, bufferSize, algorithm);
            System.out.println("Computed hash: " + hash);

            saveToDatabase(filePath, new File(filePath).length(), new Date().getTime(), hash);
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

    private static void saveToDatabase(String filePath, long fileSize, long lastModified, String hash)
            throws SQLException {
        String url = "jdbc:mysql://localhost:3306/yourdatabase";
        String user = "username";
        String password = "password";

        try (Connection conn = DriverManager.getConnection(url, user, password)) {
            String sql = "INSERT INTO file_hashes (file_path, file_size, last_modified, hash) VALUES (?, ?, ?, ?)";
            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
                pstmt.setString(1, filePath);
                pstmt.setLong(2, fileSize);
                pstmt.setLong(3, lastModified);
                pstmt.setString(4, hash);
                pstmt.executeUpdate();
            }
        } catch (SQLException e) {
            System.err.println("Error saving to database: " + e.getMessage());
            throw e;
        }
    }
}
