const express = require('express');
const axios = require('axios');
const { LRUCache } = require('lru-cache');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const commandCache = new LRUCache({ max: 100 });

app.get('/commands', async (req, res) => {
  const { command, page, limit } = req.query;
  let result = commandCache.get(command);

  if (!result) {
    try {
      result = await executeCommand(command);
      commandCache.set(command, result);
    } catch (error) {
      return res.status(500).json({ error: 'Failed to execute command' });
    }
  }

  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;

  res.json({
    data: result.slice(startIndex, endIndex),
    total: result.length,
    page,
    limit
  });
});

app.post('/commands/retry', async (req, res) => {
  const { command } = req.body;
  try {
    const result = await executeCommand(command);
    return res.status(200).json({ result });
  } catch (error) {
    return res.status(500).json({ error: 'Failed to retry command' });
  }
});

app.ws('/notifications', (ws, req) => {
  ws.on('message', async (message) => {
    const { command } = JSON.parse(message);
    try {
      const result = await executeCommand(command);
      ws.send(JSON.stringify(result));
    } catch (error) {
      ws.send(JSON.stringify({ error: 'Failed to execute command' }));
    }
  });
});

