using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

public class ConfigManager : IConfigManager
{
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;
    private readonly CacheService _cacheService;
    private readonly ILogger _logger;

    public ConfigManager(HttpClient httpClient, string apiUrl, CacheService cacheService, ILogger logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _apiUrl = apiUrl ?? throw new ArgumentNullException(nameof(apiUrl));
        _cacheService = cacheService ?? throw new ArgumentNullException(nameof(cacheService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<Config> GetConfigAsync()
    {
        try
        {
            var cachedConfig = await _cacheService.GetConfigAsync();
            if (cachedConfig != null)
            {
                return cachedConfig;
            }

            var response = await _httpClient.GetAsync(_apiUrl);
            if (!response.IsSuccessStatusCode)
            {
                _logger.LogError($"Failed to fetch config. Status code: {response.StatusCode}");
                throw new Exception("Failed to fetch config from API.");
            }

            var jsonContent = await response.Content.ReadAsStringAsync();
            var configJson = JObject.Parse(jsonContent);

            // Validate configuration data
            if (!ValidateConfig(configJson))
            {
                _logger.LogError("Invalid configuration data received.");
                throw new Exception("Invalid configuration data.");
            }

            var config = new Config
            {
                TileSize = (int)configJson["TileSize"],
                WorldWidth = (int)configJson["WorldWidth"],
                WorldHeight = (int)configJson["WorldHeight"],
                CameraSpeed = (float)configJson["CameraSpeed"]
            };

            await _cacheService.SetConfigAsync(config);
            return config;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error fetching or validating configuration.");
            throw;
        }
    }

    private bool ValidateConfig(JObject configJson)
    {
        // Add validation logic here
        if (configJson["TileSize"] == null || (int)configJson["TileSize"] <= 0)
        {
            return false;
        }
        if (configJson["WorldWidth"] == null || (int)configJson["WorldWidth"] <= 0)
        {
            return false;
        }
        if (configJson["WorldHeight"] == null || (int)configJson["WorldHeight"] <= 0)
        {
            return false;
        }
        if (configJson["CameraSpeed"] == null || (float)configJson["CameraSpeed"] <= 0)
        {
            return false;
        }
        return true;
    }
}

public interface IConfigManager
{
    Task<Config> GetConfigAsync();
}

public class Config
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public float CameraSpeed { get; set; }
}
