// Import necessary Rust standard library modules
use std::collections::HashMap;
use std::io::{self, Write};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{Instant, Duration};

// Define the Backend trait with a compile method
trait Backend {
    fn compile(&self, source_file: &str) -> Result<(), io::Error>;
}

// Implement a simple file backend as an example
struct FileBackend;

impl Backend for FileBackend {
    fn compile(&self, source_file: &str) -> Result<(), io::Error> {
        // Simulate compilation with a sleep and echo command
        Command::new("sh")
            .args(&["-c", format!("sleep 1 && echo Compiled {}", source_file).as_str()])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()?
            .wait_with_output()?;

        Ok(())
    }
}

// Define the Compiler struct
pub struct Compiler {
    backend: Box<dyn Backend>,
    max_concurrency: usize,
    resource_limits: HashMap<String, ResourceLimits>,
    logger: Logger,
}

// Define a struct to hold resource limits per source file
struct ResourceLimits {
    memory_limit_mb: u32,
    // Add other resource limits as needed
}

// Define a simple logger struct
pub struct Logger;

impl Logger {
    pub fn log(&self, message: &str) {
        println!("{}", message);
    }
}

// Implement the Compiler methods
impl Compiler {
    pub fn new(backend: Box<dyn Backend>, max_concurrency: usize, resource_limits: HashMap<String, ResourceLimits>, logger: Logger) -> Self {
        Compiler { backend, max_concurrency, resource_limits, logger }
    }

    pub fn compile_files(&self, source_files: &[&str]) -> Result<HashMap<&str, CompilationResult>, io::Error> {
        let mut results = HashMap::new();
        let semaphore = Arc::new(Mutex::new(0));

        for &source_file in source_files {
            let backend = self.backend.clone();
            let semaphore_clone = semaphore.clone();
            let resource_limits = self.resource_limits.get(source_file).cloned().unwrap_or_default();
            let logger = self.logger.clone();

            std::thread::spawn(move || {
                let mut guard = semaphore_clone.lock().unwrap();
                while *guard >= self.max_concurrency {
                    std::thread::sleep(Duration::from_millis(100));
                    *guard = *semaphore_clone.lock().unwrap();
                }
                *guard += 1;
                drop(guard);

                let start_time = Instant::now();
                let mut process = Command::new("sh")
                    .args(&["-c", format!("time -f '%e %M' {}", source_file).as_str()])
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .spawn()?;

                // Set resource limits (this is a simplified example)
                process.stdin.unwrap().write_all(format!("ulimit -v {}000\n", resource_limits.memory_limit_mb).as_bytes()).unwrap();

                let output = process.wait_with_output()?;
                if !output.status.success() {
                    logger.log(&format!("Compilation failed for {}: {}", source_file, String::from_utf8_lossy(&output.stderr)));
                    results.insert(source_file, CompilationResult::Failed);
                    return;
                }

                let duration = start_time.elapsed();
                let memory_usage_kb = output.stdout.trim().split_whitespace().nth(1).and_then(|m| m.parse::<u32>().ok()).unwrap_or_default() * 1024;

                logger.log(&format!("Compiled {} in {:?} with peak memory usage: {} KB", source_file, duration, memory_usage_kb));

                results.insert(source_file, CompilationResult::Successful(duration, memory_usage_kb));
            });
        }

        // Wait for all threads to finish
        while semaphore.lock().unwrap() > 0 {
            std::thread::sleep(Duration::from_millis(100));
        }

        Ok(results)
    }
}

// Define an enum to represent the result of a compilation task
enum CompilationResult {
    Successful(Duration, u32),
    Failed,
}
```

This code defines a `Compiler` struct that can compile a list of source files using a pluggable backend. It supports concurrent compilation tasks with thread safety and resource limiting. The `Backend` trait allows for different backends to be implemented, such as a file backend or an in-memory compiler. The `Logger` struct is used to log messages at different levels and formats. The `compile_files` method of the `Compiler` struct compiles each source file using a separate thread and logs the compilation time and memory usage. It also handles errors during compilation and ensures that the function can recover gracefully from transient failures.

