import org.springframework.cache.annotation.Cacheable;
import org.springframework.web.client.RestTemplate;
import java.util.concurrent.TimeUnit;

public class ConfigurationService {

    private final RestTemplate restTemplate;
    private final String configUrl;
    private final int maxRetries;
    private final long retryInterval;

    public ConfigurationService(RestTemplate restTemplate, String configUrl, int maxRetries, long retryInterval) {
        this.restTemplate = restTemplate;
        this.configUrl = configUrl;
        this.maxRetries = maxRetries;
        this.retryInterval = retryInterval;
    }

    @Cacheable("configurations")
    public Config loadConfiguration() {
        return fetchConfigWithRetry();
    }

    private Config fetchConfigWithRetry() {
        for (int attempt = 0; attempt < maxRetries; attempt++) {
            try {
                return restTemplate.getForObject(configUrl, Config.class);
            } catch (Exception e) {
                if (attempt == maxRetries - 1) {
                    throw new ConfigurationException("Failed to load configuration after " + maxRetries + " attempts");
                }
                try {
                    TimeUnit.SECONDS.sleep(retryInterval);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
        // This line should never be reached due to the loop condition
        throw new ConfigurationException("This should not happen");
    }

    public void applyConfiguration(Config config) {
        // Code to apply configuration to application settings
    }

    public void resetCache() {
        // Code to manually reset cache
    }
}
