<?php

// Function to update a user's password with validation using an external API
function updateUserPassword($userId, $currentPassword, $newPassword) {
    // Initialize database connection (example)
    $db = new PDO('mysql:host=localhost;dbname=users_db', 'username', 'password');

    // Validate current password against the database
    try {
        $stmt = $db->prepare("SELECT * FROM users WHERE id = :userId AND password = :currentPassword");
        $stmt->execute(['userId' => $userId, 'currentPassword' => password_hash($currentPassword, PASSWORD_DEFAULT)]);

        if ($stmt->rowCount() == 0) {
            return json_encode([
                "error" => true,
                "code" => 401,
                "message" => "Invalid current password"
            ]);
        }
    } catch (PDOException $e) {
        return json_encode([
            "error" => true,
            "code" => 500,
            "message" => "Database error: " . $e->getMessage()
        ]);
    }

    // Check new password strength using an external API
    $apiUrl = 'https://passwordstrengthcheck.com/api/v1/validate';
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $apiUrl);
    curl_setopt($ch, CURLOPT_POST, 1);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query(['password' => $newPassword]));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    try {
        $response = curl_exec($ch);

        if ($response === false) {
            return json_encode([
                "error" => true,
                "code" => 503,
                "message" => "API error: Unable to validate password"
            ]);
        }

        $apiResponse = json_decode($response, true);

        if (!$apiResponse['isStrong']) {
            return json_encode([
                "error" => true,
                "code" => 422,
                "message" => "Password is too weak: " . implode(", ", $apiResponse['errors'])
            ]);
        }
    } finally {
        curl_close($ch);
    }

    // Update the password in the database
    try {
        $stmt = $db->prepare("UPDATE users SET password = :newPassword WHERE id = :userId");
        $stmt->execute(['newPassword' => password_hash($newPassword, PASSWORD_DEFAULT), 'userId' => $userId]);

        if ($stmt->rowCount() == 1) {
            return json_encode([
                "error" => false,
                "code" => 200,
                "message" => "Password updated successfully"
            ]);
        } else {
            return json_encode([
                "error" => true,
                "code" => 500,
                "message" => "Failed to update password in the database"
            ]);
        }
    } catch (PDOException $e) {
        return json_encode([
            "error" => true,
            "code" => 500,
            "message" => "Database error: " . $e->getMessage()
        ]);
    }
}
