#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <openssl/rand.h>
#include <botan/auto_rng.h>

struct State {
    int id;
    double probability;
};

class RandomNumberGenerator {
public:
    RandomNumberGenerator(size_t numThreads = std::thread::hardware_concurrency())
        : stateTransitionProbabilities(numThreads), rng() {}

    void addState(const State& state) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            states.push_back(state);
        }
        condition.notify_one();
    }

    double getRandomNumber(size_t threadId) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this, &threadId] { return !states.empty() && currentThread == threadId; });
        auto state = states[currentState];
        if (++currentState >= states.size()) {
            currentState = 0;
        }
        lock.unlock();
        return generateRandomNumber(state.probability);
    }

private:
    std::vector<State> states;
    std::vector<double> stateTransitionProbabilities;
    Botan::AutoSeeded_RNG rng;
    size_t currentState = 0;
    size_t currentThread = 0;
    std::mutex mutex;
    std::condition_variable condition;

    double generateRandomNumber(double probability) {
        if (Botan::random_number(rng) < probability) {
            return stateTransitionProbabilities[currentThread];
        }
        return rng.random_real(0.0, 1.0);
    }
};

int main() {
    RandomNumberGenerator rng;
    std::vector<std::thread> threads;

    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        threads.emplace_back([&rng, i] { for (int j = 0; j < 1000000; ++j) rng.getRandomNumber(i); });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
