import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DistributedCacheSystem {
    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void put(String key, String value, long ttl) {
        cache.put(key, new CacheEntry(value, System.currentTimeMillis() + ttl));
    }

    public String get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && System.currentTimeMillis() < entry.expiryTime) {
            return entry.value;
        } else {
            cache.remove(key);
            return null;
        }
    }

    public void remove(String key) {
        cache.remove(key);
    }

    private static class CacheEntry {
        String value;
        long expiryTime;

        CacheEntry(String value, long expiryTime) {
            this.value = value;
            this.expiryTime = expiryTime;
        }
    }

    public void startCacheTtlCleanup() {
        scheduler.scheduleAtFixedRate(this::cleanupExpiredEntries, 1, 1, TimeUnit.MINUTES);
    }

    private void cleanupExpiredEntries() {
        cache.entrySet().removeIf(entry -> System.currentTimeMillis() >= entry.getValue().expiryTime);
    }
}
