            file.write(','.join(line) + '\n')

# Main function to orchestrate the process
def main(file_path, output_path, use_parallel=False):
    lines = read_file(file_path)
    processed_lines = []

    if use_parallel:
        with Pool(cpu_count()) as pool:
            results = pool.map(process_line, lines)
    else:
        results = [process_line(line) for line in lines]

    for result in results:
        average = calculate_average(result)
        if average is not None:
            result.append(str(average))
            processed_lines.append(result)

    write_file(processed_lines, output_path)

