// app.js
const express = require('express');
const bodyParser = require('body-parser');
const execa = require('execa');
const LRU = require('lru-cache');
const axios = require('axios');
const WebSocket = require('ws');
const mersenneTwister = require('./mersenne-twister');

const app = express();
app.use(bodyParser.json());

// Configure cache
const cache = new LRU({
  max: 1000,
  maxAge: 3600 * 1000, // Cache for 1 hour
});

// Retry mechanism with exponential backoff
async function retryWithBackoff(task, maxRetries = 5) {
  let attempt = 0;
  while (attempt < maxRetries) {
    try {
      return await task();
    } catch (error) {
      if (error.response && error.response.status === 429) {
        const delay = Math.pow(2, attempt) * 100; // Exponential backoff
        await new Promise(resolve => setTimeout(resolve, delay));
        attempt++;
      } else {
        throw error;
      }
    }
  }
  throw new Error('Too many retries');
}

// Fetch metadata from external API
async function fetchMetadata(commandOutput) {
  try {
    const response = await axios.get(`https://api.example.com/metadata?output=${commandOutput}`);
    return response.data;
  } catch (error) {
    console.error('Failed to fetch metadata:', error);
    return null;
  }
}

// Execute shell command
async function executeCommand(command) {
  try {
    const { stdout, stderr } = await execa(command, { shell: true });
    const output = stdout || stderr; // Prefer stdout if available
    const metadata = await fetchMetadata(output);
    cache.set(command, { output, metadata });
    return { output, metadata };
  } catch (error) {
    console.error('Command execution failed:', error);
    throw error;
  }
}

// WebSocket server for real-time notifications
const wss = new WebSocket.Server({ port: 8081 });

wss.on('connection', ws => {
  ws.on('message', message => {
    // Handle incoming messages if needed
  });
});

// RESTful API endpoint to query cached command results
app.get('/command-results', (req, res) => {
  const { limit = 10, offset = 0 } = req.query;
  const filteredResults = Object.entries(cache).slice(offset, offset + parseInt(limit));
  res.json(filteredResults.map(([key, value]) => ({ command: key, output: value.output, metadata: value.metadata })));
});

// Endpoint to execute a shell command
app.post('/execute', async (req, res) => {
  const { command } = req.body;
  if (!command || !/^[a-zA-Z0-9\s]+$/.test(command)) {
    return res.status(400).json({ error: 'Invalid command' });
  }
  try {
    const result = await executeCommand(command);
    ws.clients.forEach(client => {
      if (client.readyState === WebSocket.OPEN) {
        client.send(JSON.stringify(result));
      }
    });
    res.json(result);
  } catch (error) {
    res.status(500).json({ error: 'Failed to execute command' });
  }
});

// Load simulator
app.get('/load-simulator', async (req, res) => {
  const { commands } = req.query;
  if (!commands || isNaN(commands)) {
    return res.status(400).json({ error: 'Invalid number of commands' });
  }
  try {
    for (let i = 0; i < parseInt(commands); i++) {
      const randomCommand = `echo "Simulating command ${i}"`;
      await executeCommand(randomCommand);
    }
    res.json({ message: `${commands} commands simulated successfully` });
  } catch (error) {
    res.status(500).json({ error: 'Failed to simulate load' });
  }
});

// Start server
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
