// mersenne-twister.cpp
#include <iostream>
#include <random>

namespace mt {
  class MersenneTwister {
  public:
    MersenneTwister() : generator(42) {}
    ~MersenneTwister() {}

    int nextInt(int min, int max) {
      std::uniform_int_distribution<int> distribution(min, max);
      return distribution(generator);
    }

  private:
    std::mt19937 generator;
  };
}

int main() {
  mt::MersenneTwister twister;
  for (int i = 0; i < 10; i++) {
    std::cout << twister.nextInt(1, 100) << std::endl;
  }
  return 0;
}
