    }

    impl GrammarCache {
        pub fn new() -> Self { GrammarCache { cache: HashMap::new() } }

        pub fn get_or_fetch(&mut self, file_path: &str) -> Result<String, &'static str> {
            if let Some(cached_ir) = self.cache.get(file_path) {
                Ok(cached_ir.clone())
            } else {
