```cpp
#include <vector>
#include <cstring>
#include <iostream>

// Define a struct for employee records
struct Employee {
    int id;
    char* name;
    char* department;
    float salary;

    // Constructor and destructor to manage memory
    Employee(int id, const std::string& name, const std::string& department, float salary) 
        : id(id), salary(salary) {
        this->name = new char[name.length() + 1];
        strcpy(this->name, name.c_str());
        this->department = new char[department.length() + 1];
        strcpy(this->department, department.c_str());
    }

    ~Employee() {
        delete[] name;
        delete[] department;
    }
};

// Function to allocate memory for employee records
std::vector<Employee*> AllocateMemory(const std::vector<int>& ids, const std::vector<std::string>& names, 
                                    const std::vector<std::string>& departments, const std::vector<float>& salaries) {
    if (ids.size() != names.size() || ids.size() != departments.size() || ids.size() != salaries.size()) {
        std::cerr << "Error: Mismatch in input sizes." << std::endl;
        return {};
    }

    std::vector<Employee*> employees;
    for (size_t i = 0; i < ids.size(); ++i) {
        try {
            employees.push_back(new Employee(ids[i], names[i], departments[i], salaries[i]));
        } catch (const std::bad_alloc& e) {
            std::cerr << "Error: Memory allocation failed." << std::endl;
            // Clean up previously allocated memory
            for (Employee* emp : employees) {
                delete emp;
            }
            return {};
        }
    }

    return employees;
}

// Function to free the allocated memory
void FreeMemory(std::vector<Employee*>& employees) {
    for (Employee* emp : employees) {
        delete emp;
    }
    employees.clear();
}
