// Function to recursively scan directory for text files
std::vector<std::string> scanDirectory(const std::string& path) {
    std::vector<std::string> texts;
    std::filesystem::recursive_directory_iterator it(path);
    std::filesystem::recursive_directory_iterator end;
    while (it != end) {
        if (it->path().extension() == ".txt") {
            texts.push_back(it->path().string());
        }
        ++it;
    }
    return texts;
}

// Function to parse text files line by line
std::vector<std::string> parseTextFile(const std::string& filePath) {
    std::vector<std::string> lines;
    std::ifstream file(filePath);
    if (file.is_open()) {
        std::string line;
        while (getline(file, line)) {
            lines.push_back(line);
        }
        file.close();
    } else {
        std::cerr << "Unable to open file: " << filePath << std::endl;
    }
    return lines;
