#define LOG_INFO printf
#define LOG_ERROR printf
#define LOG_DEBUG printf

typedef struct {
    int value;
    // Add additional metadata fields here
} record;

void* initialize_arrays(void* arg) {
    char offsets_path[] = "offsets.csv";
    char keys_path[] = "keys.csv";
    long *offsets = NULL, *keys = NULL;
    record *records = NULL;
    int num_records = 0;
    FILE *fp;

    // Initialize mutexes and condition variables
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Log start of array initialization
    LOG_INFO("Starting array initialization...\n");

    // Read offsets from CSV file
    if ((fp = fopen(offsets_path, "r")) == NULL) {
        LOG_ERROR("Failed to open offsets.csv\n");
        return NULL;
    }
    // Count number of records and allocate memory for offsets
    num_records = count_records(fp);
    offsets = (long*)malloc(num_records * sizeof(long));
    read_csv(fp, offsets, num_records);
    fclose(fp);

    // Read keys from CSV file
    if ((fp = fopen(keys_path, "r")) == NULL) {
        LOG_ERROR("Failed to open keys.csv\n");
        return NULL;
    }
    // Allocate memory for keys
    keys = (long*)malloc(num_records * sizeof(long));
    read_csv(fp, keys, num_records);
    fclose(fp);

    // Allocate memory for records
    records = (record*)malloc(num_records * sizeof(record));
    if (records == NULL) {
        LOG_ERROR("Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize records with random values and metadata
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = generate_random_value();
        // Initialize additional metadata fields here
    }

    // Log successful initialization of arrays
    LOG_INFO("Arrays initialized successfully\n");

    // Free allocated memory when done
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int count_records(FILE *fp) {
    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        count++;
    }
    fseek(fp, 0, SEEK_SET);
    return count;
}

void read_csv(FILE *fp, long *array, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (fgets(array + i, sizeof(long), fp) == NULL) {
            array[i] = 0; // Default value for corrupted entries
        }
    }
}

int generate_random_value() {
    return rand() % 100000; // Generate a random integer between 0 and 99999
}
