public class PaymentProcessor {

    private Map<String, PaymentGateway> gateways;

    public PaymentProcessor(List<PaymentGateway> paymentGateways) {
        this.gateways = initializeGateways(paymentGateways);
    }

    private Map<String, PaymentGateway> initializeGateways(List<PaymentGateway> paymentGateways) {
        // Initialize and configure the payment gateways
        return paymentGateways.stream()
                .collect(Collectors.toMap(PaymentGateway::getType, gateway -> gateway));
    }

    public TransactionResult processTransaction(Transaction transaction) {
        String paymentMethod = transaction.getPaymentMethod();
        PaymentGateway gateway = getGatewayForPaymentMethod(paymentMethod);

        if (gateway != null) {
            return gateway.process(transaction);
        } else {
            // Fallback strategy
            return fallbackTransaction(transaction);
        }
    }

    private PaymentGateway getGatewayForPaymentMethod(String paymentMethod) {
        // Implement logic to select the appropriate gateway based on payment method and user behavior
        return gateways.get(paymentMethod);
    }

    private TransactionResult fallbackTransaction(Transaction transaction) {
        // Prioritize alternative gateways based on transaction type, urgency, and regional preferences
        for (String preferredGateway : getPreferredGateways(transaction)) {
            PaymentGateway gateway = gateways.get(preferredGateway);
            if (gateway != null && gateway.isAvailable()) {
                return gateway.process(transaction);
            }
        }
        // Fallback to default gateway if all else fails
        return gateways.get("default").process(transaction);
    }

    private List<String> getPreferredGateways(Transaction transaction) {
        // Implement logic to determine the preferred payment gateways based on transaction details
        return Arrays.asList("preferred1", "preferred2");
    }
}

interface PaymentGateway {
    String getType();
    boolean isAvailable();
    TransactionResult process(Transaction transaction);
}

class Transaction {
