    public class ServiceManagerHostedService : IHostedService
    {
        private readonly IServiceScopeFactory _serviceScopeFactory;
        private readonly IConsumer<Ignore, string> _consumer;

        public ServiceManagerHostedService(IServiceScopeFactory serviceScopeFactory, IConsumer<Ignore, string> consumer)
        {
            _serviceScopeFactory = serviceScopeFactory;
            _consumer = consumer;
        }

        public async Task StartAsync(CancellationToken cancellationToken)
        {
            _consumer.Subscribe("ServiceTriggerTopic");

            while (!cancellationToken.IsCancellationRequested)
            {
                try
                {
                    var consumeResult = await _consumer.ConsumeAsync(cancellationToken);
                    if (consumeResult.Message.Value == "Start")
                    {
                        // Logic to start service
                        Console.WriteLine("Starting service...");
                    }
                    else if (consumeResult.Message.Value == "Stop")
                    {
                        // Logic to stop service
                        Console.WriteLine("Stopping service...");
                        _consumer.StoreOffset(consumeResult);
                    }
                }
                catch (ConsumeException<Ignore, string> e)
                {
                    // Error handling for Kafka consumption
                    Console.WriteLine($"Error occured: {e.Error.Reason}");
                }
            }

            _consumer.Close();
        }

        public Task StopAsync(CancellationToken cancellationToken)
        {
            // Cleanup logic if needed
            return Task.CompletedTask;
        }
    }

