    {
        private readonly IServiceProvider _serviceProvider;

        public ServiceManager(IServiceProvider serviceProvider)
        {
            _serviceProvider = serviceProvider;
        }

        public async Task<IDataReader> ExecuteQueryAsync(string query, List<SqlParameter> parameters)
        {
            using var scope = _serviceProvider.CreateScope();
            var dbContext = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();

            return await dbContext.Database.SqlQueryRawAsync(query, parameters.ToArray());
        }
    }

    public class MessagePublisher
    {
        private readonly IProducer<Ignore, string> _producer;

        public MessagePublisher(IProducer<Ignore, string> producer)
        {
            _producer = producer;
        }

        public async Task PublishStatusUpdateAsync(string serviceId, string status)
        {
            try
            {
                await _producer.ProduceAsync("ServiceStatusTopic", new Message<Ignore, string>
                {
                    Value = $"{serviceId}: {status}"
                });
            }
            catch (KafkaException e)
            {
                // Error handling for Kafka production
                Console.WriteLine($"Error occurred: {e.Error.Reason}");
            }
        }
    }

