from flask import Flask, request, jsonify
from flask_caching import Cache
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
import stripe  # Assuming Stripe as the third-party payment gateway

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'simple'})
limiter = Limiter(
    app,
    key_func=get_remote_address,
    default_limits=["200 per day", "50 per hour"]
)

stripe.api_key = 'your_stripe_api_key'

@app.route('/payment/create', methods=['POST'])
@limiter.limit("10 per minute")
def create_payment():
    data = request.json
    payment_method_id = data.get('payment_method_id')
    amount = data.get('amount')

    # Validate and process the payment using Stripe
    try:
        charge = stripe.Charge.create(
            amount=amount,
            currency='usd',
            source=payment_method_id
        )
        return jsonify(charge), 201
    except stripe.error.StripeError as e:
        return jsonify(e.user_message), 400

@app.route('/payment/status/<charge_id>', methods=['GET'])
@cache.cached(timeout=50)
def get_payment_status(charge_id):
    try:
        charge = stripe.Charge.retrieve(charge_id)
        return jsonify(charge.status), 200
    except stripe.error.StripeError as e:
        return jsonify(e.user_message), 400

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
