```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public class SecureDecryption
{
    private static string keyFromConfig = "your_key_here";
    private static string ivFromConfig = "your_iv_here";

    public static string DecryptMessage(string base64EncodedData)
    {
        using (TripleDES tripleDes = TripleDES.Create())
        {
            byte[] key = Convert.FromBase64String(keyFromConfig);
            byte[] iv = Convert.FromBase64String(ivFromConfig);
            byte[] dataToDecrypt = Convert.FromBase64String(base64EncodedData);

            tripleDes.Key = key;
            tripleDes.IV = iv;

            using (MemoryStream msEncrypt = new MemoryStream())
            {
                using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, tripleDes.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    csEncrypt.Write(dataToDecrypt, 0, dataToDecrypt.Length);
                    csEncrypt.FlushFinalBlock();
                }

                return Encoding.UTF8.GetString(msEncrypt.ToArray());
            }
        }
    }
}

class Program
{
    static void Main(string[] args)
    {
        string base64EncodedData = "your_base64_encoded_data_here";
        string decryptedMessage = SecureDecryption.DecryptMessage(base64EncodedData);
        Console.WriteLine("Decrypted Message: " + decryptedMessage);
    }
}
