using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;

[ApiController]
[Route("api/[controller]")]
public class UserProfileController : ControllerBase
{
    private readonly IUserProfileService _userProfileService;
    private readonly IEmailService _emailService;
    private readonly IPaymentGateway _paymentGateway;

    public UserProfileController(IUserProfileService userProfileService, IEmailService emailService, IPaymentGateway paymentGateway)
    {
        _userProfileService = userProfileService;
        _emailService = emailService;
        _paymentGateway = paymentGateway;
    }

    [HttpPut("{userId}")]
    public async Task<IActionResult> UpdateUserProfile(int userId, [FromBody] UserProfileUpdateRequest request)
    {
        try
        {
            // Validate the JSON payload for correctness and completeness
            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            // Update user profile asynchronously
            var updatedProfile = await _userProfileService.UpdateUserProfileAsync(userId, request);

            // Start background job to send confirmation email
            _emailService.SendConfirmationEmail(updatedProfile.Email, userId);

            return Ok(updatedProfile);
        }
        catch (Exception ex)
        {
            // Log detailed error messages and stack traces for debugging purposes
            _logger.LogError(ex, "Failed to update user profile");
            return StatusCode(500, "Internal server error");
        }
    }
}

public class UserProfileUpdateRequest
{
    public string Name { get; set; }
    public string Email { get; set; }
    public bool IsPremium { get; set; }
}

public interface IUserProfileService
{
    Task<UserProfile> UpdateUserProfileAsync(int userId, UserProfileUpdateRequest request);
}

public interface IEmailService
{
    void SendConfirmationEmail(string email, int userId);
}

public interface IPaymentGateway
{
    Task ProcessPaymentAsync(int userId, bool isPremium);
}
