// Define constants and types
#define MAX_PATH_LENGTH 1024
#define LOG_FILE "path_monitor.log"
typedef struct {
    char directory[MAX_PATH_LENGTH];
    int max_length;
} DirectoryConfig;

// Function prototypes
void* monitor_directory(void* arg);
int adjust_path(DirectoryConfig* config, int new_max_length);
void log_message(const char* message);

// Global variables
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;

// Main function to start monitoring threads
int main() {
    DirectoryConfig configs[] = {
        {"C:\\Users\\User", 2048},
        {"/home/user/projects", 1024}
    };
    pthread_t threads[2];

    for (int i = 0; i < 2; i++) {
        if (pthread_create(&threads[i], NULL, monitor_directory, &configs[i]) != 0) {
            log_message("Failed to create thread");
        }
    }

    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

// Thread function to monitor and adjust directory paths
void* monitor_directory(void* arg) {
    DirectoryConfig* config = (DirectoryConfig*)arg;
    while (1) {
        pthread_mutex_lock(&config_mutex);
        int new_length = get_configured_length(config->directory); // Assume this function fetches the length from a distributed key-value store or config file
        if (new_length > 0 && adjust_path(config, new_length)) {
            log_message("Path adjusted: %s", config->directory);
        }
        pthread_mutex_unlock(&config_mutex);
        sleep(60); // Check every minute
    }
}

// Function to adjust the directory path based on new maximum length
int adjust_path(DirectoryConfig* config, int new_max_length) {
    if (new_max_length <= strlen(config->directory)) {
        return 0; // No change needed
    }

    char new_path[MAX_PATH_LENGTH];
    snprintf(new_path, sizeof(new_path), "%s/", config->directory);
    while (strlen(new_path) + strlen(config->directory) < new_max_length) {
        strcat(new_path, "/");
    }
    if (new_path[strlen(new_path) - 1] == '/') {
        new_path[strlen(new_path) - 1] = '\0';
    }

    strcpy(config->directory, new_path);
    return 1; // Path was adjusted
}

// Function to log messages with thread safety
void log_message(const char* message) {
    pthread_mutex_lock(&log_mutex);
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

// Assume this function fetches the configured length from a distributed key-value store or config file
int get_configured_length(const char* directory) {
    // Simulated implementation
    if (strcmp(directory, "C:\\Users\\User") == 0) {
        return 2048;
    } else if (strcmp(directory, "/home/user/projects") == 0) {
        return 1024;
    }
    return -1; // Error or unknown directory
}
