```cpp
#include <iostream>
#include <vector>
#include <future>
#include <mutex>
#include <string>

std::mutex mtx;

auto asyncReduce = [](const std::vector<std::any>& data) -> std::any {
    if (data.empty()) return std::any{};

    auto accumulate = [&](const auto& item, const auto& acc) {
        std::lock_guard<std::mutex> lock(mtx);
        return std::visit(overloaded{
            [](int a, int b) -> int { return a + b; },
            [](double a, double b) -> double { return a + b; },
            [](const std::string& a, const std::string& b) -> std::string { return a + b; },
        }, item, acc);
    };

    std::any result = data[0];
    for (size_t i = 1; i < data.size(); ++i) {
        result = accumulate(data[i], result);
    }
    return result;
};

int main() {
    std::vector<std::any> numbers = {1, 2, 3, 4, 5};
    std::vector<std::any> floats = {1.1, 2.2, 3.3};
    std::vector<std::any> strings = {"Hello", " ", "World"};

    auto futureNumbers = std::async(std::launch::async, asyncReduce, numbers);
    auto futureFloats = std::async(std::launch::async, asyncReduce, floats);
    auto futureStrings = std::async(std::launch::async, asyncReduce, strings);

    int sumNumbers = std::any_cast<int>(futureNumbers.get());
    double sumFloats = std::any_cast<double>(futureFloats.get());
    std::string concatStrings = std::any_cast<std::string>(futureStrings.get());

    std::cout << "Sum of numbers: " << sumNumbers << std::endl;
    std::cout << "Sum of floats: " << sumFloats << std::endl;
    std::cout << "Concatenated strings: " << concatStrings << std::endl;

    return 0;
}
